-- ----------------------------------------------------------------
-- Quest dialogs take the texts and emotes of the retail 15595 sniffs.
--
-- The quest-giver packets sniffed on build 15595 (the Cataclysm Preservation
-- Project's quest_details, quest_request_items and quest_offer_reward rows)
-- give each quest's dialog emotes, its request text and its reward text.
-- The request-items packet carries one emote, the one for the quest's state
-- when it was sniffed, so only a non-zero one is taken. A text the sniff
-- leaves empty stays as it is.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '11';
    SET @cOldContent = '008';

    SET @cNewVersion = '22';
    SET @cNewStructure = '11';
    SET @cNewContent = '009';
    SET @cNewDescription = 'Quest_Dialog_Values';
    SET @cNewComment = 'Quest dialogs take the texts and emotes of the retail 15595 sniffs';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
        START TRANSACTION;

        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, mighty $C, I sensed your arrival. I trust you have more news to report to me about your hunt?' WHERE `entry` = 2;
        UPDATE `quest_template` SET `RequestItemsText` = 'Oh, a shipment from my brother? Splendid! Fortune truly shines on me today!' WHERE `entry` = 5;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find Garrick''s shack? Are we finally free of that villain?', `CompleteEmote` = 1 WHERE `entry` = 6;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes? Yes? What is it?$B$BThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name''s Renee if you need anything at all.', `CompleteEmote` = 6 WHERE `entry` = 8;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 10;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N. Have you been killing Gnolls...?', `CompleteEmote` = 1 WHERE `entry` = 11;
        UPDATE `quest_template` SET `RequestItemsText` = 'Perhaps I did not make myself clear, pledge. In order to prove your worth as a servant to The People''s Militia and to the Light you need to slay 15 Defias Trappers and 15 Defias Smugglers then return to me when the deed is done.' WHERE `entry` = 12;
        UPDATE `quest_template` SET `RequestItemsText` = 'We have not time to talk, $N. The Defias Pillagers are denying the people of Westfall the peace and prosperity they deserve. Make sure at least 15 Defias Pillagers and 15 Defias Looters have been killed. That will send a clear message that corruption is not welcome here.' WHERE `entry` = 13;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, now is no time for idle chatter. If you still wish to prove yourself to The People''s Militia you need to slay the Defias I notified you about earlier. Return to me when you have completed your duty.', `IncompleteEmote` = 66 WHERE `entry` = 14;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 16;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you obtained the magenta fungus caps I need for my alchemical work? No caps - no reward!' WHERE `entry` = 17;
        UPDATE `quest_template` SET `RequestItemsText` = 'Orc pressure from Blackrock is still tense. But have you at least rid us of Tharil''zun?' WHERE `entry` = 19;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been slaying orcs, $N? If so, then show me...' WHERE `entry` = 20;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah - $N - I was just thinking about you! How goes your hunting?' WHERE `entry` = 23;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings once again, $N! Have you come to show me proof of your hunt?' WHERE `entry` = 24;
        UPDATE `quest_template` SET `RequestItemsText` = 'You back already? What''s the situation out there - all cleared up now, thanks to you?' WHERE `entry` = 25;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your return to Thunder Bluff is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.$B$BDo you have the Pendant of the Sea Lion?' WHERE `entry` = 31;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m sorry. I don''t know you... but from the look of things you have at least heard something of me. Now, what can I help you with? Do you have something for me?' WHERE `entry` = 32;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m going to miss that Verna Furlbrow so much. I don''t suppose you happened to see her on your way here?', `CompleteEmote` = 1 WHERE `entry` = 36;
        UPDATE `quest_template` SET `RequestItemsText` = 'Come back with the following ingredients: $b $b 3 Stringy Vulture Meat $b 3 Goretusk Snouts $b 3 Murloc Eyes $b 3 Okra' WHERE `entry` = 38;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 46;
        UPDATE `quest_template` SET `RequestItemsText` = 'Psst! You have that Gold Dust for me...for me?', `CompleteEmote` = 1 WHERE `entry` = 47;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hiccup! Ho ho! You want an encore?$B$BIn the land to the south where vines twist and creep$BLies a hidden well where the water runs deep$BPure as the Light''s sacred Daughter$BBring to me now some Holy Spring Water.' WHERE `entry` = 48;
        UPDATE `quest_template` SET `RequestItemsText` = 'Encore? Well, sure!$B$BAmber is the hue of my life''s longest love$BLike the last embers of dusk in the sky above$BRetrieve for me so that my love shall be born$BOne sack of each: barley, rye and corn.' WHERE `entry` = 49;
        UPDATE `quest_template` SET `RequestItemsText` = 'An encore for you? Well sure friend!$B$BI''ll mix and mix till we have a mash$BFor this will be our own private stash$BA still must be fashioned of metal strong$BBring me some Truesilver so I can finish this song.' WHERE `entry` = 50;
        UPDATE `quest_template` SET `RequestItemsText` = 'An encore? Why for you, anything!$B$BNot yet filtered but freshly distilled$BLike unseeded land waiting there tilled.$BNext I will fashion our pile of charcoal$BDeliver a sycamore branch, that is your next goal.' WHERE `entry` = 51;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, it says here that you''ve been awarded Acting Deputy Status with the Stormwind Marshals.  Congratulations.$B$BAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$B$BIt''s hard to keep track of politics in these dark days...', `RequestItemsText` = 'You have word from McBride?  Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.$B$BHere, let me have his papers...' WHERE `entry` = 54;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 55;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you killed those warriors and mages?' WHERE `entry` = 56;
        UPDATE `quest_template` SET `RequestItemsText` = 'Return to me once you have killed 15 Skeletal Fiends and 15 Skeletal Horrors, $N.' WHERE `entry` = 57;
        UPDATE `quest_template` SET `RequestItemsText` = 'I need your assistance, $N. Travel to the cemetery to the northwest and rid the eastern mausoleum of 20 Plague Spreaders.$B$BReturn to me when your task is complete.', `IncompleteEmote` = 66 WHERE `entry` = 58;
        UPDATE `quest_template` SET `RequestItemsText` = 'I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.$b$bIf you have a marker for me, then I''d be happy to make you something.', `CompleteEmote` = 1 WHERE `entry` = 59;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 60;
        UPDATE `quest_template` SET `RequestItemsText` = 'Oh, a shipment from my brother? Splendid! Fortune truly shines on me today!', `CompleteEmote` = 1 WHERE `entry` = 61;
        UPDATE `quest_template` SET `RequestItemsText` = 'The brazier still reflects the ambient light from the are, and the flame shifts slightly as you move closer.$B$BThe corruption along the hills seems to have kept its distance, and besides the missing components, the brazier looks prepared for the ritual to summon a cleansed manifestation of water.' WHERE `entry` = 63;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 64;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, I remember you. You''re the one who was asking about that Stalvan fellow. Did you ever find what you were looking for?' WHERE `entry` = 68;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have ya got there? Let me take a look at that. . .' WHERE `entry` = 70;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Have you discovered the fates of Rolf and Malakai?', `CompleteEmote` = 1 WHERE `entry` = 71;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you got there? I cannot see. My eyesight is very bad. Put it in my hands.' WHERE `entry` = 74;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 77;
        UPDATE `quest_template` SET `RequestItemsText` = 'Marshal Haggard sent you? Why didn''t you say so?$B$BAh, good ol'' Haggard. Poor chap is going to be completely blind before long. Anyway, let me see what you''ve got there.' WHERE `entry` = 78;
        UPDATE `quest_template` SET `RequestItemsText` = 'This better be good, $C. Let me see what you have and tell me your tale. But by the Light, be quick about it. Darkshire''s defense is my number one priority. I have not the time to squander on dead-end leads.' WHERE `entry` = 79;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back again, $N? What do you have this time?' WHERE `entry` = 80;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you''re not here to buy anything, and you''re not here to deliver anything, then you''re wasting my time! You better have that ripple!' WHERE `entry` = 81;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re Junior Surveyor $N, yes? Quickly now, there is a dire situation at hand! Do you have the insect parts that Fizzledowser said you would?!', `CompleteEmote` = 1 WHERE `entry` = 82;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m running low on linen, $N. Do you have any for me?', `CompleteEmote` = 1 WHERE `entry` = 83;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ugh... I''m starving! Do you have that pie for me, $N?', `CompleteEmote` = 1 WHERE `entry` = 84;
        UPDATE `quest_template` SET `RequestItemsText` = 'I don''t think it''s right feeding the boy who stole my necklace in the first place, but if that''s what it takes to get back what''s mine, then so be it!$b$bDo you have that boar meat?', `CompleteEmote` = 1 WHERE `entry` = 86;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Have you found my necklace?', `CompleteEmote` = 1 WHERE `entry` = 87;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you see her yet? Did you get her?', `CompleteEmote` = 1 WHERE `entry` = 88;
