        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to find 10 Lean Wolf Flanks yet? How about the herbs from Felicia in Stormwind?' WHERE `entry` = 90;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N. Did you get those Gooey Spider Legs yet?' WHERE `entry` = 93;
        UPDATE `quest_template` SET `RequestItemsText` = 'This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.$B$BThere is a depression at the base of the statue, where a gem or glyph might be set...' WHERE `entry` = 94;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve returned. Splendid!$B$BHow went your journey to Silverpine? Did it take you long?$B$BIt is hard for me to tell if you were successful there because so much of the land has become corrupt. Its stench overwhelms any good that you might have done. But small successes are sometimes as important as large ones. Purifying the water there was instrumental for you, and for all shamans.' WHERE `entry` = 96;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 98;
        UPDATE `quest_template` SET `RequestItemsText` = 'Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom. For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.' WHERE `entry` = 101;
