        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 103;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you laid waste to the menace known as Old Murk-Eye yet? He has been spotted roaming the coastline of Westfall.$B$BReturn to me when the foul beast is dead.', `CompleteEmote` = 1 WHERE `entry` = 104;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your task has been given to you, $N. Do you have a shard from the lich''s phylactery as proof of the task being accomplished?' WHERE `entry` = 105;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have what?? Maybell is the light of my dull life. Hurry, let me see her letter!', `CompleteEmote` = 1 WHERE `entry` = 106;
