        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your conflict with the shadowcasters? Did you find the midnight orbs?' WHERE `entry` = 115;
        UPDATE `quest_template` SET `RequestItemsText` = 'I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire. Bring those back to me and I will see to it you are rewarded.', `CompleteEmote` = 1 WHERE `entry` = 116;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 117;
