        UPDATE `quest_template` SET `RequestItemsText` = 'Loch Modan is under siege, $N!  We need every able-bodied member of the Alliance to aid our cause.  Have you killed 10 Stonesplinter Troggs and 10 Stonesplinter Scouts yet?' WHERE `entry` = 224;
