        UPDATE `quest_template` SET `RequestItemsText` = 'A note from Abercrombie the hermit, eh? I don''t know him, though if he lives out at the graveyard then I do know his brains have rotted out!', `CompleteEmote` = 1 WHERE `entry` = 251;
