        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, $N! Back so soon? No doubt you''ve been at the hunt again? Don''t worry if you''ve had some setbacks, in the long run it will make you better!$B$B... You couldn''t get much worse, anyway...', `CompleteEmote` = 1 WHERE `entry` = 271;
