        UPDATE `quest_template` SET `RequestItemsText` = 'That drunk Fitzsimmons sent you to me? Well, you can tell him I don''t have any extra ale. He''s going to have to panhandle someone else!', `CompleteEmote` = 1 WHERE `entry` = 292;
