        UPDATE `quest_template` SET `RequestItemsText` = 'Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?$B$BWell take a number and get comfortable.  I''m working on a couple engines right now and won''t have time for another job for at least a few days.$B$BOr, were you here for something else...?' WHERE `entry` = 400;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings. Either you do not know who I am, or your business with me is urgent.$b$bBecause if neither of these were true, then you would not be foolish enough to disturb me...' WHERE `entry` = 405;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 407;
