        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $C!  And what business takes you all the way out here?$B$BSomething exciting, I hope.  I haven''t been in a good fight in days, and this barrel of ale is almost dry...' WHERE `entry` = 413;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N. How goes the rat catching?' WHERE `entry` = 416;
