        UPDATE `quest_template` SET `RequestItemsText` = 'If you wish to prove yourself to me, you must kill 5 Moonrage Whitescalps.  Accomplish that task, and I will see to it your skill is put to more worthy assignments.', `IncompleteEmote` = 1 WHERE `entry` = 421;
        UPDATE `quest_template` SET `RequestItemsText` = 'Before I know what we are dealing with here, $C, I need to study the spell known as Remedy of Arugal. Bring it to me now or I shall be forced to find myself a worthy servant.' WHERE `entry` = 422;
        UPDATE `quest_template` SET `RequestItemsText` = 'I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal. Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.' WHERE `entry` = 423;
