        UPDATE `quest_template` SET `OfferRewardText` = 'Well, that makes me feel a little better...$b$bBut I won''t be happy until they''re all dead! All of them!', `RequestItemsText` = 'It makes me so mad! Grrr...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 25 WHERE `entry` = 432;
        UPDATE `quest_template` SET `OfferRewardText` = 'What a relief! I''m glad to see that you were able to save so many miners, $N. I will make sure that their families are notified immediately.$B$BThe Senate will know of your role in winning back the mines.', `RequestItemsText` = 'If we can remove the troggs from Gol''Bolar quarry, it will be the first step of many that we will have to undertake to rid ourselves of this menace.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 433;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N? Are things going well with Tyrion? He apprised me of the situation and I''ve helped him trick Marzon into going to the castle.$B$BMarzon has been a thorn in the side of many people in Stormwind; many of which are close friends of mine. No one messes with my friends... not if they know what''s healthy for them.$B$BIt''s just a shame I''m indirectly doing a favor for Shaw and SI:7 in the meantime. Oh well, not every plan is perfect.' WHERE `entry` = 434;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. You return, so I assume your investigations bore fruit?' WHERE `entry` = 439;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. What brings you back to Brill?' WHERE `entry` = 440;
