        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 484;
        UPDATE `quest_template` SET `RequestItemsText` = 'You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!"', `CompleteEmote` = 1 WHERE `entry` = 485;
        UPDATE `quest_template` SET `OfferRewardText` = '$N you have proven yourself a most worthy and able $c.  A $r who follows the path of honor as sure as you do is certain to find great glory in this world.$b$bUrsal''s death brings safety to our once slumbering druids, but the source of his corruption yet remains within our forests. With time, I trust that you will find this evil and cleanse it for the sake of all of our people. You are destined for great things, young $c.', `RequestItemsText` = 'Our brethren cannot be awakened until Ursal the Mauler has been slain, $N.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 29, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 486;
        UPDATE `quest_template` SET `RequestItemsText` = 'The road is still not safe, $c. Travel forth and slay 6 Gnarlpine Ambushers and return to me.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 66 WHERE `entry` = 487;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ha ha!  Well, done indeed.$b$bWho would have ever guessed that I, Zenn Foulhoof, would have a $r to do my bidding?  Certainly not me!  But so it goes... this beloved world of ours is full of surprises.$b$bThree cheers for the naive and gullible!', `OfferRewardEmote1` = 1 WHERE `entry` = 488;
        UPDATE `quest_template` SET `CompleteEmote` = 4, `OfferRewardEmote1` = 1 WHERE `entry` = 489;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. Have you defeated Thule Ravenclaw?' WHERE `entry` = 491;
        UPDATE `quest_template` SET `CompleteEmote` = 14 WHERE `entry` = 492;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see you are back. I hope you were able to gather the agents I need. Another deathless day will put me in such a gloomy mood.' WHERE `entry` = 496;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, are you still hunting ogres? Do you have the knucklebones I had you gather?' WHERE `entry` = 500;
        UPDATE `quest_template` SET `RequestItemsText` = 'I remember you, $N. You were going to help me out in concocting my latest elixir. I''ll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.' WHERE `entry` = 501;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you look anxious. Is there something you wish to tell me?' WHERE `entry` = 510;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N? Do you have some business with me?' WHERE `entry` = 511;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been hunting the Syndicate? Do you have those rings?' WHERE `entry` = 512;
        UPDATE `quest_template` SET `RequestItemsText` = 'Can you not see I am busy, $C? The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us. And with the human threat pressing from the south, time becomes my most precious commodity. This better be important!' WHERE `entry` = 513;
        UPDATE `quest_template` SET `RequestItemsText` = 'Dibbs from Southshore sent you, did he? How is the old bookworm doing?' WHERE `entry` = 514;
        UPDATE `quest_template` SET `RequestItemsText` = 'So glad to see you back, $N. I was growing so terribly bored here. Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.$b$bHow went the trip to the Undercity? Were you fortunate enough to slaughter any humans along the way?' WHERE `entry` = 515;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you located their base yet, $n? Time is of the essence!' WHERE `entry` = 516;
        UPDATE `quest_template` SET `RequestItemsText` = 'Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air. Makes Umpi a little nervous though.$b$bSo were you able to get a keg from the Dwarves? I swear if I have to stare at this deadly elixir without using on it someone for another day I am going to scream.' WHERE `entry` = 517;
        UPDATE `quest_template` SET `RequestItemsText` = 'You look out of breath! Do you have something to report?' WHERE `entry` = 522;
        UPDATE `quest_template` SET `RequestItemsText` = 'Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity. I want his head!' WHERE `entry` = 523;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. Have you been traveling through the foothills and mountains again? What news do you bring?' WHERE `entry` = 525;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the lightforge iron you need?' WHERE `entry` = 526;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to carry out your orders, $C? Did you dispose of Verringtan and his assistants? And where is that iron shipment?' WHERE `entry` = 529;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 531;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wish I could search the ruins too, but I fear these bones wouldn''t hold me during my climb up the mountains. However, how does your hunt for knowledge progress, $N?', `CompleteEmote` = 1 WHERE `entry` = 540;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you''ve returned! How did your foray into Alterac go? Did you bring anything back with you?' WHERE `entry` = 542;
        UPDATE `quest_template` SET `RequestItemsText` = 'Salutations, $N. Do try to avoid stepping on my pant cuffs. This outfit is newly tailored.' WHERE `entry` = 543;
        UPDATE `quest_template` SET `RequestItemsText` = 'So the lucky $N returns? How many humans have you slaughtered today? Hundreds I do hope!$b$bHave you any skulls for me?' WHERE `entry` = 546;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to retrieve my sword, $N? High Executor Darthalia will hang me from the rafters if she discovers my folly.' WHERE `entry` = 547;
        UPDATE `quest_template` SET `RequestItemsText` = 'Oh. You have something you''d like me to look at? Some scrap of lore gathered from up in the mountains, I hope...' WHERE `entry` = 551;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you recovered Helcular''s Rod yet? There are so many Yeti in this region, it will be very difficult to locate. But we must have it in order to proceed.' WHERE `entry` = 552;
        UPDATE `quest_template` SET `RequestItemsText` = 'More interruptions?$B$BAh, this parchment is covered with a very intricate, finely woven spell. I can untangle it, of course, but it''s going to take time. And time is very valuable to me...$B$BPerhaps I will just purchase it from you?' WHERE `entry` = 554;
        UPDATE `quest_template` SET `RequestItemsText` = 'Any luck finding the ingredients? I''ll tell you, this territory isn''t the peaceful place it once was. Ah, if only this unrest never occurred...', `CompleteEmote` = 1 WHERE `entry` = 555;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Elementals are tough quarry, but I know you''re up to the task. Do you have those bracers of binding?' WHERE `entry` = 557;
        UPDATE `quest_template` SET `RequestItemsText` = 'Someday, I wanna be a hero just like Jaina... well, a boy hero that is.' WHERE `entry` = 558;
        UPDATE `quest_template` SET `RequestItemsText` = 'So you have returned to the great Bartolo. Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak? Or maybe you just enjoy basking in the greatness of me, Bartolo!' WHERE `entry` = 565;
        UPDATE `quest_template` SET `RequestItemsText` = 'Our supply efforts are still being hampered by the indigenous raptor population, $c.' WHERE `entry` = 568;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you made any progress with the ogres of the Mizjah Ruins yet, $C?' WHERE `entry` = 569;
        UPDATE `quest_template` SET `RequestItemsText` = 'Has fortune been on your side, $N? Were you able to obtain an aged gorilla sinew?' WHERE `entry` = 571;
        UPDATE `quest_template` SET `RequestItemsText` = 'I am almost ready to complete the enchantment. Have you performed my bidding?' WHERE `entry` = 573;
        UPDATE `quest_template` SET `RequestItemsText` = 'Sergeant Yohwa tells me you are skilled and brave, $C. Do you have something to report?' WHERE `entry` = 574;
        UPDATE `quest_template` SET `RequestItemsText` = 'My equipment is all ready to go, $n, I just need those skins. We don''t want to keep Riddlevox waiting, that''s for sure.$b$bIt''s not a good idea for anyone to keep the chief inventor of the Tinkers'' Union unsatisfied.' WHERE `entry` = 575;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.$b$bCould really use me eye back.  Captain''s going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.$b$bWhat good is a lookout who can''t see?  The crow''s nest used to be me home...without me deadlights I''d be lucky to scrub the bilge.', `CompleteEmote` = 1 WHERE `entry` = 576;
        UPDATE `quest_template` SET `RequestItemsText` = 'Drizzlik''s Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocilisk skin boots. None finer!$b$bCan''t beat a glowing description like that, can you?$b$bExcept, maybe, if you have those skins for me?', `CompleteEmote` = 1 WHERE `entry` = 577;
        UPDATE `quest_template` SET `RequestItemsText` = 'The trolls truly possessed some amazing magical objects, $N. And now, perhaps, I have the opportunity to add one to my extensive collection. Did you have any luck finding the source of the rumor?' WHERE `entry` = 578;
        UPDATE `quest_template` SET `RequestItemsText` = 'King Varian has placed great importance on learning, and thus has provided funds for making copies of various tomes and writings available to the public. It''s very simple. You bring me a library scrip, and I can give you a copy of one of the available books.', `CompleteEmote` = 1 WHERE `entry` = 579;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 580;
        UPDATE `quest_template` SET `RequestItemsText` = '$C. Show me you have made prey of the Bloodscalp tribe.$b$bShow me your trophies.' WHERE `entry` = 581;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. I fear for our chief''s son. Do you have the shrunken heads so I may inspect them?' WHERE `entry` = 582;
        UPDATE `quest_template` SET `RequestItemsText` = 'Although my own flesh boils off my skull, I can still smell your fear.$B$BHah!  You will never complete my task...' WHERE `entry` = 586;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 587;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the shards, $N? They are needed for my final ritual, after we have the Mind''s Eye.' WHERE `entry` = 589;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, $N. The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai''Zoth.$b$bDo you have the Eye?' WHERE `entry` = 591;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. Kin''weelay told me you set out to capture Yenniku.$b$bIs it true? Do you have him?' WHERE `entry` = 592;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yenniku stands stunned before you, his mind in another place...' WHERE `entry` = 593;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Bloodscalps will one day be crushed by the Darkspears! Do you have the necklaces of our doomed foe?' WHERE `entry` = 596;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Skullsplitters will curse the day they brought us to war! Is your task complete?' WHERE `entry` = 598;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have those crystals?? I need them!!$b$bI mean...I need to know the evil Venture Company is losing ground in Stranglethorn. Because, you know, we honest folk have to make a living!', `CompleteEmote` = 1 WHERE `entry` = 600;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 601;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 602;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 604;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hey!  I don''t like the look you''re giving me, $gmister:lady;.', `CompleteEmote` = 1 WHERE `entry` = 606;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 607;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, did you find those three dogs? Did you collect their valuables?' WHERE `entry` = 609;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 610;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 611;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ahoy, $N! Have you yet found Maury''s Key?', `CompleteEmote` = 1 WHERE `entry` = 613;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 617;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get my cutlass, $N?' WHERE `entry` = 618;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Did you make it to Booty Bay? Did the goblin Krazek fix my pot??', `CompleteEmote` = 1 WHERE `entry` = 622;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 623;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Did you have luck getting the bloodstone?', `CompleteEmote` = 1 WHERE `entry` = 627;
        UPDATE `quest_template` SET `RequestItemsText` = 'I read somewhere that the saltwater crocilisks are slowly dying out... bad news for my business, isn''t it?$b$bAnyways, I hope you have that elder saltwater crocolisk skin for me!', `CompleteEmote` = 1 WHERE `entry` = 628;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 630;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 632;
        UPDATE `quest_template` SET `RequestItemsText` = 'The cache of explosives must be destroyed!' WHERE `entry` = 633;
        UPDATE `quest_template` SET `RequestItemsText` = 'You look as though you have traveled a great distance and seen much turmoil in your time, $C. These times we live in are trying on the soul. What news do you bring to me now?' WHERE `entry` = 637;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 647;
        UPDATE `quest_template` SET `RequestItemsText` = 'This is the Stone of Inner Binding. It is the strongest of the binding stones and must be unlocked for the others to open.' WHERE `entry` = 651;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, did you get everything you needed? If you didn''t and the power runs out, everything inside will be ruined and you''ll have to start over.$B$BHey, don''t look to me for sympathy; I''m all about the Gadgetzan Water Company making a profit, and if that means selling you power sources until we can afford to import water in from the icy springs of Dun Morogh, so be it!', `IncompleteEmote` = 5 WHERE `entry` = 654;
        UPDATE `quest_template` SET `RequestItemsText` = 'We appreciate your help in looking for that courier, $N.$B$BWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I''m confident that they''re up to no good--I just need proof of it before we go off and do something rash.$B$BHave you had any luck yet?' WHERE `entry` = 658;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the search and recovery mission, $n?  We really need to get those Logs and Charts back from the Maiden''s Folly and Spirit of Silverpine.$b$bIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.$b$bThat is if we ever get out of this mess...' WHERE `entry` = 662;
        UPDATE `quest_template` SET `RequestItemsText` = 'Bah, maybe I should go kill those naga scum myself. It''s obvious you''re not goin'' to do it.$B$BMaybe I can find some knitting needles so you can keep yourself busy.' WHERE `entry` = 664;
        UPDATE `quest_template` SET `RequestItemsText` = 'This is no time to talk! The goggles need to be charged with the power of the stone!' WHERE `entry` = 665;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ahoy, $C. What brings you to the bridge?' WHERE `entry` = 668;
        UPDATE `quest_template` SET `RequestItemsText` = 'The burning in my blood... it grows by the day. The $C must be stopped.' WHERE `entry` = 673;
        UPDATE `quest_template` SET `RequestItemsText` = 'You hesitate. Why? You have shown great strength thus far, $N. Do not fail me now.' WHERE `entry` = 678;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, with each passing hour our hold on Stromgarde grows more tenuous. You must make haste or our city will surely fall.' WHERE `entry` = 681;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you retrieved any Stromgarde Badges, $N? The Syndicate must learn they cannot profit from our dead.' WHERE `entry` = 682;
        UPDATE `quest_template` SET `RequestItemsText` = 'So you are $N the $C? News of your contributions to the Alliance has traveled quite far, you know?$B$BOn what business do you come before me today?' WHERE `entry` = 683;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, $C. You have a report to make?' WHERE `entry` = 684;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello. Do you have a report to submit?' WHERE `entry` = 685;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you had any luck so far, $N?$B$B<Kryten makes some notes in his journal as he reads.>$B$BIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they''ve completed their rites of passage. There''s no way to tell which shadow hunters will have the knife until you do battle.' WHERE `entry` = 691;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find those fragments?!?! You''ll need the Scroll of Myzrael if you want to trap her again, before it''s too late!' WHERE `entry` = 692;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Did you bring me my wings?' WHERE `entry` = 703;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find those urns, $N? We must find the link between them and the troggs!' WHERE `entry` = 704;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the tablet? It must hold secrets! Secrets to save us!', `CompleteEmote` = 1 WHERE `entry` = 709;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 710;
        UPDATE `quest_template` SET `RequestItemsText` = 'The stone slabs you found were ideal, $N. Lucien will be taking the extra ones back to Kharanos when we''re done here. After all, they could prove useful again.$B$BFor instance, they''d be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...' WHERE `entry` = 712;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 713;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wouldn''t wait too long to get that bracer, Orthanc.$b$bWho knows what''s going to happen next?' WHERE `entry` = 716;
        UPDATE `quest_template` SET `RequestItemsText` = 'The desert''s a bad place to be hungry, my friend, let me tell you that.$B$BHey... what''s that over there...' WHERE `entry` = 718;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, yes. Another traveler seeking something from the dwarves.$B$BMa''am, I''m truly sorry, but I''ve no time to answer meaningless questions right now.' WHERE `entry` = 724;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello. Welcome to my shop, but watch what you touch.$B$BKnowledge can be deadly.' WHERE `entry` = 727;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, we have an eager $C, I see. Are you here to learn from my collection? Good!$B$BBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.' WHERE `entry` = 728;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is the prospector alive?' WHERE `entry` = 731;
        UPDATE `quest_template` SET `RequestItemsText` = 'The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress. I have heard that sometimes they travel through Camp Boff. If you are lost, you might try your search there.' WHERE `entry` = 732;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ho! You were gone a long time. Did you get the digest?' WHERE `entry` = 737;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have news of Agmond''s fate? Did you find him?' WHERE `entry` = 739;
        UPDATE `quest_template` SET `RequestItemsText` = 'If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.' WHERE `entry` = 745;
        UPDATE `quest_template` SET `RequestItemsText` = 'Providing meat and feathers for the tribe is the first step in proving yourself as a $C before the Chief.' WHERE `entry` = 747;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N. Have you learned anything new about the Venture Co.''s plans and operations in our homeland?\n\nIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.' WHERE `entry` = 751;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, do you have the claws I sent you to gather? The Thunderhorn Water Well grows more tainted with each passing hour!' WHERE `entry` = 756;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. Do you have the teeth I asked for?' WHERE `entry` = 759;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 2 WHERE `entry` = 761;
        UPDATE `quest_template` SET `RequestItemsText` = 'My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn''t be able to handle a beast my grandfather was unable to defeat...$b$bDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.' WHERE `entry` = 766;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello again. Have you been hunting? Do you have skins for me?' WHERE `entry` = 768;
        UPDATE `quest_template` SET `RequestItemsText` = '<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>$B$BThe cog, $N, the cog!' WHERE `entry` = 777;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.' WHERE `entry` = 779;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tho''grun''s betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.$B$BIf you''ve not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.' WHERE `entry` = 782;
        UPDATE `quest_template` SET `RequestItemsText` = 'The centaurs have proven to be a consistent nuisance to the Horde. Their intentions to lay siege to our homeland cannot be tolerated.', `IncompleteEmote` = 5 WHERE `entry` = 786;
        UPDATE `quest_template` SET `RequestItemsText` = 'I hope you haven''t returned to try and convince me that you have completed your task, $N? No, of course not. I would think better of you.' WHERE `entry` = 788;
        UPDATE `quest_template` SET `RequestItemsText` = 'The carapace of a scorpid isn''t so thick that the strength of a determined $C will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.' WHERE `entry` = 789;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is your task complete, $N? Do you have the Burning Blade Medallion?' WHERE `entry` = 794;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.' WHERE `entry` = 795;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find Fizzle, $N? He, and rest of the Burning Blade, must be scoured from our lands!' WHERE `entry` = 806;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have my brother''s skull, $N? Is he finally free?' WHERE `entry` = 808;
        UPDATE `quest_template` SET `RequestItemsText` = 'I remember my first tiger hunt, $N. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.$b$bMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.' WHERE `entry` = 817;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, hello there. I spend a great deal of time studying the water - all the elements really - so much so that sometimes I don''t even notice people around me.$b$bIs there something I can help you with?' WHERE `entry` = 824;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is Zalazane defeated, $N?' WHERE `entry` = 826;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you yet entered Skull Rock, $N? Do you have the Searing Collars?' WHERE `entry` = 827;
        UPDATE `quest_template` SET `RequestItemsText` = 'My most humble greetings, $C. How might I help my $R brother today?' WHERE `entry` = 829;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have something vital to report. I can sense it behind your eyes.' WHERE `entry` = 832;
        UPDATE `quest_template` SET `IncompleteEmote` = 5 WHERE `entry` = 833;
        UPDATE `quest_template` SET `OfferRewardText` = 'I think I can breathe easy now, knowing that the harpies won''t be bothering our supply caravans anymore. And not one moment too soon, either. I hear I''m being sent some fun little toys with the next shipment!$b$bYou''re pretty good at what you do, $n, you ought to track down my boss in Ratchet. I''ll bet he could find some work for you.$b$bOh, and don''t worry, I wouldn''t forget to pay you for the service you provided me.', `RequestItemsText` = 'You wouldn''t think it from a guy like my boss Gazlowe, but he always seemed to know the score. "Don''t be afraid to take that big step," he said.$B$BHarpies won''t stop bothering us and the caravans won''t stop being attacked unless we do something about it, eh?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 835;
        UPDATE `quest_template` SET `RequestItemsText` = 'Though they do possess some intelligence and some organization, I find it constantly amazing that the quilboars were able to capture and hold so much territory in Kalimdor. Perhaps they are more crafty an enemy than I give them credit for...' WHERE `entry` = 837;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, so Takrin sent you?$B$B<Kargal warily eyes your recruitment letter and shoves it unceremoniously into his vest>$B$BI''ll sign this when you''ve earned it. I''ve got reports from down south that this whole continent is being torn apart. Meanwhile, we''ve got supply caravans backed up to the river and outposts under siege from here to Stonetalon. You want to prove your worth to the horde? Start by proving it here.', `OfferRewardEmote1` = 6, `OfferRewardEmoteDelay1` = 100 WHERE `entry` = 840;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 800 WHERE `entry` = 844;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the spores, $N? There is a concoction I must send to my associate in Thunder Bluff, which requires the spores...' WHERE `entry` = 848;
        UPDATE `quest_template` SET `RequestItemsText` = 'Once the dwarven flying machine has been destroyed I will feel the sweet satisfaction of revenge.' WHERE `entry` = 849;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Do you have Barak''s Head for me?' WHERE `entry` = 850;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 857;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 862;
        UPDATE `quest_template` SET `RequestItemsText` = 'Can I help you?' WHERE `entry` = 863;
        UPDATE `quest_template` SET `RequestItemsText` = 'Welcome back. At least, welcome back if you have returned with a sealed testing kit. Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.' WHERE `entry` = 864;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get the horns, $N? Those things are going to make me a fortune!', `DetailsEmote1` = 5 WHERE `entry` = 865;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Did you get those root samples?' WHERE `entry` = 866;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have those heads, $N?' WHERE `entry` = 869;
        UPDATE `quest_template` SET `RequestItemsText` = 'The longer it takes to stop these attacks, the harder it will be to provide supplies for the people of the Crossroads.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 1 WHERE `entry` = 871;
        UPDATE `quest_template` SET `RequestItemsText` = 'Cut off the head of their leader, and chaos ensues, $N. Learn this lesson well. It will aid you in the future.$B$BThe boars will flounder without direction, and we will be able to take back the Barrens.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 800 WHERE `entry` = 872;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to the Stagnant Oasis? Was there a fissure beneath its waters?' WHERE `entry` = 877;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your hunt, $R? <snort>$B$BThork thinks he knows the truth about who leads the raids against his people, <snort> but he shall learn how wrong he is if you are successful.$B$BMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing. <snort>' WHERE `entry` = 879;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your collection? Did you get the shells?' WHERE `entry` = 880;
        UPDATE `quest_template` SET `RequestItemsText` = 'The great cat calls to you, $N.' WHERE `entry` = 881;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, when you approached I saw a new power in your stride. Tell me -- has your spirit met with the great Lakota''mani?' WHERE `entry` = 883;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, there is a new power behind your eyes! You have met with the mighty Owatanka, have you not?' WHERE `entry` = 884;
        UPDATE `quest_template` SET `RequestItemsText` = 'There is new resolve within you, $N. A resolve born from pain...$B$BAre you burdened with the death of Washte Pawne?' WHERE `entry` = 885;
        UPDATE `quest_template` SET `RequestItemsText` = 'I don''t even want to think about the profits I''ve lost from pirate raiding, and now they set up camp on my doorstep? It''s getting out of hand, Undermine''s got to do something about it.' WHERE `entry` = 887;
        UPDATE `quest_template` SET `RequestItemsText` = 'Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.$B$BIt will not last long, but it should be enough to help you travel throughout the Barrens.' WHERE `entry` = 889;
        UPDATE `quest_template` SET `RequestItemsText` = 'My fleet is in peril with Captain Fairmount and her damned cannoneers blasting away from Northwatch Hold. I want her soldiers to pay as well. Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `DetailsEmote4` = 5 WHERE `entry` = 891;
        UPDATE `quest_template` SET `RequestItemsText` = 'I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.$B$BI have had more menial tasks, and I do so willingly if it aids the orc people.' WHERE `entry` = 893;
        UPDATE `quest_template` SET `RequestItemsText` = 'You seemed troubled, $N. How go your lessons in the Barrens? Did you find something that disturbs you?' WHERE `entry` = 897;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes?' WHERE `entry` = 898;
        UPDATE `quest_template` SET `DetailsEmote1` = 15, `DetailsEmote2` = 1, `DetailsEmote3` = 25, `DetailsEmoteDelay2` = 800 WHERE `entry` = 899;
        UPDATE `quest_template` SET `RequestItemsText` = 'Blinking lights on the control console indicate that the main control valves have not been closed off.' WHERE `entry` = 900;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your hunt, $N? Have you found the prowlers?' WHERE `entry` = 903;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to the nests, $N?' WHERE `entry` = 905;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been successful in locating the fathom core? Without it we''ll have no idea what the Twilight''s Hammer is exactly up to down there.' WHERE `entry` = 908;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, hello again $N. I was just reading the waves the sea, much like I always do. What brings you to the outpost?' WHERE `entry` = 909;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 910;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 911;
        UPDATE `quest_template` SET `RequestItemsText` = 'Memories of my nightmares haunt me, $N. Have you defeated the leaders of the fang and acquired their gems?' WHERE `entry` = 914;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wish they''d make more flavors of ice cream other than strawberry, but I guess I''m lucky that strawberry is my favorite!' WHERE `entry` = 915;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been inside the Shadowthread Cave, $N? Did you find a spider egg?' WHERE `entry` = 917;
        UPDATE `quest_template` SET `RequestItemsText` = 'The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.$B$BThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.' WHERE `entry` = 921;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, a timberling seed?  I wanted to try growing one of these to help Denalan with his studies.$B$BBut I''m afraid I''ve discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent''s taint. They are beyond my talents to repair.$B$BDenalan is very skilled with things that grow. He may find a cure for future timberlings. He may be their only hope.', `RequestItemsText` = 'Hello...$B$BAnd how may I help you?', `OfferRewardEmote1` = 1 WHERE `entry` = 922;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done! These tumors are the symptom of the timberling''s disease. They are filled with a poison that we must cleanse from our new land.$B$BI will dispose of these tumors. Thank you, $N.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 2 WHERE `entry` = 923;
        UPDATE `quest_template` SET `RequestItemsText` = 'When the orcs were alone and without friends, the tauren welcomed them to a strange land and shared with them without asking anything in return. That''s honor, $N.' WHERE `entry` = 925;
        UPDATE `quest_template` SET `OfferRewardText` = '...What is this?  A timberling heart??  It''s covered with a foul moss!$B$BThank you for bringing this to me, $N.  I will examine the heart and, if fortune shines, determine the nature of the moss about it.' WHERE `entry` = 927;
        UPDATE `quest_template` SET `OfferRewardText` = 'You found this on Teldrassil?  Intriguing... this fruit is exotic.  Perhaps its seeds were brought here from far off.  Perhaps even as far as Azeroth!  And there''s something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.$B$BThank you, $N.  Now if you''ll excuse me, I must study this further...', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 930;
        UPDATE `quest_template` SET `OfferRewardText` = 'Where did you get this?  I haven''t seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!  It''s amazing that a specimen made its way to Teldrassil.  And it''s grown to such a size!$B$BThank you, $N.  Forgive my shortness of words, but there is a test I would like to perform on this frond...', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 2 WHERE `entry` = 931;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 2, `OfferRewardEmoteDelay1` = 100 WHERE `entry` = 932;
        UPDATE `quest_template` SET `OfferRewardText` = 'Indeed, I have spoken to Corithras on my way here, and he has gifted me with the waters you have been gathering. They may well prove useful sooner than we''d imagined.$B$BStrangely, the growing corruption we''ve felt is actually a good sign. Teldrassil has been burdened with this taint for a long time, and thanks to the blessing of the dragon aspects, only now is it coming to the surface in a form that we might strike against.', `OfferRewardEmote1` = 1 WHERE `entry` = 933;
        UPDATE `quest_template` SET `RequestItemsText` = 'Along with the druids, the Oracle Tree and the Arch $C have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.' WHERE `entry` = 934;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 935;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 937;
        UPDATE `quest_template` SET `RequestItemsText` = 'Mist... It was my fault! The witches caught me off guard... I should not have let them take you...' WHERE `entry` = 938;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 939;
        UPDATE `quest_template` SET `OfferRewardText` = 'You place the heart within the planter, and it quickly digs itself in!$B$BA few seconds later it wriggles back out, cleansed.  It pulses slightly... beckoning for you to take it.', `DetailsEmote1` = 1 WHERE `entry` = 941;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Master''s Glaive, $N.$B$BGo there, then speak with me again.' WHERE `entry` = 944;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have my mushrooms, $N? Have you been to the cave?' WHERE `entry` = 947;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. You return.' WHERE `entry` = 950;
        UPDATE `quest_template` SET `RequestItemsText` = '$N. Has your rooting through the Ruins of Mathystra been fruitful?' WHERE `entry` = 951;
        UPDATE `quest_template` SET `RequestItemsText` = 'When you have studied the tablets and learned of Ameth''Aran''s fall, I will take the knowledge on to Auberdine, and inform the Circle of Ancients.' WHERE `entry` = 953;
        UPDATE `quest_template` SET `RequestItemsText` = 'The pillars of this shrine are as the bars of a prison to me, $N. No strength I still possess might break them, and no magic I wield might destroy them...$B$BFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...' WHERE `entry` = 956;
        UPDATE `quest_template` SET `RequestItemsText` = 'In truth, $N, I am afraid... Afraid that your coming--all of this--is merely a figment of a deranged mind. Can you know the torture that this is? I... Please, you must go quickly.' WHERE `entry` = 957;
        UPDATE `quest_template` SET `RequestItemsText` = 'The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.$B$BIf you''re brave enough and patient enough to seek out Mad Magglish and get that port back, I''ll see to it you get a nice reward.' WHERE `entry` = 959;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kill many and kill often, $C - we''ll need a decent supply of suitable skeletal fragments to make up the outer layer of the key. They don''t call it a Skeleton Key for nothing, you know.' WHERE `entry` = 964;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $Gsir:madam;.$B$BMay I interest you in one of my tomes?' WHERE `entry` = 968;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 969;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 970;
        UPDATE `quest_template` SET `RequestItemsText` = 'The journey to Ashenvale is long, and your task is not easy. But if you get me the manuscript, $N...then your reward will be great.' WHERE `entry` = 971;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 973;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Sentinels have a great need for supplies to reinforce themselves in Darkshore.' WHERE `entry` = 976;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 977;
        UPDATE `quest_template` SET `RequestItemsText` = 'The captains of those ships were good night elves, and they deserve a better fate than they were given. Perhaps tending to their personal effects will be the best way to put their spirits to rest.' WHERE `entry` = 982;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your search, $N?' WHERE `entry` = 984;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 992;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.' WHERE `entry` = 996;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, it''s here!  I have waited for this rare earth for quite some time.  I hope it''s still fresh...$B$BThank you for bringing it to me, $N.  You are a $r who is generous with $ghis:her; time.', `OfferRewardEmote1` = 1 WHERE `entry` = 997;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.' WHERE `entry` = 998;
        UPDATE `quest_template` SET `RequestItemsText` = 'You hear singing coming from Buzzbox 525.$b$b"Though crawler wine''s shweet, and thresher ale fine, and moonstalker moonshine ish grand. There''s nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!"$b$bThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.' WHERE `entry` = 1003;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, $N?' WHERE `entry` = 1009;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the camp, $N? Do you have a bottle of disease?' WHERE `entry` = 1011;
        UPDATE `quest_template` SET `RequestItemsText` = 'The anguish of the Dor''danil druids still haunt my dreams, $N. You must destroy their leaders!' WHERE `entry` = 1012;
        UPDATE `quest_template` SET `RequestItemsText` = 'The tome of the shrine is a mysterious object. It is not a book in the traditional sense. The leaves of the tome were blessed by Mel''Thandris herself, and records events of import in its pages.$B$BIt is hard for me to explain. If you go to the shrine, you will understand.' WHERE `entry` = 1022;
        UPDATE `quest_template` SET `CompleteEmote` = 2 WHERE `entry` = 1023;
        UPDATE `quest_template` SET `RequestItemsText` = 'The furbolg were not always our enemy, $N. But times change, and it is no longer a time of peace here in these dark woods.' WHERE `entry` = 1025;
        UPDATE `quest_template` SET `RequestItemsText` = 'You can sense a subtle yet powerful force within the shrine and surrounding trees.$B$BYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...' WHERE `entry` = 1028;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, did you find Iris Lake? Do you have the Tear?' WHERE `entry` = 1033;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you face the Shadethicket Oracle, $N? If so, then please hand me the fallen moonstone. Relara has strength left for only a few more breaths!' WHERE `entry` = 1035;
        UPDATE `quest_template` SET `RequestItemsText` = 'The woods are perilous for the unprepared. Keep your weapons close at hand and your wits even closer, or your next journey into the haunted forest may be your last.' WHERE `entry` = 1043;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you slain Ran yet, my friend?$B$BEven the Night elves do not truly deserve his wrath. His hatred burns even brighter than my own, but his mind is no longer his own. He is a threat to all the natural creatures of this forest.' WHERE `entry` = 1045;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Sentinels do what they can here in Ashenvale, but it''s thanks to $rs like you that we have gained the ground we have.' WHERE `entry` = 1046;
        UPDATE `quest_template` SET `RequestItemsText` = 'Perhaps I was not explicit in my orders, $c. I want High Inquisitor Whitemane killed once and for all. And while you''re at it, take out her top brass as well.$B$BKill that zealot, Scarlet Commander Mograine. Lay waste to Herod, the Scarlet Champion. And slaughter Houndmaster Loksey and his filthy mutts too.$B$BNow begone!' WHERE `entry` = 1048;
        UPDATE `quest_template` SET `RequestItemsText` = 'Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.$b$bOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.$b$bHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...' WHERE `entry` = 1049;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1052;
        UPDATE `quest_template` SET `RequestItemsText` = 'The corruption in the Monastery will not end until the highest ranking officials have been removed.$b$bIn the name of the Light, slay High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey. Once they have fallen, perhaps the true cause can be rekindled. Until then, anyone who crosses the path of the Crusade lies in peril.$b$bVenture forth from Southshore and make it so!', `IncompleteEmote` = 5 WHERE `entry` = 1053;
        UPDATE `quest_template` SET `RequestItemsText` = 'Look at our poor little elf friends. All caged up with no forest to frolic in!$b$bNow were you able to find me some sap? How about the whiskers from the twilight runners? Don''t suppose you have that fey dragon scale on you?$b$bAnd eyes! I''ll need so many eyes! You just can''t mix up a fierce forest magic brew without a good helping of eyes!' WHERE `entry` = 1058;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Greatwood Vale lies to the northwest, $N. Go. Strike fear into those who would pillage this land!' WHERE `entry` = 1062;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have returned, $N. Do you bring aid from Apothecary Lydon?' WHERE `entry` = 1067;
        UPDATE `quest_template` SET `RequestItemsText` = 'The tree spirits wail at the loss of their brethren, $N. You must destroy the shredders XT:4 and XT:9, or I fear Stonetalon will never be healed.' WHERE `entry` = 1068;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get the eggs, $N? I already made a shipping deal with Wharfmaster Dizzywig!' WHERE `entry` = 1069;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the battle on your end, $N?' WHERE `entry` = 1071;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello again, $N.$B$BHave you already returned from the Vale in Stonetalon with those scales?' WHERE `entry` = 1078;
        UPDATE `quest_template` SET `RequestItemsText` = 'Here, channeling magic is like drawing water from a well with a bucket full of holes.' WHERE `entry` = 1087;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1100;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1101;
        UPDATE `quest_template` SET `RequestItemsText` = 'Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.$b$bHave you the driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank''s heart?' WHERE `entry` = 1102;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ya have the sapta, $G brotha:sista;?$B$BI know another that had trouble after defeating da corrupt water spirit--seems he waited too long and he came out of the spirit world too quick fer his taste. Hate to see dat happen to another, so I''ll just wait here fer a bit to make sure no one else be needin'' me help.' WHERE `entry` = 1103;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hi hi hi! Did you get that venom??' WHERE `entry` = 1104;
        UPDATE `quest_template` SET `RequestItemsText` = 'My brother is making progress with his new fuel design, and that has me worried. I need to start work on a tortoise shell fuel tank as soon as possible!' WHERE `entry` = 1105;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, you found me. Good for you.$b$bAre you here about that axe I made for Gath''Ilzogg? Or are you here to reclaim Duchess Pamay''s honor?$b$bActually, I don''t care which it is. If you''re here to fight, then let''s get it over with...' WHERE `entry` = 1106;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find any indurium flakes, $N. I have my forge heated up and ready to test them.' WHERE `entry` = 1108;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, have you been out into the Flats? Did you bring back that load of parts I wanted?' WHERE `entry` = 1110;
        UPDATE `quest_template` SET `RequestItemsText` = 'Speak up! Tell me, are you dropping off or picking up?' WHERE `entry` = 1111;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have something for me? That''s great! let''s see it!' WHERE `entry` = 1114;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back so soon? Do you have my dream dust?' WHERE `entry` = 1116;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get anything on Nazz Steamboil? Anything he might want to keep a secret??' WHERE `entry` = 1117;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello hello. And what brings a noble $R such as you down to Booty Bay?' WHERE `entry` = 1118;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Was Fizzlebub able to help us?' WHERE `entry` = 1119;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hi! You have something for me?' WHERE `entry` = 1120;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello $N. How''d that stout work out? It''s strong stuff, isn''t it?' WHERE `entry` = 1122;
        UPDATE `quest_template` SET `RequestItemsText` = 'This is a dangerous land to be so casual, $C. What brings you to the wastes of Silithus?' WHERE `entry` = 1124;
        UPDATE `quest_template` SET `RequestItemsText` = 'Alliance or Horde, it doesn''t matter - no being deserves to be trapped on this world as a tortured spirit.  The freeing of these souls will make things right, $N.', `IncompleteEmote` = 1 WHERE `entry` = 1125;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, did it work? You''re still in one piece, which is good news. Did you find anything?' WHERE `entry` = 1126;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the pridewing venom sacs, $N? We cannot allow the orcs to use the beasts'' poisons against us!' WHERE `entry` = 1134;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to the Alterac Mountains, $N? Did you face the elusive Frostmaw?' WHERE `entry` = 1136;
        UPDATE `quest_template` SET `RequestItemsText` = '...lemon crab, whipper root crab, and Ironforge surprise crab.  That''s about it.$B$BOh, hello there $N.  Do you have them fine crab chunks I was telling you about?' WHERE `entry` = 1138;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hammertoe''s quest must be actualized, $N. I owe him that much.$B$BYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.' WHERE `entry` = 1139;
        UPDATE `quest_template` SET `IncompleteEmote` = 1 WHERE `entry` = 1140;
        UPDATE `quest_template` SET `RequestItemsText` = 'There''s plenty of good dishes you use Darkshore groupers for.  They''re good to eat, but I think it''s more fun catching them.$B$BYou caught any Darkshore groupers yet?' WHERE `entry` = 1141;
        UPDATE `quest_template` SET `RequestItemsText` = 'I envy you, $C. You have the look of someone who''s been outside the walls of Orgrimmar for a while.$B$BI myself would travel in the name of the Warchief if Thrall didn''t have need of my skills here in the city. But he leads us well, and I trust his judgement - I remain here for as long as he needs me.' WHERE `entry` = 1145;
        UPDATE `quest_template` SET `RequestItemsText` = 'With the amount of travelers heading out to the Flats for those races, I''m sure we can convince enough adventure seekers to help push back those insects. My party and I won''t be able to leave until we do.' WHERE `entry` = 1147;
        UPDATE `quest_template` SET `RequestItemsText` = 'Faith. It is far more important than some realize.$B$BIt does not matter what you believe sometimes. It is just important that you believe in something.' WHERE `entry` = 1149;
        UPDATE `quest_template` SET `RequestItemsText` = 'You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.$b$bToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.' WHERE `entry` = 1150;
        UPDATE `quest_template` SET `RequestItemsText` = 'I saw the travelers again - the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.$B$BMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.' WHERE `entry` = 1153;
        UPDATE `quest_template` SET `RequestItemsText` = 'I hope you made the Scarlet Crusade suffer some before stealing the book from them.$b$bMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead''s powerful magics. Idiots. Idiots and fools; all of them.' WHERE `entry` = 1160;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 1164;
        UPDATE `quest_template` SET `RequestItemsText` = 'Mok''Morokk tell all ogres to stay and keep this place safe. Me think ogres need to kill black dragon army and get old home back.$b$bYou help ogres get home back. Help ogres get revenge.' WHERE `entry` = 1168;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s bad enough having to clear out the wreckage of the racers without having to pick them out of burnt animal parts.' WHERE `entry` = 1175;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1176;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1187;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''d like to integrate indurium into different parts of our racers, but I need large amounts of raw indurium to create these parts.$B$BYou can find indurium ore in the Uldaman excavation in the Badlands, across the sea in Khaz Modan.$B$BThe gnomes are getting their own supply of it, so it''s important we get our own to keep pace with them.' WHERE `entry` = 1192;
        UPDATE `quest_template` SET `RequestItemsText` = 'A large, broken trap lies before you. From the looks of it, the ogres have tried to repair the trap but to no avail. A hastily written note lies next to the trap, and strangely enough it details exactly what is needed to repair it: a thorium widget and some frost oil. Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.$b$bClearly, it would seem fortuitous that very few ogres know how to read.$b$bClearly.', `CompleteEmote` = 1 WHERE `entry` = 1193;
        UPDATE `quest_template` SET `RequestItemsText` = 'Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight''s Hammer.$B$BHave you made any progress in ridding their presence?' WHERE `entry` = 1199;
        UPDATE `quest_template` SET `RequestItemsText` = 'Time is a precious commodity, $C.$B$BMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.$B$BState your business quickly or be on your way.' WHERE `entry` = 1200;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the infiltrators, $N?' WHERE `entry` = 1201;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1203;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1204;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1206;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1218;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1219;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1220;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you seen Mr. Ignatz? I sent him into the swamp some time ago and he hasn''t returned!' WHERE `entry` = 1222;
        UPDATE `quest_template` SET `RequestItemsText` = 'There is an angry spirit about you, $gbrother:sister;. What brings you to Kin''weelay?' WHERE `entry` = 1240;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1242;
        UPDATE `quest_template` SET `RequestItemsText` = 'Not too safe to be traveling about in the woods, $N. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don''t try and take anything on yourself. We''re not responsible for anything terrible that might happen to you.$B$BBut we both know you''re gonna ignore me and fight whatever comes out of the darkness anyway, don''t we? Haha, yeah, you adventurer types... all the same.', `CompleteEmote` = 1 WHERE `entry` = 1243;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1245;
        UPDATE `quest_template` SET `CompleteEmote` = 14 WHERE `entry` = 1246;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1251;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1252;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1253;
        UPDATE `quest_template` SET `RequestItemsText` = 'My research with the Mudrock tongues is progressing nicely. I trust your crab hunt goes well?' WHERE `entry` = 1258;
        UPDATE `quest_template` SET `RequestItemsText` = 'You traveled from Brackenwall Village in Dustwallow? How fares Nazeer, and how fare his efforts in the marsh?' WHERE `entry` = 1262;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N?' WHERE `entry` = 1265;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 1269;
        UPDATE `quest_template` SET `CompleteEmote` = 3 WHERE `entry` = 1276;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1319;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello again, $N. I hope you don''t mind the assistance, but we couldn''t have Hendel escaping, or worse, wind up dead.' WHERE `entry` = 1324;
        UPDATE `quest_template` SET `RequestItemsText` = 'A letter from the dwarven lands? I wonder who would call from so far to the north...$B$BPlease, let me see the order.', `CompleteEmote` = 1 WHERE `entry` = 1338;
        UPDATE `quest_template` SET `RequestItemsText` = 'I note that your task is unfinished, $N. Shall I inform Sharlindra of your ineptitude?' WHERE `entry` = 1361;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1364;
        UPDATE `quest_template` SET `RequestItemsText` = 'How is your collection of ears, $N? Large?' WHERE `entry` = 1366;
        UPDATE `quest_template` SET `RequestItemsText` = 'Leave! The Magram do not speak with the weak. We kill them!$B$BIf you want to speak with me, then show me you are strong. Return after you slay many Gelkis.' WHERE `entry` = 1367;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your two feet step on Gelkis earth. You are not welcome here!$B$BProve you seek friendship with the Gelkis. Kill Magram centaur. Return when the ground is wet with Magram blood.' WHERE `entry` = 1368;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is Khan Hratha dead? Do you have the key fragment?' WHERE `entry` = 1380;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have the charms? You showed the Kolkar they are weak?' WHERE `entry` = 1384;
        UPDATE `quest_template` SET `RequestItemsText` = 'You will go now, or the Magram will crush you! To be our friend, you must kill Gelkis.' WHERE `entry` = 1385;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you afraid of the Kolkar? Why do you not kill them? Maybe you forgot how to kill. Hurry and kill Kolkar before they are dead!' WHERE `entry` = 1386;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1387;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1389;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello! Don''t mind all the commotion, it''s just business as usual at Nethergarde Keep.$B$BYou have something for me?', `CompleteEmote` = 1 WHERE `entry` = 1395;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1398;
        UPDATE `quest_template` SET `RequestItemsText` = 'You returned. You have a report?' WHERE `entry` = 1420;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1421;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1423;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1425;
        UPDATE `quest_template` SET `RequestItemsText` = 'I was warned by a tauren companion that the satyr are not all they appear to be. He believes there is something more to them, that their evil is a twisting of their true nature. But I have not seen such things.$B$BI see only the ruthless slaughter of the weak and the corruption of those who seek dark power.$B$BI will continue in my duty of annihilating them until the Warchief directs me otherwise. Until then, I take no pity on them.' WHERE `entry` = 1434;
        UPDATE `quest_template` SET `RequestItemsText` = 'I fear Tyranis will attempt to learn the Burning Blade''s secrets and count himself among their kind if they allow it - he has always adored the power magic brings to those who are seduced by it.$B$BI''m not sure I could endure returning home to my family with news of Tyranis'' spirit flirting with such dangers. It''s a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that''s apprehensible.' WHERE `entry` = 1439;
        UPDATE `quest_template` SET `RequestItemsText` = 'I would be less trustful of one not on a holy path if they came asking about a Kor gem. But I trust your kind more than some of my kin. I do not judge your entire order based on the actions of just one of your fallen kind.' WHERE `entry` = 1442;
        UPDATE `quest_template` SET `RequestItemsText` = 'Once Jammal''an has been removed, I stand a chance of returning to my people.$b$bWith Jammal''an as their spiritual leader, the Atal''ai face certain destruction.' WHERE `entry` = 1446;
        UPDATE `quest_template` SET `RequestItemsText` = 'I didn''t mean anything by the comment ''bout you being a stupid $C. We''re friends, right? No hard feelings?', `CompleteEmote` = 11 WHERE `entry` = 1447;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!$B$BBut if I''m gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I''m gonna need me something a wee bit stronger. Hiccup!$B$BDon''t suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?$B$BHiccup!' WHERE `entry` = 1452;
        UPDATE `quest_template` SET `RequestItemsText` = 'Business is booming, $N, and I don''t have a lot of time for questions. If you''ve got business with the Reclaimers, then let''s hear it. If not, I''m gonna have to ask you to talk to one of me underlings - they''re adept enough at taking care of things ''round here.' WHERE `entry` = 1457;
        UPDATE `quest_template` SET `RequestItemsText` = 'I give you one in good faith. You already proved yourself once, but me tinkin'' you should be more careful in the future.' WHERE `entry` = 1463;
        UPDATE `quest_template` SET `RequestItemsText` = 'Speak to Telf Joolam for another Fire Sapta.' WHERE `entry` = 1464;
        UPDATE `quest_template` SET `RequestItemsText` = 'I didn''t even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.$B$BI wonder why they took up here, and how.' WHERE `entry` = 1466;
        UPDATE `quest_template` SET `OfferRewardText` = 'Um... hi.  My name is Randis, and I guess you''re looking after me?  You''re an adventurer, like my mom and dad were.  I''m happy to meet you.$B$BI hope we''ll have a lot of fun together.  I have some things I''d like to do, and the matron says you''ll be like a big $G brother : sister; to me during this week.  I''d like that a whole bunch, yes $G sir : ma''am;.' WHERE `entry` = 1468;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your power is little now, though I suspect already you sense the possibilities.$b$bEven the dead might feel alive, with that power coursing through us.' WHERE `entry` = 1470;
        UPDATE `quest_template` SET `RequestItemsText` = 'I expect to hear of your success, $N. Not meeting my expectations will be the least of your worries, however, should you fail.' WHERE `entry` = 1471;
        UPDATE `quest_template` SET `RequestItemsText` = 'Egalin was the teacher that taught me. With hardly a look, he was able to command the voidwalker he had summoned.$B$BWhen it came my turn to try, I was overconfident. Do not trifle with the powers that you wield, $N, they can consume even the vigilant.' WHERE `entry` = 1473;
        UPDATE `quest_template` SET `RequestItemsText` = 'Of the powers from beyond the void, the succubus is one of the most dangerous, as the weak are most easily wrapped around its fingers.$B$BRemember that now and in the future.' WHERE `entry` = 1474;
        UPDATE `quest_template` SET `RequestItemsText` = 'As dusk slowly descends upon my career I turn to you, $N, to help me in my final quest for the Explorers'' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.$B$BPride makes it hard for me to ask for your help in collecting the Atal''ai Tablets. But old age forces the necessity.$B$BPlease help me, $N. I want to retire from the Explorers'' League having completed their final bidding.' WHERE `entry` = 1475;
        UPDATE `quest_template` SET `RequestItemsText` = 'I have been pleasantly surprised by the speed of your progress so far, $N. Bring me the hearts and you will impress me once again.' WHERE `entry` = 1476;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 1479;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not bring me an incorrect scalp, $c. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.$B$BFate has already dealt me enough pain.' WHERE `entry` = 1481;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is important that you can control the beings that you summon through your magic. There are few enough interested in learning the ways of the $C that I would risk throwing your life away by teaching you something before you are ready.' WHERE `entry` = 1485;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, we, the Disciples of Naralex, need your help. Our numbers are dwindling with our master trapped in his twisted nightmare. We have not the forces necessary to deal with the corrupt creatures which now haunt these caverns.$b$bI beg of you, enter the caves and wage war on the deviate creatures!' WHERE `entry` = 1487;
        UPDATE `quest_template` SET `RequestItemsText` = 'Glory to the Horde, and death to our enemies, $N!$B$BThe demons in Desolace pose a greater threat than ever before. My hope of returning to the Warchief dwindles as more and more of the foul creatures seem to appear.$B$BI sometimes wish it was only the centaur we had to deal with.' WHERE `entry` = 1488;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your masters are fools to send you here, for I will never again be a Scourge slave!' WHERE `entry` = 1489;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the scales, $N? Unless you can withstand the attacks of the thunder lizards, you will not benefit from my instruction.' WHERE `entry` = 1498;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the Tablet of Verga, $N? If not, I do not wish to speak with you until you do.' WHERE `entry` = 1501;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have my steel bars?' WHERE `entry` = 1503;
        UPDATE `quest_template` SET `RequestItemsText` = 'The voidwalker is a powerful creature. I remember when it was I that was in your shoes, $N. Over the years, my own voidwalker has grown to fight me less, though I suspect that is only because it hopes I will let my guard down.$B$BRemember that, $N.' WHERE `entry` = 1504;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, what is it?' WHERE `entry` = 1511;
        UPDATE `quest_template` SET `RequestItemsText` = 'When I look upon a succubus, my heart begins to soar... But at the same time, I can almost sense my soul''s ebb, drifting away like the tides.$B$BBe wary, my friend.' WHERE `entry` = 1513;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.' WHERE `entry` = 1514;
        UPDATE `quest_template` SET `RequestItemsText` = 'Patience is earth''s greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.$B$BThe earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.$B$BOthers will be envious of your wisdom and hate you for their ignorance.' WHERE `entry` = 1516;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.$B$BIf you have the stone the earth gave to you, I will give you the totem it promised.$B$BIf not, then be gone with you until you have found your way.' WHERE `entry` = 1518;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetin''s, $N. You''ve found yerself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I''m sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.' WHERE `entry` = 1524;
        UPDATE `quest_template` SET `RequestItemsText` = 'The brazier stands about a third your height, and looks normal, save for the inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch.' WHERE `entry` = 1526;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the water yet, $N? Tales say the ruins were protected by large creatures of nature that do not care for visitors, but those could be myths to scare off the enemies of the night elves.$B$BRegardless, be careful.' WHERE `entry` = 1534;
        UPDATE `quest_template` SET `RequestItemsText` = 'I am just about prepared to send you on your other tasks. Have you filled the skin yet?$B$BI know how protective the quilboar can be. Even such a small water source is a vast hoard of wealth to them. They have great feasts when even the slightest rain comes to the Barrens. Water is sacred to their kind because it is so scarce. Do you understand?' WHERE `entry` = 1535;
        UPDATE `quest_template` SET `RequestItemsText` = 'The well remaining pure within the town reminds me of stories told to me when I was younger, $N. Even in times of great pain and sorrow one can find a sliver of hope, a small symbol to rally around. The orc people see Thrall this way. He survived against great odds and rose up to lead our people through his strength and example.$B$BI''m not sure any orc has suffered as much as he has, but at the same time, I''m not sure any orc is as strong as he is either.' WHERE `entry` = 1536;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 1558;
        UPDATE `quest_template` SET `RequestItemsText` = 'I have no time to chat. Do you have business with me?' WHERE `entry` = 1578;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find my gaffer jacks, $N? Without my gaffer jacks I can''t tune my stintle pegs!' WHERE `entry` = 1579;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find any electropellers? I''ll need them if I''m to continue my research on duck decoys...' WHERE `entry` = 1580;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Do you have the elixirs to trade?' WHERE `entry` = 1581;
        UPDATE `quest_template` SET `RequestItemsText` = 'Those feather charms the novices carry have some sort of magical power to them. It will be interesting to research them. I wouldn''t have expected it from the trolls.' WHERE `entry` = 1599;
        UPDATE `quest_template` SET `RequestItemsText` = 'I hope my John is having better luck in Ironforge. He so dislikes his trips there because it leaves the kids and me alone, but he knows it must be done. He''s so kind-hearted.$B$BSome years have been easier than others, but this one''s been rougher by far. It''s almost as though something in the air is signaling a huge change. Who knows though?' WHERE `entry` = 1644;
        UPDATE `quest_template` SET `RequestItemsText` = 'What with the influx of tradesmen here and throughout Azeroth, there''s a smaller supply of items we use to make clothes for the children of our orphanage. Helping me collect linen so my wife can make new clothes for them is very noble of you, $N. Thank you.$B$BHopefully, I''ll be able to return home to my wife soon.' WHERE `entry` = 1648;
        UPDATE `quest_template` SET `RequestItemsText` = 'The items you''re seeking will be difficult to acquire, but I can assure you, the weapon I will craft for you will be worth the effort.$B$BIt will be my finest work to date, and only a small payment for the service you''ve done me.' WHERE `entry` = 1654;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, young one? What can Kauth do for you?$B$BThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?' WHERE `entry` = 1656;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you delivered our "gift" to the people of Southshore?$B$B<Darkcaller Yanka laughs wickedly.>' WHERE `entry` = 1657;
        UPDATE `quest_template` SET `RequestItemsText` = 'I saw your fight with Bartleby. Nicely done! Did you get his mug?' WHERE `entry` = 1665;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you make the switch?' WHERE `entry` = 1679;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you entered Ironband''s Compound? Did you find the umbral ore?' WHERE `entry` = 1681;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you defeated the Shade of Elura, $N? And do you have the lost elunite ore?' WHERE `entry` = 1686;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 1687;
        UPDATE `quest_template` SET `RequestItemsText` = 'Even the older and wiser can be unmanned by the wiles of youth and beauty, $N. A piece of advice you would do well to remember throughout your life.' WHERE `entry` = 1688;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back so soon? I hope you were able to bring some goblin-style justice to those Wastewander Bandits and Thieves like I asked you to!' WHERE `entry` = 1690;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, were you able to take out those nomads like I asked? The Gadgetzan Water Company is developing plans based on your success here! Don''t let us down, now...' WHERE `entry` = 1691;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, young $C. How might my skills serve you?' WHERE `entry` = 1692;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, and well met. How might I be of service to you?' WHERE `entry` = 1700;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the scavenger hunt, $N? Do you have the materials?' WHERE `entry` = 1701;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello! Dry times, don''t you think?' WHERE `entry` = 1702;
        UPDATE `quest_template` SET `RequestItemsText` = 'Good day, or morning or evening. I can''t tell from way down here. So do you have business for me?' WHERE `entry` = 1704;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, do you have the burning blood and rock? I''ll need them to complete the armor.' WHERE `entry` = 1705;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1707;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello hello, $N! Do you have the searing coral? I can''t wait to get to work!' WHERE `entry` = 1708;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the shells, $N? They are quite strong, and can be rendered into a lacquer I will use to coat the links of my new mail armor.' WHERE `entry` = 1710;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the items, $N? Gathering them is the proof I need that you have the strength to face Cyclonian.' WHERE `entry` = 1712;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, I must have the whirlwind heart!' WHERE `entry` = 1713;
        UPDATE `quest_template` SET `RequestItemsText` = 'Was your search a success, $N?', `CompleteEmote` = 1 WHERE `entry` = 1738;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 1739;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yer back! I''m glad to see it, $N. My wounds are healed and I''m about ready to return to Helm''s Bed lake as soon as I c''n convince me wife that I''ll be fine.' WHERE `entry` = 1784;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is Henze safe, $N? Were you successful?$B$BBetween your skill with a weapon, and the power of the Light, I''d imagine Heroes'' Vigil is safe from any Defias threat, but that''s for the King and his advisors to say.', `CompleteEmote` = 1 WHERE `entry` = 1787;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes your search for the robes, $N? Have you created them yourself? Such personal touches I find make the imbuing of magic that much sweeter. It gives you a greater sense of accomplishment. But I understand if you choose the quicker path and have it made for you - there''s something to be said for such... ambition.', `CompleteEmote` = 1 WHERE `entry` = 1796;
        UPDATE `quest_template` SET `RequestItemsText` = 'And obviously not being a mage, I wonder if I can trust you at all. I can smell the power of the arcane on you, but you seem to have eluded the stank of corruption that comes so willingly with your kind.$B$BYes, a $C... a $C has come to ask for my help.$B$BWell, what is it I can do for you, $N?', `CompleteEmote` = 1 WHERE `entry` = 1799;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are we there yet?' WHERE `entry` = 1800;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did the rumors prove true, $N?', `CompleteEmote` = 1 WHERE `entry` = 1802;
        UPDATE `quest_template` SET `RequestItemsText` = 'It may be that you are chasing after fairy tales, $N, but truth can be found at the center of even the wildest rumors.' WHERE `entry` = 1803;
        UPDATE `quest_template` SET `RequestItemsText` = 'Haven''t seen you around these parts for a while. Have you found the tome and the rods?', `CompleteEmote` = 1 WHERE `entry` = 1804;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N? Of what service can I be to you?' WHERE `entry` = 1805;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your task is yet undone, $N. It is not wise for a $C to show fear...' WHERE `entry` = 1819;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the heirlooms, Sictor?' WHERE `entry` = 1821;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the antennae? If so then give them to me quickly, for twitching antennae do not twitch forever...' WHERE `entry` = 1824;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the items on my scroll, $N?' WHERE `entry` = 1838;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the horn? Is the matriarch free of pain?' WHERE `entry` = 1844;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m waiting for those shinbones, $N. They''ll make a nice frame for your leg guards.' WHERE `entry` = 1846;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it not vexing to have the subject of your desire within your grasp, but to have no way of getting to it?' WHERE `entry` = 1858;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the sample, $N? The flow of magic in Stormwind and Elwynn has been altered, and I must know if it is seeping into the water.' WHERE `entry` = 1861;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back again, $n?  If you have five more Wastewander water pouches, then I have a care package with your name on it!', `CompleteEmote` = 5 WHERE `entry` = 1878;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the gizmonitor? I must have it before its energy supply runs out!' WHERE `entry` = 1880;
        UPDATE `quest_template` SET `RequestItemsText` = 'You must hurry, $N. Destroy the ju-ju heaps!' WHERE `entry` = 1884;
