        UPDATE `quest_template` SET `RequestItemsText` = 'Well, look who it is! Took your sweet time getting here, I see. Let''s hope this isn''t a waste of my time! You''ll not get paid unless you have everything I asked for. And trust me on this - we''ll be double and triple checking everything!' WHERE `entry` = 2340;
