        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, gentle $C. The day has been long and not a single experiment successful...I hope you bring good news to me.' WHERE `entry` = 2933;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you know the spider god''s name?' WHERE `entry` = 2936;
