        UPDATE `quest_template` SET `RequestItemsText` = 'Remember, $N - we must be tolerant yet rigid in our beliefs!' WHERE `entry` = 5251;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 5262;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 5263;
        UPDATE `quest_template` SET `RequestItemsText` = 'Compassion is what separates us from the animals, $N. Remember that...' WHERE `entry` = 5282;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, ain''t nothing like a good forge tan. Ye can tell who''s got the really good tans by their apron lines.' WHERE `entry` = 5283;
        UPDATE `quest_template` SET `RequestItemsText` = '<Ironus is busy stacking gold coins into neat little piles.>' WHERE `entry` = 5284;
        UPDATE `quest_template` SET `RequestItemsText` = 'For the glory of the Horde!' WHERE `entry` = 5302;
        UPDATE `quest_template` SET `CompleteEmote` = 25 WHERE `entry` = 5341;
        UPDATE `quest_template` SET `RequestItemsText` = 'Bow your head in my presence, $R. I am a noble, after all, and you are a copperless peasant.' WHERE `entry` = 5343;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 5344;
        UPDATE `quest_template` SET `RequestItemsText` = 'What news have you, $C! Ah - a message from my brother you say? Well then, hand over the report!' WHERE `entry` = 5361;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Butcher must be stopped!' WHERE `entry` = 5382;
        UPDATE `quest_template` SET `RequestItemsText` = 'Be wary, Kirtonos is a seasoned fighter.' WHERE `entry` = 5384;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 5385;
        UPDATE `quest_template` SET `RequestItemsText` = 'A Minion''s Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term "weaker" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.$B$BThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I''m happy to do, provided you have earned enough scourgestones!' WHERE `entry` = 5402;
        UPDATE `quest_template` SET `RequestItemsText` = 'A Corruptor''s Scourgestone is the insignia of the Scourge''s overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!$B$BOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one these insignia.  Use caution in acquiring one, $N - such powerful beings are not to be trifled with.' WHERE `entry` = 5404;
        UPDATE `quest_template` SET `RequestItemsText` = 'A Corruptor''s Scourgestone is the insignia of the Scourge''s overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!$B$BOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one these insignia.  Use caution in acquiring one, $N - such powerful beings are not to be trifled with.' WHERE `entry` = 5406;
        UPDATE `quest_template` SET `RequestItemsText` = 'An Invader''s Scourgestone is the insignia of the Scourge''s elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.$B$BThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.' WHERE `entry` = 5407;
        UPDATE `quest_template` SET `RequestItemsText` = 'A Minion''s Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term "weaker" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.$B$BThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I''m happy to do, provided you have earned enough scourgestones!' WHERE `entry` = 5408;
