        UPDATE `quest_template` SET `IncompleteEmote` = 6 WHERE `entry` = 6004;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 6021;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you crying? If this is too ''tedious'' for you, ''hero,'' I recommend that you head back to the Dark Lady and inform her of the horrible mistreatment you received at my farmstead.$b$bNow get out of my sight!' WHERE `entry` = 6022;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you found them yet, $N? With the two of them taken care of, I can proceed to enter Hearthglen to take a closer look at their setup. I can''t do it without your help. Please, find Radley and Durgen for me.' WHERE `entry` = 6023;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s a dangerous task, $n. I envy your courage.' WHERE `entry` = 6025;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, $N! It''s good to see you again. Do you have the Book of the Ancients?$b$b' WHERE `entry` = 6027;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, $N. On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp. I might also have some work for you...', `CompleteEmote` = 1 WHERE `entry` = 6028;
        UPDATE `quest_template` SET `RequestItemsText` = 'May the Light guide you in these troubling times, $C. What brings you here to this beacon of hope in the middle of darkness and despair?', `CompleteEmote` = 1 WHERE `entry` = 6030;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 6032;
        UPDATE `quest_template` SET `RequestItemsText` = 'It could have been worse. I could have had you collecting bat guano.$B$B<Nathanos stares at you in contemplation.>$B$BHrm... Hey! Wait a minute. Where are you going?' WHERE `entry` = 6042;
        UPDATE `quest_template` SET `RequestItemsText` = 'Practice your skills, $N. Tame the adult plainstrider.' WHERE `entry` = 6061;
        UPDATE `quest_template` SET `RequestItemsText` = 'Good luck, young $C.' WHERE `entry` = 6062;
        UPDATE `quest_template` SET `RequestItemsText` = 'You will learn, $N, and one day you will be a great $C.' WHERE `entry` = 6063;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t worry, lass! You''ll get ta try a few before you''ll need to decide on just one.' WHERE `entry` = 6064;
        UPDATE `quest_template` SET `RequestItemsText` = 'You need to practice in order to gain the skills you need to effectively control your pet. Have you tamed a surf crawler?' WHERE `entry` = 6083;
        UPDATE `quest_template` SET `RequestItemsText` = 'What do you think of the snow leopard, $N?' WHERE `entry` = 6084;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you tamed the ice claw bear yet?' WHERE `entry` = 6085;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you found a prairie stalker?' WHERE `entry` = 6087;
        UPDATE `quest_template` SET `RequestItemsText` = 'You will soon be ready, $N.' WHERE `entry` = 6088;
        UPDATE `quest_template` SET `RequestItemsText` = 'Understanding the balance between nature and oneself is a way of life for every $R.' WHERE `entry` = 6101;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re the one that the Cenarion Circle in Moonglade sent? That''s wonderful! We''ve quite the crisis our hands here regarding the poor deer, and we''re happy for all the help we can get.$B$BDo you have the sample of water that Dendrite Starblaze said you''d have? He notified me that you''d draw one so we could work on a cure together...' WHERE `entry` = 6122;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you got the reagents I need to make the salve? The deer aren''t getting any better on their own, so we better hurry to help them out!' WHERE `entry` = 6123;
        UPDATE `quest_template` SET `RequestItemsText` = 'You are the one that the Cenarion Circle in Moonglade sent, yes? This is most fortuitous for us! We are stymied in our effort to bring balance to the sickly gazelles that wander the northern Barrens; we''re happy for all the help we can get.$B$BDo you have the sample of water that Dendrite Starblaze said you''d have? He notified me that you''d draw one so we could work on a cure together...' WHERE `entry` = 6127;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you got the reagents I need to make the salve? The gazelle aren''t getting any better on their own, so we better not tarry in our effort to save them!' WHERE `entry` = 6128;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed what was asked of you by Tonga Runetotem at the Crossroads? Your work is not complete unless it is.' WHERE `entry` = 6129;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 6134;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have I told you lately that I hate you?', `IncompleteEmote` = 6 WHERE `entry` = 6136;
        UPDATE `quest_template` SET `RequestItemsText` = 'What is your status, $N?' WHERE `entry` = 6148;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the beasts head yet, $N? It will pay for its crimes. I don''t care if it''s corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!' WHERE `entry` = 6162;
        UPDATE `quest_template` SET `RequestItemsText` = 'After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The bastard...' WHERE `entry` = 6163;
        UPDATE `quest_template` SET `RequestItemsText` = 'You look like you''re in a hurry. Well, then you came to the right place!', `CompleteEmote` = 1 WHERE `entry` = 6181;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 6185;
        UPDATE `quest_template` SET `RequestItemsText` = '<Highlord Bolvar Fordragon is lost in thought.>' WHERE `entry` = 6187;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is that sweat on your brow, lad? You''ve been running too much. Next time, take a gryphon!' WHERE `entry` = 6261;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve been traveling, eh? Have you been anywhere interesting?', `CompleteEmote` = 1 WHERE `entry` = 6281;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not be weary of Charred Vale; many evil creatures reside in those hills. Stay strong $N, and you shall prevail over this threat to our people. Go now and strike hard - our children shall never know of the evil of what was.' WHERE `entry` = 6282;
        UPDATE `quest_template` SET `RequestItemsText` = 'Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.$b$bThe bloodfuries will be helpless with out... surely we can vanquish them forever!' WHERE `entry` = 6283;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re back from Stormwind? Did Osric send the armor?', `CompleteEmote` = 1 WHERE `entry` = 6285;
