        UPDATE `quest_template` SET `OfferRewardText` = 'Good work, $N.  These weapons will ensure our Deathguards don''t get caught unprepared.$B$BYou have done a valuable service for our Dark Lady.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 66, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 6324;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 6341;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6342;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6343;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6344;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6361;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, a new bundle of hides.  I will get to work on these immediately!$B$BThank you, $gbrother:sister;.  You have done me a great service.  Here are some coins to pay for your time and travel costs.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6362;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 6363;
        UPDATE `quest_template` SET `RequestItemsText` = 'You need to get somewhere fast? Then you''re talking to the right orc!' WHERE `entry` = 6365;
        UPDATE `quest_template` SET `RequestItemsText` = 'These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.$b$bHave you planted all of the Gaea seeds?' WHERE `entry` = 6381;
        UPDATE `quest_template` SET `RequestItemsText` = 'Something smells good! You don''t have raw meat on you, do you?' WHERE `entry` = 6384;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you returned from Orgrimmar? Did Gryshka like the meat I sent her?' WHERE `entry` = 6386;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6387;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6388;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 6389;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you done it, $N? Have you released the termites in the lumber mill?$B$BIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!' WHERE `entry` = 6390;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, the latest list of Gremlock''s best pupils.  I have a batch of honorary cleavers ready to go.  I just need to engrave the names of the students...', `RequestItemsText` = 'What can I do for you, $gsir:my lady;?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6391;
        UPDATE `quest_template` SET `OfferRewardText` = 'You brought the cleaver.  Great!  I''ll get these to my students.  I''m sure they''re eager to use them on some fresh boar meat.$B$BThank you for your help, $N.  I am in your debt, but I hope this money will at least cover your travel costs.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 6392;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you entered the Burning Blade Coven, $N? Did you find my pick?' WHERE `entry` = 6394;
        UPDATE `quest_template` SET `RequestItemsText` = 'We must respect our dead, $N. It is one of the ways in which we differ from the Scourge...' WHERE `entry` = 6395;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hey mon, have you slain the hairy blood feeders? I fear none here in Stonetalon but I don''t go walking around here at night... if you know what I mean mon!$b$bAs long as I stay off there dinner plate then all is well.$b$bGood luck to you, $C!' WHERE `entry` = 6461;
        UPDATE `quest_template` SET `CompleteEmote` = 14 WHERE `entry` = 6462;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you seen my brother Ruul? He walked into the forest days ago and has not returned...' WHERE `entry` = 6482;
        UPDATE `quest_template` SET `RequestItemsText` = 'The flow of time does not stop or slow, $R. While my life is eternal, yours is not. Waste not the time that you have...' WHERE `entry` = 6502;
        UPDATE `quest_template` SET `RequestItemsText` = 'I await reports of your outrunner kills, $N.' WHERE `entry` = 6503;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you found the Ambassador, $N? Is he dead?$B$BWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.$B$BThe only optimistic sign from the events you''ve told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.' WHERE `entry` = 6521;
        UPDATE `quest_template` SET `RequestItemsText` = 'Torek was sent on a mission against Silverwing Outpost. Was the attack successful?' WHERE `entry` = 6544;
        UPDATE `quest_template` SET `RequestItemsText` = 'So you''re here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.$B$BYou''d best learn fast if you expect to keep up here. The threat of the naga grows, $N. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.$B$BBut if you''d like to pitch in with that effort, speak with one of the others here at the outpost.' WHERE `entry` = 6545;
        UPDATE `quest_template` SET `RequestItemsText` = 'Much danger lies along this path, $N. You''d do best to remember this while traveling in these lands. The threat of the alliance is quite near.$B$BWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale. I have also discovered that the naga have taken over a large area of the land of Azshara.$B$BIt''s good to see that we are still bolstering our numbers -- be ready for what lies ahead, $N.' WHERE `entry` = 6546;
        UPDATE `quest_template` SET `RequestItemsText` = 'Keep an eye out, $R. The elves are often hiding in the shadows...$B$BWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.$B$BI assume you have my next orders from Kadrak?' WHERE `entry` = 6547;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you killed them yet?' WHERE `entry` = 6548;
        UPDATE `quest_template` SET `RequestItemsText` = 'May the Earthmother be with you, $N.$B$BPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.' WHERE `entry` = 6561;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 6563;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is not often I see one of the Horde in these parts of Lordaeron. What is it that you have for Myranda?' WHERE `entry` = 6568;
        UPDATE `quest_template` SET `RequestItemsText` = 'The eyes of that which we wish to mimic are the most important ingredient of any illusion, $N.$B$B<Myranda points to a bag almost overflowing with eyeballs labeled ''Scarlet Crusade.''>$B$B<Myranda laughs.>', `CompleteEmote` = 11 WHERE `entry` = 6569;
        UPDATE `quest_template` SET `RequestItemsText` = 'I hope you can come through with the supplies!' WHERE `entry` = 6571;
        UPDATE `quest_template` SET `RequestItemsText` = 'Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.$B$B..But what sort of payment do you have for me? You can''t just take them, you know! My time isn''t cheap!$B$BWhat I really need is a good gun to carry with me on my travels. A girl''s gotta protect herself, you know? There''s a gun I really like that I''m sure an engineer would have no problem making.$B$BSo, if you bring me a deadly blunderbuss, I''ll give you the saw blade shipment. Do we have a deal?' WHERE `entry` = 6581;
        UPDATE `quest_template` SET `RequestItemsText` = '<Emberstrife hisses.>' WHERE `entry` = 6582;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not return here until you have bathed in the blood of our enemies and drank in their suffering.' WHERE `entry` = 6583;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ironically, whelp, time is of the essencccce.' WHERE `entry` = 6584;
        UPDATE `quest_template` SET `RequestItemsText` = 'Changesss... I sense them taking place in you, whelp. Pass this test and only ceremony remains.' WHERE `entry` = 6585;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not panic, $N!' WHERE `entry` = 6601;
        UPDATE `quest_template` SET `RequestItemsText` = 'I don''t think I need to tell you that Drakkisath is not to be taken lightly.$B$BI let the thousands dead by his hand do the talking.' WHERE `entry` = 6602;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 6607;
        UPDATE `quest_template` SET `OfferRewardText` = 'You are in for a special treat, $N. Watch and learn!$B$B<Dirge begins to prepare clamlette surprise.>', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 6610;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you defeat Chief Murgut, $N? Did you retrieve his Foulweald Totem?' WHERE `entry` = 6621;
        UPDATE `quest_template` SET `RequestItemsText` = 'Miraculous work, doctor. Simply miraculous.' WHERE `entry` = 6622;
        UPDATE `quest_template` SET `RequestItemsText` = 'Miraculous work, doctor. Simply miraculous.' WHERE `entry` = 6624;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the hunt, $N? Seeing just this small sample of this diplomat''s power here removes any doubt I had that the Scourge are one of the greatest threats this world has ever seen.' WHERE `entry` = 6626;
        UPDATE `quest_template` SET `RequestItemsText` = 'Life is full of questions, $C. You will never be able to answer all of them, but with some time and study, perhaps you will become a little more knowledgeable.' WHERE `entry` = 6627;
        UPDATE `quest_template` SET `RequestItemsText` = 'There is only one rule I feel you must know if you wish to survive in this world: the more you know, the more you''ll see.$b$bIf you study, if you observe, then you will begin to see things in the world that no other $r will see.' WHERE `entry` = 6628;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you killed Grundig Darkcloud and his personal band of Brutes?' WHERE `entry` = 6629;
        UPDATE `quest_template` SET `RequestItemsText` = 'Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.$B$BFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.' WHERE `entry` = 6642;
        UPDATE `quest_template` SET `RequestItemsText` = 'Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.$B$BMany of the Brotherhood have been lost in their search for Fiery Cores.$B$BOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.' WHERE `entry` = 6643;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Thorium Brotherhood sympathizes with your plight, $r. This is why Lokthos has been empowered to bargain.$B$BOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.' WHERE `entry` = 6644;
        UPDATE `quest_template` SET `RequestItemsText` = 'Many of the sacred recipes require the skin from Ragnaros'' chosen pets.$B$BOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.' WHERE `entry` = 6645;
        UPDATE `quest_template` SET `RequestItemsText` = 'The tears of the Fire Lord are a rare find indeed.$B$BOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood. \n' WHERE `entry` = 6646;
        UPDATE `quest_template` SET `RequestItemsText` = '<Nipsy puts his index finger through one of the air holes in the carton.>$b$bAlive and kicking... and just in time!' WHERE `entry` = 6662;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you meet Milton?<Fahrad laughs.>' WHERE `entry` = 6681;
        UPDATE `quest_template` SET `RequestItemsText` = 'We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It''s impossible to kill them off fast enough to have any noticeable impact on their population!$B$BWe''ve found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is ''dealt'' with internally.$B$BPick their pockets clean and turn the emblems in to me or one of the other guards.$B$BStart at Durnholde, south of here.' WHERE `entry` = 6701;
        UPDATE `quest_template` SET `RequestItemsText` = 'I need more armor scraps, $N! Do you have any?' WHERE `entry` = 6741;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, we need more armor scraps to supply our troops!' WHERE `entry` = 6781;
        UPDATE `quest_template` SET `RequestItemsText` = 'I come from Thunder Bluff, $r. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.$b$bBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.$b$bVictory will be assured when the elemental lord is loosed upon the Stormpike army.' WHERE `entry` = 6801;
        UPDATE `quest_template` SET `RequestItemsText` = 'Cowardice is not a thing we hold in regard, $c.  Go to Silithus and prove your bravery.' WHERE `entry` = 6805;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the Eye, $C?  Do you have the strength to enter Blackrock Spire?' WHERE `entry` = 6821;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your success in the Molten Core awaits, $N.' WHERE `entry` = 6822;
        UPDATE `quest_template` SET `RequestItemsText` = 'We must prepare the new fleet of War Riders, $r! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.$b$bI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!' WHERE `entry` = 6825;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve worked hard, $n, but we have only just begun!$b$bMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!$b$bMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.$b$bMake haste, soldier!' WHERE `entry` = 6826;
        UPDATE `quest_template` SET `RequestItemsText` = 'I was locked up in a dwarven hellhole for days. You better believe I want revenge!$b$bWe must plan carefully.$b$bFirst, my war riders need targets to gun for - high priority targets. I''m going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You''ve definitely got your work cut out for you.' WHERE `entry` = 6827;
        UPDATE `quest_template` SET `RequestItemsText` = 'Why, hello there! Hrmm...$b$bLet me be a little honest with you, friend... you smell a bit ripe. Whiffy, one might say. Now I''m not making a personal assailment of your being. I''m just saying... in the future, you may want to freshen up a little after coming in from the field. It will make those first impressions a little more positively impressionable!$b$bAnyhoo... what can I do for you?' WHERE `entry` = 6844;
        UPDATE `quest_template` SET `RequestItemsText` = 'My troops are supplied and ready to assault.  We just need orders from Noreg Stormpike and I''ll send them into the fray!' WHERE `entry` = 6846;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.$b$bThe damage has grown too great for the Circle to control! Ivus must be called to our aid.$b$bThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, $n!' WHERE `entry` = 6881;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 6921;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, hello again $N.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?' WHERE `entry` = 6922;
        UPDATE `quest_template` SET `RequestItemsText` = 'The elite Frostwolf units that guard the lines must be dealt with, soldier! I''m tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I''ll deploy the air strike.' WHERE `entry` = 6941;
        UPDATE `quest_template` SET `RequestItemsText` = 'My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.$b$bThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.$b$bOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!' WHERE `entry` = 6942;
        UPDATE `quest_template` SET `RequestItemsText` = 'Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.$B$BReturn to the battlefield and strike at the heart of the Frostwolf''s command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!' WHERE `entry` = 6943;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to the Coldtooth mine, $N? Do you have the supplies I asked for?' WHERE `entry` = 6982;
        UPDATE `quest_template` SET `CompleteEmote` = 5 WHERE `entry` = 6983;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you enter the Irondeep mine, $N? Did you raid its supplies?' WHERE `entry` = 6985;
        UPDATE `quest_template` SET `RequestItemsText` = 'Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!' WHERE `entry` = 7001;
        UPDATE `quest_template` SET `RequestItemsText` = 'Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won''t do something as disappointing as explode on the user.$B$BOh, I mean for the zappers other than the one I gave you.  Absolutely!', `CompleteEmote` = 6 WHERE `entry` = 7003;
        UPDATE `quest_template` SET `RequestItemsText` = 'Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!' WHERE `entry` = 7027;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t ask questions!$B$BYou have my request.', `CompleteEmote` = 25 WHERE `entry` = 7028;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you wish to restart the ritual, please abandon our first attempt and then speak to me again.' WHERE `entry` = 7046;
        UPDATE `quest_template` SET `RequestItemsText` = 'I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?' WHERE `entry` = 7061;
        UPDATE `quest_template` SET `RequestItemsText` = 'I feel the weight of imposing my plea on the mortal races, but we are left with no other options. The races of Azeroth have proven without a doubt they can overcome such things when they work together, so it is to them I ask for help.$B$BI only hope it is enough.$B$BZaetar, brother to Remulos, brought many pains to this world, and ultimately it caused his own death. There is a lesson there to all of us if we are wise enough to see it.' WHERE `entry` = 7065;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have the scent of corruption on you, $N... much like many adventurers these days. But something about you is different. Is there something you''ve come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.$B$BPlease, I implore you, tell me why you''ve sought an audience with me.', `CompleteEmote` = 1 WHERE `entry` = 7066;
        UPDATE `quest_template` SET `RequestItemsText` = 'You find the crystals yet? Rituals of power, spells of great strength - those shadowshards maybe very helpful in all kind of arcane magics.' WHERE `entry` = 7068;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you have not yet assaulted a graveyard. Return to me when this task is complete!' WHERE `entry` = 7081;
        UPDATE `quest_template` SET `RequestItemsText` = 'Attack a graveyard held by the Alliance!' WHERE `entry` = 7082;
        UPDATE `quest_template` SET `RequestItemsText` = 'You haven''t yet assaulted a bunker, $N! Are you waiting for others to claim your glory?' WHERE `entry` = 7101;
        UPDATE `quest_template` SET `RequestItemsText` = 'You haven''t yet assaulted a tower, $N! What are you waiting for?' WHERE `entry` = 7102;
        UPDATE `quest_template` SET `RequestItemsText` = 'You haven''t captured the mine yet, $N!$B$BAfter we control a mine, it will be much easier to gather minerals and supplies from it.' WHERE `entry` = 7122;
        UPDATE `quest_template` SET `RequestItemsText` = 'You haven''t yet captured a mine, $N! Find one that we do not control and defeat it''s leader! ' WHERE `entry` = 7124;
        UPDATE `quest_template` SET `RequestItemsText` = 'Go, $N.  Go to Alterac Valley and defeat the orc general!', `IncompleteEmote` = 6 WHERE `entry` = 7141;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the hunting, $N. Do you have any armor scraps for me?' WHERE `entry` = 7224;
        UPDATE `quest_template` SET `RequestItemsText` = 'How it must pain him to remain as one of the living while his beloved brother has ascended to perfection.' WHERE `entry` = 7281;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is with heavy heart that I give such an order, soldier.' WHERE `entry` = 7282;
        UPDATE `quest_template` SET `RequestItemsText` = 'Anything I would care to hear?' WHERE `entry` = 7301;
        UPDATE `quest_template` SET `RequestItemsText` = 'Status of the hunt, soldier?' WHERE `entry` = 7302;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 7321;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, $r. I am Kolark, Bounty Hunter from Thunderbluff. Much of the world I have traveled and much I have seen.$B$BMy journeys across the South Seas led to the discovery of these wonderous thorium headed arrows. Alas, I have an endless supply of the arrows but have exhausted my supply of shells. Bah, no self respecting Tauren would ever be caught dead using a flimsy bow. The arrows are useless!$B$BI will offer a trade: An even exchange of thorium shells for my thorium headed arrows. Deal?', `CompleteEmote` = 6 WHERE `entry` = 7341;
        UPDATE `quest_template` SET `RequestItemsText` = 'Can you believe this rubbish?! The last shipment of ammunition from Kharanos was botched! All we have for ammo now are these flimsy, good for nothing arrows! What in the world am I going to do with 500,000 thorium headed arrows?$b$bI''ll tell you what, kid. If you can bring me thorium shells, I''ll trade you thorium headed arrows - straight up! Deal?' WHERE `entry` = 7342;
        UPDATE `quest_template` SET `RequestItemsText` = 'They seek to exterminate us? It is they who shall be exterminated.' WHERE `entry` = 7361;
        UPDATE `quest_template` SET `RequestItemsText` = 'I don''t care where the hair comes from, $R.' WHERE `entry` = 7362;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, it is true. My brother is a human. Shameful... A stain upon my nearly immaculate record.' WHERE `entry` = 7363;
        UPDATE `quest_template` SET `RequestItemsText` = 'Benedictus! I am but a speck in the shadow of his grandeur. Praise him!' WHERE `entry` = 7366;
        UPDATE `quest_template` SET `OfferRewardText` = 'Along with the druids, the Oracle Tree has been carefully monitoring the growth of Teldrassil. Our observations have been disheartening, but all is not without hope.$B$BThe tree is indeed recovering since its blessing, but the growth is still somehow stunted... hindered.$B$BWe suspect some portion of the corruption remains within the tree, waiting to be cleansed. We simply need to find it.', `OfferRewardEmote1` = 1 WHERE `entry` = 7383;
        UPDATE `quest_template` SET `RequestItemsText` = 'I deal in wholesale irony, soldier.' WHERE `entry` = 7401;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s called the Gordok Shackle Key - well, that''s what these "tons o'' fun" keep calling it. I think any of the ogres might have it, but I''m not sure if any specific ones do. Maybe the guards have a better chance of having one...$b$bWhat am I talking about - you have it already, don''t you?! Is that it there??!' WHERE `entry` = 7429;
        UPDATE `quest_template` SET `RequestItemsText` = 'My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.' WHERE `entry` = 7481;
        UPDATE `quest_template` SET `RequestItemsText` = 'My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.' WHERE `entry` = 7482;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 7489;
        UPDATE `quest_template` SET `RequestItemsText` = '<Thrall''s stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>' WHERE `entry` = 7490;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7493;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7495;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7497;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, one of our greatest compilations. This one has been missing for ages.' WHERE `entry` = 7507;
        UPDATE `quest_template` SET `RequestItemsText` = 'Excellent, let us begin...' WHERE `entry` = 7508;
        UPDATE `quest_template` SET `RequestItemsText` = 'Perhaps one day, another will wield the prismatic blade.' WHERE `entry` = 7509;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have something for me?  It''s not a big, juicy spider, is it?  Or maybe a roach?  I hope it''s still alive... I so love chewing on them when they''re still alive...' WHERE `entry` = 7564;
        UPDATE `quest_template` SET `RequestItemsText` = 'Only the blood of Wildspawn satyr will suffice.' WHERE `entry` = 7581;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hrm? Well?' WHERE `entry` = 7583;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t tell anyone this but Niby is daft.', `CompleteEmote` = 1 WHERE `entry` = 7602;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get lost?', `CompleteEmote` = 1 WHERE `entry` = 7603;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to Jaedenar, $N? Did you get the stardust from Lord Banehollow?' WHERE `entry` = 7625;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have those elixirs, $N? Mor''zul told me you need a Bell of Dethmoora, and making one of those takes a lot of shadow power!' WHERE `entry` = 7626;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Wheel of the Black March isn''t easy to make, and takes a lot of materials. Have you gathered them yet?' WHERE `entry` = 7627;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you bring the dragonscales, $N? I don''t want to start on the candle until I have them... or I might blow up the whole camp!' WHERE `entry` = 7628;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you been to the Scholomance, $N? Has the imp yet infused the parchment with the stardust?' WHERE `entry` = 7629;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the arcanite, $N? Once I have it I can make you the black lodestone.' WHERE `entry` = 7630;
        UPDATE `quest_template` SET `RequestItemsText` = '<Vartrus groans.>' WHERE `entry` = 7632;
        UPDATE `quest_template` SET `RequestItemsText` = 'I am certain that you will have little difficulty in finding and slaying a black dragon, $N. Do not waste my time with idle chatter.' WHERE `entry` = 7635;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not be fooled by their disguises!' WHERE `entry` = 7636;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings, noble $C! I have prepared my trusted censer with the freshest of incense and blessed it thrice for your use. Your donation will help us in Ironforge not only create a new censer, but also to bolster sagging reserves of food for our needy.' WHERE `entry` = 7637;
        UPDATE `quest_template` SET `RequestItemsText` = 'Welcome back, $N. Have you acquired the exorcism censer?' WHERE `entry` = 7639;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is good to see you again $N. Is your work done in Terrordale?' WHERE `entry` = 7640;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, $C. I won''t be able to finish your barding without the things I mentioned. Have you gotten everything together?' WHERE `entry` = 7642;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Ancient Equine Spirit looks at you expectantly, as though it wants something from you.' WHERE `entry` = 7643;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you''re back! Were you able to successfully deal with Merideth Carlson and Tendris Warpwood?  Honestly, I''m not sure which one is a greater threat at times...' WHERE `entry` = 7644;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have come so very far, $N. Your final act of worldly-item sacrifice will be the genesis for one of your greatest accomplishments. I can feel it in the very fiber of my being!' WHERE `entry` = 7646;
        UPDATE `quest_template` SET `RequestItemsText` = 'The spirit of the fallen charger looks upon you with a mournful gaze. Sad, almost hollow eyes look at you as though all hope was lost to it.' WHERE `entry` = 7647;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re progressing along nicely, $N. Once you have made your barding, you''ll be well on your way to the next task.' WHERE `entry` = 7648;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7650;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7654;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7655;
        UPDATE `quest_template` SET `RequestItemsText` = 'For the chest piece plans, I''ll be needin'' 30 thorium bars.$B$B$BOh boy, there you go again. Are you gonna be runnin'' to yer blue Gods, askin'' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life''s fair.' WHERE `entry` = 7656;
        UPDATE `quest_template` SET `RequestItemsText` = 'Just hand over 25 thorium bars and the helm plans are yers.' WHERE `entry` = 7657;
        UPDATE `quest_template` SET `RequestItemsText` = 'Just hand over 30 thorium bars and the leg plans are yers.$B$BI know, I''m driving you into bankruptcy! I''ve heard it all before so you can save your sob story, weakling.' WHERE `entry` = 7658;
        UPDATE `quest_template` SET `RequestItemsText` = 'For the shoulder plans, I''ll be needin'' 10 thorium bars.' WHERE `entry` = 7659;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you bring me your old fast wolf, I will trade it in for one from the new pack.   The new wolf will be just as fast as your old one, but have a different look to it.   You can look at the swift wolves we already have around the yard here to see what it will look like.' WHERE `entry` = 7660;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you bring me your old fast wolf, I will trade it in for one from the new pack.   The new wolf will be just as fast as your old one, but have a different look to it.   You can look at the swift wolves we already have around the yard here to see what it will look like.' WHERE `entry` = 7661;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you bring me your aging kodo, I will trade it in for one from the new herd.   The new kodo will be just as fast as your old one, but have a different look to it.   You can look at the great kodos we already have around the yard here to see what you will have to choose from.' WHERE `entry` = 7662;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you bring me your aging kodo, I will trade it in for one from the new herd.   The new kodo will be just as fast as your old one, but have a different look to it.   You can look at the great kodos we already have around the yard here to see what you will have to choose from.' WHERE `entry` = 7663;
        UPDATE `quest_template` SET `RequestItemsText` = 'You bring me your old raptor, I give you new one with freshly sharpened claws!  The new raptor will be just as fast as your old one, but with a new look to him.   You can look at the swift raptors here to see what you will have to choose from.' WHERE `entry` = 7664;
        UPDATE `quest_template` SET `RequestItemsText` = 'You bring me your old raptor, I give you new one with freshly sharpened claws!  The new raptor will be just as fast as your old one, but with a new look to him.   You can look at the swift raptors here to see what you will have to choose from.' WHERE `entry` = 7665;
        UPDATE `quest_template` SET `RequestItemsText` = 'I feel awkward asking for material assistance, but my divination scryer - the device I hope to finish - requires one of each. If you cannot help me, I''d certainly understand.' WHERE `entry` = 7667;
        UPDATE `quest_template` SET `CompleteEmote` = 34 WHERE `entry` = 7701;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 7721;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 7722;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did ye pound ''em?' WHERE `entry` = 7723;
        UPDATE `quest_template` SET `RequestItemsText` = 'Was he right? Does it come out their rumps?' WHERE `entry` = 7724;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ah, the fruits of research and utilization in the form of sweet, sweet residue.  Well, that is to say, I don''t taste it or anything when I study it.$B$BMuch.', `CompleteEmote` = 6 WHERE `entry` = 7725;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 7726;
        UPDATE `quest_template` SET `RequestItemsText` = '<Hansel is busily rubbing his bunions.>$B$BDon''t just stand there, grab some oil and a luffa and get to scrubbin'' these bunions.$B$BYe don''t have a luffa? Well then! Perhaps it''s time I sent you out to find a luffa?$B$BHey, where are ye goin''?' WHERE `entry` = 7727;
        UPDATE `quest_template` SET `RequestItemsText` = 'We''re gonna need to weigh you with and without clothes to be sure.' WHERE `entry` = 7729;
        UPDATE `quest_template` SET `RequestItemsText` = 'If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!$B$BImagine that!' WHERE `entry` = 7733;
        UPDATE `quest_template` SET `RequestItemsText` = 'If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!$B$BImagine that!', `CompleteEmote` = 5 WHERE `entry` = 7734;
        UPDATE `quest_template` SET `RequestItemsText` = 'Let''s not waste more of my precious time with jibber jabber, $r. It''s time to focus on replenishing our dwindling fiery flux supply.$B$BWhat I''m gonna need from you is the following:$B$B*Incendosaur scales.$B$B*Kingsblood.$B$B*Coal.$B$BI''ll take all that you can offer!$B$BAnd you''ll do it fast if you wanna get in good with the Brotherhood.' WHERE `entry` = 7736;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve worked your way up through the Brotherhood''s corporate hierarchy, $r. We have begun to look favorably upon you. Quite an accomplishment!$B$BIf you''re interested in more work and earning more respect amongst us, listen up.$B$BWe can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths.$B$BBring me all the Dark Iron residue you find!' WHERE `entry` = 7737;
        UPDATE `quest_template` SET `RequestItemsText` = '<Demitrian cowers in your presence.>' WHERE `entry` = 7787;
        UPDATE `quest_template` SET `RequestItemsText` = 'A benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.' WHERE `entry` = 7793;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.' WHERE `entry` = 7794;
        UPDATE `quest_template` SET `RequestItemsText` = '$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.' WHERE `entry` = 7795;
        UPDATE `quest_template` SET `RequestItemsText` = 'Whenever you are ready to hand in the stack of runecloth, I''ll accept it.' WHERE `entry` = 7796;
