        UPDATE `quest_template` SET `RequestItemsText` = 'Yes? What have you got there?' WHERE `entry` = 8857;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hmmm...' WHERE `entry` = 8858;
        UPDATE `quest_template` SET `RequestItemsText` = 'Greetings! Are you here for the party! Or perhaps you just need to rest those weary feet of yours...' WHERE `entry` = 8860;
        UPDATE `quest_template` SET `RequestItemsText` = 'Good day, $C! Did you come to Thunder Bluff for our celebrations?  Or are you here to rest a weary hoof between hunts?' WHERE `entry` = 8861;
        UPDATE `quest_template` SET `RequestItemsText` = 'Elune''s candle is an artifact of great reverence to the disciples of the Lunar Festival. Stored within the candle is true moonlight, ready to be unleashed!$b$bThis light is harmless to most creatures, but you will find that Omen and his minions are burned and dazzled by it.' WHERE `entry` = 8862;
        UPDATE `quest_template` SET `RequestItemsText` = 'I have a selection of dresses that may be of interest to you.  Such dresses have been worn in times past during the Lunar Festival, and the selection I have today is perhaps the finest I have ever seen.  Each is hand-crafted with only the finest and softest of components.$B$BIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?', `CompleteEmote` = 1 WHERE `entry` = 8864;
        UPDATE `quest_template` SET `RequestItemsText` = 'I am please to inform you that I have a fine selection of festive pant suits available for you to own... but only in trade for coins of ancestry.  If fashion is important to you, then these are what you''re looking for!  I assure you that you will not find pant suits like these anywhere else.$B$BIn exchange for some Coins of Ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?', `CompleteEmote` = 1 WHERE `entry` = 8865;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find the launchers, $N?' WHERE `entry` = 8867;
        UPDATE `quest_template` SET `RequestItemsText` = 'Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort! Bring me coins of ancestry and I will grant you the knowledge of their crafting.' WHERE `entry` = 8881;
        UPDATE `quest_template` SET `RequestItemsText` = 'The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers! Is it not then logical for you to learn the secrets of making cluster launchers? Bring me coins of ancestry and I will give this knowledge to you.' WHERE `entry` = 8882;
        UPDATE `quest_template` SET `RequestItemsText` = 'We rangers of the Farstrider Retreat are dedicated to setting right the damage that has been wreaked upon our fair lands. We will go to any length to do so.$B$BI trust that you have returned with the murloc heads I tasked you to gather? ' WHERE `entry` = 8884;
        UPDATE `quest_template` SET `RequestItemsText` = 'You are the instrument of my success and revenge!$B$BHave you the ring? ' WHERE `entry` = 8885;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it! You''ve saved me from ruin and delivered my revenge upon those disgusting creatures!$B$BNow if I can just get these pretty rangers here to help me with this cargo, I''ll finally get out of here! I''ll have to come back when Velendris has retaken the shipyard.$B$BHere, take this coin. It''s what little I can afford, and the least that I can do to reward your efforts.', `RequestItemsText` = 'I am grateful for the assistance of someone like you, $N. It almost puts a smile on my face. But then I realize what these monsters have done to my ship and what''s happening to Quel''Thalas.$B$BHave you managed to retrieve any of my cargo?', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmoteDelay2` = 500, `OfferRewardEmoteDelay3` = 500 WHERE `entry` = 8886;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh you sweet, sweet $c! I had no idea that those disgusting Grimscale murlocs had also pirated away with my navigation rutters! Without them, I would have no chance of navigating the seas again once we retake the anchorage and repair the ship.$B$BThank you very much! Here, take this coin as a sign of my appreciation.', `RequestItemsText` = 'Hello, $c, you''re a sight for sore eyes. I know, it''s crazy for me to be here, what with the anchorage overrun by the Wretched. Velendris and his rangers have sworn to protect me on the condition that I get out of here as soon as I''ve recovered my cargo.$B$BWhat''s that you have there... it looks vaguely familiar?', `OfferRewardEmote1` = 1 WHERE `entry` = 8887;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you teach those Wretched a lesson?' WHERE `entry` = 8892;
