        UPDATE `quest_template` SET `RequestItemsText` = 'You did an exemplary job on the first bundle, $n. If you have more, I will take them now. For every bundle that you turn in, I will reward you with another insignia.' WHERE `entry` = 9125;
        UPDATE `quest_template` SET `RequestItemsText` = 'Truth be told, I use the cores to create Frostfire armor. It is the armor used by the mages battling in Naxxramas. Without you and others like you, we would most definitely be losing this war.$B$BWith that said, bring me more cores and I shall grant you more insignias.\n' WHERE `entry` = 9129;
