        UPDATE `quest_template` SET `RequestItemsText` = 'For every armful of the scraps, I''ll give you an insignia - the more the better. Now get out of my sight before I split you in two!\n', `CompleteEmote` = 25 WHERE `entry` = 9132;
        UPDATE `quest_template` SET `OfferRewardText` = 'What''s this? Sathiel wants all of this!?$B$BDid you bring anyone with you to help take it back?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 9133;
