        UPDATE `quest_template` SET `RequestItemsText` = 'I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren. He''s in the tower on the west side of town.$B$BAnd, $C, when you''re done talking with him return to me; I have something dire that needs to be dealt with immediately!' WHERE `entry` = 9329;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 9330;
