        UPDATE `quest_template` SET `RequestItemsText` = 'Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.$B$BBring them to me.  I''ll make due note of your service should your performance go above and beyond the call of duty.' WHERE `entry` = 9338;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve proven yourself today, $n.$b$bWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way.', `OfferRewardEmote1` = 1 WHERE `entry` = 9339;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve returned. Is the task done?' WHERE `entry` = 9340;
        UPDATE `quest_template` SET `OfferRewardText` = 'In order to have great cuisine, you need to have great ingredients.  And these eggs look great!$B$BI''ve just finished cleaning off my frying pan, so you''re more than welcome to join me for a meal!', `RequestItemsText` = 'You have those eggs yet?$B$B<Legassi''s stomach grumbles in anticipation.>', `CompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 9349;
        UPDATE `quest_template` SET `OfferRewardText` = 'Night elves?  Here?  Those rats!$B$BDo you suppose they had anything to do with the malfunction in my sanctum?  If you have any information, you''d better take it to Captain Sunbrand at once!', `RequestItemsText` = 'Have you uncovered anything? Are the night elves behind this?' WHERE `entry` = 9352;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to clear the road?' WHERE `entry` = 9355;
