        UPDATE `quest_template` SET `OfferRewardText` = 'Hmm...$B$BThis looks edible, if spiced properly. Just don''t tell Screed where his breakfast came from, ok?', `OfferRewardEmote1` = 1 WHERE `entry` = 9361;
