        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, good of Magistrix Dawnstrider to finally respond to my simple requests.  I should take up the matter of her attitude with the regent lord in Silvermoon. She''s quite rude!$B$BNothing for you to $g concern yourself with though : worry your little head over;. Now that you''re here, maybe I''ll finally be able to get those party supplies that I''ve been waiting for?', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 6, `OfferRewardEmoteDelay2` = 1000, `OfferRewardEmoteDelay3` = 1000 WHERE `entry` = 9395;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well, $N.  It is always unfortunate to have to resort to taking a life, even when it''s that of a dangerous beast such as the rock flayer.$B$BYou have my thanks for carrying out this grim task.', `RequestItemsText` = 'Welcome back, $N. Have you completed the task I asked of you?' WHERE `entry` = 9398;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it!  I''m in your debt, $N.  Look at all the Dreghoods that are showing up.$B$BUnder my guidance they''ll learn all about the old ways, you''ll see.', `RequestItemsText` = 'You''ve returned! Did you complete your task?' WHERE `entry` = 9399;
        UPDATE `quest_template` SET `RequestItemsText` = 'How''s the water?' WHERE `entry` = 9402;
        UPDATE `quest_template` SET `RequestItemsText` = 'Only water from the Elrendar Falls has the purity required for use with magic. Do you have it? ' WHERE `entry` = 9403;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have the living branch? Hand it over quickly! ' WHERE `entry` = 9404;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work!  This will do nicely to replenish our depleted healing crystals.$B$BBut now that you''re here, I think I have another use for you, if you''re willing?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 9409;
        UPDATE `quest_template` SET `OfferRewardText` = 'Great job, $N!  I hereby proclaim you an honorary Longbeard.$B$BStick around and have a drink with us, won''t you?', `RequestItemsText` = 'You''re back!  How did you do?' WHERE `entry` = 9417;
        UPDATE `quest_template` SET `RequestItemsText` = 'Be careful out there, but also be quick. We have no time to lose.' WHERE `entry` = 9419;
