        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, I feel the fel presence in the pools weakening.$B$BYou''ve done well, $N.', `RequestItemsText` = 'Have you completed your task, $N?' WHERE `entry` = 9426;
        UPDATE `quest_template` SET `OfferRewardText` = 'The essence of Aggonar lived on in the form of his foul offspring Aggonis.  With your success in defeating the demon, we can begin to work towards restoring the pools to their former purity.$B$BYou have our thanks, $N.  Your work will have a deep impact in this world.' WHERE `entry` = 9427;
