        UPDATE `quest_template` SET `OfferRewardText` = 'Impressive.  Most impressive.$B$BYou''ve got potential, kid.  Now I''m going to give you the chance to have some real fun!', `RequestItemsText` = 'You think the clefthoof bulls are just going to fall dead at your feet here in front of the campfire?' WHERE `entry` = 9850;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it!  You took down Banthar!  I never had a doubt, $N.$B$BHere, I think you''ve more than earned this.', `RequestItemsText` = 'A warm fire and a $g woman : man; at your side for idle chit-chat is something you can get at home.  Here we hunt big game or die trying.' WHERE `entry` = 9851;
        UPDATE `quest_template` SET `OfferRewardText` = '$N!  You bring joy to this old dwarf''s heart.$B$BYou have now proven yourself; you''ve joined the ranks of the elite!  Others ran away in fear, or died, trampled under the foot of the beast.  You used your mind, your cunning, your determination to prove your mastery of the hunt.$B$BTake this and know that you are always welcome to hunt at my side!' WHERE `entry` = 9852;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you come to know the peace that comes with knowing your place in nature?  Are you the hunter or the hunted?', `IncompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 9854;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you learned yet to calm the beating of your heart?  To be as still as a calm lake and patient, waiting for the right moment to strike down your quarry?', `IncompleteEmote` = 6 WHERE `entry` = 9855;
        UPDATE `quest_template` SET `OfferRewardText` = 'Her eye looks as if it is still alive.  Do you think that she can still see into your soul?$B$B$N, you can now count yourself as one of the elite safari hunters.  And you are another step closer to stalking the ultimate prey of this land, Tusker!$B$BYou''ve earned the right to have this.  May it serve you well.' WHERE `entry` = 9856;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s a good tale... <cough>...of how you bagged all of those stags, $c.  But I think that you can do better.  I''ve got something else in mind for you.', `RequestItemsText` = 'I''m just going to lay here a little while longer.  I should be fine soon.' WHERE `entry` = 9857;
        UPDATE `quest_template` SET `OfferRewardText` = '<cough>, <cough>... $N!  You did it.  There''s only...<cough>... one thing left to...<cough>... do then.', `RequestItemsText` = 'I don''t suppose...<cough>... you''ve taken care of those...<cough>... thorngrazers yet?' WHERE `entry` = 9858;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wow!  You did it!  That''s really Bach''lor''s hoof!$B$BUm, I''m starting to feel much better it would seem.  Here, let me give you something in celebration of your proven hunting prowess!', `RequestItemsText` = '<Harold looks up at you weakly, but manages a smile.>$B$BYou have...<cough>... the hoof?' WHERE `entry` = 9859;
        UPDATE `quest_template` SET `CompleteEmote` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 9861;
        UPDATE `quest_template` SET `OfferRewardText` = 'You saw them controlling the elements? The wind bent to their will?$B$B<Morgh is lost in thought for a moment.>$B$BThis is troubling, $N. I must consult with the others.$B$BWe thank you for your efforts, $N. Perhaps you should return to your village and see if they have any other information about the Murkbloods and their nefarious goals.', `RequestItemsText` = 'The air spirit claims that the Murkblood are searching for something at Sunspring...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 9862;
