        UPDATE `quest_template` SET `RequestItemsText` = 'This is merely one step in a long process. Ogres, like dogs, must be shown the difference between right and wrong. Telling them does no good.' WHERE `entry` = 9945;
        UPDATE `quest_template` SET `RequestItemsText` = '<Ungriz sighs.>$B$BI know it''s a lot to ask for, $N; but bring them back alive...' WHERE `entry` = 9948;
        UPDATE `quest_template` SET `RequestItemsText` = 'Rokag has told me about his plan. You have the eyes?' WHERE `entry` = 9950;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s for the best, really.  If it cannot civilly accept an invitation then it has no business attending.$B$B<Warden Treelos looks momentarily confused.>$B$BWho are you and what are you doing here?  You must get out of here quickly before it is too late!', `RequestItemsText` = 'We should never have invited them to dinner.  That much is certain!$B$BOr, at least, we should have insisted upon a couple of courses before the dessert that they brought.' WHERE `entry` = 9951;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 9954;
        UPDATE `quest_template` SET `RequestItemsText` = 'Where''s Corki?' WHERE `entry` = 9955;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 9956;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m glad that the refuge sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he''s insane.$B$BI don''t know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.$B$BWill you help me?' WHERE `entry` = 9957;
        UPDATE `quest_template` SET `RequestItemsText` = 'The fight''s over when you or your opponent are dead on the floor.' WHERE `entry` = 9962;
        UPDATE `quest_template` SET `RequestItemsText` = 'The fight''s over when you or your opponent are dead on the floor.' WHERE `entry` = 9967;
        UPDATE `quest_template` SET `OfferRewardText` = 'Odd.  The samples from the vicious teromoths are infused with what feels to me to be pure mana.$B$BIt would seem that whatever caused all of this death also left behind that strong field of residual energy.  But for some reason the teromoths were not killed by it; instead being driven into an agitated state.$B$BIt seems apparent that this strange energy is the by-product of whatever attacked the thicket.' WHERE `entry` = 9968;
        UPDATE `quest_template` SET `RequestItemsText` = 'The fight''s over when you or your opponent are dead on the floor.' WHERE `entry` = 9970;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, I was right.  That was the corpse of one of the Broken?  And you can confirm that there was a strange object on the ground next to him?$B$BThis doesn''t make any sense.  What would one of the Broken be doing here?  And what is that thing it had with him?$B$BIs it what caused all of this death?', `RequestItemsText` = 'Have you discovered anything yet?' WHERE `entry` = 9971;
        UPDATE `quest_template` SET `RequestItemsText` = 'The fight''s over when you or your opponent are dead on the floor.' WHERE `entry` = 9972;
