        UPDATE `quest_template` SET `RequestItemsText` = 'Have you begun to clear the fouled water spirits?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10067;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have proven yourself a capable student. I look forward to continuing your lessons in the future.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 1000, `CompleteEmote` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 10069;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have a knack for the healing arts, $N. You should find no lack of people clamoring for your skills.$B$BSee me again when you are ready for further training.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 1 WHERE `entry` = 10072;
        UPDATE `quest_template` SET `RequestItemsText` = 'This base was the primary draenei research facility for the study of naaru crystals.$B$BWhat we have discovered is a veritable goldmine of research notes about the crystals from the "diamond" mountain, Oshu''gun. It would seem that everything in this region carries with it some residual powder of the Oshu''gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.' WHERE `entry` = 10075;
        UPDATE `quest_template` SET `RequestItemsText` = 'This base was the primary draenei research facility for the study of naaru crystals.$B$BWhat we have discovered is a veritable goldmine of research notes about the crystals from the "diamond" mountain, Oshu''gun. It would seem that everything in this region carries with it some residual powder of the Oshu''gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.' WHERE `entry` = 10077;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s the spirit!$B$BI''m glad we finally got some reinforcements, but I''m not so sure about their attitude toward the Horde. Where I come from, anyone with a weapon pointed at you is an enemy and needs to be dealt with like one!', `RequestItemsText` = 'You seem to be in good spirits. Has burning Horde siege machinery put the spring back in your step?' WHERE `entry` = 10078;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me the shaking''s over and my boys can get back to work... please?' WHERE `entry` = 10079;
        UPDATE `quest_template` SET `RequestItemsText` = 'You do not need a potion to see spirits, $N.' WHERE `entry` = 10082;
        UPDATE `quest_template` SET `RequestItemsText` = 'Move as the wind, $N.' WHERE `entry` = 10085;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''ve been looking for the telltale signs of burning cannons -- smoke plumes, or the cries of burning fel orcs...$B$BAny luck on your mission?' WHERE `entry` = 10087;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you bring news from the Shadow Labyrinth? Is the danger there finally dealt with?' WHERE `entry` = 10095;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good!  Those marsh beasts have no right to invade the home of the sporeloks!$B$BIt would be better if these creatures would learn to live in harmony, but when that''s not possible, we''ll be here to take care of the situation!$B$BHere, please take one of these as thanks for your help.', `RequestItemsText` = 'What?  Back so soon?  How did it go?' WHERE `entry` = 10096;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find her, $N? Was she still being held within the halls?' WHERE `entry` = 10097;
        UPDATE `quest_template` SET `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 10098;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m almost afraid to ask. Seeing you come out of the mine alive means one of two things: either you killed the bastard, or you lost your nerve. Well, which is it?' WHERE `entry` = 10099;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, return to me when you have aided in the capture of each of the forts!' WHERE `entry` = 10106;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 10109;
        UPDATE `quest_template` SET `RequestItemsText` = 'Return to me after you have helped capture each fort!' WHERE `entry` = 10110;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did I mention my love for eggs? Completion', `CompleteEmote` = 1 WHERE `entry` = 10111;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, indeed, I do believe that it''s all getting clearer now.$B$BAnd I think that your diligence in this matter deserves more than just the information that you seek.', `CompleteEmote` = 1 WHERE `entry` = 10112;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you seen what the Daggerfen have done? Now you understand why we must isolate them from the other Lost Ones.' WHERE `entry` = 10115;
        UPDATE `quest_template` SET `RequestItemsText` = 'The only thing the Daggerfen understand is swift and brutal action. They should know that we will not let them have their way.' WHERE `entry` = 10118;
        UPDATE `quest_template` SET `RequestItemsText` = 'Thrallmar is safe so long as the arcanist and his bloodmages remain at the front.' WHERE `entry` = 10123;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have eliminated the colossal menace?' WHERE `entry` = 10132;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hmph.  Just looks like a big lump of unrefined crystal to me.$B$BAdmittedly, I can feel a sickly, evil aura emanating off of it, but that''s not exactly in my line of work.  I''m just here to put an end to the mountain giant menace.', `RequestItemsText` = 'That''s a big crystal you have there.  Did you get that while you were up at the ridge killing colossi?$B$BLet me take a look at it.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10134;
        UPDATE `quest_template` SET `RequestItemsText` = 'Destiny calls, $N. Arazzius the Cruel has eluded justice long enough. Let his death be a message to all those who would oppose the Horde. You are next.', `CompleteEmote` = 1 WHERE `entry` = 10136;
        UPDATE `quest_template` SET `OfferRewardText` = 'Our expedition to this forsaken, wreck of a world has almost ground to a halt, $n. We encountered more resistance than we bargained for.$B$BAs if facing the Burning Legion again wasn''t bad enough - there are horrors in this land unlike anything we''ve ever encountered.', `CompleteEmote` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274, `OfferRewardEmote4` = 1 WHERE `entry` = 10140;
        UPDATE `quest_template` SET `OfferRewardText` = 'Force Commander Danath may have misunderstood my request for reinforcements. You look capable, but... I asked for a full sized battalion!$B$BYou see, we have a bit of a demon problem...', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 66, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 5 WHERE `entry` = 10141;
        UPDATE `quest_template` SET `OfferRewardText` = 'Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth new dreadlords.$B$BNow for the bad news: I''ve got your new orders...', `RequestItemsText` = 'Honor Hold is safe so long as the archers guard our skies.', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10142;
        UPDATE `quest_template` SET `OfferRewardText` = 'Glad to meet you, soldier.$B$BEnough chatting... now listen up -- I have a vital mission for you and I want you to succeed... and survive!', `OfferRewardEmote1` = 1 WHERE `entry` = 10143;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $n.  Disabling those portals will stem the flow of Legion reinforcements for a long time!$B$BBut we can''t rest yet...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 10144;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 11 WHERE `entry` = 10146;
        UPDATE `quest_template` SET `RequestItemsText` = 'How fares your attempt to clear Thornfang Hill?' WHERE `entry` = 10159;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lieutenant Amadi nods.>$B$BGood, we need all the help we can get. The increasing fel orc presence around the Southern Rampart concerns me. I sent out a scout to investigate, but he hasn''t yet returned.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10160;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10161;
