        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10165;
        UPDATE `quest_template` SET `RequestItemsText` = '<D''ore''s spirit hums.>$B$BGreetings, $N.' WHERE `entry` = 10167;
        UPDATE `quest_template` SET `RequestItemsText` = '<Mother Kashur is visibly upset.>These naaru are wise beyond all manner of life on this world. ' WHERE `entry` = 10168;
        UPDATE `quest_template` SET `RequestItemsText` = 'The smell of herbs and spices fills the air around the pot.' WHERE `entry` = 10169;
        UPDATE `quest_template` SET `RequestItemsText` = '<Greatmother Geyah is lying down.>' WHERE `entry` = 10172;
        UPDATE `quest_template` SET `RequestItemsText` = 'At last, we meet.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10176;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10180;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you found, $N?' WHERE `entry` = 10182;
        UPDATE `quest_template` SET `RequestItemsText` = 'Busy, busy.  No time to waste!  There''s a rocket ship to be built!$B$BWhat do you want?' WHERE `entry` = 10183;
        UPDATE `quest_template` SET `RequestItemsText` = 'It pains me to know there is so little to be done for our comrades.' WHERE `entry` = 10184;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you managed to clear out some of the mana creatures from the village ruins?' WHERE `entry` = 10185;
        UPDATE `quest_template` SET `RequestItemsText` = 'Does it look like the X-52 Nether-Rocket is ready for liftoff?  Am I cruising the Twisting Nether in the comfort of my command chair?  Exploiting strange new worlds?  Seeking out new technology and business opportunities?  Boldly going where no goblin has gone before?$B$BNo!$B$BSo, I hope you have those crystals that I sent you after.' WHERE `entry` = 10186;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back so soon?$B$BIs everything okay with the Maxx A. Million Mk. V?!' WHERE `entry` = 10191;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes it, $N? Got any news? What have you done for me lately?' WHERE `entry` = 10193;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the eavesdropping, $N? You''d best hurry. I''m getting antsy here.' WHERE `entry` = 10198;
        UPDATE `quest_template` SET `OfferRewardText` = '<You tell Rakoria the results of the test and she throws her head back, laughing.>', `RequestItemsText` = 'Well, do you have the test results?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 10201;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10202;
        UPDATE `quest_template` SET `RequestItemsText` = 'Isn''t this place great? And everyday yields something new and exotic!$B$BWhat a stroke of luck that we nearly destroyed the town digging down here.' WHERE `entry` = 10203;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you investigate the bloodgems used by the Sunfury magisters, $N?' WHERE `entry` = 10204;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s over then? Warp-Raider Nesaad is dead?' WHERE `entry` = 10205;
        UPDATE `quest_template` SET `RequestItemsText` = 'Back with their tech so soon?  You better not just be pulling my leg here, $C.$B$BThe success of the X-52 project out here depends upon you getting us that stuff a.s.a.p.!' WHERE `entry` = 10206;
        UPDATE `quest_template` SET `OfferRewardText` = '<You''re not sure whether it''s just distortion, or the archmage really is smiling.>$B$BWith the last of my possessions restored, I have everything I need to break through Kael''thas''s magic. I''ll begin working the spell right away.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10209;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10210;
        UPDATE `quest_template` SET `RequestItemsText` = 'The stories of men are ephemeral, $N. The stories of cities last well into the years.' WHERE `entry` = 10211;
        UPDATE `quest_template` SET `RequestItemsText` = 'This device has over a dozen buttons, none of which look familiar to you.' WHERE `entry` = 10216;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, little flesh beast.' WHERE `entry` = 10218;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you taught the Unyielding the consequences of defying the Forsaken?  ' WHERE `entry` = 10220;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you saved us from the depredations of Dr. Boom? I promise this time there won''t be any exploding wagons, though that was a lot of fun!$B$BWe really should do that more often.' WHERE `entry` = 10221;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done, $N? Have you avenged the fallen of Kirin''Var Village?' WHERE `entry` = 10222;
        UPDATE `quest_template` SET `OfferRewardText` = '<You''re not certain, but it seems as though Custodian Dieworth is on the verge of tears.>$B$BAt last, it is through. If I could will myself out of existence, I would, but the truth is I don''t know how to let go. For the ones in the village, it is difficult but straightforward. I suppose this is the price we pay for retaining such strong ties to this place.', `RequestItemsText` = 'Have you finished the task, $N?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10223;
        UPDATE `quest_template` SET `RequestItemsText` = 'Um, hi. I''m a little busy here. What''s that you have there?' WHERE `entry` = 10225;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have the power from those elementals yet? Oh, don''t hurry or anything. It''s just my life and career on the line.' WHERE `entry` = 10226;
        UPDATE `quest_template` SET `OfferRewardText` = 'The child is correct. I was once a "death priest."$B$B<Ramdor winces.>$B$BSuch an unsavory title.$B$BThrough that corridor lies the Auchenai Crypts. Inside you will find the remnants of my priory. They are all mad now, of course. Insane to the last! I suppose I stood out, being the last one among them with any common sense. Of course, I was excommunicated for my beliefs.$B$BWhat are my beliefs, you say?', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 10227;
        UPDATE `quest_template` SET `CompleteEmote` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 274 WHERE `entry` = 10228;
        UPDATE `quest_template` SET `RequestItemsText` = 'Whaddya want?', `CompleteEmote` = 1 WHERE `entry` = 10231;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, that''s good and bad news, now isn''t it?  We''ve dealt them a blow, but with the Burning Legion running free all over the Netherstorm - and getting closer to us here - well, I don''t know how it''s going to go.$B$BI have a feeling that we''re going to have to change gears here for a while.  Hope you''ll be able to help us out, $N.', `RequestItemsText` = 'I sure hope that you''re up to that tussle with the Burning Legion.$B$BThere aren''t many things that I hate worse than those that renege on a deal, or <cough> gnomes, but demons are certainly one of them!', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 10232;
        UPDATE `quest_template` SET `RequestItemsText` = 'Smoke rises from the Sunfury Hold fortifications. Is that your handiwork?' WHERE `entry` = 10233;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 11, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000 WHERE `entry` = 10234;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10236;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you saved my peons yet? Please hurry, I''m afraid they are going to be eaten and they probably won''t taste very good. If they taste really bad the fel orcs might get really mad at me.' WHERE `entry` = 10238;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you activated all the runes? I''m eager to see if we can''t improve upon the blood elf method here. Anything one of Kael''thas''s men can do. real Kirin Tor can do better.' WHERE `entry` = 10240;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed your task, $N?' WHERE `entry` = 10241;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10242;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed your task, $N?' WHERE `entry` = 10246;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10252;
        UPDATE `quest_template` SET `OfferRewardText` = 'If the old draenei said to destroy the book, why didn''t you?$B$B<Ramdor glares at you.>$B$BBah, what''s the difference. You might be greedy but at least you''re honest.$B$BMe on the other hand... I lied to get this book. I have no idea where these poor lost souls kept their treasure nor would I tell you if I did - however - I do have something for you. You did a good thing on this day. Perhaps a great thing... You should be rewarded.$B$BBy the way, welcome to the fold.$B$B<Ramdor points to the spirits.>', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 25 WHERE `entry` = 10253;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well met, my $gbrother:sister;.  I''m glad you''ve come. I am Danath - leader of the Sons of Lothar, and force commander of this hold.', `CompleteEmote` = 1 WHERE `entry` = 10254;
        UPDATE `quest_template` SET `OfferRewardText` = '<You describe the results of your scrying.>$B$BCommander Sarannis, you say? Hmm...$B$BShe''s one of Kael''thas''s advisors, but certainly not a mage. I remember her from the attack on Kirin''Var Village. I think your impressions are correct, $N. She''s not maintaining the curse personally, but she holds the key to it.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10256;
        UPDATE `quest_template` SET `OfferRewardText` = '<The archmage''s eyes light up when you hand him the stone.>$B$BAmazing! From what little I''ve seen of the fate of Farahlon, I''m not certain I want to go outside, but it''s much better than being trapped here for the rest of my days.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10257;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10259;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done? Have you wiped the Zaxxis scum from the face of Outland and brought me their insignia?' WHERE `entry` = 10262;
        UPDATE `quest_template` SET `RequestItemsText` = 'I get the impression that the prince is looking for a particular crystal, but I''m not certain what it is.$B$BHave you already recovered the one from the dreadlord?' WHERE `entry` = 10265;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, it''s true.  The blood elves have reneged on yet another purchase of goods that has already been delivered.$B$BAs Nether-Stalker Khay''ji has vouched for you, I am hopeful that you will be able to assist me in this matter.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 10266;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 15, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000 WHERE `entry` = 10267;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, traveler. You come to Hazzin because you are in need of my goods?' WHERE `entry` = 10269;
        UPDATE `quest_template` SET `RequestItemsText` = 'This Marid is a fool, or shall I say, was a fool.' WHERE `entry` = 10273;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello again, my friend. How fare your efforts to find the crystal?' WHERE `entry` = 10276;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not return until you have at least a rudimentary understanding of what is happening.', `IncompleteEmote` = 1 WHERE `entry` = 10277;
        UPDATE `quest_template` SET `RequestItemsText` = '<The musical tinkling of the naaru''s speech fills your mind.>$B$BI sense that you have something of great power with you, $R.  What is it that you bring to me?' WHERE `entry` = 10280;
        UPDATE `quest_template` SET `RequestItemsText` = 'Who are you?' WHERE `entry` = 10283;
        UPDATE `quest_template` SET `RequestItemsText` = '<Erozion nods.>' WHERE `entry` = 10284;
        UPDATE `quest_template` SET `CompleteEmote` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274, `OfferRewardEmote4` = 1 WHERE `entry` = 10288;
        UPDATE `quest_template` SET `RequestItemsText` = 'A report from Orion? Give it here, quickly!$B$B<Frowning, General Krakork quickly scans the tattered document.>$B$BDamn, it''s just as we feared. Orion and his warriors could be overrun at any moment!' WHERE `entry` = 10289;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have done well, $N. The timeways are safe once more.', `RequestItemsText` = 'You may only use one chrono-beacon per pocket of time.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10297;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re finished? That''s good news. Hopefully, we can find a way to avoid the killing of these mutated beasts in the future.$b$bI believe I have formed a plan that might give us an alternative solution to this problem, but I will need your help.', `RequestItemsText` = 'I am working on a solution I think may be effective with the strange creatures. I just need more time.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `CompleteEmote` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 10302;
        UPDATE `quest_template` SET `RequestItemsText` = 'There are too many of them... We must whittle them down or else the survivors will have no chance against them.' WHERE `entry` = 10303;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you found, $N?' WHERE `entry` = 10305;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you found, $N?' WHERE `entry` = 10306;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you found, $N?' WHERE `entry` = 10307;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Consortium is keenly interested in wiping out all of the Zaxxis rebels at the Heap to the south.$B$B$C, if you would like to ingratiate yourself further with us, go back down there and bring back more of their affiliation insignia.' WHERE `entry` = 10308;
        UPDATE `quest_template` SET `RequestItemsText` = 'My eyesight must be going from all of the nether radiation. You have that fel reaver''s heart yet?' WHERE `entry` = 10309;
        UPDATE `quest_template` SET `OfferRewardText` = 'That is most excellent news, my friend!$B$BYou and Drijya have done us a great service.  With that warp-gate out of commission, the nearby demons will not be getting any further reinforcements.$B$BPlease allow me to reward you in the proper manner of the Consortium.', `RequestItemsText` = 'How may I help you?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 10310;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 1 WHERE `entry` = 10311;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you performed the measurements I asked for, $N?' WHERE `entry` = 10313;
        UPDATE `quest_template` SET `RequestItemsText` = 'How many nethermancers have you managed to fell?' WHERE `entry` = 10315;
        UPDATE `quest_template` SET `RequestItemsText` = 'What news do you bring from Manaforge Ara? Did you deal with Foreman Sundown?' WHERE `entry` = 10318;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you destroyed the lich of that wretched Naberius?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 10320;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wonderful! You''re turning into quite the hunter, $n.$b$bHow would you like to look more like me? Well here is your chance! While you were out hunting, I fashioned these items out of some buck hides I had laying around. Take your pick!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 10324;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10325;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you bear more of our enemies'' insignias, $C?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.', `CompleteEmote` = 1 WHERE `entry` = 10326;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''ll take any leftover marks you might have.  Do not worry; your actions will be duly noted.' WHERE `entry` = 10327;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 10328;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did the plan work? I was half-expecting you to get blown up, to tell you the truth.' WHERE `entry` = 10329;
        UPDATE `quest_template` SET `RequestItemsText` = '<There appear to be tears in the apprentice''s eyes as he speaks.>$B$BHave you... dealt with Master Rhonsus?' WHERE `entry` = 10332;
        UPDATE `quest_template` SET `OfferRewardText` = 'What?!  He called me his ''partner''?  I''m his wife!$B$BAnd he said I had a sharp tongue!  Ooh, when I get back to Area 52, I''m going to box his big, green ears!$B$BBut I''m glad that you''re here.  He was right about one thing; I can definitely use your help!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 10333;
