        UPDATE `quest_template` SET `OfferRewardText` = 'Hah hah!  A fresh $r from the mainland!  Well don''t worry -- Shatter Point might make you queasy but she doesn''t stray far!$B$BAnd I''ve only seen her flip upside down once... or twice.', `OfferRewardEmote1` = 1 WHERE `entry` = 10340;
