        UPDATE `quest_template` SET `RequestItemsText` = 'You have saved us all. What can we do to thank you?' WHERE `entry` = 10842;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Mok''Nathal do not accept failure, or make excuses. Either you vanquish your foe, or he kills you!$B$BSince you are standing before me, you must have killed Gnosh Brognat already.' WHERE `entry` = 10843;
        UPDATE `quest_template` SET `RequestItemsText` = 'Though you will not further yourself in my eyes, there is no shame in admitting that you aren''t up to the challenge of slaying the mother of the Singing Ridge nether drakes.$B$BIs that what you are here to tell me?' WHERE `entry` = 10845;
        UPDATE `quest_template` SET `RequestItemsText` = 'We have many enemies. Some we have chosen, and some, such as the Vehk''nir, we have not.$B$BRegardless, we shall slay all of their chieftains until none stand before us.' WHERE `entry` = 10846;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.$b$bBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk''s gaze fixates on the south.$b$bThese Eyes are all seeing.', `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 10847;
        UPDATE `quest_template` SET `OfferRewardText` = 'Those foul spirits deserved to die. The death they would have wrought on others is reason enough.$b$bWe cannot hope to redeem those in Terokk''s grasp. But we shall deliver them a devastating blow in the name of the Light.', `RequestItemsText` = 'Evil grows in Veil Rhaze. Put it down, $r.' WHERE `entry` = 10848;
