        UPDATE `quest_template` SET `OfferRewardText` = 'The stories don''t even come close to how cool this place is.  It''s amazing!$B$BIs it true that a powerful wizard named Medivh created it?$B$BI wonder what''s on the other side?  You''ve been there, right?  Hmm, we should definitely go someplace on the other side of the Dark Portal!', `OfferRewardEmote2` = 1 WHERE `entry` = 10951;
        UPDATE `quest_template` SET `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 10952;
        UPDATE `quest_template` SET `OfferRewardText` = 'You bring a child here?  Foolhardy, but I promise that she will come to no harm, at least as long as she doesn''t get too close to Incineratus.$B$BHmm, unfortunate that she''s a blood elf.  Were she capable of a deep connection to the world, we could teach her some things so that she might aid us to heal its wounds.  But, perhaps her exposure to the elements here will give her some insight into their workings.$B$BGo in peace and see to it that you take good care of her.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 10953;
