        UPDATE `quest_template` SET `RequestItemsText` = '<Budd eyes the note suspiciously.>$B$BWhat have you there, $C?' WHERE `entry` = 11130;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you promised to save the children!' WHERE `entry` = 11131;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ahh yes, $n, isn''t it?$b$bHave you recovered my map yet?' WHERE `entry` = 11132;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed your assault on the deserter base?' WHERE `entry` = 11134;
        UPDATE `quest_template` SET `RequestItemsText` = 'We''re talking again are we? That must mean that you''ve done it! You''ve shown those rotten Northsea pirates a thing or two!$b$bRight?' WHERE `entry` = 11153;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ugh, what''s that smell? Ack, it''s you! Well, I guess I did send you on a smelly job!$B$BThank you, $c. Don''t worry, I''ll get this stuff back to Petrov as soon as we get out of here.$B$B<Feknut yells out loud to the explorers.>$B$BYou hear that guys? Lets get the hell out of here!!!', `CompleteEmote` = 6, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 15 WHERE `entry` = 11154;
        UPDATE `quest_template` SET `OfferRewardText` = 'This will make a fine meal for the men.$B$B<The chef leans in closer to whisper in your ear.>$B$BHere, $g boy : deary;, take some for yourself. You look like you could use some more meat on your bones!' WHERE `entry` = 11155;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work! With any luck at all, the destruction of their egg clutches and whelps should drive off those fiery beasts and prevent that magical blaze from spreading.$B$BWait... what''s that sound? It sounds like the beating of wings.', `RequestItemsText` = 'How go your efforts?', `OfferRewardEmote1` = 1 WHERE `entry` = 11157;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hurry, mon!$B$BBudd be sendin'' me into Zul''Aman alone to test his mask if I don''t be givin'' him those tusks soon!', `CompleteEmote` = 1 WHERE `entry` = 11164;
        UPDATE `quest_template` SET `RequestItemsText` = 'I trust that my hand-crafted disguises have given you adequate protection in Zul''aman.$B$BHave you scouted those areas for me? Or shall I begin looking for your replacements?', `IncompleteEmote` = 1 WHERE `entry` = 11166;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11167;
        UPDATE `quest_template` SET `OfferRewardText` = 'You continue to prove your competence, $N.  Hopefully this toxin will be enough to boost our plague to the levels that we need to.$B$BAt the very least it should help weaken the recipient and make them more susceptible to infection.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11168;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re back!', `DetailsEmote1` = 11, `OfferRewardEmote1` = 388 WHERE `entry` = 11170;
        UPDATE `quest_template` SET `RequestItemsText` = 'I hope you appreciate the magnitude of the opportunity I''ve given you, Diedthreexs.$B$BHave you taken care of old Malacrass yet?', `IncompleteEmote` = 1 WHERE `entry` = 11171;
        UPDATE `quest_template` SET `OfferRewardText` = 'Grrr. I knew it! He''s sooooo over-protective! This is just embarassing.$B$BNot that I''m not happy to see you... I am! We all are. We can use your help!' WHERE `entry` = 11175;
        UPDATE `quest_template` SET `RequestItemsText` = '<Budd tries to mask his displeasure at your presence.>$B$BYou again....$B$BI don''t know how else to say it - I''m simply too busy with my preparations to hold your hand any longer.$B$BTrust me, $N, it''s all for the best. Perhaps, by some miracle, you might eventually build a name for yourself.$B$BIf so, you''ll be able to say that you got your start from the incomparable Budd Nedreck!' WHERE `entry` = 11178;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you learned from the spirits haunting this place?' WHERE `entry` = 11180;
        UPDATE `quest_template` SET `OfferRewardText` = 'Unfortunate that one predator must be used to put down another, but that is the natural order of things.$B$BPerhaps now the proto-drakes and their whelps can go back to living peacefully. Somehow I doubt it with the reawakening of the vrykul.', `RequestItemsText` = 'How fare your efforts against the meddlesome handlers, little one?', `OfferRewardEmote1` = 33 WHERE `entry` = 11182;
        UPDATE `quest_template` SET `OfferRewardText` = '<Malister beckons you closer and speaks in whispered tones.>$B$BI was worried that something like this might happen. I tried to dissuade the captain from this course of action, but he is a dwarf of action with a definite outlook on how things should proceed.$B$BLet us speak of the options left to us.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11187;
        UPDATE `quest_template` SET `OfferRewardText` = '<The mage-lieutenant sighs.>$B$BUnfortunate business to be certain. Well, what''s done is done. With any luck the new whelps that grow to be drakes at Ember Clutch will not retain a memory of our shameful actions therein.$B$BAnd with a bit more luck, the boundaries of that magical forest will not continue to spread.$B$BHere, $N, please take this pittance from the treasury for all of your troubles. It''s the least that we can do.', `RequestItemsText` = 'It is unfortunate that the captain had to have you go rile up the proto-drakes. Though they seem to lack the intelligence of some of the dragons we know, they still seem to be noble creatures. Not to mention the situation it places us in.$B$BDare I ask if you have dealt with the situation?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11188;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, bless ya, $N, bless ya!$B$BJust set ''em down right where yer standin''. I''ll have one o'' the boys come load ''em up soon enough and we can stop worryin'' ''bout runnin'' out o'' balls ta shoot at Skorn.', `RequestItemsText` = 'We''re runnin'' dangerously low on rounds ''round here, $c. Our enemies need poundin'', especially Skorn!$B$BYa got more balls fer us?' WHERE `entry` = 11190;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hey, $N! I hear ya been workin'' yer way into Budd''s crew. Ya won''t live to regret that move, friend, I can promise ya that.$B$BWhatcha got there, mon?', `CompleteEmote` = 1 WHERE `entry` = 11195;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 11199;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice!$B$BBut what''s this about the stuff you found inside those tanks? Are you saying that the Forsaken are spraying a plague upon the vrykul down there?', `RequestItemsText` = 'It''s hard to tell from all the way over here exactly what''s happening down there. Did you manage to put those plague tanks to the torch?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 11202;
        UPDATE `quest_template` SET `OfferRewardText` = 'The ore gave you a strange feeling? Maybe we won''t use that stuff after all.$B$B<Steelring looks at the stuff and takes a step back, changing the subject.>$B$BThose gems look really nice! I wonder what I can get for them? Of course, there are always repairs, and new stuff to be made.$B$BYou know, I''ve really found working with you to be profitable. Take this... it''s the least that I can do!', `CompleteEmote` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 4, `OfferRewardEmote3` = 1 WHERE `entry` = 11218;
        UPDATE `quest_template` SET `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 11219;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you back with your report, $n?', `DetailsEmote1` = 25, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 300 WHERE `entry` = 11221;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m indebted to you, $c. At least with most of the mules and equipment recovered, we can hope to rebuild our numbers soon.$B$BPlease, take this.', `RequestItemsText` = 'This is quite a blow to our efforts. I don''t even want to know what they discovered down there.$B$BIt''s enough to keep me awake at night just trying to imagine what it could be.', `OfferRewardEmote1` = 1 WHERE `entry` = 11224;
        UPDATE `quest_template` SET `OfferRewardText` = 'Did you hunt down some crows, boy?  Good boy, good boy!$B$BAh, these hounds remind me of my days raising purebreds in Tirisfal... those were good times!', `RequestItemsText` = 'Did you feed this little rascal here yet?', `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 3000, `OfferRewardEmote1` = 4 WHERE `entry` = 11227;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 11229;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 4 WHERE `entry` = 11230;
        UPDATE `quest_template` SET `OfferRewardText` = 'Bless you child! With your help, the Light shines even in the darkest of places.$B$BPlease, take this as just compensation for your good deeds. I shall see to the salvation of those you freed; at least, those truly within the Light, and the Alliance, who returned here to the keep.', `RequestItemsText` = 'With the prisoners at Gjalerbron freed, the vrykul will be unable to continue their unholy rites.$B$BYou''re our only hope of stopping them.', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11231;
        UPDATE `quest_template` SET `RequestItemsText` = 'The cannons, $n. Is someone going to take care of them?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 11232;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are the Alliance leaders dead, $N? Do not return until they are.', `DetailsEmote1` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 11233;
        UPDATE `quest_template` SET `OfferRewardText` = 'It was about time.  The Alliance has been a thorn in our side for a long time now.$B$BThere''s no time to celebrate, however.  Look to the west, it appears we have visitors.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11234;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work, $N, and good riddance.$B$BBut, what you say about that place troubles me still, and I think our culling is not quite at an end!', `OfferRewardEmote1` = 1 WHERE `entry` = 11235;
        UPDATE `quest_template` SET `OfferRewardText` = '<The captain breathes a sigh of relief.>$B$BWell, that should take some of the pressure off of us.$B$B$N, time and again you have proven yourself invaluable to Westguard Keep and the Alliance at large. Pick something from the treasury, $g boy : girl;! It''s the least we can do!', `RequestItemsText` = 'Are you sure that you killed Mezhen and his necrolords, $c?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 11236;
        UPDATE `quest_template` SET `RequestItemsText` = 'What?! Plans for an attack upon the keep?$B$BA FROST WYRM?!!!', `CompleteEmote` = 5, `OfferRewardEmote1` = 5 WHERE `entry` = 11237;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wow, that horn is cold!$B$BOnce again you''ve saved Westguard Keep from certain doom. What a curious $g man : woman; you are, $N. If only there were more of you.$B$BWell, this certainly calls for a reward. Which do you prefer?', `RequestItemsText` = 'Is the attack averted? Are the frost wyrm and its master destroyed?$B$BDid you retrieve the horn?', `CompleteEmote` = 6, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6 WHERE `entry` = 11238;
        UPDATE `quest_template` SET `OfferRewardText` = '<The priest quietly mouths a benediction for you.>$B$BBless you, $N, you have answered my prayers. Stand proudly in the Light, chin held high with the knowledge that your actions were most holy!$B$BI''m certain that the church''s coffers can yield up something of use to you.', `RequestItemsText` = 'The Holy Light moves through your actions and in all things.$B$BNo creature, no place, no matter how wicked, can escape its wrath!', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 11239;
        UPDATE `quest_template` SET `OfferRewardText` = '<The sapper grumbles as if he wishes that you hadn''t succeeded.>$B$BThe captain will be pleased to hear of your success.$B$BYou know, since you''ve been such a good sport in dealing with this Whisper Gulch business, why don''t you take your pick of one of these?', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 6 WHERE `entry` = 11240;
        UPDATE `quest_template` SET `OfferRewardText` = 'Apothecary Hanes is alive?  You burned the Alliance supplies to the ground?  He must''ve gotten a real kick out of that.$B$BAt any rate, the Royal Apothecary Society is in your debt, $N.  We thank you from the bottom of our black, black hearts.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 11, `OfferRewardEmoteDelay2` = 3000 WHERE `entry` = 11241;
        UPDATE `quest_template` SET `RequestItemsText` = 'The fate of the world may very well rest with us.' WHERE `entry` = 11243;
        UPDATE `quest_template` SET `OfferRewardText` = 'What the vrykul did to our scouts was a gruesome display of savagery. It was a scare tactic, meant to weaken our resolve... to send us running in fear for our lives.$B$BIt failed.$B$BWe are going to show those monsters what it means to wage war against the Alliance!', `RequestItemsText` = 'Find those scouts!' WHERE `entry` = 11244;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent targeting, $g sir : ma''am;! I''ll have to remember to buy a round for the cannoneers back at the keep.', `RequestItemsText` = 'Getting too close to those towers is certain death as long as those casters are up there.', `OfferRewardEmote1` = 1 WHERE `entry` = 11245;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, $g sir : ma''am;, I have to say that you went about that particular business with a bit of zeal.$B$B<The sergeant looks at you warily.>$B$BAnyway, if you don''t mind, I''ll be taking my machete back now. It looks dull and we wouldn''t want you to accidentally slip and carve me up, too.', `RequestItemsText` = 'One thing that I know for certain is that I don''t want to see any of these bigguns standing back up after we''ve knocked ''em down!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 11246;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very good, $g sir : ma''am;. That couldn''t have been done without your help.$B$BI''m sure that the captain will be pleased with my report on the matter once we''re done here.', `RequestItemsText` = 'May I suggest that when we set the buildings ablaze, we not tarry too long inside of them?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11247;
        UPDATE `quest_template` SET `OfferRewardText` = 'A pleasure to meet you, $g sir : ma''am;! I look forward to working with you.$B$BSpeaking of which, we have a great deal to do.', `OfferRewardEmote1` = 66 WHERE `entry` = 11248;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, $g my son : my daughter;, that is ominous-looking, and you obviously had the right of it.$B$BThank you for bringing this scroll to me. I am very keen to study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.$B$BBy defeating the Winterskorn thane, you proved him unworthy. The Light only knows what he would have become, and what terror he might have rained down upon us, had you not slain him.', `CompleteEmote` = 6, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11249;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s unbelievably good news! I knew that you could pull it off, $N!$B$BAt least someone around here can produce results!$B$BWell, this calls for a reward. Go ahead, take your pick; the treasury is open to you.', `CompleteEmote` = 6, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 2 WHERE `entry` = 11250;
        UPDATE `quest_template` SET `OfferRewardText` = 'Late though ye may be, it''s good to see a friendly face.$b$bNow stop standin'' around with yer thumb up yer nose. there''s work to be done!', `DetailsEmote1` = 396, `DetailsEmote2` = 1, `DetailsEmote3` = 25, `DetailsEmote4` = 1, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500 WHERE `entry` = 11251;
        UPDATE `quest_template` SET `RequestItemsText` = 'Good to see you''re well, $n.$b$bWe''ve had about as many casualties as we can handle.' WHERE `entry` = 11252;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 11253;
        UPDATE `quest_template` SET `OfferRewardText` = '<The high executor looks at the map intently, occasionally looking up at landmarks around the Fjord.>$B$BHere''s the eastern coastline over here.  The Dragonflayer and Winterskorn villages are here and here... and this must be us over here, marked for death.', `OfferRewardEmote1` = 274 WHERE `entry` = 11254;
        UPDATE `quest_template` SET `RequestItemsText` = 'Put some backbone into it, $n! People''s lives are at stake here!' WHERE `entry` = 11255;
        UPDATE `quest_template` SET `OfferRewardText` = 'It will be interesting to learn about your people, $c, while fighting alongside you.$B$BShall we proceed?', `DetailsEmote1` = 25, `DetailsEmote2` = 1, `DetailsEmote3` = 66, `OfferRewardEmote1` = 1 WHERE `entry` = 11256;
        UPDATE `quest_template` SET `OfferRewardText` = 'Have you done that before? Your skill with my machete seemed practiced.$B$B<The brave looks at you warily.>$B$BI''ll take it back from you now, $c.', `RequestItemsText` = 'These vrykul have strange customs, would you not agree, $n?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 11257;
        UPDATE `quest_template` SET `OfferRewardText` = '<The brave nods at you in clear approval of your handling of the torch>$B$BLet these vrykul feel the heat of the land. Let them know the fear they would instill in others!', `RequestItemsText` = 'I suggest that when we set the buildings ablaze, we not stay inside of them. The fire spirit will not spare us in its thirst to destroy.', `DetailsEmote1` = 1, `DetailsEmote2` = 6, `DetailsEmote3` = 66, `OfferRewardEmote1` = 1 WHERE `entry` = 11258;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have a strong arm, $N.$B$BIt looks as if those wind riders finally made themselves useful instead of just standing around and drinking all day.', `RequestItemsText` = 'Getting too close to those towers is certain death as long as those casters are up there.', `DetailsEmote1` = 66, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11259;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, that is ominous-looking, and you obviously had the right of it.$B$BThank you for bringing this scroll to me. I will study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.$B$BBy defeating the Winterskorn thane, you proved him unworthy. Who knows what he would have become, and what terror he might have rained down upon us, had you not slain him?', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 6 WHERE `entry` = 11260;
        UPDATE `quest_template` SET `OfferRewardText` = 'That is good news indeed! You have given us some breathing room to further our preparations for leaving.$B$BPlease, take one of these as a sign of our appreciation.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 11261;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have my thanks, $N. I know that you do not have any duty to me or my people.$B$BWhat you say about that place troubles me still, and I sense that our culling is not quite at an end.', `RequestItemsText` = 'How is the fight at Gjalerbron coming?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 11263;
        UPDATE `quest_template` SET `OfferRewardText` = '<Chieftain Ashtotem breathes a sigh of relief.>$B$BThat should take some of the pressure off.$B$B$N, time and again you have proven your value to the taunka of Camp Winterhoof. Please, choose something from our bounty. I insist.', `DetailsEmote1` = 5, `DetailsEmote2` = 25, `DetailsEmote3` = 5 WHERE `entry` = 11264;
        UPDATE `quest_template` SET `OfferRewardText` = 'A great stone is lifted from my shoulders to hear of your success. And I smile to know that some you freed were taunka.$B$BPlease, take this as a gift for what you have done. I shall see to the health of those you freed.', `RequestItemsText` = 'With the prisoners at Gjalerbron freed, the vrykul will be unable to continue their rituals.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11265;
        UPDATE `quest_template` SET `RequestItemsText` = 'What?! Plans for an attack upon our camp?$B$BFROM A GREAT WYRM IN THE SKY?!!!', `OfferRewardEmote1` = 5 WHERE `entry` = 11266;
        UPDATE `quest_template` SET `OfferRewardText` = 'This horn is as cold as the land... perhaps even colder!$B$BYou have saved Camp Winterhoof from certain doom, not that we''ll be staying here much longer. What a curious $g man : woman; you are, $N. Perhaps you $r-types from over the ocean are not so bad after all.$B$BThis calls for a reward. Which do you prefer?', `RequestItemsText` = 'Is the attack averted? Is the great death wyrm and its master destroyed?$B$BDid you retrieve the horn?', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6 WHERE `entry` = 11267;
        UPDATE `quest_template` SET `OfferRewardText` = '<The greatmother nods her approval of your actions.>$B$BThank you, $N, you have done what is right and you have bought us a little more time to finish our preparations for leaving. We will soon make the journey north.$B$BI am too old; when we go, I will not be able to carry everything with me. Would you like to take one of these?', `RequestItemsText` = 'Have you destroyed the walking dead at Gjalerbron?', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 11268;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank goodness! This should be enough to finish the order in time. Of course, I won''t sleep until the troops arrive, but that''s far better than risking Captain Adams'' wrath.$B$BI''ve heard the stories they tell about him!' WHERE `entry` = 11269;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m glad you''ve proven you can follow orders.  If I had a copper piece for every arrogant fool in shiny armor to come here and think they''re above the chain of command... well, I''d have a few gold.$B$BNow that you''ve demonstrated a measure of discipline, I have other tasks more suitable for someone of your caliber.', `RequestItemsText` = 'I don''t care how many giants, dragons or kobolds you''ve killed before. Get this job done and come back when you''re finished.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11270;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11271;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is good to see you again, $n. Unless you haven''t killed that aberration of an elf yet, in which case I''d get going if I were you.' WHERE `entry` = 11272;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve found Pulroy. A bit too late it seems.$B$BWhile looking over the corpse you see a journal clenched tightly in Pulroy''s death grip. Upon examining the journal you read what appears to be the scribbling of a dying dwarf.' WHERE `entry` = 11273;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve found Zedd. You''re no doctor but the prognosis for Zedd is most assuredly negative.$B$BIt looks as if they were preparing to feed him to the worgs. Gruesome...' WHERE `entry` = 11274;
        UPDATE `quest_template` SET `OfferRewardText` = 'These are all fine horns, $N. Let me examine them and select the one I will use in the hunt.$B$BI''ll give the rest to the craftsmen for use in their carvings.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11275;
        UPDATE `quest_template` SET `OfferRewardText` = 'About bloody time! Pulroy and Zedd are dead.$B$BAnd Daegarn...$B$B<Glorenfeld shakes his head.>$B$BTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something ''bout a sacrifice to the "Dread King."$B$BThe cipher is hidden away in Daegarn''s grimy beard.$B$BWhat? Dwarves hide things in their beards all the time!' WHERE `entry` = 11276;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well, mate. Now that we''ve secured the tablets we can try and save Daegarn''s life and recover the cipher that will help us decode the meaning behind these ancient relics!$B$BI''ll hold on to these tablets, you rescue Daegarn.\n\n' WHERE `entry` = 11277;
        UPDATE `quest_template` SET `OfferRewardText` = 'What?! No, this can''t be right.$B$BCURSES!$B$BThis batch of the plague doesn''t seem to have had any real effect on the proto-whelps at all other than to make them glow green!$B$BMy dream of using the plague upon anything we come into contact with seems to have gone up in smoke!', `DetailsEmote1` = 1, `DetailsEmote2` = 6, `DetailsEmote3` = 25, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 11279;
        UPDATE `quest_template` SET `OfferRewardText` = 'NOOOOOOOOOOOOOOOO!!!$B$B<The plaguebringer begins to cry.>$B$BAll of my hopes... all of my dreams, ruined!$B$BLeave me, $N. Leave me to my despair. I''m nothing.$B$BHere, you might as well take all of my worldly possessions. When the rest of the apothecaries hear of my failure, I''ll be done for and won''t need them anyway.', `RequestItemsText` = 'Well, out with it! Did our little experiment work?$B$BDid the proto-drake like its snack? Did it dissolve from the inside?', `DetailsEmote1` = 5, `DetailsEmote2` = 6, `DetailsEmote3` = 1, `OfferRewardEmote1` = 22, `OfferRewardEmote2` = 18, `OfferRewardEmote3` = 274 WHERE `entry` = 11280;
        UPDATE `quest_template` SET `OfferRewardText` = '<Nokoma listens to your report from the test.>$B$BI''m relieved that the horn worked so well... maybe too well if what you''re saying was true. You''re sure the beast spoke? I don''t know if I can go on with the hunt if that''s true. I''ll have to speak with Chief Ashtotem about it.$B$BThis horn may end up being merely decorative, but that won''t diminish its worth. Thank you for all your help, $N.', `RequestItemsText` = 'Did you get a chance to test that horn?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11281;
        UPDATE `quest_template` SET `RequestItemsText` = 'You kill them vrykuls? They sure is tough!' WHERE `entry` = 11282;
        UPDATE `quest_template` SET `RequestItemsText` = 'You done with the killings yet? Winterskorn town right across from here!', `DetailsEmote1` = 1 WHERE `entry` = 11283;
        UPDATE `quest_template` SET `RequestItemsText` = 'You done burning everything? Make sure you not leave something not burned.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11285;
        UPDATE `quest_template` SET `OfferRewardText` = '<The sage grunts his approval at your actions on his behalf.>$B$BPerhaps I will be able to find the time soon to study these artifacts and come to an understanding of their significance.$B$BBut now there are more pressing matters to attend to.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 11286;
        UPDATE `quest_template` SET `OfferRewardText` = 'You feel compelled to place the sacred blade next to the body of Ares.$B$BUpon doing this you are once again blinded by light.', `RequestItemsText` = '<Ares is unconscious.>' WHERE `entry` = 11288;
        UPDATE `quest_template` SET `OfferRewardText` = 'Many men and women died to recover this blade. Alas, I fear valiant Ares will not be the last.$B$BBut you do the Light''s work, hero. This sacred blade will be wielded by Lord Tirion Fordring himself. Even now the Argent Crusade works toward Icecrown. Lord Fordring has vowed that he will tear down the walls of the cursed place himself! And with the blade, he just might stand a chance against the Lich King.$B$BLord Fordring remains our greatest hope.' WHERE `entry` = 11289;
        UPDATE `quest_template` SET `OfferRewardText` = '<Vice Admiral Keller glances over the plans.>$B$BOutstanding! By the looks of things, there are many more vrykul villages in the fjord. A different tribe of vrykul is preparing an assault on Westguard Keep. Hell, for all I know it may already be too late. We haven''t heard from Westguard in days. Either way, we must alert Westguard!' WHERE `entry` = 11290;
        UPDATE `quest_template` SET `OfferRewardText` = '<Captain Adams takes the plans from you.>$B$BI''m glad you decided to come over. My advisors and I will need some time to study these plans. In the meantime, we can use all the help we can get!', `RequestItemsText` = 'Valgarde has not fallen? That''s a surprise.$B$BMust be due to your help. It sure wasn''t because of Keller.', `CompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11291;
        UPDATE `quest_template` SET `OfferRewardText` = '<Trapper Jethan inspects the creatures you''ve brought him.>$B$BNicely done. Some of these will fetch a better price than others, but I should have plenty to trade with the locals.' WHERE `entry` = 11292;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you finished spreading the word about Brewfest? But more importantly, did you let people know about the Barleybrews?', `IncompleteEmote` = 1 WHERE `entry` = 11293;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you let everyone know that the Thunderbrews are here at Brewfest?' WHERE `entry` = 11294;
        UPDATE `quest_template` SET `OfferRewardText` = 'You come to help?  Good... good...$B$BGorth was getting tired of killing vrykuls all day.  Help is welcome!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 53 WHERE `entry` = 11295;
        UPDATE `quest_template` SET `OfferRewardText` = 'That was a very brave act, $c. I did not know that your people were capable of such selflessness.$B$BNext time I will heed the warnings of my elders and steer clear of the Rivenwood. I advise you to do the same.', `RequestItemsText` = 'I hold out hope that my hunting force is still alive.$B$BThe sting of the widows is slow to be fatal. They like to keep their victims alive long enough that their babies will be able to gorge themselves when they hatch.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11296;
        UPDATE `quest_template` SET `OfferRewardText` = '<The apothecary pours out a tankard of the beverage for himself.>$B$BWell, here I go!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11298;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yep. You found me. Woopedy-do!$B$BAnd no, I don''t have the cipher. My beard was the first thing those beasts checked! Oluf''s the one that''s got it now. He''s the chieftain of the gladiators.' WHERE `entry` = 11299;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fascinating tale! Something is actually judgin'' these things? To what end?! For what purpose?$B$BWell, never mind that nonsense. Someone else can figure out that stuff. We got the cipher and the tablets back - and only two fatalities in the whole ordeal.' WHERE `entry` = 11300;
        UPDATE `quest_template` SET `OfferRewardText` = 'These brains are beautiful! Gorgeous, even! They''re exactly what I need.$B$BThank you for your help, $N. Now I''ll show Malthus the truth his beer goggles couldn''t reveal.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11301;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lurielle listens as you introduce yourself.>$B$BIt is good to finally meet you, $N. We have long hoped that you and the other newcomers might send representatives. We don''t often venture beyond the borders of our glades, especially amid the changes the land is going through.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11302;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11303;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 3000, `OfferRewardEmote1` = 5 WHERE `entry` = 11304;
        UPDATE `quest_template` SET `DetailsEmote1` = 6 WHERE `entry` = 11305;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent!  You are an apt pupil, $N.$B$BNow comes the fun part.  Deployment!', `DetailsEmote1` = 21, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 3000, `OfferRewardEmote1` = 4 WHERE `entry` = 11306;
        UPDATE `quest_template` SET `OfferRewardText` = 'The plague didn''t disintegrate our subjects?  Are you certain, $N??!$B$BThere must be an external factor we''re not accounting for... perhaps the low temperatures of this climate?  Perhaps... a mutation in the strain!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 3000 WHERE `entry` = 11307;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 3000 WHERE `entry` = 11308;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you done with the cleanup in Halgrind?', `DetailsEmote1` = 11, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 3000, `OfferRewardEmote1` = 4 WHERE `entry` = 11310;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you culled the elementals?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11311;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lurielle listens as you introduce yourself.>$B$BIt is good to meet you, $c. My sisters have often watched the taunka search the forests for us, but we are forbidden by our queen from interacting with outsiders. You only see us now because the land has become unsettled and many of my sisters are in danger.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11312;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lurielle accepts the cores from you quietly.>$B$BThank you, $N.$B$B<Lurielle glances at the icy cores sadly.>$B$BI promise, my friends, I will do all I can to restore you.' WHERE `entry` = 11313;
        UPDATE `quest_template` SET `OfferRewardText` = 'So there is hope for my sisters?$B$B<Lurielle looks away from you, then down at the ground.>$B$BI feel guilty for not thinking of the pendant sooner. We might have saved even more of the sisters.', `RequestItemsText` = 'Were you able to heal any of my sisters using the pendant?' WHERE `entry` = 11314;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you returned from the Vibrant Glade?' WHERE `entry` = 11315;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you seen the horrors of the Twisted Glade for yourself?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11316;
        UPDATE `quest_template` SET `OfferRewardText` = 'Already I can sense the change within you.$B$BAre you ready for what comes next?', `RequestItemsText` = 'Did you find inner peace at the shrine? Is your turmoil gone?', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 11317;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to handle the speed?', `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 11318;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Twisted Glade is a terrible place. I never imagined our homes could become something so loathesome.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11319;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff? Got something for me?', `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 11321;
        UPDATE `quest_template` SET `OfferRewardText` = 'Already I can sense the change within you.$B$BAre you ready for what comes next?', `RequestItemsText` = 'Did you find inner peace at the shrine? Is your turmoil gone?', `OfferRewardEmote1` = 6 WHERE `entry` = 11322;
        UPDATE `quest_template` SET `OfferRewardText` = 'Garwal was not a worg at all! I know of these creatures... they are called worgen.$B$BBut, Ulfang indicated that it came south from the Grizzly Hills? Odd. There aren''t any worgen there.$B$BI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.$B$BPlease, you must accept this as a sign of gratitude.' WHERE `entry` = 11324;
        UPDATE `quest_template` SET `OfferRewardText` = 'Garwal was not a worg at all! The thing you describe him turning into sounds a lot like a worgen!$B$BBut, Ulfang said that it came south from the Grizzly Hills? Odd. There aren''t any worgen there.$B$BI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.$B$BPlease, you must accept this as a sign of gratitude.', `CompleteEmote` = 6, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 1 WHERE `entry` = 11326;
        UPDATE `quest_template` SET `OfferRewardText` = 'Holy... what the hell?! Look at this stuff!$B$BWe need to get this back to the keep a.s.a.p.!', `RequestItemsText` = 'That place looks like a nightmare. Vrykul or not, no one deserves to be the victim of the Royal Apothecary Society.$B$BGlad I''m standing safely over here. You find that package yet?', `CompleteEmote` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 11327;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh... hey, that''sh different!$B$BOkay, let me shee that shtuff. I jusht love tinkering with alchemy!$B$BInteresting, interesting... here, I think I know jusht what to do. A little mixing of that with the jusht the right amount of thish.$B$BYou know, I think a little dash of this rotgut will help, too ...hic!', `CompleteEmote` = 6, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11328;
        UPDATE `quest_template` SET `OfferRewardText` = 'Huh? Well that sucks! Darn, I made thingsh worsh. In fact, I think I perfected their plague for them ...hic!$B$B<Peppy grimaces and takes a huge gulp of whatever noxious brew she''s been drinking.>$B$BWell, I wash hoping that it wouldn''t come down to thish, but it looks like there''sh no alternative ...hic.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 11330;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, $N, what is it now?$B$BWHAT?!! A Forsaken super plague that melts you in no time?$B$BYou oozed my vrykul prisoner?$B$B<The captain looks almost sad and spits in disgust.>$B$BAlright, I know what we need to do. Or rather, what YOU need to do!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 5 WHERE `entry` = 11331;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nicely done, $N, nicely done!$B$B<The captain seems beside himself with glee.>$B$BThat''ll show those good-for-nothing Forsaken to think about messing with us!$B$BI''d say you''ve earned yourself something from the treasury!', `RequestItemsText` = 'Those plague tanks destroyed, yet? That new plague looms over our heads like certain death, $c!' WHERE `entry` = 11332;
        UPDATE `quest_template` SET `OfferRewardText` = 'A bit worse for the wear but still functional.$B$B<Thoralius reaches into the pouch and removes some odd looking roots.>$B$BNow to place them in the fire and inhale!$B$B<Thoralius throws the roots into the smoldering incense burner.>$B$B<Thoralius inhales deeply. His body begins to quiver.>$B$BWha... What... It cannot be... I cannot...' WHERE `entry` = 11333;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me, $n. What news do you bring from the front?', `IncompleteEmote` = 1 WHERE `entry` = 11335;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me, $n. What news do you bring from the front?', `IncompleteEmote` = 1 WHERE `entry` = 11336;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me, $n. What news do you bring from the front?', `IncompleteEmote` = 1 WHERE `entry` = 11337;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me, $n. What news do you bring from the front?', `IncompleteEmote` = 1 WHERE `entry` = 11338;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you discovered?' WHERE `entry` = 11343;
        UPDATE `quest_template` SET `OfferRewardText` = 'Human children born of vrykul? And Ymiron ordered the deaths of all human born offspring?$B$B<Thoralius goes silent for a moment.>$B$BAs much as I wish to deny what is so plainly presented to me, I cannot. There is no extinct "missing link" to humans as the Explorers'' League proposed. The vrykul are the missing link. They are the progenitors of humanity.', `RequestItemsText` = 'What have you discovered?' WHERE `entry` = 11344;
        UPDATE `quest_template` SET `OfferRewardText` = '<Prospector Belvar browses the book of runes.>$B$BHmm... there''s so much here. I''m going to need some time to study it, and if we hope to understand these runes, we''ll need to try to make our own.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11346;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well in defeating Binder Murdis, but the Iron Dwarves won''t give up easily.$B$BWe''ve made a lot of progress in understanding how they manipulate runes. Perhaps next time we encounter them, our knowledge will give us an advantage.', `RequestItemsText` = 'Have you tried the rune?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11348;
        UPDATE `quest_template` SET `OfferRewardText` = '<Belvar handles the tools carefully.>$B$BI''m going to try these out. If we''re to understand the Iron Dwarves'' motives and defeat them, I need to know exactly what the runes are doing.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11349;
        UPDATE `quest_template` SET `OfferRewardText` = '<The longrunner browses the book of runes.>$B$BI''m no loremaster, but I have some familiarity with the language of the Iron Dwarves. I think the runes they''re carving on the giants are derived from their spoken language, but there are some differences.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11350;
        UPDATE `quest_template` SET `OfferRewardText` = '<Pembe examines the tools.>$B$BThese are more delicate than I''d thought. Allow me a moment to try them out.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11351;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well in defeating Binder Murdis, but the Iron Dwarves won''t give up easily.$B$BAs my people move north, I''m certain we will encounter the Iron Dwarves again. Next time, we will be prepared to thwart them before they can dig in.', `RequestItemsText` = 'Have you tried the rune?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11352;
        UPDATE `quest_template` SET `OfferRewardText` = '<Researcher Aderan listens to your findings.>$B$BThe runes for "north" and "west" appeared multiple times? There''s a highly reinforced command to move in that direction, but the runes are more than propulsion. Something is attracting them, but what?', `RequestItemsText` = 'What have you found?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11355;
        UPDATE `quest_template` SET `OfferRewardText` = '<Aderan listens as you describe your findings.>$B$BOf course! This Megalith must be the key to the Iron Dwarves'' plans. We must destroy it before their plan comes to fruition!', `RequestItemsText` = 'Have you discovered what lodestone attracts the giants?', `OfferRewardEmote1` = 1 WHERE `entry` = 11358;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well in felling Megalith, but I wonder about his final words.$B$BYou''re sure he said the Stoneforge?$B$BI know of no place with that name, but it sounds like a word with origins in the titans. What plans do the Iron Dwarves have for such a thing? This bears watching, $N, for we must find it before the Iron Dwarves'' plan comes to fruition.', `RequestItemsText` = 'Do you bring news of Megalith''s downfall?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11359;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $N. Have you been perfecting your fire fighting techniques? Don''t forget about the practice area to the north!' WHERE `entry` = 11360;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you dowsed any fires, $n?  The training area is west of Razor Hill''s western exit.' WHERE `entry` = 11361;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have returned. The centurions all lay dead?' WHERE `entry` = 11364;
        UPDATE `quest_template` SET `OfferRewardText` = '<The sage listens to your findings.>$B$BThe runes for "north" and "west" appeared over and over? I''m not an expert in these runes, but the repetition of them suggests a strong command.$B$BThese carvings are more than passive directions, though. They seem to pull the giants toward something, but what?', `RequestItemsText` = 'What have you found?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11365;
        UPDATE `quest_template` SET `OfferRewardText` = '<Edan listens as you describe your findings.>$B$BMegalith? A literal transcription from the tablet! This Megalith must be the centerpiece of the iron ones'' mysterious plans.', `RequestItemsText` = 'Have you discovered what lodestone attracts the giants?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11366;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well in felling Megalith, but I wonder about his final words.$B$BYou''re sure he said the Stoneforge?$B$BIt is not a name our people know, but it sounds like it might be a creation of the "titans" the ousiders speak of. The Iron Dwarves have ever been a cunning and dangerous foe, $N. We must watch these giants and find this Stoneforge before they can carry out their plans.', `RequestItemsText` = 'Do you bring news of Megalith''s downfall?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11367;
        UPDATE `quest_template` SET `RequestItemsText` = 'How fares your fight against the coilfang myrmidons?' WHERE `entry` = 11371;
        UPDATE `quest_template` SET `RequestItemsText` = 'Not many know that the source of Shaffar''s magic rests solely within his amulet. Without it he is powerless.$B$BThen again, if you have it that must mean that he is dead.' WHERE `entry` = 11373;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you''ll know it when you see it.$B$BPerhaps it is something akin to the being''s voice box?' WHERE `entry` = 11375;
        UPDATE `quest_template` SET `RequestItemsText` = 'The instructors, they are all dead? No?$B$BDid I not say not to return unless you had killed them all?' WHERE `entry` = 11376;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.$b$bPlease, help yourself to some of my extra stock.  I''m sure someone of your talent could put it to good use.', `CompleteEmote` = 1 WHERE `entry` = 11377;
        UPDATE `quest_template` SET `RequestItemsText` = 'The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?$B$BAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?$B$BHe''ll lie, I suppose.' WHERE `entry` = 11378;
        UPDATE `quest_template` SET `OfferRewardText` = 'Now look at that...$b$b<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>$b$bSweet A''dal that''s good!  A cook with your potential shouldn''t be without $ghis:her; proper materials.  Take some of my extra stock and make me proud.', `OfferRewardEmote1` = 0 WHERE `entry` = 11379;
        UPDATE `quest_template` SET `OfferRewardText` = 'Those are the juiciest mana berries I''ve ever seen.  I think I''m getting smarter just by looking at them.$b$bSince I no longer need most of my meat and fish stock, why don''t you take some?  I''m certain you could make something delicious.', `IncompleteEmote` = 6, `CompleteEmote` = 1 WHERE `entry` = 11380;
        UPDATE `quest_template` SET `OfferRewardText` = 'That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it''s done.$b$bAs promised, here''s your cut.  And because you did such a fine job, I''m going to throw in some of my extra stock.', `CompleteEmote` = 1 WHERE `entry` = 11381;
        UPDATE `quest_template` SET `IncompleteEmote` = 1 WHERE `entry` = 11382;
        UPDATE `quest_template` SET `RequestItemsText` = 'We are speaking, but I sense that all of the rift lords are not yet dead.$B$BReturn again when they are, $C.', `IncompleteEmote` = 1 WHERE `entry` = 11383;
        UPDATE `quest_template` SET `RequestItemsText` = 'How can it be that we are speaking when the channelers are not all lying dead?' WHERE `entry` = 11385;
        UPDATE `quest_template` SET `RequestItemsText` = '<The nether-stalker cocks his head in apparent confusion at your presence.>$B$BThe destroyers have not all been destroyed.' WHERE `entry` = 11387;
        UPDATE `quest_template` SET `RequestItemsText` = 'It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.$B$BBetter you than me!' WHERE `entry` = 11388;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you not know how to get to Tempest Keep and the Arcatraz? East through the Netherstorm and then fly or fall, the choice is yours.' WHERE `entry` = 11389;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good job, though I think ye might be wanting a refresher course in basic piloting.$B$BWell, no matter, one warm body''s as good as another. Here''s yer haul for the day. ', `RequestItemsText` = 'Eh? You finished with all of that hauling?' WHERE `entry` = 11390;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice shooting, ace.$B$BHere''s your wages. Come back tomorrow for another round, ya hear?', `RequestItemsText` = 'Gargoyles?! I saw them out there! Did ya take care of ''em all?$B$BWhat''s the world comin'' to when a dwarf cannot even dig without being attacked.', `OfferRewardEmote1` = 1 WHERE `entry` = 11391;
        UPDATE `quest_template` SET `OfferRewardText` = '<The explorer beams a smile as you tell him who sent you. He continues in hushed tones.>$B$BIrena was concerned about me?  She gets that from her father you know.' WHERE `entry` = 11393;
        UPDATE `quest_template` SET `OfferRewardText` = '<Jaren seems very excited about your success, but motions you to keep your conversation to a whisper.>$B$BGreat job, $N! That''s a lot of Scourge goo all over your stuff though. You might want to think about a quick dip in the strait. It''s cold, but it''ll get you cleaned up right quick.', `RequestItemsText` = 'I don''t know, $c, it doesn''t look like you''ve destroyed enough of them yet.' WHERE `entry` = 11394;
        UPDATE `quest_template` SET `OfferRewardText` = 'I know what this is! $N, it''s a controlling device for those scourging crystals!$B$BI bet anything that it can be used to shut down their force fields. Hmmm.$B$B<The explorer looks thoughtful as he ponders the implications of you having the device.>' WHERE `entry` = 11395;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice!$B$B<Jaren looks around quickly to make sure that nothing noticed his outburst.>$B$BAlright, you certainly earned your pick of one of these things I found while I was down here.$B$BAnd, $N, if you happen to find yourself back at Steel Gate, give Irena my love and let her know that I''m okay.', `RequestItemsText` = 'I don''t know, $n. I think you need to take out a few more of those things.' WHERE `entry` = 11396;
        UPDATE `quest_template` SET `OfferRewardText` = '<Anastasia ponders your success for a moment.>$B$BA satisfactory job to be certain, yet somehow I sense that there''s something else we should be doing to stop the efforts of the Scourge on that beach.', `RequestItemsText` = 'That''s interesting, when last I looked it didn''t appear as if you''d destroyed enough of them yet. Perhaps you might redouble your efforts?', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 11397;
        UPDATE `quest_template` SET `OfferRewardText` = 'I can tell you what this is, $N. It''s a controlling device for those scourging crystals down there!$B$BI bet anything that it can be used to shut down their force fields. Hmmm.$B$B<The apothecary looks thoughtful as she ponders the implications of you having the device.>', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 11398;
        UPDATE `quest_template` SET `OfferRewardText` = '<Anastasia turns and smiles at her succubus.>$B$BVery well, $N, I concede that you have certainly earned a choice of one of these.', `RequestItemsText` = 'You still haven''t destroyed enough scourging crystals. No reward until you do so.', `DetailsEmote1` = 69, `DetailsEmote2` = 30, `DetailsEmote3` = 6, `DetailsEmoteDelay2` = 2000 WHERE `entry` = 11399;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is that an "Honorary Brewer" stamp you''ve got on your hand?' WHERE `entry` = 11400;
        UPDATE `quest_template` SET `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 11404;
        UPDATE `quest_template` SET `RequestItemsText` = 'This dirt has been recently disturbed. Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.' WHERE `entry` = 11405;
        UPDATE `quest_template` SET `OfferRewardText` = 'So the quartermaster sent you?$B$B<Gil seems relieved.>$B$BTo be honest, we''re running a bit behind here and we''re going to need some help making our goals.$B$B<Gil shudders.>$B$BNone of the men want to brave the wrath of Captain Adams.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11406;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you finished spreading the word about Brewfest?' WHERE `entry` = 11407;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you finished spreading the word about Brewfest? But more importantly, did you let people know about the amazing troll brew?' WHERE `entry` = 11408;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you got a handle on riding racing rams?' WHERE `entry` = 11409;
        UPDATE `quest_template` SET `OfferRewardText` = 'At last, we can finally fish in peace! ''Course, by the time we catch anything, the expedition''ll arrive and claim it all for themselves.$B$BYou have our thanks, $N. Don''t be a stranger ''round here.', `RequestItemsText` = 'I''m itching to try out the new bait.$b$bHave you had any luck with Frostfin?' WHERE `entry` = 11410;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you see the mess that goblin made? I hope you didn''t do too much reckless off-roading.' WHERE `entry` = 11412;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff? Got something for me?' WHERE `entry` = 11413;
        UPDATE `quest_template` SET `RequestItemsText` = '<A low growl rises from Ulfang''s throat.>$B$BBjomolf and Varg are not dead!' WHERE `entry` = 11415;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ulfang howls loudly at your defeat of his great eagle enemy.>$B$BThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.$B$BLet us not waste the sacrifice that she has made for us. Here, eat them!' WHERE `entry` = 11416;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ulfang howls loudly at your defeat of his great eagle enemy.>$B$BThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.$B$BLet us not waste the sacrifice that she has made for us. Here, eat them!' WHERE `entry` = 11417;
        UPDATE `quest_template` SET `OfferRewardText` = 'You saw a nest, with hatchlings? Hmm... so our "he" is actually a "she," eh?$B$BI guess that settles it. I suppose I wouldn''t want to move a nest full of hatchlings just because of a new neighbor, either.$B$B<Gil favors Trapper Jethan with a mock glare.>$B$BI''m sure we''d get along just fine if ol'' Jethan would stop trying to make a trophy of her.', `RequestItemsText` = 'Did Aderan''s charm work?' WHERE `entry` = 11418;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is that an "Honorary Brewer" stamp you''ve got on your hand?' WHERE `entry` = 11419;
        UPDATE `quest_template` SET `OfferRewardText` = '<Zorek flips through the manual.>$B$BHrm, interesting...$B$BAccording to the manual, the vrykul have a special tool that allows them to control the harpoon guns with deadly accuracy. It looks a bit like the wheel of one of our ships. Furthermore, it''s portable and seems to plug into the harpoon guns like a key. We need to get our hands on one of those!' WHERE `entry` = 11420;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $N! You took out a good chunk of their dragon riders and really pissed off their leadership.$B$BAre you ready to head back to Valgarde and report the good news to Zorek? If so, I''ve got a crazy idea!\n', `RequestItemsText` = 'Is Wyrmskull up in flames?', `CompleteEmote` = 6, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 6, `OfferRewardEmote4` = 5 WHERE `entry` = 11421;
        UPDATE `quest_template` SET `OfferRewardText` = '<Reaching out to take his son''s trident from you, Old Icefin''s hand shakes a little. Could it be that the aged murloc is grieving?>$B$B<Is that just extra moisture pooling at the base of his eye?>', `RequestItemsText` = '<One of Old Icefin''s dead fish-like eyes studies you, clearly looking for signs of his son''s trident.>' WHERE `entry` = 11422;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is of tremendous value, $N.  I must renew my efforts in salvaging and translating vrykul texts.$B$BDon''t get me wrong.  Our enemies need to be destroyed... their ancient knowledge doesn''t.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 11423;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hmmmmph... these will do for now.  There seems to be some oddness to them.$B$BI tell ya - I''ve handled body parts for years now and never have I had such a weird feeling in my stomach.  Anyway, a deal is a deal.  Here''s your payment.', `OfferRewardEmote1` = 396 WHERE `entry` = 11424;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lieutenant Icehammer takes the harpoon control mechanism from you.>$B$BAh, you come bearing gifts!', `CompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 11427;
        UPDATE `quest_template` SET `OfferRewardText` = 'My heart broke when I learned the keepers had turned against us. Once, we considered them our brothers and our closest friends.$B$BI grieve for the brothers and sisters we have lost, but without your help, there would be no hope for our future. You will always be welcome among us, $N.', `RequestItemsText` = 'Have you rid the Twisted Glade of Keeper Witherleaf?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11428;
        UPDATE `quest_template` SET `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11429;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11430;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were ya drunk enough to see the little buggers?' WHERE `entry` = 11431;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did what had to be done. Though some might consider it dishonorable to slay the helpless, in this case you would have been a fool to have done otherwise.$B$BAnd we certainly couldn''t have just left them standing there to be ritually wakened, now could we?$B$BIt was a brave thing you did for all of us down in those catacombs, $N.', `RequestItemsText` = '$N, I find it implausible that you have dealt with enough of the dormant vrykul. Come back when you have done so.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11432;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did what had to be done. The unwise might consider it dishonorable to slay the helpless while they awaken, but in this case you would have been a fool to have done otherwise.$B$BAnd we certainly couldn''t have just left them standing there to be ritually wakened, now could we?$B$BIt was a brave thing you did for all of us down in those catacombs, $r.', `RequestItemsText` = 'I find it unlikely that you have dealt with enough of the dormant vrykul. Come back when you have done so.', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11433;
        UPDATE `quest_template` SET `OfferRewardText` = 'You are insane, $N! What kind of degenerate would actually launch themselves from a harpoon gun as a method of travel?$B$BBut I guess you need to be a little crazy to pull off what you did up there on the bluffs! Fantastic work! We''ve gotten word that the Dragonflayer leader, Ingvar, is furious! Maybe one day you''ll be ready to stomp his face into the dirt - in the name of our beloved Alliance.', `RequestItemsText` = '<Zorek raises an eyebrow at you.>', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11436;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $n.  Have you been perfecting your fire fighting techniques?  Don''t forget about the practice area to the south!' WHERE `entry` = 11439;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $n. Have you been perfecting your fire fighting techniques? Don''t forget about the practice area to the west!' WHERE `entry` = 11440;
        UPDATE `quest_template` SET `IncompleteEmote` = 1, `CompleteEmote` = 1 WHERE `entry` = 11441;
        UPDATE `quest_template` SET `OfferRewardText` = '<Stanwad takes the bundle from you and begins sorting the data.>$B$BWow. How many people did you say died to get this information?$B$B<Stanwad shakes his head.>$B$BYou''ll be happy to know that what McSorf and his crew of bumbling imbeciles discovered is an ancient recipe for tundra stew. Did he not notice the icons of common vegetables and the pictograph of a humanoid mouth chompin'' down on said veggies? You don''t need a damned cipher to break this code!', `RequestItemsText` = '<Stanwad grumbles.>' WHERE `entry` = 11448;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you dowsed any fires, $n? The training area is west of Brill.' WHERE `entry` = 11449;
