        UPDATE `quest_template` SET `OfferRewardText` = 'Orfus is a good tuskarr - one of our strongest warriors. I knew he would not let us down.$B$BAllow me to see what it is that you have brought.', `CompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11507;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yarr, matey. Grezzix never did like to get his hands dirty! A pirate''s life for Grezzix is a good one, so long as Grezzix doesn''t have to do any of the work.$B$BI''ve seen those artifacts. It''s the reason I''m here and not at Scalawag myself! Bad, bad things those are...$B$BHey, it''s your life though, right? You wanna get inside Scalawag and Grezzix can help.', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 5 WHERE `entry` = 11508;
        UPDATE `quest_template` SET `OfferRewardText` = '<Harry raises an eyebrow at you.>$B$BSo you''re like me, eh? A little eccentric.$B$B<Harry whispers.>$B$BNobody dresses like that around here.$B$BAbout those artifacts... Everyone that came into contact with that stuff has ended up dead, missing or both.$B$BIf you''re still interested in learning more, I can help - but it''ll cost you.$B$B<Harry winks.>$B$BYou scratch my back and I''ll try to not stick a dagger in yours.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11509;
        UPDATE `quest_template` SET `OfferRewardText` = '<Harry takes the crystal from you and gently pets it.>$B$BOh my precious! Did the big, mean whale hurt you? It''ll be ok. I''ll never let you out of my sight again!$B$B<Harry looks up at you.>$B$BSo, where were we?', `CompleteEmote` = 6, `OfferRewardEmote1` = 275, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 11510;
