        UPDATE `quest_template` SET `OfferRewardText` = 'I will not say that I am pleased to ask you to do such things on our behalf. It is all we can do to prepare quickly for our departure, though we know not yet where we go.$B$BMy sorcerers tell me that you are here to save the land from He Who Walks in Shadow.$B$BI trust that you will save the peoples of the land as well.', `RequestItemsText` = 'The natural balance has been tipped over and over of late.$B$BI hope that you will be able to help us survive the upheaval of our way of life.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 11958;
        UPDATE `quest_template` SET `OfferRewardText` = 'Loguhn''s honorable sacrifice at your hands is exactly what my people need. Now we will make the most of the wolvar in-fighting for his place.$B$BIt will have to be enough.', `RequestItemsText` = 'Is that Loguhn''s blood or your own, $r?', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 11959;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, I guess you saved plenty of them. Thank you, $r.$B$BNow the wolvar will have a chance of surviving along with us. If we survive at all, that is.$B$BDo you think that you could return tomorrow so that we can save more of the pups?', `CompleteEmote` = 6, `OfferRewardEmote1` = 2 WHERE `entry` = 11960;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!$B$BTake this blossom, $n.  Take it, and leave me be... I must attend to this precious fuel...', `OfferRewardEmote1` = 2 WHERE `entry` = 11964;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you rallied the survivors, $N?' WHERE `entry` = 11965;
