        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 12129;
        UPDATE `quest_template` SET `OfferRewardText` = '<Raegar wipes his forehead with the back of his hand.>$B$BOh, no. This is going to be harder than I thought. These things don''t have serial numbers or anything, do they?$B$BNever a gnome around when you need one...', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12130;
        UPDATE `quest_template` SET `OfferRewardText` = '<Raegar takes the batteries from you.>$B$BExcellent! We should be all ready to go.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12131;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12132;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you taken care of the hunters in the village yet, $N?' WHERE `entry` = 12134;
        UPDATE `quest_template` SET `RequestItemsText` = '$N, you promised to save the children!' WHERE `entry` = 12135;
        UPDATE `quest_template` SET `OfferRewardText` = '<Gort takes the tome from you and begins reading.>$B$BWHAT! This can''t be right. I''ve known some of these orcs for years!$B$BLeave me, $N. I have much work to do and many traitors to execute.$B$BTake one of these items for your trouble. You''ve done a great service for the Horde this day.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 2, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1 WHERE `entry` = 12136;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have done well.$b$bPlease, sit and listen. There are many things we must discuss.', `OfferRewardEmote1` = 1 WHERE `entry` = 12137;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12138;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do not waste time, $N. Angrathar awaits!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12140;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 12141;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you finish off those pests?' WHERE `entry` = 12142;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done?' WHERE `entry` = 12143;
