        UPDATE `quest_template` SET `RequestItemsText` = 'You not a real mon til you killed a dragon... mon.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12145;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12146;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 12147;
        UPDATE `quest_template` SET `CompleteEmote` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 12148;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you defeated the magnataur?', `OfferRewardEmote1` = 1 WHERE `entry` = 12149;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get the name?  Do you know who the magnataur warlord is?', `OfferRewardEmote1` = 1 WHERE `entry` = 12150;
        UPDATE `quest_template` SET `OfferRewardText` = 'You are formidable indeed.$B$BWith Grom''thar the Thunderbringer gone, we can leave the remaining magnataur to fight among themselves and turn our attentions back towards more prominent threats.$B$BImpressive work, $c. ', `CompleteEmote` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 12151;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is done.$b$bYour selflessness has brought eternal peace to many souls, ending eons of misery.$b$bMay this act lighten your own soul and lessen your burdens, for I see that there are yet many perils you must face.$b$bFarewell, $n.', `RequestItemsText` = 'Has Jin''arrak been defeated, $N?', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 12152;
        UPDATE `quest_template` SET `OfferRewardText` = 'It worked?$B$B<Raegar clears his throat.>$B$BI mean... of course it worked! This is incredible!$B$BYears from now, Explorers'' League initiates will hear the story of how Raegar Breakbrow, $N, and some hunk o'' junk golem defeated the thane of Dun Argol!', `RequestItemsText` = 'Were you able to get past the iron thane''s defenses?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12153;
        UPDATE `quest_template` SET `OfferRewardText` = '<Raegar nods approvingly.>$B$BI can''t stand to see explosives go to waste and it''ll set our enemies back for sure.', `RequestItemsText` = 'Have you disabled the power source for their runeforges?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12154;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you put my friends to rest yet, $N?' WHERE `entry` = 12159;
        UPDATE `quest_template` SET `OfferRewardText` = 'Curse our luck.  We find the one functioning mine this side of the hills and it''s full of Scourge.$B$BNo offense, friend.  But that survivor you found sounds like he''s been a little traumatized due to losing his friends.  Arugal''s been dead for years... I even saw his grave once.' WHERE `entry` = 12160;
        UPDATE `quest_template` SET `OfferRewardText` = 'We got him good, $N.  But not good enough.$B$BOne thing''s for sure... we won''t be seeing him around these parts any longer.', `RequestItemsText` = 'It''s good to see you, $N.' WHERE `entry` = 12164;
        UPDATE `quest_template` SET `OfferRewardText` = 'So Tormak''s going to go ahead with the plan? I suppose he wouldn''t have sent you if he didn''t.$B$BOh, bother... Now how am I going to figure out how to put this together under all this pressure?' WHERE `entry` = 12165;
        UPDATE `quest_template` SET `RequestItemsText` = 'It is a shame that we cannot heal the bears and elk that have fallen victim to the Scourge presence.$B$BAt least we can prevent the taint from spreading further.' WHERE `entry` = 12166;
        UPDATE `quest_template` SET `RequestItemsText` = 'I sense something foul is near.$B$BIt is upon your person! What is it, $N?', `CompleteEmote` = 6 WHERE `entry` = 12168;
        UPDATE `quest_template` SET `RequestItemsText` = 'I sense that High Cultist Zangus yet lives.$B$BIs there something wrong, $N? Perhaps you need to rest first?' WHERE `entry` = 12169;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you slain the Alliance dogs? Victory must be ours!' WHERE `entry` = 12170;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you attuned? You mustn''t lie about this, $N.$B$BIf you fail to prepare yourself properly, and I teach you the spell, the first time that you cast it will be the last time anyone will ever see you!' WHERE `entry` = 12172;
        UPDATE `quest_template` SET `OfferRewardText` = 'Just who do you take me for?  These hides smell of flour!$B$BThis is a complete insult to the Horde!' WHERE `entry` = 12178;
        UPDATE `quest_template` SET `OfferRewardText` = '<Mountaineer Kilian listens as you relate what the captive prospectors told you.>$B$BThey mentioned Loken and a war against stone giants? You''re certain?$B$BSo Raegar''s instincts were right. We have to find a way to get in there and learn more about their plans.', `RequestItemsText` = 'Did you locate the missing prospectors?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12180;
        UPDATE `quest_template` SET `RequestItemsText` = 'You are the delivery $g boy:girl;?' WHERE `entry` = 12182;
        UPDATE `quest_template` SET `OfferRewardText` = '<Kilian takes the uniform from you.>$B$BThis should do. I won''t have time to sew on a little patch with ''$N'' embroidered on it or anything, but anyone looking closely at you should be convinced that you''re an overseer by the time we''re done with you.', `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12183;
        UPDATE `quest_template` SET `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12184;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did the disguise work?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12185;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well now! Good ol'' Prigmon sent ya did he?$b$bThis should make fer some mighty fine eatin''. Needs just a couple things...', `OfferRewardEmote1` = 5 WHERE `entry` = 12190;
        UPDATE `quest_template` SET `RequestItemsText` = 'Chug from the mug, then chuck the mug at S.T.O.U.T. I think he can withstand the pounding. I wouldn''t have stol.. er... built him if he couldn''t!' WHERE `entry` = 12191;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff?  Got something for me?' WHERE `entry` = 12193;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff?  Got something for me?' WHERE `entry` = 12194;
        UPDATE `quest_template` SET `OfferRewardText` = '<Rokar wipes his forehead with the back of his hand.>$B$BOh, thank the Light. He was threatening not to feed me until you returned. Let''s sort through this pile of parts and see what we can make.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12196;
        UPDATE `quest_template` SET `OfferRewardText` = '<Rokar takes the batteries from you.>$B$BThese are low, but they''ll be enough to start up the golem. He''s nowhere near ready for battle, though.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12197;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, now Tormak can''t complain anymore. This baby''s as ready as I can make it.$B$BAfter you tear your way through Dun Argol with it, that overgrown cow''ll have to release me.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12198;
        UPDATE `quest_template` SET `OfferRewardText` = 'So the prospector made good on his promises? Good. I was beginning to wonder if all of this scrounging for bits of metal and stealing building materials would amount to anything.$B$BIt''s a shame he''s of no further use to us.', `RequestItemsText` = 'Please tell me it worked...', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12199;
        UPDATE `quest_template` SET `OfferRewardText` = 'I do believe that the blight is now ready for a field test. Fortuitously, the dread citadel, Naxxramas, is laying siege to Wintergarde Keep. From beneath the very earth that Wintergarde was built upon rise the living dead, eager to do the bidding of Kel''Thuzad.$B$BThe Alliance are, of course, outmanned and outgunned. The people laid to rest in the Wintergarde Mausoleum awaken, hungering for flesh!$B$BPerhaps we shall give them a taste of the blight, yes?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 12200;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12201;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12202;
        UPDATE `quest_template` SET `OfferRewardText` = 'So he means to foment civil war between the factions of the titans'' creation? Why does this titan city of Ulduar mean so much to him? I suppose this is what Kurun and his giants are hoping to prevent.$B$BWell, I doubt we''re in a position to keep the giants from fighting each other, but we can find a way to use this to our advantage. I must inform our leaders at once.', `RequestItemsText` = 'What did you learn of Loken?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12203;
        UPDATE `quest_template` SET `RequestItemsText` = 'What did you find?', `DetailsEmote1` = 1 WHERE `entry` = 12204;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very well done, $r. I trust that you were cleverly vicious in your slaying?$B$BLet''s see, how much I can offer you from the coffins... er, excuse me, coffers?', `RequestItemsText` = 'Are you here to waste my time, $Gboy:girl;, or did you fulfill my vendetta against the Scarlet Onslaught?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 5 WHERE `entry` = 12205;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you do it?$B$BHey, I forgot to tell you that you probably shouldn''t let any of that stuff get on you! It''s nasty, and you''ll never get the stains out, let alone have a hell of a time healing the bubbled-away fleshy bits.' WHERE `entry` = 12206;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 12207;
        UPDATE `quest_template` SET `OfferRewardText` = 'You do not smell so fresh now, new meat.$B$BVery well, all of this will do. By what name might I call you, $c?', `RequestItemsText` = 'I''ll take what armor and weapons you can steal for me, new meat.$B$BThough they''ll be of inferior quality to what I can make here, it''s better than nothing.', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 12209;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 6 WHERE `entry` = 12210;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh good! For a moment I thought I was going to have to test the rats out on someone to make sure that they weren''t defective.$B$BProgress, finally!', `RequestItemsText` = 'Well? Success I assume?$B$BDon''t tell me that they have some kind of protection against being eaten by rats?!', `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 25, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 12211;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 12212;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you done what I asked of you, $N?', `DetailsEmote1` = 1 WHERE `entry` = 12213;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, nothing makes me happier than a job well done.$B$BYou''ve done Venomspite a great service in acquiring these horses, $c.', `RequestItemsText` = 'I''m sure glad that you came around. I was afraid that I was going to have to go down there and rustle them up myself.', `DetailsEmote1` = 3, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 11, `OfferRewardEmote3` = 1 WHERE `entry` = 12214;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work, $c.$b$bThis should help ensure that the wildlife in these parts ends up where it should - roasting over our fires.', `RequestItemsText` = 'A few less worgs hunting these forests, I trust?', `OfferRewardEmote1` = 1 WHERE `entry` = 12215;
        UPDATE `quest_template` SET `OfferRewardText` = 'Outstanding!$b$bOur stores are nearly replenished now. You''ve done your part, $n.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 12216;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed your task, $c?', `OfferRewardEmote1` = 1 WHERE `entry` = 12217;
        UPDATE `quest_template` SET `RequestItemsText` = 'This test will be the final experiment in the series, $N.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 12218;
        UPDATE `quest_template` SET `OfferRewardText` = 'The slime is not natural, $N.  Its very nature is corrupt and... evil.$B$BWe must find out more.', `OfferRewardEmote1` = 1 WHERE `entry` = 12219;
        UPDATE `quest_template` SET `OfferRewardText` = 'The energy in the orb is... overpowering...$B$BA dark force has tainted the ground near Vordrassil''s remains.  We will need to investigate more.', `RequestItemsText` = 'Have you done what I asked of you, $N? ', `OfferRewardEmote1` = 1 WHERE `entry` = 12220;
        UPDATE `quest_template` SET `OfferRewardText` = '<Doctor Malefious looks through the contents of the package.>$B$BGlorious! Exactly to specifications!$B$BHere is your payment, $N. Keep what you''ve seen and done to yourself. This work is all classified - information is given out on a need to know basis.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12221;
        UPDATE `quest_template` SET `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12222;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you done the deed?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12223;
        UPDATE `quest_template` SET `OfferRewardText` = 'Lok''tar ogar! I have heard much about you, $N. Your battle scars run deep - a testament to your dedication and power!$B$BWith the flanking attacks of the Lich King crushed in both the west and east, only the forces at the gate remain. We gain ground each day, soon to break through this wall and into Icecrown!$B$BOnce we stop the skeletal dragons, Highlord Fordragon and I will take the field.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12224;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did what!!!$b$bThose were Amberseeds! And that was an entire harvest''s worth!$b$bThose magical seeds may have been the answer to our food crisis. Believe me when I tell you, $n, you''re going to make this right!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 12225;
        UPDATE `quest_template` SET `OfferRewardText` = 'These should do just fine...$b$b<Anderhol deftly twists the stalks, collecting their slick fluids in a tiny vial.>$b$bThere we go, now it''s time to get down to business.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 12226;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, $n? Everything come out okay?$b$bHmm, looks like we caught ''em just in time....', `OfferRewardEmote1` = 6 WHERE `entry` = 12227;
        UPDATE `quest_template` SET `OfferRewardText` = '<The deathguard rubs his hands together in anticipation.>$B$BExcellent. Their loss is my... our gain!$B$BYou didn''t have trouble with any of these along the way? Some of them look rather unstable. I may be undead, but I value my existence!', `RequestItemsText` = 'You''d think that they''d let me make use of the blight spreaders... maybe load them up with something nasty to destroy the ballistae.$B$BBut no, they tell me that they''re only for special missions.$B$BWhatever!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 25, `DetailsEmote4` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 11, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 12230;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you spoken to Ursoc''s children yet, $N?' WHERE `entry` = 12231;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh happy day!$B$BBy not using the time and resources of the apothecaries to get the job done, I''m sure to attract the attention of the high executor!$B$BThinking outside the box, that''s what I''m all about. Yes, yes, you had a hand in helping too.$B$BHere, if I give you something will you promise to not mention your part in all of this?', `RequestItemsText` = 'Someday I''ll be lead deathguard!$B$BSomeday....', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 12232;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you take too long, their daily plans will change, and we may have to start over again.$B$BDon''t take too long!' WHERE `entry` = 12234;
        UPDATE `quest_template` SET `OfferRewardText` = '<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>', `RequestItemsText` = 'You''ve returned. Did you succeed?', `DetailsEmote1` = 1 WHERE `entry` = 12236;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hurry, $N! You need to save the helpless villagers!' WHERE `entry` = 12237;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have word from the spy mistress?$B$B<The agent looks around to make sure that no one is watching as she puts down her shovel.>$B$BLet me see those plans.', `RequestItemsText` = '<The agent eyes you up and down, and then silently motions you over.>$B$BDon''t blow my cover, $c!', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 12239;
        UPDATE `quest_template` SET `OfferRewardText` = 'I knew my sister wouldn''t let us down.$B$BWell done, $N. The Onslaught''s lumbermill will be out of commission for a while, which means no new construction or ballistae.$B$BThanks for helping me to live up to the family name.', `RequestItemsText` = 'I miss my sister, $N. I hope she''s well.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 6, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 1 WHERE `entry` = 12240;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $N.  I''ll take those from you.$B$BThe corruptive power of these seeds is dangerous.  I must destroy them right away.', `OfferRewardEmote1` = 1 WHERE `entry` = 12242;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ahhahahahahahahahaha!$B$BWithout their rutters, they''ve got nowhere to run to now.$B$BLooks to me like the end of the Scarlet Onslaught, and just when they were getting started. How sad.$B$BHeh.', `RequestItemsText` = 'Please do NOT tell me that their sails were somehow protected from my burning water!$B$BI''d hate to have to test it out here again.', `DetailsEmote1` = 25, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `DetailsEmote4` = 11, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 12243;
        UPDATE `quest_template` SET `OfferRewardText` = '<Synipus whistles.>$b$bOh, she''s a beauty! We''ll fix her up nice.$b$bIf you''re short on things to do, go talk to Gordun and get a ride down to Venture Bay. They''re sure to need a hand.$b$bOh, and while you''re there, use these keys on a Refurbished Shredder. Wait ''til ya see what these babies can do when they''re cleaned up!', `RequestItemsText` = 'No time for chit-chat. These shredders might tip the balance for the alliance!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 12244;
        UPDATE `quest_template` SET `OfferRewardText` = 'What? You were expecting us to have you rescue them?$B$BNow why would we do that when they have a proven track record of getting themselves captured in the first place?$B$BNorthrend is a cold place, young $N. I suggest that you adjust to it.', `RequestItemsText` = 'It''s simple really. You''re sent out to kill four incompetent fools that are likely to blab all of our secrets anytime now, and you go out and do it.$B$B<The high executor puts on an unholy grin.>', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 25 WHERE `entry` = 12245;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you spoken to Orsonn and Kodian yet?' WHERE `entry` = 12247;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve returned. Did you succeed?' WHERE `entry` = 12249;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $N.  I''ll take those from you.$B$BThe corruptive power of these seeds is dangerous.  I must destroy them right away.' WHERE `entry` = 12250;
        UPDATE `quest_template` SET `OfferRewardText` = 'They knew all of that? And who the hell is this Grand Admiral Westwind that he spoke of?!$B$B<The high executor grumbles to himself about hating surprises.>$B$BBetter that we know than have to guess. I hope that you left your... er, my mark.', `RequestItemsText` = 'What news do you bring? Success, no doubt?', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 12252;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you rescued our trapped villagers?' WHERE `entry` = 12253;
        UPDATE `quest_template` SET `OfferRewardText` = 'A newly scribed blessing at the back of the book you say?$B$B<The agent glances over your shoulder as you flip to the page at the end.>$B$BDamn it all! That''s the high abbot''s handwriting! I''d stake your life on it.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 6, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 2000 WHERE `entry` = 12254;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you overcome the thane? We cannot risk leaving him in power.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12255;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you done the deed?' WHERE `entry` = 12257;
        UPDATE `quest_template` SET `RequestItemsText` = 'Put them out of their misery, $N.' WHERE `entry` = 12258;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you overcome the thane?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12259;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 12260;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you placed the ward?', `OfferRewardEmote1` = 1 WHERE `entry` = 12261;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see the blood on your hands... it is done then?', `OfferRewardEmote1` = 11 WHERE `entry` = 12262;
        UPDATE `quest_template` SET `RequestItemsText` = 'I tire of this pestilence.', `OfferRewardEmote1` = 1 WHERE `entry` = 12263;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hearing their screams... watching the last life fade from their wretched bodies... it''s invigorating, is it not?$B$BI relish it.', `RequestItemsText` = 'I cannot help but wonder whether they are naive enough to think that I will abide this or if they are simply suicidal.', `OfferRewardEmote1` = 6 WHERE `entry` = 12264;
        UPDATE `quest_template` SET `RequestItemsText` = 'Power wasted on the weak and useless.$B$BShow me a being worth of the life and magic they have been gifted, and then perhaps we can talk of waste before extinguishing their presence.$B$BDon''t worry, I''ll wait.', `OfferRewardEmote1` = 1 WHERE `entry` = 12265;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, it''s you.$B$BI had hoped Serinar would simply return himself once the task was done... I suppose he''s distracted by something or another to kill. He''s missing out on a gloriously messy battle!$B$BAre you still here? I''m done with you.', `OfferRewardEmote1` = 1 WHERE `entry` = 12266;
        UPDATE `quest_template` SET `RequestItemsText` = 'You are quite an effective tool, $c. Your hand in this purging is appreciated.' WHERE `entry` = 12267;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes indeed. These should do the trick...$b$bThere. One more shredder ready for the fight. Thanks, $n.', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 12268;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12269;
        UPDATE `quest_template` SET `RequestItemsText` = 'Get me those shredders yet, $c?' WHERE `entry` = 12270;
        UPDATE `quest_template` SET `OfferRewardText` = 'LeCraft had it you say? That makes sense.$B$BI recognize it from my youthful days as a torturer in the court of King Terenas of fallen Lordaeron. It''s known as a rod of compulsion.$B$B<The high executor wrings his hands together in evil anticipation of what''s to come.>$B$BI have an idea for how we can make good use of it!', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmoteDelay3` = 1000 WHERE `entry` = 12271;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12272;
        UPDATE `quest_template` SET `OfferRewardText` = '<You think you see just the hint of a smile cross Wroth''s face before quickly disappearing.>$B$BYou''re now my favorite $c, $N. If you have a mind to, I''d like you to think about joining up as an officer in the Hand of Vengeance.$B$BWe can start you out as a deathguard, and in a few decades I think you have what it takes to make junior executor!$B$BNo? Well don''t be too hasty... take your time and mull it over.', `RequestItemsText` = 'Well?!', `DetailsEmote1` = 5, `DetailsEmote2` = 25, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 25, `OfferRewardEmote4` = 1, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 12273;
        UPDATE `quest_template` SET `OfferRewardText` = 'What the hell is going on here?!$B$BHe jumped on his own? You''re certain that you didn''t push him?$B$B<The agent narrows her eyes at you.>$B$BFine. Clearly there''s much more going on in this place than we first thought. ', `RequestItemsText` = 'What did you find out? Have you even talked with him yet?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `DetailsEmote4` = 1, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 1, `OfferRewardEmoteDelay3` = 1000 WHERE `entry` = 12274;
        UPDATE `quest_template` SET `RequestItemsText` = '<Quarterflash nods.>$B$BHe was a good gnome, one of our best. Slinkin will be missed.' WHERE `entry` = 12277;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have your membership forms filled out?' WHERE `entry` = 12278;
        UPDATE `quest_template` SET `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12279;
