        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12282;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 12283;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is that Alliance blood on your weapon, $r?' WHERE `entry` = 12284;
        UPDATE `quest_template` SET `OfferRewardText` = 'Let''s see them bring her back to life without her head!$B$B<The high executor''s laugh draws a number of furtive glances.>$B$BI''m a little concerned that you let this grand admiral get away, but you''re still the $g hero : heroine; of the day, $N!$B$BTake your pick... you''ve earned it!', `RequestItemsText` = 'Should I tell my forces to begin making our way toward Agmar''s Hammer?$B$BOr did you manage kill the high general?', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 1, `DetailsEmote4` = 5, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 12285;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you healed our wounded yet, $N?' WHERE `entry` = 12288;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $n.$b$bYou''ve bought us some time here, though likely no more than a day. Nevertheless, the Alliance is grateful for your efforts.', `RequestItemsText` = 'How goes the fight, $N?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12289;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12290;
        UPDATE `quest_template` SET `RequestItemsText` = 'I have enough murkweed to make more elixirs, $N.' WHERE `entry` = 12291;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s locked, isn''t it?  It looks pretty ordinary.$B$B<Lieutenant Dumont Shakes the chest, producing a rattling wooden sound.>$B$BNo matter, I suppose.  If this gets us the edge we need against the Horde, then I could care less if the cure for the Plague was in there. ' WHERE `entry` = 12292;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 2 WHERE `entry` = 12293;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent news, $N.  With the locals'' help we''ll have the logistical support we need to outmaneuver the Horde in this region.$B$BI have further tasks for you if you''re interested.', `OfferRewardEmote1` = 1 WHERE `entry` = 12294;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s good to finally meet you, $N!  We''d heard about you up here.  Welcome to Silverbrook.$B$BThese trappers are a great bunch of lads and lasses.  Hardy people, they know the lay of the land really well.  You''ll find it''s a great thing that we finally won them over to our side.' WHERE `entry` = 12295;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wonderful!$b$bThe Alliance shall live to see another day, in part due to your diligence.$b$bPlease accept my thanks, friend.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 12296;
        UPDATE `quest_template` SET `OfferRewardText` = '<Greer lifts his glasses onto the top of his head and reads the note, looking back up at you curiously when he''s done.>$B$BYou will have my fastest gryphon! This information must be delivered to High Commander Wyrmbane at once!\n', `CompleteEmote` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 12297;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12298;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 2 WHERE `entry` = 12299;
        UPDATE `quest_template` SET `RequestItemsText` = 'The people in Silverbrook... they''re not what they seem.' WHERE `entry` = 12300;
        UPDATE `quest_template` SET `OfferRewardText` = 'Who''s there?  Are you here to kill me?$B$BPlease!  You don''t have to do this!' WHERE `entry` = 12302;
        UPDATE `quest_template` SET `OfferRewardText` = 'Can''t you just see it now, $c? It''ll be the vacation spot of Northrend!$B$BWhat do you think of the name, "Hansen''s Cove", or maybe "$N Bay"? Kind of catchy, don''t you think?', `OfferRewardEmote1` = 6 WHERE `entry` = 12304;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do ya have your membership forms filled out?' WHERE `entry` = 12306;
        UPDATE `quest_template` SET `OfferRewardText` = '<Katja reels away from you nervously.>$B$BThank you, $N.  You didn''t get any wolfsbane on you, did you?  I''ve got these... allergies that act up once in a while.', `RequestItemsText` = 'Yes, $c?' WHERE `entry` = 12307;
        UPDATE `quest_template` SET `OfferRewardText` = 'Worgen.  Blasted, Light-forsaken, filth-ridden worgen.$B$BIt''s time we showed the locals what us civilized folk do with beasts like them.', `RequestItemsText` = 'You made it back. I was a worried about you, $N.', `OfferRewardEmote1` = 66 WHERE `entry` = 12308;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s a shame those trappers turned out to be... afflicted.  We sure could''ve used a few more fighting men.$B$BMay the poor souls rest in peace.', `RequestItemsText` = 'Is it done, %N?' WHERE `entry` = 12310;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is Amarion dead?' WHERE `entry` = 12311;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12312;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you slain Captain Zorna?' WHERE `entry` = 12314;
