        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12319;
        UPDATE `quest_template` SET `RequestItemsText` = 'You come from high command, my $g son:girl;?', `CompleteEmote` = 6 WHERE `entry` = 12320;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you smoked out the last of the Venture Company guys yet?' WHERE `entry` = 12323;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you smoked out the last of the Venture Company vermin yet?' WHERE `entry` = 12324;
        UPDATE `quest_template` SET `RequestItemsText` = 'Name''s Cash. Ambo Cash. And the pleasure is all yours.' WHERE `entry` = 12326;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N?', `OfferRewardEmote1` = 1 WHERE `entry` = 12327;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good.  These will do just fine.$B$BI will have the potion ready for you in no time at all.' WHERE `entry` = 12328;
        UPDATE `quest_template` SET `OfferRewardText` = 'I was wondering when you''d turn up.  Think you can give me a hand here?' WHERE `entry` = 12329;
        UPDATE `quest_template` SET `OfferRewardText` = 'That... that was close.$B$BWe need to save Anya.  Now!', `RequestItemsText` = 'I''m glad to see you in one piece.' WHERE `entry` = 12330;
        UPDATE `quest_template` SET `OfferRewardText` = 'Incredible! Let me just say that I continue to be amazed by what you younger races seem capable of.$B$BWe are indebted to you. Will you come back and help us again tomorrow?', `RequestItemsText` = 'How fares the fight? Are we pushing them back?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 12372;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re back.  And you''re alive.$B$BNow what''s this nonsense about worgen?', `RequestItemsText` = 'Did you complete your task? If not, what are you doing here?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12412;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed your task yet, $N?', `DetailsEmote1` = 1 WHERE `entry` = 12413;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get all the mustangs we''ll need?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12414;
        UPDATE `quest_template` SET `OfferRewardText` = '<Soulok nods in approval.>$B$BWell done, $N. We must not let the Alliance gain any kind of advantage.', `OfferRewardEmote1` = 1 WHERE `entry` = 12415;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m glad you''re still with us, $r.' WHERE `entry` = 12416;
        UPDATE `quest_template` SET `RequestItemsText` = 'I started to worry that the Scourge in the shrine had claimed you. It is good that you yet live.' WHERE `entry` = 12417;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve returned! Have you don as I''ve asked of you?' WHERE `entry` = 12418;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dahlia was taken by the Scourge? This is a sad day for all of us.$B$BI will look to finding a new keeper once the shrine is retaken. Thank you for your efforts... the Ruby Dragonshrine is a sacred place to us, and the sacrifices your kind have made will not be easily forgotten.$B$BIt is good to know there are still heroes such as you - I will call upon you one day. Until that day comes, may your adventures be fruitful.', `RequestItemsText` = 'Hello, $r. I sense the presence of my Ruby Brooch. Hand it here.$B$BWhat has become of Dahlia?', `CompleteEmote` = 2, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 12419;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hah!  Is this some sort of joke?$B$BI barely have any use for books I can actually understand.' WHERE `entry` = 12423;
        UPDATE `quest_template` SET `OfferRewardText` = 'Could it be?  The man who wrote this journal feared for his daughters'' lives so he sent them away from Silverbrook.$B$BWe just captured an outcast in the outskirts of town about the same age as the eldest daughter.$B$BListen, $N.  There''s more happening here than meets the eye... we can''t just burn this diary.', `DetailsEmote1` = 1 WHERE `entry` = 12424;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s not over until you or the bear tips over, friend!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 12427;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 12428;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 12429;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fancy footwork, fancy footwork.  You really made quick work of that crazy orc, friend.$B$BOdds were against you seven-to-one; made some nice coin on that one!', `DetailsEmote1` = 1 WHERE `entry` = 12430;
        UPDATE `quest_template` SET `OfferRewardText` = 'What happened today... had to happen.  It doesn''t mean I have to be happy about it.$B$BI''ve freed my people from a tyrant, but I''ve also lost a sister.  I thank you for your help, $N.  I wish to be alone now.', `DetailsEmote1` = 5 WHERE `entry` = 12431;
        UPDATE `quest_template` SET `RequestItemsText` = 'Has that Alliance lumber been burned yet, $c?', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 5 WHERE `entry` = 12432;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ahh yes. That''ll save me hours.$b$bTake this for your trouble, friend. And keep an eye out for more element 115. I''ll take all you can find.', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12433;
        UPDATE `quest_template` SET `OfferRewardText` = 'You must be $N. The queen informed me that you would be coming.$B$BIf you are willing, we are in great need of your assistance.', `OfferRewardEmote1` = 1 WHERE `entry` = 12435;
        UPDATE `quest_template` SET `RequestItemsText` = 'Has that Horde lumber ship been burned yet, $N?' WHERE `entry` = 12437;
        UPDATE `quest_template` SET `RequestItemsText` = 'Are you here to collect a bounty, ally?' WHERE `entry` = 12438;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you faced Bloodpaw?' WHERE `entry` = 12441;
        UPDATE `quest_template` SET `RequestItemsText` = '<Leoric grits his teeth.>$B$BIs that pompous fool dead?' WHERE `entry` = 12442;
        UPDATE `quest_template` SET `RequestItemsText` = 'How''s the hunt going?', `OfferRewardEmote1` = 113 WHERE `entry` = 12444;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m trying to decide at which I''m more surprised... that you actually came to the aid of a Black Dragon or that you''re still in one piece after speaking with Nalice.$B$BHer words drip venom, but I suppose Wyrmrest can keep even our kind in check sometimes.$B$BOr perhaps it''s just the armies of the red dragonflight that are massed around her.', `OfferRewardEmote1` = 1 WHERE `entry` = 12447;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is a disgusting task, but I thank you for doing it.$B$BThe Scourge cannot be permitted to push any further out of the shrine lest all of these lands be overrun.' WHERE `entry` = 12448;
        UPDATE `quest_template` SET `OfferRewardText` = 'In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.$B$BI don''t know a word in your tongue that could express how much this means to my kind. Thank you, $r.' WHERE `entry` = 12449;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dahlia... they turned her?$B$BDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.$B$BYou have honored us with your selfless assistance today, $r. Perhaps not all of the Horde bear the black hearts of their ancestors.  I will send word to the council of what your kind have accomplished here.', `RequestItemsText` = 'You''ve returned! Have you done as I''ve asked of you?' WHERE `entry` = 12450;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 12451;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you done what I asked of you, $N?', `DetailsEmote1` = 1 WHERE `entry` = 12453;
