        UPDATE `quest_template` SET `RequestItemsText` = 'Have you rescued our injured soldiers?' WHERE `entry` = 12457;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12458;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent. Just as I suspected all along. I shall have to attempt to contact Ysera and see if she approves.$B$BIf she can be coaxed from her nightmare, of course.$B$BThank you, $N. You have been indispensable.', `RequestItemsText` = 'What were the results? Are they destroyed?$B$BI need answers!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 12459;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ambassador Golluck sent you?$B$BIf you talk to him again, please let him know that we are very appreciative of his aid. We are fighting battles on far too many fronts.' WHERE `entry` = 12461;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you break yourself off a piece?' WHERE `entry` = 12462;
        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12464;
        UPDATE `quest_template` SET `OfferRewardText` = 'You saw Nozdormu? That doesn''t make any sense.$B$B<Chromie thinks a moment about what you''ve said.>$B$BActually, that''s great news! We had no idea of where or when the Lord of Time had gone to. We just knew that he had disappeared to deal with very important matters.$B$BSo, even though the leader of the Infinite Dragonflight wasn''t revealed, you''ve discovered that Nozdormu is alive and well, and fighting back against them!$B$BThank you, $N. I''ll be seeing you soon!', `RequestItemsText` = 'What news do you bring? What happened at the Bronze Dragonshrine?$B$BDid you find out who the leader of the Infinite Dragonflight is?', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 4, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 1 WHERE `entry` = 12470;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 12471;
        UPDATE `quest_template` SET `RequestItemsText` = '<Yorik lets out a sigh of relief.>$B$BWe thought you might not show up, $N.' WHERE `entry` = 12472;
