        UPDATE `quest_template` SET `CompleteEmote` = 6 WHERE `entry` = 12477;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you searched Frostmourne Cavern?' WHERE `entry` = 12478;
        UPDATE `quest_template` SET `RequestItemsText` = 'Assassination work isn''t as glamorous as it''s made out to be.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12481;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N.' WHERE `entry` = 12482;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nothin'' better than watchin'' them shcourge burn... <hic>.$b$bWrote a little shong about it. Wanna hear it? Here goes....', `RequestItemsText` = 'Whatcha got there, $r?' WHERE `entry` = 12484;
        UPDATE `quest_template` SET `RequestItemsText` = '$n, your face has a grim set to it. Do you have dire news?' WHERE `entry` = 12491;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hey $N, your face is all smudged! Have you been to Blackrock Depths?' WHERE `entry` = 12492;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have come seeking my council, mortal. This I know, but do you know what it is that you face?$B$B<Alexstrasza points northward.>$B$BNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.$B$BFrost wyrms, mortal, should be the least of your concerns.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 1 WHERE `entry` = 12496;
        UPDATE `quest_template` SET `OfferRewardText` = 'The bravery of mortals never fails to astound me. Death affixes its cold stare upon you and in return you rise to challenge its assertion! It is why your kind is so loved... and so hated.$B$BEven though the Red Dragonflight is entrenched in a war with Malygos, there is something that we can do to help.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12497;
        UPDATE `quest_template` SET `CompleteEmote` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 12498;
        UPDATE `quest_template` SET `OfferRewardText` = 'My father was right about you, $N. Everything that he said has come to pass - only one final duty remains unfulfilled. I will now lead the Kor''kron to the front line. The time to end this war is at hand. The Lich King''s tyranny ends today!$B$BTake my post now, $N, and stand guard over our forces.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 2, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 66 WHERE `entry` = 12500;
        UPDATE `quest_template` SET `RequestItemsText` = 'What news from our posts, $r?' WHERE `entry` = 12501;
        UPDATE `quest_template` SET `RequestItemsText` = 'Perhaps you could destroy a few more?' WHERE `entry` = 12503;
        UPDATE `quest_template` SET `OfferRewardText` = 'Alright then. We''ll collect up the rest and head back to the stand.$B$BIt''s a shame that we have to leave so soon. Doesn''t quite feel like the job''s done here, and quite frankly, I get the feeling that prophet in front of the altar is going to be big trouble!', `RequestItemsText` = 'I''ll need more of them to report back in than that.' WHERE `entry` = 12504;
        UPDATE `quest_template` SET `OfferRewardText` = '<The dwarf sergeant warily eyes the orders in your hand.>$B$BAre those new orders for me, $g mister : miss;?' WHERE `entry` = 12505;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dead?$B$B<The hexxer''s spirit is visibly lowered at the news you bring.>$B$BThey''ve killed Sseratus and drunk deeply of his mojo; the prophet especially!$B$BWe must figure out a way to put an end to him before he drinks too much more!', `RequestItemsText` = 'What did you see, $r?' WHERE `entry` = 12506;
        UPDATE `quest_template` SET `RequestItemsText` = 'How about killing a few more?' WHERE `entry` = 12508;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent. When combined with the mojo, these fluids will dilute the effectiveness of the mojo without completely eliminating it.$B$BNow, one more thing.' WHERE `entry` = 12510;
        UPDATE `quest_template` SET `OfferRewardText` = 'Saved them all, did you? Outstanding!$b$bMaybe you''d consider sticking around the post here? We could sure use someone like you....', `RequestItemsText` = 'Have you rescued our veterans, $N?' WHERE `entry` = 12512;
        UPDATE `quest_template` SET `OfferRewardText` = '<The hexxer nods his approval.>$B$BHand that fungus over and I''ll mix it up with the mojo and elemental lord fluids.', `RequestItemsText` = 'Do you have all of the fungus?$B$BOh, and watch out for the basilisks lurking over there.' WHERE `entry` = 12514;
        UPDATE `quest_template` SET `OfferRewardText` = 'Amazing! You''ve saved your people and the rest of Northrend from his madness.$B$BUnfortunately there''s more of this insanity occurring up in the higher tiers of Zul''Drak.', `RequestItemsText` = 'Is it over?$B$BDid the modified mojo work?$B$BDid you deliver vengeance for Sseratus by slaying his prophet?' WHERE `entry` = 12516;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see that you have managed to complete a deck of Mages! Congratulations!' WHERE `entry` = 12518;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you master the rhinos, or are you throwing in the towel?' WHERE `entry` = 12520;
        UPDATE `quest_template` SET `CompleteEmote` = 1 WHERE `entry` = 12522;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you dealt with Swindlegrin and his bodyguard?' WHERE `entry` = 12525;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, most excellent! Thank you. The crystals appear to be in fine condition!$B$BI have no doubt that Pestlepot put you up to doing his chores for him. Nevertheless, your assistance in this matter is greatly appreciated!', `RequestItemsText` = 'What''s all this?$B$BBy any chance have you seen my no-good apprentice, Pestlepot?$B$BI sent him on an errand quite some time ago and he has yet to return!' WHERE `entry` = 12527;
        UPDATE `quest_template` SET `RequestItemsText` = 'You still alive! Hardknuckles not eat you yet?$B$BMaybe they eat you later.' WHERE `entry` = 12529;
        UPDATE `quest_template` SET `RequestItemsText` = 'What you want, slave?' WHERE `entry` = 12530;
        UPDATE `quest_template` SET `RequestItemsText` = 'You learn the hunt?' WHERE `entry` = 12533;
        UPDATE `quest_template` SET `RequestItemsText` = 'They tell Zepik you good hunter for not being Frenzyheart.' WHERE `entry` = 12536;
        UPDATE `quest_template` SET `RequestItemsText` = 'Zepik think this go much better with partner. You strong for not Frenzyheart.' WHERE `entry` = 12537;
        UPDATE `quest_template` SET `RequestItemsText` = 'We best hunters of basin!' WHERE `entry` = 12538;
        UPDATE `quest_template` SET `OfferRewardText` = 'Mere footsteps from here lies the Drakkari empire.$B$B<Valus points east.>$B$BFor thousands of years the Drakkari remained isolated, preferring to keep within the boundaries of their sprawling temple cities and ziggurats. It was surprising then, to come upon this wreckage. Further up, beyond the foreboding stairs leading into Zul''Drak, Drak''Tharon Keep lies in ruin. The entire first tier of Zul''Drak, destroyed...$B$BWhy has the Scourge waited until now to attack?  ', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 12542;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, have you consulted the native oracle?' WHERE `entry` = 12544;
        UPDATE `quest_template` SET `OfferRewardText` = 'As you can see, the Scourge war machine presses onward, yet the armies of the Horde and the Alliance remain divided, making for easy prey. It is for this reason that we must remain united.$B$B<Valus is lost in contemplation for a moment.>$B$BThe Argent Crusade has use for a $g man:woman; like you. Perhaps you would be interested in joining our cause? To battle and die at the side of the Ashbringer?', `RequestItemsText` = 'Leave nothing for the Lich King to resurrect!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 6 WHERE `entry` = 12545;
        UPDATE `quest_template` SET `RequestItemsText` = 'Those who would threaten life... have they been dealt with?' WHERE `entry` = 12546;
        UPDATE `quest_template` SET `RequestItemsText` = '<The rune-shaped slot on The Etymidian''s chest appears to glow with faint power.>' WHERE `entry` = 12547;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you tested your skills against the dreadsabers?' WHERE `entry` = 12549;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the tracking?' WHERE `entry` = 12550;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you make the kills?' WHERE `entry` = 12551;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s not enough!$B$B<The sergeant''s voice cracks as he mourns the corruption of his fallen comrades.>$B$BWe must do more to show respect for the memories of those men!', `RequestItemsText` = 'No, $c, you''re not quite done. I know for a fact that there are still necromagi walking around at Kolramas.' WHERE `entry` = 12552;
        UPDATE `quest_template` SET `OfferRewardText` = 'Those''ll do!$B$BNow we''re going to need some raw parts so that I can put the launching device together for you.' WHERE `entry` = 12553;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re the $g hero : heroine; of the hour, $N.$B$B<Moonshard kicks the head away from him.>$B$BYou deserve our deepest respect, and something more I think.' WHERE `entry` = 12554;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yay! You''re the best, $N!$B$BI wasn''t looking forward to being sprayed with Scourge stuff, that''s for sure! I guess it''s going to be hard for those stupid nerubians to spread their evil now!$B$BHow about I give you a little something for saving my skin?', `RequestItemsText` = 'You sure you brought down enough of those things? Do I look like I want the plague?!' WHERE `entry` = 12555;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, yes, that''s a good start.$b$bShould I call upon you to help me with an actual recipe, you''ll need to locate ingredients in a timely manner.$b$bKeep that in mind, $c.$b$bFarewell.', `RequestItemsText` = 'Have you become accustomed to my laboratory, $c?' WHERE `entry` = 12557;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re back, little one. I was beginning to worry about your well-being.' WHERE `entry` = 12559;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $g sir : ma''am;!$B$BI''ll see to it that the commander is apprised of your mission results.', `RequestItemsText` = 'If I may suggest, you might want to take care of a few more of those Drakkari water binders.' WHERE `entry` = 12562;
        UPDATE `quest_template` SET `RequestItemsText` = 'What news from our posts, $r?' WHERE `entry` = 12563;
        UPDATE `quest_template` SET `OfferRewardText` = '<If Zim''Abwa could move his face, Zim''Abwa would make a vicious grin.>', `RequestItemsText` = '<Zim''Abwa stares inscrutably to the north and the south.>' WHERE `entry` = 12565;
        UPDATE `quest_template` SET `RequestItemsText` = '<Zim''Abwa''s stony visage pierces your soul.$B$BZim''Abwa is pleased, but wants you to show more appreciation and respect by giving him more Drakkari offerings.$B$BHe will reward you in kind.>' WHERE `entry` = 12567;
        UPDATE `quest_template` SET `RequestItemsText` = 'Who you? You stink of puppy-men.' WHERE `entry` = 12570;
        UPDATE `quest_template` SET `RequestItemsText` = '<High-Oracle Soo-say seems to stare right through you.>' WHERE `entry` = 12571;
        UPDATE `quest_template` SET `RequestItemsText` = 'Puppy-men play nice now?' WHERE `entry` = 12573;
        UPDATE `quest_template` SET `RequestItemsText` = 'They always want fight! We no want fight, but we need to protect sacred stuffs.' WHERE `entry` = 12576;
        UPDATE `quest_template` SET `RequestItemsText` = 'Soo-say fumbles a bit, but he''s not dumb. I do think he''s been far too forgiving though... the puppy-men are not going to stop or leave us alone. The only way to stop them is to kill them... there is no "peace."$B$B<Moodle puffs up his chest and points to himself.>$B$BThat I am good at.' WHERE `entry` = 12578;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wish I had known how key the pillars and the stones were much earlier... perhaps I could have prevented this.' WHERE `entry` = 12580;
        UPDATE `quest_template` SET `RequestItemsText` = '<The phylactery rests ominously on the ground next to Artruis''s dead form.>' WHERE `entry` = 12581;
        UPDATE `quest_template` SET `OfferRewardText` = 'I know you weren''t traitor thing like others said. We hunt together... I know you better than all of them. Thank you for saving me.$B$BMay sound funny... I not a big fan of big-tongues... but even I feel little bad for big-tongue dying like that though...they fight good enough they deserve fair fight.$B$BYou want to be friends with Frenzyheart again? I think I can convince them that you save me and got the big-tongues good. I no want you to make me look dumb though, so you sure no more big-tongues for you?', `OfferRewardEmote1` = 1 WHERE `entry` = 12582;
        UPDATE `quest_template` SET `OfferRewardText` = '<The specialist steps back a bit when presented with the parts.>$B$BEw, those things are totally gross!$B$BOkay, okay, hand them over and I''ll see what I can do. I probably should have had you take them to a priest first for purification.' WHERE `entry` = 12583;
        UPDATE `quest_template` SET `OfferRewardText` = 'Can you not feel the pure evil of the stuff?$B$BWe must use the expertise and magics at our disposal, combined with the power of the Holy Light, to pierce the veil of iniquity surrounding this tainted ore. We must determine its origins.$B$BQuickly, hand the saronite to me!', `RequestItemsText` = 'Yes, $c?$B$BPlease tell me that you have the saronite that we requested Captain Rupert to acquire?' WHERE `entry` = 12584;
        UPDATE `quest_template` SET `RequestItemsText` = 'What news from our posts, $r?' WHERE `entry` = 12587;
        UPDATE `quest_template` SET `RequestItemsText` = 'Satisfied with the results?' WHERE `entry` = 12589;
        UPDATE `quest_template` SET `RequestItemsText` = 'Care to count ''em up?' WHERE `entry` = 12592;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s about time you got your carcass back here! Thought we''d lost ya to the Scourge - not that it would''ve been a great loss....$b$bIf you''re going to continue to serve the Crusade, you''d best make a more impressive showing.$b$bTake note, $r! Your future patrols will be rewarded based on your timeliness.$b$bDismissed.', `RequestItemsText` = 'Have you met with each of my captains, $r?' WHERE `entry` = 12596;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fine specimens, $n.$b$bOn behalf of my soldiers, I thank you for your efforts today.$b$bCaptain Rupert is likely the next stop on your patrol. He''s stationed at the wall just east of here.' WHERE `entry` = 12597;
        UPDATE `quest_template` SET `OfferRewardText` = 'We''re not out of the woods by any means, but your efforts have helped to slow the enemy down.$b$bCaptain Grondel up in Drak''Agal will likely have need of you.$b$bFarewell, $n.', `RequestItemsText` = 'Have you sealed the nerubian tunnels, $N?' WHERE `entry` = 12598;
        UPDATE `quest_template` SET `OfferRewardText` = 'Mighty kind of ya, $n. Mighty kind indeed.$b$bNow you''ll be findin'' ol'' Finklestein due west o'' here, just over the rise.' WHERE `entry` = 12599;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you tested your skills?' WHERE `entry` = 12603;
        UPDATE `quest_template` SET `OfferRewardText` = 'These nerubians have taken a heavy toll, $c.$b$bNevertheless, I am grateful for your efforts.', `RequestItemsText` = 'Have you freed our soldiers from the clutches of the nerubians?' WHERE `entry` = 12606;
        UPDATE `quest_template` SET `RequestItemsText` = 'Everything taken care of?' WHERE `entry` = 12607;
        UPDATE `quest_template` SET `OfferRewardText` = 'These look to be excellent samples, $n.$b$bThank you for your assistance.' WHERE `entry` = 12609;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $n.$b$bI thank you for your assistance.' WHERE `entry` = 12610;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done, $N?' WHERE `entry` = 12611;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, you''re alive. How did you fare?' WHERE `entry` = 12614;
        UPDATE `quest_template` SET `OfferRewardText` = '<Zim''Torga''s thoughts pervade your own. She senses the offerings you are about give to her and is pleased.>$B$B<She conveys that you will be appropriately rewarded.>', `RequestItemsText` = '<You can feel the eyes of the Mother of Prosperity upon you. She is wondering what a $r such as yourself is doing standing before her.>' WHERE `entry` = 12615;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you destroyed the trespassers, $N?' WHERE `entry` = 12617;
        UPDATE `quest_template` SET `RequestItemsText` = '<Zim''Torga looks on impassively. She wonders if you seek her continued blessings by presenting more Drakkari offerings to honor her.>' WHERE `entry` = 12618;
        UPDATE `quest_template` SET `RequestItemsText` = 'The runeblade is an extension of your being. A death knight cannot battle without a runeblade.' WHERE `entry` = 12619;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you taken care of the cultists, $N?' WHERE `entry` = 12620;
        UPDATE `quest_template` SET `RequestItemsText` = 'We have little time. The Scourge is preparing for a final push.' WHERE `entry` = 12621;
        UPDATE `quest_template` SET `OfferRewardText` = 'The scalper thinkin'' that you be his kind of $r!$B$BWhat''s these candybars doin'' in here? What we do with this, mon?$B$BAhunae say that you can have them back!' WHERE `entry` = 12622;
        UPDATE `quest_template` SET `OfferRewardText` = 'Greetings to you, $c. I am glad to hear that Ubungo found someone that he could trust.$B$BWelcome to Zim''Torga.' WHERE `entry` = 12623;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, I can already feel the difference. Thank you.$B$BLet us see if we can make contact with the gods now.', `RequestItemsText` = 'I am still unable to make contact. The ritual of the medicine men is still intact.$B$BPlease go back there and disturb each of their cauldrons.' WHERE `entry` = 12627;
        UPDATE `quest_template` SET `OfferRewardText` = '<Stefan sifts through the foul components.>$b$bWell, it''s far from perfect, but it''ll have to do. Now brace yourself, $c. This is where it gets good....' WHERE `entry` = 12629;
        UPDATE `quest_template` SET `OfferRewardText` = 'You know, you remind me an awful lot of my Nass.$b$bMaybe it''s just the nose...', `RequestItemsText` = 'How''s that boot holding up, $r?' WHERE `entry` = 12630;
        UPDATE `quest_template` SET `OfferRewardText` = 'I am indeed familiar with items such as this.$b$b<Stefan looks you in the eye.>$b$bIt would seem, $n, that you have been... chosen.' WHERE `entry` = 12631;
        UPDATE `quest_template` SET `RequestItemsText` = 'There are more of my offspring that you must free from their torment!' WHERE `entry` = 12632;
        UPDATE `quest_template` SET `OfferRewardText` = 'Aw, prime specimens!$B$BYou can see there the divergence from the root symbology. Quite extraordinary.$B$BWhat a pity that the ice trolls are determined to bring about their own demise.$B$BDid you know, for instance, that the Drakkari were exiled from the rest of the troll nations for their extremely violent ways?$B$BIt''s true! How did you think trolls ended up in such a harsh climate as this?' WHERE `entry` = 12635;
        UPDATE `quest_template` SET `OfferRewardText` = 'Now you''ve observed the fate that was meant to befall you.$b$bAs I mentioned before, this was no coincidence. The creation of such a device is very involved, and the required resources would not be squandered on a random target.$b$bThe simple truth of the matter is this; You''re wanted by the Scourge....', `RequestItemsText` = 'Yes, $r?' WHERE `entry` = 12637;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $r?' WHERE `entry` = 12638;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have a few more of those rifts to seal before we be talkin'' again, $N.' WHERE `entry` = 12640;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t keep me waiting, $N. What are the results?' WHERE `entry` = 12645;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it.$B$BBut now there is one other thing that I need you to do.' WHERE `entry` = 12646;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done what had to be done and honored me in the process.$B$BI give you my deepest thanks, $N. I only hope that you and Har''koa will be able to help the others.', `RequestItemsText` = 'If you do not put an end to my suffering soon, $N, all may be lost.' WHERE `entry` = 12647;
        UPDATE `quest_template` SET `OfferRewardText` = 'So? How are you enjoying scourge life?$b$bBelieve me, it''s not all it''s cracked up to be....', `RequestItemsText` = 'Well, $n?$b$bDid you purchase that flask?' WHERE `entry` = 12648;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, $n?$b$bDid you purchase that flask?' WHERE `entry` = 12649;
        UPDATE `quest_template` SET `OfferRewardText` = 'Let me look at those.$B$B<The chronicler examines the artifacts that you have recovered.>$B$BHmph, I''d say that we''re lucky you liberated these when you did, $c.$B$BHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.$B$BBut after the Sundering, the land broke off, eventually becoming Northrend.$B$BThis, of course, is why we see Drakkari in the southern continents as well as here.' WHERE `entry` = 12650;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yoo dun feed da goolz?' WHERE `entry` = 12652;
        UPDATE `quest_template` SET `OfferRewardText` = '<The cat goddess howls in pain.>$B$BMy spirit cries out in grief at the loss of another friend. But fear not, he will return and his spirit will live on forever.' WHERE `entry` = 12653;
        UPDATE `quest_template` SET `OfferRewardText` = '<Zim''Rhuk acknowledges the offerings you intend to place before him, though he knows that you took them from the corpses of others.>$B$B<If you give the offerings to him, he reluctantly agrees to grant you his blessing.>', `RequestItemsText` = '<You sense that Zim''Rhuk does not trust you. He is attempting to call out to one of his guardians.>' WHERE `entry` = 12655;
        UPDATE `quest_template` SET `RequestItemsText` = '<Zim''Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>$B$B<Place the offerings before him and he will grant you his blessing again.>' WHERE `entry` = 12656;
        UPDATE `quest_template` SET `OfferRewardText` = 'Aw, me thinkin'' that too funny.$B$B$N is my kind of $r!$B$BYou still got my knife?', `RequestItemsText` = 'Ahunae know there be no way that $N scalp that many of the Heb''Drakkar so quickly.' WHERE `entry` = 12659;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done, $N?' WHERE `entry` = 12660;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, now... I must admit I''m more than a little surprised to see you, $n.$b$bTell me what you''ve learned.', `RequestItemsText` = 'Have you earned their commander''s trust, $N?' WHERE `entry` = 12661;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it!$B$B<Dagoda gives you a big kiss on the cheek.>$B$BYou have no idea how much of a relief that is to me! Defending against trolls on all sides is really putting a strain on us. Not to mention his incessant yelling.$B$BPlease, $N, take your pick of what we have to offer.', `RequestItemsText` = 'He''s not dead. I can still hear him yelling from here!' WHERE `entry` = 12662;
        UPDATE `quest_template` SET `RequestItemsText` = 'You an'' me gunna take Gundrak, mon.' WHERE `entry` = 12663;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, now ya be seein'' what we be up against, mon.$b$bI want ya ta go down, learn da land, mingle with yer bretheren. Prepare yourself...$b$bSoon, dere be much for ya to do. Don''t ya be disappointin'' me!', `RequestItemsText` = 'Have ya taken in da battlefield yet, mon?' WHERE `entry` = 12664;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you for bringing my kitten back safely.$B$BDeep down I knew it. I wanted to deny it, but your eyes have revealed the truth.$B$BNevertheless, I sense something else. All is not as it seems.', `RequestItemsText` = 'What seems to be the delay, $N?' WHERE `entry` = 12665;
        UPDATE `quest_template` SET `OfferRewardText` = '<The leopard goddess looks saddened at the collection of holy symbols that you have brought before her.>$B$BThere was a time when these meant something. Let''s see if we can put them to better use.' WHERE `entry` = 12666;
        UPDATE `quest_template` SET `RequestItemsText` = 'Why do you return when your task is not yet complete? Do you not realize that I can destroy you with but a thought?$B$BGo now, little $r. Complete that which I commanded of you!' WHERE `entry` = 12668;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice work, $n!$b$bDiluting those cauldrons will not only save lives, it will slow the growth of the Scourge in this region.$b$bNow come, tell me what you''ve learned of Drakuru''s strategy in Zul''Drak.', `RequestItemsText` = 'Please, $N, tell me you haven''t blown your cover....' WHERE `entry` = 12669;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N?' WHERE `entry` = 12671;
        UPDATE `quest_template` SET `OfferRewardText` = 'They''ll do. Likely I won''t even need them.$B$BBut it was fun watching you run around at my command.', `RequestItemsText` = 'What a shame that Har''koa didn''t send you along sooner. Then again, she and I never did get along.$B$BShe probably held back your help just long enough for this to happen.' WHERE `entry` = 12672;
        UPDATE `quest_template` SET `OfferRewardText` = 'Da crystals be pilin'' up like never before!$b$bYou keep up da good work, $n. I got more tasks for ya real soon.' WHERE `entry` = 12673;
        UPDATE `quest_template` SET `OfferRewardText` = '<The terrible spirit before you lets loose a blood-chilling cackle.>$B$BThey had it coming. And I''ll give them more of the same again and again and again....', `RequestItemsText` = 'DO YOU THINK THAT I''M A FOOL?$B$BTHEY''RE NOT DEAD!' WHERE `entry` = 12674;
        UPDATE `quest_template` SET `OfferRewardText` = 'A portion of my spirit?$B$B<The snow leopard goddess pauses a moment to consider.>$B$BThat''s quite an expensive gift considering that this is for revenge and I''m already greatly weakened by the actions of my subduers.$B$BStill, I may know a way.' WHERE `entry` = 12675;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent!$b$bYour undercover work has truly paid off, $n.$b$bNow let''s have a look at that scepter....', `RequestItemsText` = 'Were you successful in clearing those scourgewagons, $N?' WHERE `entry` = 12676;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fascinating!$b$bWe''ll look into the properties of these crystals right away.$b$bNow tell me, $n, what is the latest with this Drakuru fellow?', `RequestItemsText` = 'Welcome back, $n.$b$bWere you able to steal any samples of Drakuru''s crystals?' WHERE `entry` = 12677;
        UPDATE `quest_template` SET `RequestItemsText` = 'This is the opening sonata, $c. The Scourge death march begins with the eradication of the front lines.' WHERE `entry` = 12678;
        UPDATE `quest_template` SET `RequestItemsText` = 'You don''t want to walk forever, do you?' WHERE `entry` = 12680;
        UPDATE `quest_template` SET `RequestItemsText` = 'I wish that there were something that we could do to bring Mam''toth back to life, but there isn''t.$B$BWe can honor him and his sacrifice by continuing the fight against the Drakkari.' WHERE `entry` = 12684;
        UPDATE `quest_template` SET `OfferRewardText` = '<The witch doctor shakes his head in disbelief.>$B$BIt sounds like you barely escaped Quetz''lun''s underworld alive.$B$BI''m glad that it''s you out there. I don''t know if I would have had the courage to deal with that situation!', `RequestItemsText` = 'What brings you back to me, $N?' WHERE `entry` = 12685;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ya done good, $n. You be learnin'' faster than I had hoped.$b$bGo now, get ya some rest. Soon I be givin'' ya an even greater test!' WHERE `entry` = 12686;
        UPDATE `quest_template` SET `RequestItemsText` = 'You must take the deathcharger by force, $c!' WHERE `entry` = 12687;
        UPDATE `quest_template` SET `OfferRewardText` = 'We done it, mon!$b$bI got da chieftains all caged up and you led my abominations to victory over their armies.$b$bIt be time ta celebrate, mon!' WHERE `entry` = 12690;
        UPDATE `quest_template` SET `RequestItemsText` = 'One small note: miners don''t always become ghouls. Sometimes they turn into enraged spirits, hell-bent on killing you.' WHERE `entry` = 12698;
        UPDATE `quest_template` SET `RequestItemsText` = 'Death knights know no fear!' WHERE `entry` = 12701;
        UPDATE `quest_template` SET `RequestItemsText` = 'So many big-tongues to kill! So fun, eh?' WHERE `entry` = 12703;
        UPDATE `quest_template` SET `RequestItemsText` = 'Thank you for help dryskin. You very good to us.' WHERE `entry` = 12705;
        UPDATE `quest_template` SET `RequestItemsText` = 'I was certain you wouldn''t make it back here in one piece, death knight. Perhaps there is more to you than I first surmised.', `CompleteEmote` = 1 WHERE `entry` = 12706;
        UPDATE `quest_template` SET `RequestItemsText` = 'What? You done already?$B$BDid you enact wooly justice upon those sorry ice trolls?' WHERE `entry` = 12707;
        UPDATE `quest_template` SET `OfferRewardText` = 'That should make them think twice about making more of those things. I shudder to think what it would be like to have to fight an army of those things.$B$B<The element-tamer is thoughtful for a moment.>$B$BI guess it would be just like fighting the endless waves of the Scourge.', `RequestItemsText` = 'Surely you couldn''t have dealt with all of the enchanted tiki warriors so quickly?' WHERE `entry` = 12708;
        UPDATE `quest_template` SET `OfferRewardText` = 'Just look at all of that!$B$BSee here, $N. This piece you recovered vividly illustrates that the Drakkari became aware of the weakening of the land that the Scourge caused by their presence.$B$BThe warlord felt compelled to take the opportunity this presented. He pushed the prophets to kill their gods in an effort to control the power and fight back against the Lich King''s forces.$B$BEither way they were doomed. They inadvertently chose to be the instrument of their own destruction!' WHERE `entry` = 12709;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, there ya have it, mon.$b$bWe be makin'' da ultimate scourge army ta serve da Lich King. He gunna be most pleased!$b$bYou keep da scepter, $n. You gunna be needin'' it ta command my army in battle....$b$bSoon!', `RequestItemsText` = 'Have ya gone ta witness my creations, $N?' WHERE `entry` = 12710;
        UPDATE `quest_template` SET `OfferRewardText` = 'It might have been better if I hadn''t asked you to bring it back here instead of heading directly to Gundrak.$B$BHowever, I think that it''s best that you hear what else I have to say first.' WHERE `entry` = 12712;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, it is done.$b$bWe still have much to do, but our work here will be much more manageable thanks to your efforts.$b$bPlease accept this as a token of our gratitude.' WHERE `entry` = 12713;
        UPDATE `quest_template` SET `RequestItemsText` = 'Use the persuaders on Scarlet Crusaders. One of them will eventually... crack.' WHERE `entry` = 12720;
        UPDATE `quest_template` SET `OfferRewardText` = 'No!$B$BAnother god destroyed, its power stolen. And now the prophet of Akali has threatened us directly.$B$BWhen he comes, he will come for Har''koa. We cannot allow him to take her power too.$B$BWe must consult the gods once more, $N. They will tell us what must be done.', `RequestItemsText` = 'What happened?' WHERE `entry` = 12721;
        UPDATE `quest_template` SET `RequestItemsText` = 'Like lambs to the slaughter...' WHERE `entry` = 12722;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you collected the data from Winterfin Caverns yet, $N?' WHERE `entry` = 12728;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your bravery seems boundless, $N.$B$BPlease hand me the heart and the essence, and I will fashion them into that which will compel the prophet to appear before you.' WHERE `entry` = 12729;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it! $N, you are the champion of Zul''Drak!$B$BWe will never be able to repay the debt that we owe to you, but the Zandalari have given into my trust a number of objects they believe you might have an interest in.$B$BPlease, I want you to have a token of our appreciation, but hurry. I sense another issue of urgency!', `RequestItemsText` = 'I can only offer you the warmth of my words and the encouragement that comes with them.$B$BTake what time you need to steel and prepare yourself, but I implore you not to take too long or the prophet will surely descend upon us.' WHERE `entry` = 12730;
        UPDATE `quest_template` SET `RequestItemsText` = 'You bring Rejek gift?' WHERE `entry` = 12732;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you completed Death''s Challenge?' WHERE `entry` = 12733;
        UPDATE `quest_template` SET `RequestItemsText` = 'You play cleansing song yet, $N?' WHERE `entry` = 12735;
        UPDATE `quest_template` SET `RequestItemsText` = 'You feel smart yet, $r?' WHERE `entry` = 12736;
