        UPDATE `quest_template` SET `OfferRewardText` = 'You''re a good $g man : woman;, $N. We''re fortunate that you happened to stop by.$B$BStick around a while. I''m sure that we have much that a capable $c such as yourself can do.', `RequestItemsText` = 'If you''re back here talking to me why do I still see my people falling to their deaths?' WHERE `entry` = 12740;
