        UPDATE `quest_template` SET `RequestItemsText` = 'You''re going to miss the courier and then I''m going to be forced to kill you. By forced I mean I will take great pleasure in ending your life.$B$BHURRY UP!' WHERE `entry` = 12754;
        UPDATE `quest_template` SET `RequestItemsText` = '<Orbaz laughs.>$B$BWhat is this? Some child''s coloring book?' WHERE `entry` = 12756;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kind of messy! But still so fun.' WHERE `entry` = 12759;
        UPDATE `quest_template` SET `RequestItemsText` = 'Vekgar teach you super secret, eh? Only strongest Frenzyheart get to know secret.' WHERE `entry` = 12760;
        UPDATE `quest_template` SET `RequestItemsText` = 'Very powerful. Puppy-men not know about power of Great Ones. Dumb puppy-men.' WHERE `entry` = 12761;
        UPDATE `quest_template` SET `OfferRewardText` = 'You must be $N. I was told you''d be coming.$B$B<The ambassador grunts.>$B$BI have something that I want you to take care of. If you do, you''ll prove yourself to the dragons here.' WHERE `entry` = 12767;
        UPDATE `quest_template` SET `OfferRewardText` = 'Back so soon, $N?$B$BVargastrasz sent word ahead of you. Thank you for what you did at the Ruby Dragonshrine.' WHERE `entry` = 12769;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 12770;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $n. A stouter $r I never did see! The trials of Outland have made you tough, brother. You do your race proud!' WHERE `entry` = 12771;
        UPDATE `quest_template` SET `RequestItemsText` = '$n, my son. Once again we are pulled into a conflict that may sunder all we know. It is good to have a $c of your talents lend his strength to this world tree''s defense.' WHERE `entry` = 12773;
        UPDATE `quest_template` SET `RequestItemsText` = '$n, it''s good to see you. Your strength and skills are a boon during this time of tribulations.' WHERE `entry` = 12774;
        UPDATE `quest_template` SET `RequestItemsText` = 'My son, the lands of the humans and orcs have treated you well. Such strength now swells within you...' WHERE `entry` = 12776;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kill them all...' WHERE `entry` = 12779;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see you have a special voucher. Give it to me and I will offer you something in exchange.' WHERE `entry` = 12781;
        UPDATE `quest_template` SET `RequestItemsText` = 'Welcome to Orgrimmar, $n. Grand Apothecary Putress sent word ahead of you... do you have the infected brain?' WHERE `entry` = 12785;
        UPDATE `quest_template` SET `RequestItemsText` = 'Welcome to Thunder Bluff, $n. Grand Apothecary Putress sent word ahead of you... do you have the infected brain?' WHERE `entry` = 12786;
        UPDATE `quest_template` SET `RequestItemsText` = 'Salutations, $n. You come from Shattrath? You have instructions from Grand Apothecary Putress?' WHERE `entry` = 12787;
        UPDATE `quest_template` SET `RequestItemsText` = 'Welcome to Silvermoon, $n. Grand Apothecary Putress sent word ahead of you... do you have the infected brain?' WHERE `entry` = 12788;
        UPDATE `quest_template` SET `RequestItemsText` = 'I sense that you haven''t yet tested out both of the teleport crystals.$B$BThat''s alright, take your time.', `OfferRewardEmote1` = 1 WHERE `entry` = 12790;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome to Dalaran.$B$BI''ll see to it that the ring is returned.' WHERE `entry` = 12794;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see that you have managed to complete a deck of Swords. Excellent.' WHERE `entry` = 12798;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $c.$b$bThis should save my men some precious time.', `RequestItemsText` = 'Good day, $r.$b$bHave you collected the ectoplasm Finklestein asked for?' WHERE `entry` = 12799;
        UPDATE `quest_template` SET `OfferRewardText` = 'Impressive, mon! Fate be kind in bringin'' us together.$b$bSoon I be avengin'' me bruddas by cleansin'' Drak''Tharon, and you be awarded Drak''Tharon''s greatest treasure.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 12802;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you recovered the elementals'' energy, $N?' WHERE `entry` = 12805;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $n! Look at you! I see you have grown precisely one-point-seven-three microspans since last I saw you. The airs of Outland have had an effect on you, I am certain of it.' WHERE `entry` = 12809;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s not glamorous work, but it is necessary.$B$BNow why is it that we are talking again before you are done, $c?' WHERE `entry` = 12810;
        UPDATE `quest_template` SET `RequestItemsText` = 'Salutations, $n. You come from Shattrath? You have instructions from Grand Apothecary Putress?' WHERE `entry` = 12812;
        UPDATE `quest_template` SET `RequestItemsText` = 'Surely you''re not done so soon?' WHERE `entry` = 12813;
        UPDATE `quest_template` SET `RequestItemsText` = 'What took so long? Are their gryphons slow? We''ll have to do something about that.' WHERE `entry` = 12814;
        UPDATE `quest_template` SET `RequestItemsText` = 'What you back so soon for? I know I can still see those Onslaught boys still flyin'' around down there!' WHERE `entry` = 12815;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you investigated the invasion yet? There''s no time for dawdling!' WHERE `entry` = 12816;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you investigated the invasion yet? There''s no time for dawdling!' WHERE `entry` = 12817;
        UPDATE `quest_template` SET `OfferRewardText` = 'These will do nicely, thanks!$B$BDid you happen to see Dim out there? I sent him out a long while back and he never came back. I hope he''s alright.$B$BSpeaking of which... I wonder where Janks is...', `RequestItemsText` = 'We have to have something we can use to insulate our engines against this cold... think, Jeer, think!$B$BOh hey! Did you get some of that wreckage for me?' WHERE `entry` = 12818;
        UPDATE `quest_template` SET `RequestItemsText` = 'If Janks were here, I could have just sent him on this errand. Oh... on second thought... I''m not sure I told him where the safe path is anyway.$B$BGood thing I have you resourceful adventure types around, eh?' WHERE `entry` = 12819;
        UPDATE `quest_template` SET `OfferRewardText` = 'So... here I sat, basking in the awesomeness that is me, and in the distance, I hear a pop! Then another! Then a dozen more! And a smile crept onto my face at the thought of all those magnataur and snobolds eagerly rushing to their own deaths.$B$BWas it glorious?', `RequestItemsText` = 'You got some of their gross little snobold buddies too I hope?' WHERE `entry` = 12820;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent!$B$B<A fierce grin creeps onto Ricket''s face.>$B$BLet the destruction begin!' WHERE `entry` = 12821;
        UPDATE `quest_template` SET `RequestItemsText` = 'Nothing strikes fear into the enemy quite like a goblin sapper!' WHERE `entry` = 12822;
        UPDATE `quest_template` SET `OfferRewardText` = 'The whole mountain shook! Was it gorgeous? I bet it was! How could it not be?$B$BAnd the Inventor''s League tells me all of my inventions just blow up. Darn right they do! Hah!', `RequestItemsText` = 'That explosive bundle is my baby... it took me weeks to perfect it. WEEKS!$B$BThat''s a long time... okay.' WHERE `entry` = 12823;
        UPDATE `quest_template` SET `OfferRewardText` = 'You blew the whole place up? Way to go! I bet Gino got a kick out of that.$B$BWe really appreciate all of the help you''ve lent us, $n. How ''bout a souvenir for your troubles?' WHERE `entry` = 12824;
        UPDATE `quest_template` SET `OfferRewardText` = 'And it''s already well-done! I outdo myself sometimes.$B$BThanks much, friend!', `RequestItemsText` = 'I know my plan was brilliant. Don''t even worry about it.$B$BDoes it feel good to be in the presence of greatness? A little tingly maybe?' WHERE `entry` = 12828;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ha ha! Good to see you''re up for some dirty work.$B$BMuch appreciated there, pal!', `RequestItemsText` = 'Be careful near that dispenser! Those things are dangerous.' WHERE `entry` = 12829;
        UPDATE `quest_template` SET `OfferRewardText` = 'Woo! That''s a ripe stench right there! You had to get hands-on with some of those snobolds, didn''t ya?$B$BI do appreciate it though!' WHERE `entry` = 12830;
        UPDATE `quest_template` SET `RequestItemsText` = '<The Injured Goblin Miner writhes in pain.>' WHERE `entry` = 12831;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thanks for helping out our miner back there, $n! I should be able to put together an antidote no problem.$B$BIf you stumble into Tore again, tell her that she''s a jerk for me, will ya?', `RequestItemsText` = 'I take it that things went well at the cavern? Was Tore decent to you?' WHERE `entry` = 12832;
        UPDATE `quest_template` SET `RequestItemsText` = 'Boom! Ha ha!' WHERE `entry` = 12833;
        UPDATE `quest_template` SET `RequestItemsText` = 'I like Ricket cause she''s sooo delicious!$B$BOh, hey there again! How goes the pest control?' WHERE `entry` = 12836;
        UPDATE `quest_template` SET `RequestItemsText` = 'Where is Grand Admiral Westwind?' WHERE `entry` = 12840;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find our men, $N?' WHERE `entry` = 12843;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes?' WHERE `entry` = 12847;
        UPDATE `quest_template` SET `OfferRewardText` = 'Perhaps you do have the heart of a warrior.$b$bTime will tell...', `RequestItemsText` = 'Have you survived the battle, $N?' WHERE `entry` = 12851;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome to K3!$B$BWe came here to make our way into those peaks and get our fair share of some of those amazing titan machines. Progress on that end has been somewhat minimal, though. Gnolls, snobolds, magnataur... there''s no shortage of trouble to go around... not to mention, we can''t seem to keep any fliers in the air without their motors freezing.$B$BThere''s plenty of work to be done though - lend a hand, eh?', `OfferRewardEmote1` = 3, `OfferRewardEmote2` = 1 WHERE `entry` = 12853;
        UPDATE `quest_template` SET `RequestItemsText` = 'Who are you?' WHERE `entry` = 12855;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your efforts appear to have been successful, sister.$b$bYou have brought glory to the Brunnhildar!', `RequestItemsText` = 'Was your mission successful, $gbrother:sister;?' WHERE `entry` = 12856;
        UPDATE `quest_template` SET `OfferRewardText` = '<Chief Rageclaw cries.>$B$BHad Ragemane since pup. Sad day for Rageclaw. First troll attack Rageclaw, then troll make Ragemane bad. Rageclaw never trade with troll again!' WHERE `entry` = 12857;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hrm, put fires out?' WHERE `entry` = 12859;
        UPDATE `quest_template` SET `OfferRewardText` = 'Rageclaw thank you, $N. Though Rageclaw Den probably lost forever and troll-Rageclaw friendship also lost forever... and also now I think of it, Ragemane lost forever too. Also brother-in-law. He gone. Hrm, have you seen Chief''s mate? I think she gone too.$B$BMaybe you go now. Chief a little depressed.', `RequestItemsText` = 'You rescue Rageclaw?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12861;
        UPDATE `quest_template` SET `RequestItemsText` = 'These birds have been loyal to us for a long time... we get on pretty well.' WHERE `entry` = 12865;
        UPDATE `quest_template` SET `RequestItemsText` = 'Persistent buggers... can''t ever seem to rid ourselves of all of them. They breed like rabbits.' WHERE `entry` = 12866;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s too cold here the usual pests... we get harpies. Lucky us.' WHERE `entry` = 12868;
        UPDATE `quest_template` SET `RequestItemsText` = 'Ye''ve come back to me. Have ye come back to me victorious?' WHERE `entry` = 12874;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were the scouts right? Were there dwarves down there?' WHERE `entry` = 12876;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hello, $r.$b$bI am pleased that you have opted to utilize your tongue over your blade when making my acquaintance. I have found that a more and more rare quality among your kind of late.' WHERE `entry` = 12877;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hey there, $glad:lass;! Good to meet ya in person. Did you find it?' WHERE `entry` = 12880;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12882;
        UPDATE `quest_template` SET `OfferRewardText` = 'If this is the same Drakuru from Drak''Tharon Keep we are going to need... outside assistance.$B$BDeath knights of Acherus are stationed nearby, undoubtedly following the same trail of Scourge destruction that lead the Argent Crusade here. As half of our army is tied up at the Argent Stand, battling crazed Drakkari trolls, we will have to join forces with the Knights of the Ebon Blade.$B$B<Lantinga mutters under his breath.>$B$BI was hoping I''d never have to see those scoundrels again after Light''s Hope...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 12883;
        UPDATE `quest_template` SET `OfferRewardText` = '<Stefan reads the missive, then crumples it up and tosses it into the fire.>$B$BOld news. The Argent Crusade is - once again - late to the party. We''ve been tracking Drakuru since Grizzly Hills. He is slated for eradication.' WHERE `entry` = 12884;
        UPDATE `quest_template` SET `RequestItemsText` = 'Begone!' WHERE `entry` = 12886;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Ocular still stands! Thassarian was a fool to trust you.$B$BWhoever you are, don''t return again until it is destroyed. My position here must not be compromised!' WHERE `entry` = 12887;
        UPDATE `quest_template` SET `RequestItemsText` = '<You open SCRAP-E''s access panel.>' WHERE `entry` = 12888;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Ocular still stands! Koltira was a fool to trust you.$B$BWhoever you are, don''t return again until it is destroyed. My position here must not be compromised!' WHERE `entry` = 12892;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have NOT turned them yet. Do not insult my intelligence, $c!' WHERE `entry` = 12893;
        UPDATE `quest_template` SET `OfferRewardText` = 'Everything was fine until the Scourge attacked. They took off with Dargath, Gerk and Burr and they also destroyed our ride. Guess who led that attack?$B$B<MacKellar nods.>$B$BNavarius...$B$BSeems this whole area is some type of factory for Scourge. We''re in the middle of a damned undead mine field!', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 396 WHERE `entry` = 12894;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 12895;
        UPDATE `quest_template` SET `RequestItemsText` = 'I ask you, $N, why would we be speaking again if General Lightsbane yet exists?' WHERE `entry` = 12896;
        UPDATE `quest_template` SET `OfferRewardText` = '<Gerk is dying.>$B$BTh... They say these Vargul are the... the ones that weren''t found worthy by the Lich King. Can... Can you im... imagine it? Just th... think how powerful the... the... worthy must be...$B$BI''ll say a prayer for you in the hereafter, hero... May you never have to face them in number.', `RequestItemsText` = 'You''re doing the world a favor, friend. These monsters must be stopped!' WHERE `entry` = 12904;
        UPDATE `quest_template` SET `OfferRewardText` = 'I was expecting a replacement for one of my overseers.  It''s about time you showed up.$B$BLet''s put you to work.' WHERE `entry` = 12905;
        UPDATE `quest_template` SET `RequestItemsText` = 'Is it done? I hope you didn''t slay too many of the mongrels. We need the manpower.' WHERE `entry` = 12906;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re back. Did you kill the insubordinate pig?' WHERE `entry` = 12907;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 12909;
        UPDATE `quest_template` SET `OfferRewardText` = '<An image of a dwarf appears as you activate the communicator. It can only be Brann Bronzebeard.>$B$B<From the look on his face, Brann seems shocked to see you and begins gesturing furiously.>', `RequestItemsText` = 'Who... who''re you?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 6 WHERE `entry` = 12910;
        UPDATE `quest_template` SET `OfferRewardText` = 'A... A storm giant? I don''t know about this, $N. That sounds risky. On the other hand, I don''t think we have too many other options.$B$BIf I do this you have to promise me that you will get your giant friend to help us deal with Navarius and his cronies.' WHERE `entry` = 12912;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12913;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, it is done then.$b$bLet us hope it is enough.', `RequestItemsText` = 'Does Fjorn still live, $c?' WHERE `entry` = 12915;
        UPDATE `quest_template` SET `OfferRewardText` = 'FREEDOM!$B$BDo not be afraid, little one. Gymer is an honorable giant. Like you and your people, I too wish to see the Scourge driven away from this land and the Lich King destroyed. I will help you, as promised, to the best of my ability.', `RequestItemsText` = 'I am a giant of my word, little one.' WHERE `entry` = 12916;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12917;
        UPDATE `quest_template` SET `RequestItemsText` = 'You are most generous.  The least I can do is to teach you the skills of gem perfection.' WHERE `entry` = 12918;
        UPDATE `quest_template` SET `OfferRewardText` = 'Unbelievable! This will be a story for the ages, $N! One $g man:woman; rode upon the head of the king of storm giants and decimated an entire Scourge army!$B$BAnd I was there to see it all happen...', `RequestItemsText` = 'What is going on? Are our enemies dead?' WHERE `entry` = 12919;
        UPDATE `quest_template` SET `OfferRewardText` = '<Boktar listens as you describe your conversation with Brann.>$B$BThere''s truth to the dwarf''s words. Vor''takh''s plan is not the way of the Horde. If Brann Bronzebeard knows of a way to stop these iron dwarves and their patron, it serves us to help him.', `RequestItemsText` = 'What did you find out?', `DetailsEmote1` = 25, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 12920;
        UPDATE `quest_template` SET `OfferRewardText` = 'You place the metal on the anvil and immediately upon adding the sparks they work the ore furiously.$b$bWhen at last they burn out, you are left with a large piece of metal that gleams with a light of its own.' WHERE `entry` = 12922;
        UPDATE `quest_template` SET `OfferRewardText` = 'It would seem that I have refined my technique considerably. That, or the legends surrounding this anvil are true.$b$bThis suit of armor is superior to the last, and took less material to create.$b$bWith the excess, I was able to fashion you a little something as payment for your assistance.' WHERE `entry` = 12924;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you destroy the blighted eggs?' WHERE `entry` = 12925;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12926;
        UPDATE `quest_template` SET `OfferRewardText` = '<Brann looks at the disk as you hold it up.>$B$BI can''t tell if there''s anything stored there or not, $g lad:lass;. You''ll have to tell me what happened.$B$B<You describe the data retrieval process.>$B$BSo it worked? At least we can count on Keeper Mimir to be systematic.', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12927;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5 WHERE `entry` = 12928;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12930;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the battle?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 12931;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you healed the fallen defenders?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 5 WHERE `entry` = 12937;
        UPDATE `quest_template` SET `RequestItemsText` = 'Perhaps you could go back and challenge a few more?' WHERE `entry` = 12939;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you punish our wayward brethren?' WHERE `entry` = 12942;
        UPDATE `quest_template` SET `RequestItemsText` = 'My scouts inform me that Ufrang yet lives.$B$BDo you not know how to read, $r?' WHERE `entry` = 12943;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes?' WHERE `entry` = 12953;
        UPDATE `quest_template` SET `RequestItemsText` = 'No payout until the fight''s over, $gman:woman;.' WHERE `entry` = 12954;
        UPDATE `quest_template` SET `RequestItemsText` = 'Why are you here?$B$BGo and humiliate them!' WHERE `entry` = 12955;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you freed the slaves of the stormforged?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12957;
        UPDATE `quest_template` SET `OfferRewardText` = '<Bouldercrag reaches out to take the ore, but then recoils.>$B$BThat ore... I can''t touch it. It seethes with unnatural energy. No creature of stone can handle it. What do they mean to do with this?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 12964;
        UPDATE `quest_template` SET `OfferRewardText` = '<Bouldercrag nods grimly.>$B$BYou''ve weakened the stormforged considerably, but they''ll keep fighting. Their casualties matter nothing to them, while our defenders continue to fall. Even if it costs them a hundred or a thousand iron corpses, they''ll keep fighting until we''ve been pounded to gravel.', `RequestItemsText` = 'Is it true? Does Valduran possess powerful relics of the titans? Did you destroy them?', `DetailsEmote1` = 5, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12965;
        UPDATE `quest_template` SET `OfferRewardText` = 'Reforging Thorim''s armor? It can be done.$b$bFirst though, there''s the matter of the anvil...' WHERE `entry` = 12966;
        UPDATE `quest_template` SET `OfferRewardText` = 'An honorable performance, $r. I shall inform the king of your assistance.$b$bThe anvil is nearly cool enough. I shall see you in Dun Niffelem soon.', `RequestItemsText` = 'Were you able to lead Snorri to another victory, $c?' WHERE `entry` = 12967;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find Yulda?' WHERE `entry` = 12968;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''re back.' WHERE `entry` = 12969;
        UPDATE `quest_template` SET `RequestItemsText` = 'Keep it down, the others might start getting suspicious.' WHERE `entry` = 12970;
        UPDATE `quest_template` SET `RequestItemsText` = 'Yes, $N?' WHERE `entry` = 12971;
        UPDATE `quest_template` SET `OfferRewardText` = 'Think we''ll give you your own bear just like that?  You''ll have to prove yourself before you get anything from us.$B$BDo not think too highly of yourself just because you bested a few challengers in the Hyldsmeet.' WHERE `entry` = 12972;
        UPDATE `quest_template` SET `RequestItemsText` = 'My pardons, $glad:lass;! I got all caught up in tha moment and I neglected ye entirely.' WHERE `entry` = 12973;
        UPDATE `quest_template` SET `OfferRewardText` = 'Another good deed you have done on Thorim''s behalf, $c.$b$bThis will help to soften the hearts of my people towards him.' WHERE `entry` = 12975;
        UPDATE `quest_template` SET `OfferRewardText` = '<Njormeld''s eyes become noticeably moist as he pours the contents of the bag onto the anvil.>$b$bThe Horn of Hodir....$b$bThis was a sacred gift to our people from Hodir himself, $r. It is a relic of great importance to us.$b$bWhen you next return to our stronghold you shall see the fruits of your labor.$b$bFarewell.' WHERE `entry` = 12976;
        UPDATE `quest_template` SET `RequestItemsText` = 'Strong gusts of wind swirl around the horn, causing its sound to echo throughout the surrounding mountains.$B$BTo any unknowing passersby, it might seem to be blowing itself....' WHERE `entry` = 12977;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you taken the hammer to the irons at Nidavelir?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 12978;
        UPDATE `quest_template` SET `OfferRewardText` = 'Careful, now. Keep that plate as far away from me as you can. Even being in its presence is enough to inflict pain.$B$BBut you''re right, $N, these are gigantic armor plates for a war golem of normal size. What would the stormforged be doing with them? There''s only one way to find out.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12979;
        UPDATE `quest_template` SET `OfferRewardText` = '<Bruor listens as you describe what you learned in the workshop.>$B$BSo Valduran''s master has given him this sinister metal to construct a giant weapon? That must be what he intends to use for the final strike against us! We need to stop him before he''s able to complete it and unleash this weapon.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12980;
        UPDATE `quest_template` SET `RequestItemsText` = 'Certainly there are more of my death knights to be loosed from their cages?!' WHERE `entry` = 12982;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you find a matriarch?' WHERE `entry` = 12983;
        UPDATE `quest_template` SET `RequestItemsText` = 'Valduran must be dealt with before the refuge falls.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 12984;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is nearly done.$b$bWith this artifact in place, Dun Niffelem shall be warned of impending dangers before they are upon us.' WHERE `entry` = 12985;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you returned with the knowledge that I seek, $r?' WHERE `entry` = 12986;
        UPDATE `quest_template` SET `OfferRewardText` = '<Njormeld gazes up at Hodir''s Helm, visibly moved.>$b$bThat will do, little $r.$b$bThat will do....', `RequestItemsText` = 'Have you mounted Hodirs Helm, $r?' WHERE `entry` = 12987;
        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to hamper them by sabotaging the forges?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12988;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve returned!' WHERE `entry` = 12989;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you decimated the iron colossus'' workforce?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12991;
        UPDATE `quest_template` SET `RequestItemsText` = 'Dems vrykuls not killed!' WHERE `entry` = 12992;
        UPDATE `quest_template` SET `OfferRewardText` = '<Bouldercrag begins to look over the documents, his eyes wide.>$B$BI had no idea the irons were capable of this! Our men will have no chance against this behemoth if it''s completed. Fortunately, it looks like they''re still lacking a key part.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12993;
        UPDATE `quest_template` SET `RequestItemsText` = 'The frostworg denmother looks at you curiously.' WHERE `entry` = 12994;
        UPDATE `quest_template` SET `RequestItemsText` = 'Oh now, $N, I don''t think you''re quite done yet.' WHERE `entry` = 12995;
        UPDATE `quest_template` SET `OfferRewardText` = 'Not bad.  I was hoping Kirgaraak would snap your neck so I could keep your bear.$B$BJust joking, sister.  Well... half-joking.  That''s a really nice bear you''ve got.', `RequestItemsText` = 'How did it go with the yeti?' WHERE `entry` = 12996;
        UPDATE `quest_template` SET `OfferRewardText` = 'You really did it!  You made it out with your health.  Wish we could say the same for your bear.$B$BIt''s going to take a while for her to recover.  Fortunately you won''t need her for a while.', `RequestItemsText` = 'Hail, $Gbrother:sister;.' WHERE `entry` = 12997;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tell me that the heart didn''t fall into enemy hands.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 12998;
        UPDATE `quest_template` SET `OfferRewardText` = 'These furs are rather... large.  I''d hate to see the worgs you had to face off with.$B$BWe''re all very thankful.  The temperature is starting to drop already.', `OfferRewardEmote1` = 1 WHERE `entry` = 13000;
        UPDATE `quest_template` SET `RequestItemsText` = 'Dis is what I been lookin'' for.  Now I be learnin'' you Gem Perfection.' WHERE `entry` = 13002;
        UPDATE `quest_template` SET `RequestItemsText` = 'Your donation is much appreciated.  Let me teach you of gem perfection.' WHERE `entry` = 13004;
        UPDATE `quest_template` SET `RequestItemsText` = 'Hail, $N! What news do you bring?' WHERE `entry` = 13005;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you defeated the iron colossus and spared the refuge from destruction?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 13007;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you freed the webbed crusaders?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13008;
        UPDATE `quest_template` SET `OfferRewardText` = '<As you present Thorim with the reforged suit of armor, he is visibly stricken by its splendor.>$b$bYou have done well, $r, but there remains much to be done.' WHERE `entry` = 13009;
        UPDATE `quest_template` SET `OfferRewardText` = 'Words cannot express my gratitude, $c.$b$bYou have served me honorably. Please accept this token of my gratitude.', `RequestItemsText` = 'Back again, little $r?' WHERE `entry` = 13010;
        UPDATE `quest_template` SET `OfferRewardText` = 'So it is done.$b$bWe have heard the screams of Jormuttar as they echoed from across the valley.$b$bYou have done our people a service this day, little $r.', `RequestItemsText` = 'Have you slain Jormuttar?' WHERE `entry` = 13011;
        UPDATE `quest_template` SET `RequestItemsText` = 'What have you learned from the records of Camp Tunka''lo?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 13034;
        UPDATE `quest_template` SET `RequestItemsText` = 'It''s good to see you again, $N.' WHERE `entry` = 13035;
        UPDATE `quest_template` SET `OfferRewardText` = 'Where both the Alliance and the Horde failed, the Argent Crusade succeeded. The success, however, was short lived. Our breach into Icecrown was quickly - and with force - rebuffed.$B$BThe Lich King''s retaliatory strike was immediate and brutal. Now we are on the defensive.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13036;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13037;
        UPDATE `quest_template` SET `OfferRewardText` = 'The chieftain''s spirit told you to bring this to me?$B$B<Xarantaur examines the totem.>$B$BAh, I see what he intended. By telling you to use this totem to close the rifts in the deep, he has given us a clue as to what''s happening to the timeline. A wise chieftain, this Swiftspear, watching over his people even in death.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13038;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t give up, $N!', `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5 WHERE `entry` = 13039;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 13040;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have not finished what I asked of you.$B$BPlease leave and do not return until you have done so or I will be very cross.' WHERE `entry` = 13042;
        UPDATE `quest_template` SET `RequestItemsText` = 'You recovered the doctor''s tome, but you didn''t finish him off using the flesh giant?$B$BGet back in there and kill him before it''s too late!' WHERE `entry` = 13043;
        UPDATE `quest_template` SET `OfferRewardText` = '<Penumbrius nods.>$B$BMy kin will help. Together we will battle the Lich King and his undead legions.\n', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 396 WHERE `entry` = 13044;
        UPDATE `quest_template` SET `OfferRewardText` = 'Arthas... He strikes recklessly - without care or caution. We have caught him off guard.$B$B<Highlord Tirion Fordring pauses, lost in thought for a moment.>$B$BWe will bolster our defenses and weather the storm.$B$BHow good are you with a cannon, $N?', `RequestItemsText` = 'With each minute that passes their chance of survival decreases.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 13045;
        UPDATE `quest_template` SET `OfferRewardText` = 'No... it cannot be...$B$BNo one can defeat Thorim in single combat.  Not a giant, nor a beast... no one!  Especially not that coward of a brother of his.$B$BOn my forefathers'' names, this I swear...$B$BLoken will pay for this!', `RequestItemsText` = 'Ach, $N!  It''s good to see you, little one.' WHERE `entry` = 13047;
        UPDATE `quest_template` SET `OfferRewardText` = '<Xarantaur accepts the Lorehammer from you.>$B$BAt last, we''ve pinpointed the time of Stormhoof in history. With this knowledge, we can restore the timeline.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13048;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13049;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes... these will do.  Let us hope my plan works, $N.$B$BVeranus is a great drake.  I''d hate to have to settle for a lesser one.' WHERE `entry` = 13050;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13058;
        UPDATE `quest_template` SET `RequestItemsText` = 'I sense that you haven''t yet defeated Thane Illska. Does something stay your hand?' WHERE `entry` = 13059;
        UPDATE `quest_template` SET `OfferRewardText` = '<Olut winces.>$B$BThat looked painful. It was a pretty grand entrance though.$B$BAre you here to help us find a path into Icecrown? As you can see, our first foray in that direction didn''t end too admirably. I''m thinking we might be better off breaching the place from another side.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13060;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, sister, you think that completing a few simple chores makes you a heroine?$b$bYou shall learn....' WHERE `entry` = 13063;
        UPDATE `quest_template` SET `OfferRewardText` = 'You now know a bit of the history of this land... my land.$b$bI call upon you to assist me in setting these wrongs to right.', `RequestItemsText` = 'Hear my words, $r.' WHERE `entry` = 13064;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 13068;
        UPDATE `quest_template` SET `RequestItemsText` = 'Tsk, tsk... you haven''t shot down your fair share of proto-drakes today!' WHERE `entry` = 13069;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 1 WHERE `entry` = 13070;
        UPDATE `quest_template` SET `RequestItemsText` = 'What? Vile not see lots of fire!!!$B$B$N, go back and make more fire!' WHERE `entry` = 13071;
        UPDATE `quest_template` SET `OfferRewardText` = 'Bridenbrad has contracted the plague? I cannot imagine a worse fate for one who has devoted his life to the ways of light, nor can I fathom leaving him to die without lifting a finger to help.$B$BNo, undeath shall not be his fate. We shall find a way to aid this hero.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 274, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 13072;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hello child.$B$BI understand Tirion''s request and trust in his judgment, we will see what we can do for this Crusader Bridenbrad. What you ask is no simple task - the Scourge are not of this world, and many have failed in attempting to strip their corruption over the years.$B$BIn a being of nobility and light, all is not without hope.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13073;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13074;
        UPDATE `quest_template` SET `OfferRewardText` = 'Tirion sent you to Remulos? I''m... I''m flattered. One does not call favors in with beings of such power idly, no matter how noble or altruistic they might be. You too are kind to have gone to such lengths on my behalf. You have my thanks.$B$BPlant the seed - I am ready.', `RequestItemsText` = 'Well met, $c. I knew that you would return, despite my warnings, but I''m pleased that you heeded my desire to not risk anyone else.$B$BWhy have you come back to me?', `DetailsEmote1` = 1 WHERE `entry` = 13075;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 13076;
        UPDATE `quest_template` SET `OfferRewardText` = 'Greetings to you, $r.$B$BThe concern is clear on your face. Please tell me what troubles you.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13077;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13078;
        UPDATE `quest_template` SET `OfferRewardText` = 'The breath of Alexstrasza... you have gone to the dragon-queen herself? I''m extremely grateful.$B$BI understand the risks of such cleansing and I am prepared. Proceed, $c.', `DetailsEmote1` = 1 WHERE `entry` = 13079;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Scourge plague is no simple foe to defeat. Alexstrasza''s words suggest that perhaps we can yet save our Bridenbrad from the unimaginable fate of the unliving should he fall, but I will not give him up so easily.$B$BThere is yet one more path of light I would like to pursue. One more being who might avert this horrible fate.', `OfferRewardEmote1` = 1 WHERE `entry` = 13080;
        UPDATE `quest_template` SET `OfferRewardText` = '<A gentle ringing fills your head as you approach the naaru.>$B$BI know why you have come.', `DetailsEmote1` = 1 WHERE `entry` = 13081;
        UPDATE `quest_template` SET `OfferRewardText` = '<As you approach Crusader Bridenbrad, you cannot help but notice that his skin has taken on a pale hue and his breaths are shallow. It is clear that he has little time left.>$B$BYou have returned to me, $c. I must admit... it is good to see you again... your face renews my hope that this land will be free of Arthas''s grasp one day soon. I''m proud to have met you...$B$B<Bridenbrad''s words trail off, a dim smile on his face. As life seems to slip from him, a gentle ringing fills your ears.>' WHERE `entry` = 13082;
        UPDATE `quest_template` SET `OfferRewardText` = 'I am glad you were able to save him from undeath. With A''dal''s blessing, he will know no evil in his afterlife.$B$BWe shall take heart in his shining example and in your selflessness. Thank you for all that you have done.', `OfferRewardEmote1` = 1 WHERE `entry` = 13083;
        UPDATE `quest_template` SET `RequestItemsText` = 'You have more work to do.' WHERE `entry` = 13084;
        UPDATE `quest_template` SET `RequestItemsText` = 'The screams of the dying will haunt me forever! Help them!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 13086;
