        UPDATE `quest_template` SET `RequestItemsText` = 'My disgust for Warlocks is only exceeded by my hate for the undead. However, they can both prove useful at times.' WHERE `entry` = 13539;
        UPDATE `quest_template` SET `RequestItemsText` = 'No, that just won''t do. Please return when you have the female leopards and bears that I''ll need for the arduous journey back home.' WHERE `entry` = 13549;
        UPDATE `quest_template` SET `RequestItemsText` = 'No ordinary tributes were good enough for the great Hodir when he walked among the frost giants.$B$BHe might not be with us anymore, but we''ve kept the tradition of offering tribute to his strength and wisdom.  It would do much for your renown to partake in this tradition, small $c.' WHERE `entry` = 13559;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you tested yourself in combat against the Scourge?' WHERE `entry` = 13592;
        UPDATE `quest_template` SET `OfferRewardText` = '<The sentinel eyes you appreciatively for a moment.>$B$BA job well done, $c. If you''re any indication of the quality of the $r adventurers we''re going to be seeing more of, we should have this war against the orcs and their Horde taken care of faster than expected.', `DetailsEmote1` = 25, `DetailsEmote2` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 13594;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have helped me to return to the ground, $N.$B$BNow my hair will cease to sprout for these creatures. Better yet, I will be regrown all the sooner.' WHERE `entry` = 13595;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very well done, $N. Your actions in the Zoram Strand against the naga are commendable.$B$BI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves. We know this, for we share a history with them.$B$BThe naga are cursed Highborne night elves. Ten thousand years ago, Queen Azshara made a pact of desperation with the Old Gods to save her surviving people from a watery grave.$B$BThe naga are the result of that pact.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 66 WHERE `entry` = 13602;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 13604;
        UPDATE `quest_template` SET `RequestItemsText` = 'Freya''s sigil, $N? Do ye have it?', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 13606;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s locked?  Figures!$B$BLet''s see what information this junk heap can give us...', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 6, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 274 WHERE `entry` = 13607;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 13609;
        UPDATE `quest_template` SET `RequestItemsText` = 'Well, $N? Do ye have it?', `DetailsEmote1` = 1, `DetailsEmote2` = 4, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 13610;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 6, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 13611;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hello, $c.$B$BWhat''s that? You say that Shyela sent you?$B$B<The night elf briskly rubs his nimble hands together.>$B$BVery well, let''s get started.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 13617;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, Evenar was succesful. Actually, more to the point, YOU were successful.$B$BI cannot thank you enough, $c, but there is more that must be done to the leaves before they will serve as a curative for what ails the child, Relara.', `RequestItemsText` = 'You''re a brave one to come here given the circumstances.$B$BWhat business have you, stranger?', `DetailsEmote1` = 25, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 13623;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''d received a report about you from some of my scouts out in the forest but I had no idea how capable you are!$B$BThank you, $N. With what you''ve accomplished the tide is turned. I''ve no doubt now that we''ll rout them by the end of the day!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 13624;
        UPDATE `quest_template` SET `RequestItemsText` = 'How goes the mounted combat practice?' WHERE `entry` = 13625;
        UPDATE `quest_template` SET `OfferRewardText` = 'I do not look forward to writing the letter to the Argent Dawn embassy in Darnassus. At least we''ll be able to send their most prized possessions back for their loved ones.$B$BI cannot thank you enough for your courage, $N. Please accept this on behalf of the post.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 2 WHERE `entry` = 13626;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you get the "goods" we talked about?' WHERE `entry` = 13627;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $N.$B$BWith the moonstones of Ordil''Aran deactivated, we should not need to worry about any further incursions of furbolg here.$B$BHowever, my scouts have returned with disturbing news from the furbolg village. There is an imminent danger massing there.$B$BI wonder, might I entice you to carry a warning to Astranaar for me?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 6 WHERE `entry` = 13630;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 13631;
        UPDATE `quest_template` SET `OfferRewardText` = 'We are in your debt, $c. If I know anything about the furbolg, they do not like their noses bloodied.$B$BIt won''t be long now before they tuck tail and return to their village.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 2, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 6 WHERE `entry` = 13632;
        UPDATE `quest_template` SET `OfferRewardText` = 'So you''re saying this knight''s story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can''t confront him until we know for certain whether he was involved in these murders.$B$BDo nothing to arouse his suspicions, $N. Discretion will serve us well as we continue to investigate.', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 13634;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13641;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the concoction blessed by the Light of Elune, it should be ready for delivery to Astranaar.$B$BThere is no time to waste, $N!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 13642;
        UPDATE `quest_template` SET `OfferRewardText` = 'So you say Lorien Sunblaze was done in by poison and Sir Wendell was burnt alive? Dreadful ways to die, both of them. Only Conall was killed by cold steel, and from your description, it was a coward''s strike, not honorable combat that laid him in his grave.$B$BAll three sparred with and were scheduled to fight the Black Knight. This cannot be a coincidence. Now, we must find a way to prove it was the Black Knight''s work.', `RequestItemsText` = 'Have you visisted the graves of the slain combatants?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 13643;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the death of the harbinger, I can begin to cleanse the lake.$B$BYou have my deepest thanks, $N. I mourn the loss of your friend, but know that his remains will fuel the reclamation of the forest hereabouts.', `DetailsEmote1` = 33, `OfferRewardEmote1` = 33 WHERE `entry` = 13644;
        UPDATE `quest_template` SET `OfferRewardText` = 'Teronis is dead?$B$B<The lady weeps softly for the loss of her friend and then composes herself after a moment.>$B$BWe must see to it that his sacrifice was not in vain. Are you willing to see this through, $c?$B$BVery well, allow me some time to think about how we should proceed. I will know shortly.', `DetailsEmote1` = 6, `DetailsEmote2` = 2, `OfferRewardEmote1` = 18, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay2` = 2000 WHERE `entry` = 13645;
        UPDATE `quest_template` SET `OfferRewardText` = 'Avana is alive?! I feared that she might be dead when we heard about the attack on Maestra''s Post!$B$BAs you can see, we have our hands full with the Horde here as well.$B$BYou have given me the greatest gift by letting me know she is well. Any time that you wish to ride one of my nightsabers back to Maestra''s Post, it is yours.', `DetailsEmote1` = 4, `DetailsEmote2` = 2, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 13646;
        UPDATE `quest_template` SET `OfferRewardText` = '<Crusader Rhydalla examines the bag''s contents with a look of disgust on her face.>$B$BIt''s all here, $N: the poison that killed Lorien, a collection of knives, torches, and oil. No man has cause to possess these things here and no squire would do so without orders from his knightly master. We''ve found our murderer, $N, but who is he working for?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13654;
        UPDATE `quest_template` SET `RequestItemsText` = 'You''ve worked your way up through the Brotherhood''s corporate hierarchy, $r. We have begun to look favorably upon you. Quite an accomplishment!$B$BIf you''re interested in more work and earning more respect amongst us, listen up.$B$BWe can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths.$B$BBring me all the Dark Iron residue you find!' WHERE `entry` = 13662;
        UPDATE `quest_template` SET `OfferRewardText` = '<Crusader Rhydalla''s face pales as she reads the orders.>$B$BThis can only mean one thing, $N. The Black Knight is a member of the Cult of the Damned and has been sent by Arthas to disrupt the tournament!$B$BThe Black Knight has proven himself a fearsome combatant, and you will need to be every bit as good if you wish to face him. When you are a champion, return to me and we''ll find a way to ensure his defeat.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13663;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the death of the Black Knight, the tournament may once again serve its purpose. The champions of the Horde and Alliance may demonstrate their skill at arms and train for the day when Arthas and his minions will no longer threaten us.$B$BYou have the thanks of the Argent Crusade, $N, and that of all who have answered our call.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13664;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you tested yourself in combat against the Scourge?' WHERE `entry` = 13671;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 13673;
