        UPDATE `quest_template` SET `OfferRewardText` = '<Dousing the tear within the moonwell, the waters begin to glow and churn with startling activity.>', `DetailsEmote1` = 274, `DetailsEmote2` = 6, `DetailsEmote3` = 25, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 13919;
        UPDATE `quest_template` SET `OfferRewardText` = '<The satyr sneers, but when he realizes you are not here to chastise him, he changes his expression.>$B$BFinally, my redemption is at hand. I have waited long for this day and I think I know how to help you in turn.', `OfferRewardEmote1` = 1, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 13921;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have all of the moonstones that are needed. And yet, it is said that a sacrifice of life is the only way to ensure the saving of another.$B$BI will ensure that no matter what, the moonstones will cure Relara.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13922;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, $N, you have saved my daughter! I know the power of the moonstones will give back my daughter her strength!$B$BI can never repay you fully for the aid you have given me, but... please, take this. Other than Relara, it is my most dear possession.', `DetailsEmote1` = 16, `DetailsEmote2` = 2, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 2, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 13924;
        UPDATE `quest_template` SET `RequestItemsText` = 'You taking care of us?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13926;
        UPDATE `quest_template` SET `RequestItemsText` = 'Orphan lady say Kekek go with you.' WHERE `entry` = 13927;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $c. We have our hands full defending the retreat, but when I can catch my breath, I''ll see to it that these sisters are returned to life, the Goddess willing.$B$BYou''ve demonstrated your prowess... we can use your help.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 13928;
        UPDATE `quest_template` SET `RequestItemsText` = 'Can we see the big tree? Can we?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13929;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kekek want to visit bear-men tree. We go.' WHERE `entry` = 13930;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff? Got something for me?' WHERE `entry` = 13931;
        UPDATE `quest_template` SET `RequestItemsText` = 'What''s happening hot stuff? Got something for me?' WHERE `entry` = 13932;
        UPDATE `quest_template` SET `RequestItemsText` = 'We visit shrine to dragon-things?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13933;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kekek want to visit dragonshrine.' WHERE `entry` = 13934;
        UPDATE `quest_template` SET `OfferRewardText` = 'A brutal display, but one fitting for the enemies of Ashenvale. The Horde dares to think that they can take our beloved forest away from us.$B$BThey are fatally mistaken!$B$BYou have saved Raynewood from destruction, $N. Surely we can find a reward suitable for our champion?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 15 WHERE `entry` = 13935;
        UPDATE `quest_template` SET `RequestItemsText` = 'We go to the Wonderworks?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13937;
        UPDATE `quest_template` SET `RequestItemsText` = 'This toy store yet?' WHERE `entry` = 13938;
        UPDATE `quest_template` SET `OfferRewardText` = 'Impressive. I hope my huntress carried her weight.$B$BIf we continue with this fervor, we may yet still free Teldrassil from the corruption that Alexstrasza herself could not burn out.', `RequestItemsText` = 'Are their numbers weakened?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 13945;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good. I know this probably wasn''t very pleasant work, but we greatly appreciate it.$B$BI fear for our dear Teldrassil... it seems it is becoming more corrupt by the day, and our ignorance to the cause is plaguing me greatly.', `RequestItemsText` = 'Did you have any success in routing those grellkin for us?', `OfferRewardEmote1` = 1 WHERE `entry` = 13946;
        UPDATE `quest_template` SET `RequestItemsText` = 'You take us to Winterfin Retreat? Meet new friends maybe?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13950;
        UPDATE `quest_template` SET `RequestItemsText` = 'You take Kekek to Snowfall Glade now?' WHERE `entry` = 13951;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 13954;
        UPDATE `quest_template` SET `RequestItemsText` = 'We go see dragon queen now?' WHERE `entry` = 13955;
        UPDATE `quest_template` SET `OfferRewardText` = 'We got to meet a Great One! Too bad it was during his nap time, but we understand. We like naps, too! Maybe we learn naps from Great Ones like we learn about shrines and shinies!$B$BCan we come back and visit the Great One again when not sleeping?', `RequestItemsText` = 'Do you know how to find a Great One? We''ve never seen one before.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13956;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do we have to go back? We want to stay with you.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 13959;
        UPDATE `quest_template` SET `RequestItemsText` = 'Kekek not want to go. Kekek want to see more of Northrend with Jeursey.' WHERE `entry` = 13960;
