        UPDATE `quest_template` SET `OfferRewardText` = 'After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.$b$bUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.' WHERE `entry` = 14193;
