        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well, $N.  You''ve done more than could be asked of any Gilnean.$B$BWe''re running low on ammunition.  It''s time to regroup inside now.' WHERE `entry` = 14218;
        UPDATE `quest_template` SET `OfferRewardText` = 'They... they''ve stopped coming.$B$BNo, $N.  That''s not a good thing.' WHERE `entry` = 14222;
        UPDATE `quest_template` SET `OfferRewardText` = 'Orcs?! They were sunk and stranded too?  And now the Alliance are on the island? Do you think they''re going to kill us?$B$B<Sassy looks thoughtful.>$B$BI think it''s time for a little sitdown with these orcs.' WHERE `entry` = 14233;
        UPDATE `quest_template` SET `OfferRewardText` = '<The orc makes a move to grab the field journal from you, but then stops herself, exhaling deeply.>$B$BI apologize. It has been a very rough couple of days for all of us.$B$BI am Aggra. All of us here are what remains of the crew of the Draka''s Fury.$B$BPerhaps we can work together. We have a common enemy in the Alliance. Their SI:7 assassins are all over this island and they''re not going to stop until we''re all dead.', `RequestItemsText` = '<The orc narrows her eyes at you.>$B$BYou must have been on the goblin slave ship that was sunk. What''s that you have in your hand?', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 14234;
        UPDATE `quest_template` SET `OfferRewardText` = 'Goblin, can you fight?$B$BFor your sake, I hope so. Otherwise, there may be no breaking through this hell of killer plants.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 6 WHERE `entry` = 14235;
        UPDATE `quest_template` SET `OfferRewardText` = 'I saw it with my own eyes, and still I do not believe it!$B$BYou have our thanks and the debt of our lives, little goblin. I hope that soon we can repay you the honor.$B$BMay I ask a small favor of you while my scouts and I move on?', `DetailsEmote1` = 5, `DetailsEmoteDelay1` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6 WHERE `entry` = 14236;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 11, `OfferRewardEmote1` = 66 WHERE `entry` = 14237;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N, well done. We''ll make an orc of you yet!$B$BTime to move on. We''d better hurry.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 11 WHERE `entry` = 14238;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s up to you now. Are you going to come back to life and be the $g hero : heroine; that your fellow survivors need you to be, or are you going to rest for eternity here?$B$BOnly you can decide.$B$BDon''t go into the Light, $N!', `OfferRewardEmote1` = 4 WHERE `entry` = 14239;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hello, little goblin. Bastia is fast, no?$B$BWe have something very important that needs doing. Can you help us?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 25 WHERE `entry` = 14240;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hmm, where the heck is the ignition?$B$BIt''ll be a wonder if it flies without doing something weird, like turning into a chicken or shrinking down to the size of an ant.$B$BHey look, someone left their loose change in the ashtray! What else is in there?', `DetailsEmote1` = 5 WHERE `entry` = 14241;
        UPDATE `quest_template` SET `OfferRewardText` = 'If not for you, I would surely be on my way back to Stormwind to be paraded as a trophy and a slave.$B$BThe Alliance dogs found me unconscious on the shore and put me in this magical cage. It was keeping me from connecting with the elements.$B$BNo longer!', `OfferRewardEmote1` = 1 WHERE `entry` = 14242;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 2 WHERE `entry` = 14243;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 6, `OfferRewardEmote1` = 396 WHERE `entry` = 14244;
        UPDATE `quest_template` SET `OfferRewardText` = '<cough, cough!>$B$BHey! Where''s the dock?! Someone stole the dock and the oil refinery from our town-in-a-box!$B$BWho would do such a thing?$B$BWhere''s the Trade Prince?', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 14245;
        UPDATE `quest_template` SET `OfferRewardText` = 'Boss! Er, well, I guess you''re not the boss anymore, but still, good to see you!$B$BCan you believe it? We''ve got a cave full of intelligent killer monkeys mining kaja''mite!', `DetailsEmote1` = 5, `DetailsEmote2` = 6, `DetailsEmote3` = 5, `DetailsEmoteDelay2` = 2000, `DetailsEmoteDelay3` = 2000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay2` = 2000 WHERE `entry` = 14248;
        UPDATE `quest_template` SET `OfferRewardText` = '$N!  Where have you been?$B$BAnyway... it''s great to see you in one piece.' WHERE `entry` = 14265;
        UPDATE `quest_template` SET `RequestItemsText` = 'Could it be...?' WHERE `entry` = 14268;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 14280;
        UPDATE `quest_template` SET `OfferRewardText` = '<Aggra gives you the eye as if she doesn''t quite believe what you are telling her.>$B$BI am not easily impressed, but if what you are telling me is true, then I have never before heard of such a thing.$B$BYou have my thanks, $N.', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 14303;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 14326;
        UPDATE `quest_template` SET `OfferRewardText` = '$N!!!  You ARE alive!$B$BI thought I was having dreams about the old days when I heard your voice...' WHERE `entry` = 14336;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, $N!  Just like old times...$B$BI''m going to have to work hard at not shooting you, but Krennan explained everything to us.' WHERE `entry` = 14347;
        UPDATE `quest_template` SET `OfferRewardText` = 'You and me, $N.  We make a great team...$B$BIt''s good to have you back.' WHERE `entry` = 14348;
        UPDATE `quest_template` SET `OfferRewardText` = 'The relics are intact! Well, indeed, that is something.$b$bYou have put my mind at ease, $r. Please accept this as my gift to you.', `DetailsEmote1` = 5, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500, `OfferRewardEmote1` = 5 WHERE `entry` = 14354;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the ritual completed, you are awarded a divine gift.$b$bYou can''t help but to feel a great sense of honor as you receive one of Elune''s boons.' WHERE `entry` = 14357;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 5, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500 WHERE `entry` = 14361;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 14365;
        UPDATE `quest_template` SET `OfferRewardText` = 'I need you to pull through, $N.  This dosage is strong enough to kill a horse.$B$BBut I know you.  I know what you''re made of.  You will be fine.$B$BTrust me.  I know what you''re going through.$B$BNow drink up and close your eyes.' WHERE `entry` = 14375;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome to Nijel''s Point, $r.$b$bNow, let''s see about getting you briefed on our situation here.', `DetailsEmote1` = 5, `DetailsEmote2` = 396, `DetailsEmote3` = 66, `OfferRewardEmote1` = 396 WHERE `entry` = 14384;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 14387;
        UPDATE `quest_template` SET `OfferRewardText` = 'Liam is right.  We must get everyone to higher ground.$B$BYou must help me spread the word while I manage the logistics of the evacuation.' WHERE `entry` = 14397;
        UPDATE `quest_template` SET `OfferRewardText` = 'Why thank you, $N.  I hope you didn''t peek!$B$BWhere are your manners, dear?' WHERE `entry` = 14399;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 14400;
        UPDATE `quest_template` SET `OfferRewardText` = 'There he is!  Grandma''s special boy!$B$BThank you so much for finding him.  I hope it wasn''t too much trouble.$B$BMy... what manner of dirt found its way underneath my fingernails!' WHERE `entry` = 14401;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 14404;
        UPDATE `quest_template` SET `OfferRewardText` = 'Stay back! Don''t make me...$B$BIs it you?  By the Light!  It''s you, $N!' WHERE `entry` = 14406;
        UPDATE `quest_template` SET `OfferRewardText` = 'Are you ready to set sail, $N?  Your people have been granted shelter in the lands of the kaldorei.$B$BDo not worry, $r.  Your people will get a chance to fight for Gilneas again.  This time, with the full strength of the Alliance.' WHERE `entry` = 14434;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 14438;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wow, oh wow! Is that who I think it is?$B$BYou rescued Thrall, Warchief of the Horde?!!!$B$B<Sassy $g gives you an appraising look : looks envious of you;.>$B$BWell, let''s see about getting over to that larger island. I sure as heck don''t want to swim the strait with all of those sharks down there.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 14445;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome to your first true test as a tauren.', `DetailsEmote1` = 1 WHERE `entry` = 14449;
        UPDATE `quest_template` SET `OfferRewardText` = '<Chief Hawkwind holds the mane of Thornmantle over his head.>$B$BThe Chief of the Bristleback is slain. Greatmother Hawkwind''s spirit has been avenged!' WHERE `entry` = 14460;
        UPDATE `quest_template` SET `OfferRewardText` = '$N.  I''ve heard much about you.$B$BI understand you were crucial in my family''s survival during the outbreak in Gilneas City.', `OfferRewardEmote1` = 2 WHERE `entry` = 14465;
        UPDATE `quest_template` SET `OfferRewardText` = 'There you are, $N.  I''ve been expecting you.$B$BI got word of your recovery and... wait -- do you feel that?' WHERE `entry` = 14466;
        UPDATE `quest_template` SET `OfferRewardText` = 'Look, $N!  Look at what''s become of Duskhaven!$B$BLook at what''s become of the last safe place in Gilneas!' WHERE `entry` = 14467;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 14473;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, thank heavens that you survived, $N! I thought for sure that you''d drowned when I saw you go over the side!$B$B<Sassy''s eyes fill up with tears as she hugs you.>$B$BLook at all of these folks you saved!', `DetailsEmote1` = 5, `DetailsEmote2` = 6, `DetailsEmoteDelay2` = 2000, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 6, `OfferRewardEmoteDelay2` = 2000 WHERE `entry` = 14474;
