        UPDATE `quest_template` SET `OfferRewardText` = 'The land is clearly still in great upheaval if it took such effort to calm.$B$BRemember this, $n.  Do not forget seeing the fate of those who would scar the Earth Mother.' WHERE `entry` = 14491;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 20440;
