        UPDATE `quest_template` SET `OfferRewardText` = 'Thanks for stopping, $N.  Our carriage got hit pretty bad.$B$BThe one in front of us got it worse.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 25 WHERE `entry` = 24438;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Grimtotem...$B$B<Mull scowls.>$B$BI''d hoped to see the end of my days before Tauren attacked other Tauren senselessly on the very plains of Mulgore.  But be proud, $N.  You have done a great thing for the land, and for our people.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 24440;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $N.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.$B$BThe Thunderhorn Well is a symbol of my own tribe, and to know it is being desecrated by our own kind raises a fury in me I haven''t felt for years.', `OfferRewardEmote1` = 2 WHERE `entry` = 24441;
        UPDATE `quest_template` SET `DetailsEmote1` = 50, `DetailsEmote2` = 50, `DetailsEmote3` = 50, `DetailsEmote4` = 1 WHERE `entry` = 24456;
