        UPDATE `quest_template` SET `OfferRewardText` = 'Now that ye''ve got a new hunter trick under yer belt, and now that I''ve got some of yer money, go out there an'' track some beasts!  Come back sometime in the future, an'' we''ll talk again.', `DetailsEmote1` = 396, `OfferRewardEmote1` = 1 WHERE `entry` = 24530;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 1 WHERE `entry` = 24535;
