        UPDATE `quest_template` SET `OfferRewardText` = 'There you are, my $g boy : girl;! Quick, there''s no time to waste! We need to get one of these shredders back in working order.$B$BI''m bringing you off the bench... you''re going to win the game and the title for us!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 24567;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''ve been expecting you, $N.  Do not be alarmed.$B$BMy name is Belysra.  I am a priestess of the moon... a night elf.$B$BYou might not know my people, but the destinies of our two races have been linked since the Curse befell you.' WHERE `entry` = 24578;
