        UPDATE `quest_template` SET `OfferRewardText` = 'Anotha newblood, eh?$B$BYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real $c.$B$BLets not waste anymore time ''den.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 60, `DetailsEmoteDelay3` = 60, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 24607;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 66 WHERE `entry` = 24616;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re all right, $N!  I''ve been waiting for this day for a long time, it truly is great to see you friend.$B$BI''ve heard of what you''ve done and I''m thankful... especially for Lorna -- she''s all I''ve left.  I will send for her right away.', `OfferRewardEmote1` = 1 WHERE `entry` = 24617;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 3 WHERE `entry` = 24622;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 60, `OfferRewardEmote1` = 1 WHERE `entry` = 24623;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $c.$B$BIt will be takin'' brave and determined people like you ta drive da Darkspear up again. I hope dere are more people even half as dedicated to come.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 60, `OfferRewardEmote1` = 1 WHERE `entry` = 24624;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $n! Dis naga has set us back quite some time, but nothin'' will be holdin'' us down foreva.$B$BIt''s good ta be havin'' ya wit us, $n. Ya have a fierce heart within ya.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 60, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 24625;
        UPDATE `quest_template` SET `OfferRewardText` = 'Swiftclaw! Kijara was tellin'' me about him and he sounded like he''d be a handful. I don''t mind da challenge - it''s da spirited ones like dat that be makin'' da bravest and truest companions when real times of need be comin''.$B$BTank ya, hon. Ya''ve been very helpful.', `DetailsEmote1` = 1, `DetailsEmote2` = 6, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 60, `DetailsEmoteDelay3` = 60 WHERE `entry` = 24626;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 24628;
