        UPDATE `quest_template` SET `DetailsEmote1` = 274 WHERE `entry` = 24684;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Halls of Reflection lie ahead.$B$BIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 60, `OfferRewardEmote1` = 5 WHERE `entry` = 24712;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Halls of Reflection. Finally.$B$BLet me know when you are ready, $c. I will not be so naive as to think that Arthas left his precious sword entirely unguarded.', `OfferRewardEmote1` = 1 WHERE `entry` = 24713;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice! Look at the size of those things!$B$BThere''s no way that Grapplehammer''s going to be able to top those!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 24741;
        UPDATE `quest_template` SET `OfferRewardText` = 'Eureka! My genius saves the day yet again! Take that Bamm Megabomb!$B$BAnd now, to reap the benefits!', `DetailsEmote1` = 5, `OfferRewardEmote1` = 4 WHERE `entry` = 24744;
        UPDATE `quest_template` SET `OfferRewardText` = 'Anotha newblood, eh?$B$BYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real $c.$B$BLets not waste anymore time ''den.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 60, `DetailsEmoteDelay3` = 60, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 24776;
