        UPDATE `quest_template` SET `OfferRewardEmote1` = 6 WHERE `entry` = 24781;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yet again, vengeance slips through my grasp. It''s hard to believe how much stronger he''s gotten.$B$BIt was foolish of you to come for me, but it''s good to know that there are still some champions of the Horde that aren''t useless cowards.$B$BThe information Uther gave us may well be key to finally killing Arthas, though it is becoming more and more clear that the Horde will not be able to accomplish this on their own.$B$BGo, $c. I expect your prowess may be needed again very soon.', `DetailsEmoteDelay1` = 60, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay1` = 60, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 24802;
        UPDATE `quest_template` SET `RequestItemsText` = 'The Kalu''ak have a long tradition of honing our fishing skills by putting them to the the test every week.$B$BThe first person to catch and bring a blacktip shark to me will be rewarded handsomely, and be known as the greatest fisherman of the north... for a couple days at least.$B$BThe blacktip shark''s favorite food is the pygmy suckerfish. Try fishing for the blacktip wherever you would normally catch the suckerfish.' WHERE `entry` = 24803;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m afraid we''ve already had a winner for today, young $N. However, if you bring a shark, I''ll see that it''s released back into the waters, and I might just have a little something for you...' WHERE `entry` = 24806;
