        UPDATE `quest_template` SET `OfferRewardText` = 'Tha power dat burst forth when tha Sea Witch died was immense. I can use dis power ta enact a vision of places far away.$B$BObserve, youngblood. I want ya ta be here when I make contact wit'' Thrall, perhaps it will be grantin'' ya insight as well.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24814;
