        UPDATE `quest_template` SET `OfferRewardText` = 'I wish I could have seen the looks on their scaly faces when you blew up their banners and replaced them with our own.$B$BOn second thought, I don''t want to be close enough to see their snarls.', `DetailsEmote1` = 1 WHERE `entry` = 24858;
