        UPDATE `quest_template` SET `OfferRewardText` = 'Okay, I think that''s good enough for now, but they took a bunch of the townsfolk captive.$B$BWe''re going to have to take the fight to them!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 396 WHERE `entry` = 24901;
