        UPDATE `quest_template` SET `RequestItemsText` = 'How may I be of service, $r?' WHERE `entry` = 24919;
        UPDATE `quest_template` SET `OfferRewardText` = '$N? What are you doing wearing that pygmy helm? Looks like it''s about to fall apart.$B$BI''m glad that they sent you up here. I thought for sure they were going to send that jerk, Grapplehammer and his ego-enabling assistant.', `DetailsEmote1` = 6, `DetailsEmote2` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 24924;
        UPDATE `quest_template` SET `OfferRewardText` = 'Great job, but that''s not even half of the hostages that they took from town.$B$BDarn it all! They must have taken the rest of the captives to their other villages up in the volcano!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 24925;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice work, $g bud : girlfriend;! Hope he wasn''t too tough.', `DetailsEmote1` = 396, `OfferRewardEmote1` = 273 WHERE `entry` = 24929;
        UPDATE `quest_template` SET `OfferRewardText` = 'If I hadn''t seen you kill a few of the mangy things with my own eyes, I''d think you did not complete the task I asked of you.$B$BIt looks like we''re hardly putting a dent in their numbers.', `RequestItemsText` = 'What is it then, $N?' WHERE `entry` = 24930;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ahh, perfect! Just what I need...full of potent focusing energies...$B$B...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!$B$BNow take your pay and be off!' WHERE `entry` = 24931;
        UPDATE `quest_template` SET `OfferRewardText` = 'Man, this stuff looks delicious. I''m half tempted to just fry some up myself.$B$BNo! We''ve gotta focus on gettin'' out of here.$B$BMaybe just one piece...' WHERE `entry` = 24933;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 5 WHERE `entry` = 24937;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 71 WHERE `entry` = 24940;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it! No more zombies to worry about. Let''s pause a moment in silence for the stinky departed.$B$BOkay, done.', `DetailsEmote1` = 274, `OfferRewardEmote1` = 71, `OfferRewardEmote2` = 16, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 24942;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 1 WHERE `entry` = 24945;
        UPDATE `quest_template` SET `OfferRewardText` = 'This will do. In fact, it''s more than we need. I devised an ingenious idea for a weapon that the boots will be turned into once you get them to Hobart.$B$BHand the powder over and I''ll load it into the Super Booster Rocket Boots.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24946;
        UPDATE `quest_template` SET `OfferRewardText` = 'There''s no time to waste, $G boy : girl;!$B$BWhat''s wrong with the actuator on the left boot?!', `DetailsEmote1` = 396, `OfferRewardEmote1` = 5 WHERE `entry` = 24952;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh man, that was awesome! You should''ve seen the flames coming out of the hive!$B$BHere''s your reward, for entertaining me as much as for clearing the hive!', `RequestItemsText` = 'I didn''t hear no cave-ins, pal! Try again!' WHERE `entry` = 24953;
        UPDATE `quest_template` SET `OfferRewardText` = 'Careful with those glands, $N, careful!$B$B<Grapplehammer''s eyes light up at the sight of the fiery organs.>$B$BAnd now to load them into the refashioned shredder boot. I''m certain that you''ll be surprised and amazed by my genius invention.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 24954;
        UPDATE `quest_template` SET `OfferRewardText` = 'I managed to get everyone else safely back to town.$B$BJump in, we gotta get out of here before the volcano blows for good!!!', `OfferRewardEmote1` = 1 WHERE `entry` = 24958;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 24959;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well, $c.  As you can see, not all of us have resigned to our fates.  I''m glad to see that you''re at least willing to work.$b$bValdred will be a valuable asset to the Forsaken.  As for the other two... there is not much we can do.  We cannot force them to join us.', `RequestItemsText` = 'No dilly-dallying now.  You''re among the Forsaken now, and we hold ours to a higher standard.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `OfferRewardEmote1` = 396 WHERE `entry` = 24960;
        UPDATE `quest_template` SET `OfferRewardText` = 'You say she ran away?  What a shame.$b$bVery well.  As long as she''s maintained her free will, there''s still hope.', `RequestItemsText` = 'Have you spoken with her yet?  She needs to be shown the truth.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 24961;
        UPDATE `quest_template` SET `OfferRewardText` = 'I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you''ll find everything I can teach you to be worthwhile.$B$BGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need hunters with your type of cunning in the future.$b$bYou will be the backbone of our salvation. Do not forget it.', `RequestItemsText` = 'Ah, so you''ve arrived. Good. I overheard that a few others were able to escape "death" and were heading into town. Perhaps that resilience will pay off in the future also.$B$BYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 24962;
        UPDATE `quest_template` SET `OfferRewardText` = 'You seem to be somewhat of a natural, $n.  This is good.  I can''t teach you everything myself.$b$bGo, practice what we''ve discussed today.  Return when you''re stronger, and we''ll cover some more tricks and abilities.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 24964;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''ve got to admit, the spell I just taught you probably won''t increase your intellect severalfold.  That was a lie to get you to buy my services.  But it will still be a helpful spell for you and your allies.$b$bNo hard feelings!', `RequestItemsText` = 'What''s the matter... did you run out of money?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 24965;
        UPDATE `quest_template` SET `OfferRewardText` = '$N.  You made it.$b$bYou see those tents up there?  That''s where we''re headed.  The battle''s probably already started.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 1 WHERE `entry` = 24970;
        UPDATE `quest_template` SET `OfferRewardText` = 'Being born again under the power of a val''kyr is a strenuous process.  Many don''t survive the shock, turning into zombies or ghouls.$b$bOthers retain just enough humanity to seem normal on the outside... but they''re sick inside.  We should have slain those rotbrains the day they were raised.$b$bAs for you... you''re a strong $c, $n.  I knew you''d do well.  You''ll be headed out of Deathknell soon.', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 24971;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, this is very good. You''ve done well in obtaining this information, $n. Hmm... names of the Scarlet Crusade officers in the Tirisfal Glades...$b$bImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.  I will pass this information forward.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 66 WHERE `entry` = 24972;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, it''s a start.  It''ll take a few weeks or months to fully clean out the infestation.  After that, we''ll have to get down there with some torches to burn away the webbing.$b$bYou''ve done your duty well, $n.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 24973;
        UPDATE `quest_template` SET `RequestItemsText` = 'Oh, the pain of loneliness is too much to bear!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 24974;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24975;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 11, `OfferRewardEmote1` = 1 WHERE `entry` = 24976;
        UPDATE `quest_template` SET `RequestItemsText` = 'Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your...$b$b...oh wait.  Is that food for me?  I am so hungry...', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 11 WHERE `entry` = 24977;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 396 WHERE `entry` = 24978;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Scarlet Crusade takes no prisoners.  That they would do so with this young woman... curious.$b$bThe powers that you describe are even more curious.  She passed through the bars of her prison and killed her captor?  Why hadn''t she done that in the first place?', `OfferRewardEmote1` = 1 WHERE `entry` = 24979;
        UPDATE `quest_template` SET `RequestItemsText` = 'If you wish to prove your worth to The Dark Lady, slay 10 Scarlet Warriors, $c.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24980;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24981;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396 WHERE `entry` = 24982;
        UPDATE `quest_template` SET `OfferRewardText` = 'Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.$B$BWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.', `OfferRewardEmote1` = 1 WHERE `entry` = 24983;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24988;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is troubling to hear of the Scourge slipping past the Bulwark.  Even now, they are ceaseless in their assaults.$B$BBut we will not give in.  The Lich King is dead; we will not be taken again!', `DetailsEmote1` = 1 WHERE `entry` = 24989;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24990;
        UPDATE `quest_template` SET `OfferRewardText` = 'Holland?  He''s an amateur.  You don''t need a fancy two-story apothecarium to make plague... you need love.  And maybe some good assistants.$b$bLet me show you how plague is REALLY made.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24991;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, my doom weed. Excellent!$B$B<Apothecary Jerrod rubs his hands together greedily.>$B$BThese will come in quite handy. You''ve done me, uh, the Lady, a fine service today, $N. As promised, here is the reward that you deserve.', `RequestItemsText` = '<The apothecary mutters to himself.>$b$bThey brought me gloom weed?  GLOOM WEED?!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 24994;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 24995;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 24996;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 24997;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 66 WHERE `entry` = 24998;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1 WHERE `entry` = 24999;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.$B$BContinue the struggle as we all do, $N, and one day the Forsaken will have the dominion over Azeroth that they are owed!', `DetailsEmote1` = 1 WHERE `entry` = 25003;
        UPDATE `quest_template` SET `RequestItemsText` = 'Our battles with the Scourge wage on, $N.  Do your part and throw those cursed, mindless undead back into the Plaguelands!' WHERE `entry` = 25004;
        UPDATE `quest_template` SET `OfferRewardText` = 'Devlin Agamand?  Is that him you carry in your sack there?  Ha!$b$bYes, I know what Coleman wants to try, and I want to try it too.  I hope you''re prepared, $N.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 396 WHERE `entry` = 25005;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25006;
        UPDATE `quest_template` SET `OfferRewardText` = '<The High Executor sizes you up.>$b$bNot much of a $c, are you?  Well, you will be when I''m done with you.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 274 WHERE `entry` = 25007;
        UPDATE `quest_template` SET `RequestItemsText` = 'I see you have returned but your task is not complete.  Perhaps you are at ease with the mere humans interfering with The Dark Lady''s plan?  Or perhaps you can heed the call of duty and slay the Scarlet band that lies only moments away!', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25009;
        UPDATE `quest_template` SET `OfferRewardText` = 'As you look over the ruins of the camp, you hear a whisper behind you.$b$b<"I could kill you right now if I wanted to.  You''d better watch your step, $r.">', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25010;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25011;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25012;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 25013;
        UPDATE `quest_template` SET `RequestItemsText` = 'I should mention, you''re probably going to need a machete to hack through this mess.\n\nThis jungle came out of nowhere!' WHERE `entry` = 25015;
        UPDATE `quest_template` SET `OfferRewardText` = '<Mazoga gathers the pile of blood in his hands and raises it to his mouth. It liquifies and pours gorily down his throat.>$B$BDey drink de blood, dey get de power. I drink dere blood...$B$B<Mazoga gives you a wide, blood-smeared grin.>', `OfferRewardEmote1` = 7 WHERE `entry` = 25021;
        UPDATE `quest_template` SET `OfferRewardText` = 'I told you we would meet again, $N.$B$B<The Warchief gives you an appraising look.>$B$BUnfortunate that it''s under such dire circumstances.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 396 WHERE `entry` = 25023;
        UPDATE `quest_template` SET `RequestItemsText` = 'There are yet more Alliance paratroopers that need to be dispatched if we''re to get about the business of escaping from this island, $N.', `DetailsEmote1` = 396, `OfferRewardEmote1` = 25 WHERE `entry` = 25024;
        UPDATE `quest_template` SET `OfferRewardText` = '<Mazoga grins as he takes the sword from you in both hands.>$B$BDidn''t like ya much, eh? More in this world craves blood than just trolls, mon.$B$BLet''s find the other blade...', `OfferRewardEmote1` = 11 WHERE `entry` = 25025;
        UPDATE `quest_template` SET `OfferRewardText` = '<Mazoga tilts his head back and inhales the clumps of mysterious material. His eyes flash.>$B$BPowerful stuff, mon... ah, if ya could see what I see now... mebbe you go try it yaself sometime.$B$BThe spirits call...', `OfferRewardEmote1` = 7 WHERE `entry` = 25026;
        UPDATE `quest_template` SET `OfferRewardText` = 'Revenge has a sweet taste, don''t you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.$B$BIt is a foolish hope, I know.  But it is a hope I foster nonetheless.', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 396 WHERE `entry` = 25029;
        UPDATE `quest_template` SET `OfferRewardText` = 'Argh!  Get back!  Oh, you''re not Scourge, are you?$b$bThank the Banshee Queen that you''re here.  I''ve greatly underestimated how bad it''s gotten up here.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `OfferRewardEmote1` = 396 WHERE `entry` = 25031;
        UPDATE `quest_template` SET `OfferRewardText` = 'Mazoga? He''s taken the sword? That filthy...$B$B<Trenton glowers for a moment.>$B$BAt least you escaped with your life. The Lasher''s bite is a vicious one.', `OfferRewardEmote1` = 6 WHERE `entry` = 25032;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good to have ya, $G brotha:sista;.$B$BVol''jin makes us all proud in dese moments. It feels good ta be tacklin'' threats head on.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25035;
        UPDATE `quest_template` SET `OfferRewardText` = 'What''s this? Gloom weed?! I''ve no need for gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.$b$bWe''ll deal with the gloom weed later.  For now, we''ve got other matters to discuss.', `DetailsEmote1` = 35, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1 WHERE `entry` = 25038;
        UPDATE `quest_template` SET `RequestItemsText` = '<Trawley licks his lips, barely able to constrain his drool.>\n\nYou get my steaks yet? Nice and bloody?' WHERE `entry` = 25042;
        UPDATE `quest_template` SET `OfferRewardText` = 'From birth to grave to undeath, we all have our own path to follow.  Some are easier than others.  It sounds like this Voss girl has had a rough path so far.$b$bHopefully she ultimately chooses to join us and follow the Dark Lady.  With power like hers, we could do incredible things.$b$bBy the way, $N... excellent work out there.  If you''re ever ready and willing, I may have some more work for you in the Plaguelands.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25046;
        UPDATE `quest_template` SET `OfferRewardText` = 'Most of this looks just fine! How lucky!$B$BThe Steamwheedle goblins will be so happy to see their cargo back safe and sound. And here''s a reward for your good deeds, of course!$B$BWe''ve got lots of other stuff to do though! Busy busy!' WHERE `entry` = 25048;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, it''s going to be so much nicer around here now that they''re gone!$B$BAt least until more show up. But thank you!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 25049;
        UPDATE `quest_template` SET `OfferRewardText` = 'That was great! It looks like most of the goblins we helped made it back here and didn''t blow up. We really showed that goblin girl!$B$BHere''s a special reward for you, $gmister:miss;.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 25050;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fantastic! Gosh, this will make enough wire for an entire army.$B$BLucky us!', `RequestItemsText` = 'I hope you don''t think you''re hiding any for yourself, silly! These goggles can see right through your bags.$B$BAnd your armor.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 25054;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 25056;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmote3` = 273, `DetailsEmote4` = 6, `OfferRewardEmote1` = 4 WHERE `entry` = 25058;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m amazed that Soothfancy was capable of following a simple set of instructions. And ones that required him to keep his foolish mouth silenced as well.$B$BIn addition, it is honestly good to see you again, $n. Now that I''ve dropped the charade, you''ll get to see how gnomes get things done around here.' WHERE `entry` = 25061;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hey there, hon. Vol''jin sent you? So sweet of him to be thinkin'' of me.$B$BI surely could use da help, but ya have a bit more walkin'' ahead of ya.', `DetailsEmote1` = 1 WHERE `entry` = 25064;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 4 WHERE `entry` = 25066;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thanks for the help, this was really killin'' things here. Once you start losing men, you start losing manpower. And morale. And weapons. And the magazines you loaned to that one guy.$B$BYou know how it is.', `DetailsEmote1` = 396, `OfferRewardEmote1` = 396 WHERE `entry` = 25072;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome, young $r.$B$BYa come highly recommended, mon. It''s nice ta finally be meetin'' ya in person.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25073;
        UPDATE `quest_template` SET `RequestItemsText` = 'Do you have a keg of Blast-O powder yet?\n\nWhen you get one ... don''t shake it.' WHERE `entry` = 25079;
        UPDATE `quest_template` SET `OfferRewardText` = 'Those val''kyr have been really busy resurrecting you newbies lately.  I''ve already seen a couple dozen new bodies run down that hill since this morning.$b$bYou, however, are the most promising $c I''ve seen today.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25089;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done.  I enjoyed watching you smash those undead into rotting pulp!' WHERE `entry` = 25090;
        UPDATE `quest_template` SET `OfferRewardText` = 'Marin sent you? I''m appreciative of his help.$B$BI''m here to seek out Sul''thraze. If you wish to help, speak with Mazoga...he''s been cooperative so far.', `DetailsEmote1` = 1 WHERE `entry` = 25091;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 25, `OfferRewardEmote1` = 2 WHERE `entry` = 25093;
        UPDATE `quest_template` SET `OfferRewardText` = 'Once again you have helped us to overcome our mutual enemy, the Alliance.$B$BNow it is time for us to help you.', `DetailsEmote1` = 1 WHERE `entry` = 25098;
        UPDATE `quest_template` SET `OfferRewardText` = 'Of course you can borrow Bastia. That is, if she''ll take you.$B$B<Kilag winks.>', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25099;
        UPDATE `quest_template` SET `OfferRewardText` = '$N?! Nice kitty.$B$BLook we don''t have much time here. You might have noticed that the volcano is blowing?!', `DetailsEmote1` = 396, `OfferRewardEmote1` = 5 WHERE `entry` = 25100;
        UPDATE `quest_template` SET `RequestItemsText` = 'How''s the situation down there?\n\nWhen the raid started I popped a bullet into their ringleader, Stonespire, but they just kept right on coming.' WHERE `entry` = 25106;
        UPDATE `quest_template` SET `OfferRewardText` = '<The assistant looks confused.>$B$BHuh... what? Who?', `DetailsEmote1` = 5, `OfferRewardEmote1` = 6, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 25109;
        UPDATE `quest_template` SET `OfferRewardText` = '<Assistant Greely spots the Kaja''Cola Zero-One in your hand and her eyes seem to come to life.>' WHERE `entry` = 25110;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 25111;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 21 WHERE `entry` = 25112;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 273 WHERE `entry` = 25115;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 25121;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25122;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `OfferRewardEmote1` = 5 WHERE `entry` = 25123;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 25125;
        UPDATE `quest_template` SET `RequestItemsText` = '<Marley''s breathing is ragged, coming and going in shuddering gasps.>\n\n<His eyes look at you imploringly.>' WHERE `entry` = 25151;
        UPDATE `quest_template` SET `OfferRewardText` = 'Another one of Kaltunk''s recruits, hm?$b$bA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you''re ready to leave the Valley, you''ll be a proud warrior of the Horde.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 11, `DetailsEmote4` = 25, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 4 WHERE `entry` = 25152;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m glad you were here, mon.$B$BToshe be lookin'' like he wants to chase dem down. You should go help''em.', `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25164;
        UPDATE `quest_template` SET `DetailsEmote1` = 94, `DetailsEmote2` = 94 WHERE `entry` = 25165;
        UPDATE `quest_template` SET `OfferRewardText` = 'He was controlling a sea giant? Fascinating. If we''d managed to investigate further...$B$BOh, I mean, wow, that''s totally crazy! But thank goodness he''s gone, hooray! Mister Noggenfogger will be so pleased.$B$BHere''s a nice big reward, you!' WHERE `entry` = 25166;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 25167;
        UPDATE `quest_template` SET `OfferRewardText` = 'A battle well-fought, $c, but I still have my doubts about our effectiveness.  These humans don''t seem to be going anywhere.$b$bYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 60 WHERE `entry` = 25168;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25169;
        UPDATE `quest_template` SET `DetailsEmote1` = 94, `DetailsEmote2` = 94, `DetailsEmote3` = 94, `OfferRewardEmote1` = 94 WHERE `entry` = 25170;
        UPDATE `quest_template` SET `OfferRewardText` = 'That troll wants us to send help?  Bah, he can forget it.  I''ve got my own human problems to worry about, and even those are the least of my worries right now.$b$bSen''jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25171;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 15, `OfferRewardEmote1` = 66 WHERE `entry` = 25173;
        UPDATE `quest_template` SET `OfferRewardText` = '$G You brought me my treasure!  What a sweetheart!: About time you showed up.  Don''t even think about stealing that treasure... it''s worthless here in Kalimdor, anyhow.;', `RequestItemsText` = '$g<Gail purrs disarmingly at you.>: <Gail glares menacingly at you.>;', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25176;
        UPDATE `quest_template` SET `OfferRewardText` = 'The scent of the sea hangs about you, $N.  Your efforts may have purchased another day for Razor Hill.$b$bI will pass word of your deeds up my chain of command.  You have our gratitude.', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `OfferRewardEmote1` = 66 WHERE `entry` = 25177;
        UPDATE `quest_template` SET `OfferRewardText` = '$g You really know how to treat a girl, you know that?  If you ever need anything...: Well, I suppose you''re not completely useless.  Now stay away from my men!;', `RequestItemsText` = '$g Has my knight in shining armor returned?: Well?;', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25178;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''ve already spoken with several orcs that have returned from the beach.  All of them told me that you were the one who saved them.$b$bYou''ve done a noble task today, $N.  Lok''tar ogar!  For the Horde!', `OfferRewardEmote1` = 1 WHERE `entry` = 25179;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 25184;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 25187;
        UPDATE `quest_template` SET `OfferRewardText` = 'I used that trick you taught me with the spyglass, and I watched you running around down there.  Quite impressive!$b$bHow''d you make the old woman fly, by the way?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 25188;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 2 WHERE `entry` = 25189;
        UPDATE `quest_template` SET `OfferRewardText` = '<Raggaran appears to have calmed down a bit since your last encounter.>$b$bGood, good.  One step closer to eliminating those beady-eyed, basket-wearing, hog-nosed, two-toed...$b$b<Raggaran''s anger is clearly rising again.>$b$b...hunchbacked, squealing, prickly... no-good... gnome-loving... GREEEAAAAGH!  Quilboar!', `RequestItemsText` = 'I hate quilboar!', `DetailsEmote1` = 1, `DetailsEmote2` = 15, `OfferRewardEmote1` = 1 WHERE `entry` = 25190;
        UPDATE `quest_template` SET `OfferRewardText` = '<Again, Raggaran appears calmer.>$b$bYou''ve done well, stranger.$b$bI''m sorry you had to see me like that.  Thank you for killing the quilboar, but maybe you should leave before I fly into another one of my rages.', `DetailsEmote1` = 22, `OfferRewardEmote1` = 1 WHERE `entry` = 25192;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $r.  I will get to work on the necklace right away.$b$bBefore Kron died, I had made this for him to wear.  I have no use for it now, but perhaps you might.', `DetailsEmote1` = 1, `DetailsEmote2` = 18, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25193;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 275, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25194;
        UPDATE `quest_template` SET `OfferRewardText` = 'Something happened to Screamslash when the cataclysm hit, Zen''Taji thinks.  He wasn''t always so violent and irrational.$b$bThank you for your help, $N.  Zen''Taji gonna get back to his studying now.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25195;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re the one who handled the Burning Blade to the south?  I''ve got ears in all kinds of places, $g boy: my girl;, and word travels fast.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25196;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 25, `OfferRewardEmote1` = 1 WHERE `entry` = 25200;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yeah, these will do nicely. You did good, kid. I''ll see to it that you get the best footbomb uniform ever made.$B$BIn the meantime, you''ve got other bombs to drop on the Trade Prince''s lackeys.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 273 WHERE `entry` = 25201;
        UPDATE `quest_template` SET `OfferRewardText` = 'He got just what he deserved. There, there, don''t cry. You''ll find someone else that''ll treat you right.$B$BHere, let me take that... we wouldn''t want people to think that you''re crazy.', `DetailsEmote1` = 274, `DetailsEmote2` = 273, `OfferRewardEmote1` = 1 WHERE `entry` = 25202;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 29, `OfferRewardEmote1` = 1 WHERE `entry` = 25203;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 25204;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 25205;
        UPDATE `quest_template` SET `OfferRewardText` = 'See?  The shaman''s tales are nothing but that... a youngling''s bedtime stories.  The new Horde takes what it wants, and doesn''t waste time with such frivolity.$b$bIf you get a chance, I recommend you tell Shin... and those like him... not to waste any more of your time.' WHERE `entry` = 25206;
        UPDATE `quest_template` SET `OfferRewardText` = 'I was wondering where you were!$B$BDon''t worry, Hobart will get that footbomb uniform converted into the most Ultimate Footbomb Uniform ever!', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25213;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 25, `OfferRewardEmote1` = 6 WHERE `entry` = 25214;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25215;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25216;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25217;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25218;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you. Seriously. If I would have had to endure another shipwreckee laughing at me, I swear I would have gored someone.$B$BI''ll let you know if I come up with anything.', `DetailsEmote1` = 1 WHERE `entry` = 25219;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25220;
        UPDATE `quest_template` SET `OfferRewardText` = 'Swift work. Very impressive.$B$BThat Fathom-Lord got away... I don''t see him anywhere. He''s most certainly the key to finding our captured friends.$B$BI will hunt him down. He cannot stay hidden for long.', `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25221;
        UPDATE `quest_template` SET `OfferRewardText` = 'A friendly face! Welcome!$B$BVery kind of you to come check on us. We''re fine. A naga scouting force did find us, but I''m pretty sure none escaped. We should be safe for now.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25222;
        UPDATE `quest_template` SET `OfferRewardText` = 'So you managed to pass this part of the test without getting yourself eaten by Smolderos or being incinerated by the fire elementals?$B$BI suppose I should congratulate you on ascending the lowest rung of our ladder.$B$BWell... congratulations, recruit!', `OfferRewardEmote1` = 1 WHERE `entry` = 25224;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 24 WHERE `entry` = 25227;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25232;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25233;
        UPDATE `quest_template` SET `OfferRewardText` = '<Jadi kicks open one of the crates and picks up a curved dagger within. She immediately winces in pain.>$B$BAugh! Cursed - this metal is cursed - it bites!$B$B<When the dagger falls to the ground, it shatters, as if made of brittle glass.>$B$BWhat demented workmanship is this? $N, I''ve never fought any foe like this before.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273, `OfferRewardEmote3` = 1 WHERE `entry` = 25234;
        UPDATE `quest_template` SET `OfferRewardText` = 'The electricity was only one of the dangers.  If those carcasses rot too long under the water, that entire source becomes undrinkable.$b$bWell done, $c.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 22, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25236;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m sure she deserved it, $N. She should never have betrayed you like that.$B$BIt gives me the shivers to think that she might have kissed that monster, the Trade Prince!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25243;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25244;
        UPDATE `quest_template` SET `RequestItemsText` = 'You seek to change the path you walk, $n?' WHERE `entry` = 25246;
        UPDATE `quest_template` SET `RequestItemsText` = 'You seek to change the path you walk, $n?' WHERE `entry` = 25247;
        UPDATE `quest_template` SET `RequestItemsText` = 'You seek to change the path you walk, $n?' WHERE `entry` = 25248;
        UPDATE `quest_template` SET `RequestItemsText` = 'You seek to change the path you walk, $n?' WHERE `entry` = 25249;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it! You did it!$B$BWe''re saved, $N!', `DetailsEmote1` = 5, `OfferRewardEmote1` = 4 WHERE `entry` = 25251;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25255;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 25256;
        UPDATE `quest_template` SET `OfferRewardText` = 'I watched you fight out there.  How long you been a $c?$b$bYou''re alright, kid.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25257;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25258;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25259;
        UPDATE `quest_template` SET `OfferRewardText` = 'I ask for an orb, and you bring half of the goblin''s arm with you?  I like the way you work.$b$bTell you what... you''ve already given me a hand.  Allow me to return the favor.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 21 WHERE `entry` = 25260;
        UPDATE `quest_template` SET `OfferRewardText` = 'Welcome, $N.  Word reached me of your coming, and of your exploits in Durotar.$B$BYou are a $c of growing skill and renown.$B$BStay on the pure path, and your future will be great indeed.', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 25261;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, and where did you get this?  Good Margoz sent you to me, did he?$B$BWell, let me take a closer look...', `RequestItemsText` = 'My most humble greetings, $c.  How might I help my $r $gbrother:sister; today?', `OfferRewardEmote1` = 5 WHERE `entry` = 25263;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 25264;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 15 WHERE `entry` = 25265;
        UPDATE `quest_template` SET `OfferRewardText` = '<The orc continues on in hushed tones.>$B$BI know who sent you. Did he give you something to deliver to me?', `RequestItemsText` = 'What possible business could you have in Orgrimmar, goblin?', `DetailsEmote1` = 396, `DetailsEmote2` = 397, `DetailsEmote3` = 2, `OfferRewardEmote1` = 1, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 25266;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thrall had you deliver this?$B$B<The Warchief takes a step back, visibly shaken.>$B$BI understand the meaning of this all too well, goblin.$B$B<Garrosh points to Gobber.>$B$BThis smelly thing was caught unattended in the city and seems to recognize you.$B$BI have already put others of your kind to work in Azshara. Take it with you when you leave.$B$BFrom this day forward, you and your Bilgewater Cartel will serve the Horde!', `RequestItemsText` = 'What is this, goblin? Your kind are not allowed inside Grommash Hold.$B$BLeave before I have to teach you your place.', `DetailsEmote1` = 25, `DetailsEmote2` = 11, `DetailsEmoteDelay1` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 397, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 25267;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re here to rescue me, $c? Thank you!$B$BNo, no, don''t worry about the cage for now. My life isn''t important. We''ve got to save the shrine, first.', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25268;
        UPDATE `quest_template` SET `OfferRewardText` = 'Lok''tar, $c! Don''t worry about this cage - these animals will come to fear me before long.$B$BMy first priority is to clear this filth away from my beloved shrine.', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `OfferRewardEmote1` = 15, `OfferRewardEmote2` = 1 WHERE `entry` = 25269;
        UPDATE `quest_template` SET `OfferRewardText` = '<Takrik examines the incense.>$B$BDisgusting. This is like the incense we burn when we wish to commune with the spirits... but it''s... befouled.', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 274, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25270;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ian examines the incense.>$B$BAs I suspected. These reagents bear the marks of the Twilight''s Hammer. And here, the name "Lycanthoth." I believe these are used in a summoning ritual...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 25271;
        UPDATE `quest_template` SET `OfferRewardText` = 'You were brave to face down Lycanthoth, $N. Like myself, he was a primal force of nature... but his origins were from a darker place.$B$BThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.$B$BCome, $c. Climb onto my back, and let us show these beasts the true face of ferocity!', `DetailsEmote1` = 1, `DetailsEmote2` = 5 WHERE `entry` = 25272;
        UPDATE `quest_template` SET `OfferRewardText` = 'You were brave to face down Lycanthoth, $N. Like myself, he was a primal force of nature... but his origins were from a darker place.$B$BThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.$B$BCome, $c. Climb onto my back, and let us show these beasts the true face of ferocity!' WHERE `entry` = 25273;
        UPDATE `quest_template` SET `OfferRewardText` = '$N? The $N?!$B$B<The labor captain eyes you up and down.>$B$BThe rumors are already flying about you. I don''t know if I should be thankful or frightened that you''re here. At least we don''t have any volcanoes in Azshara!$B$BHonestly, I can''t believe you''re showing your face here... Trade Prince Gallywix has setup shop atop the mountain!', `DetailsEmote1` = 25, `DetailsEmote2` = 1, `DetailsEmote3` = 15, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 25, `OfferRewardEmote3` = 1 WHERE `entry` = 25275;
        UPDATE `quest_template` SET `OfferRewardText` = '$Ndamus?  Let us hope your parents brought you into this world with more than just a ridiculous name.' WHERE `entry` = 25276;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hah! So you really sent some heads rolling, did you?$B$BIt was said during the War of the Ancients that Lo''Gosh fought demons for ten days solid. Hopefully you weren''t fighting that long...', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25277;
        UPDATE `quest_template` SET `OfferRewardText` = 'You really cleared that place out, didn''t you? Well done!$B$BThe night elves once told me a story about how Goldrinn fought and killed a dreadlord, even as three others clung to his flanks, burning his flesh. I wonder if you or I will ever have the strength to do the same?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4, `OfferRewardEmote3` = 273 WHERE `entry` = 25278;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 25279;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 5 WHERE `entry` = 25280;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 1 WHERE `entry` = 25281;
        UPDATE `quest_template` SET `OfferRewardText` = 'You think you''re ready for the next step then, $Ndamus?$B$BLet''s see what you''re capable of.' WHERE `entry` = 25291;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent job, $N.  Or should I say: "$N"damus?$B$BGive me a minute to read these.' WHERE `entry` = 25296;
        UPDATE `quest_template` SET `OfferRewardText` = '<You dump out the current contents of the cauldron, instantly killing the surrounding plant life.>$B$B<The draught you brew in its place boils chunky and reeks of rotted cabbage. You turn your head aside and bottle it up.>', `RequestItemsText` = '<The cauldron burbles, filled with a disgusting liquid.>' WHERE `entry` = 25297;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent! Let''s hope the damage wasn''t permanent.$B$BJudging by the poor victims still in camp here, the Twilight''s Hammer really messed with their heads.' WHERE `entry` = 25298;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve succeeded, $Ndamus.  You''re ready for the next step.' WHERE `entry` = 25299;
        UPDATE `quest_template` SET `OfferRewardText` = '<You approach the Eye of Twilight. As your fingertips graze its luminescent surface, you are aware of a malignant presence peering back at you, searching your soul.>$B$B<Instinctively, you draw back.>' WHERE `entry` = 25300;
        UPDATE `quest_template` SET `OfferRewardText` = '<A heavy tome, bound in flesh, lies open on the table.>$B$B<The language - pictographic and scrawled in rust-colored ink - is undecipherable, but notes and translations are tucked within several pages. This must be what you''re looking for.>' WHERE `entry` = 25301;
        UPDATE `quest_template` SET `OfferRewardText` = '<Flush with the energies of the captured elementals, you stand before the Twilight Apocrypha. The pages turn of their own accord.>$B$B<Suddenly, you see what the Eye sees. It is yours to command!>' WHERE `entry` = 25303;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re on the fast-track to success.  Let us hope you don''t ruin your track record with such silly notions as compassion and humaneness.$B$BCome, then.  Let us discuss your future.', `OfferRewardEmote1` = 1 WHERE `entry` = 25309;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $Ndamus.  We must show all would-be competitors that we are not ones to give up easily.' WHERE `entry` = 25310;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hello, yes? What? You? Oh, you''re one of the ones I sent after the Eye of Twilight, aren''t you?$B$BGood work, very good. I suppose that''s a valuable lesson:$B$BNever to take orders from a big purple ball.' WHERE `entry` = 25312;
        UPDATE `quest_template` SET `OfferRewardText` = 'You.  You''re clearly not with them.$B$BAn ally then?' WHERE `entry` = 25315;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ysera appears to be in some sort of trance.>' WHERE `entry` = 25316;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 25324;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did well, $N.  I will take Fandral to Moonglade myself.$B$BHis prison will be far enough from the battlefront there.', `RequestItemsText` = 'Is Staghelm with you, $N?' WHERE `entry` = 25325;
        UPDATE `quest_template` SET `OfferRewardText` = '<Kristoff reaches down to snatch the key.>$B$BIt''s about time!$B$B<He squirms in his bonds, trying to reach the padlock behind his back.>$B$B...Can I get a little help here?', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25328;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $Ndamus.  I''m having the servants you chose for me briefed on their new duties.' WHERE `entry` = 25330;
        UPDATE `quest_template` SET `OfferRewardText` = 'Kristoff, Kristoff... Oh yes, I remember now. I recall sending him on what amounted to a suicide mission.$B$BHe survived? I suppose that means he failed.$B$BStill, you deserve at least some coin for the trouble.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 374, `OfferRewardEmote3` = 273 WHERE `entry` = 25332;
        UPDATE `quest_template` SET `OfferRewardText` = 'We''d all suspected da naga, but I knew nothin'' of the Twilight Cult bein'' beneath the waves. Somehow dey are corruptin'' and pervertin'' the elements, makin'' demselves into dese horrors.$B$BWe goin'' ta have to be fightin'' both of dese threats to stand a chance of bringin'' peace ta Vashj''ir. We don''t have da men ta do that yet.$B$BCome, $c, we got much ta do.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25334;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25352;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, it is true! You indeed carry lightning in your hands.$B$BYou are the chosen one, $N. You will be my champion, and carry my vengeance to realms where I cannot tread...', `RequestItemsText` = 'We meet again, $c. You carve a path of fear and confusion in your wake.$B$B<Goldrinn''s eyes twinkle expectantly.> ' WHERE `entry` = 25353;
        UPDATE `quest_template` SET `OfferRewardText` = 'Impressive, $N. Very impressive.$B$BYou embody all of the strength of the wolf ancient, and possess the wisdom to use your powers well. I salute you.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 66 WHERE `entry` = 25354;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, it is true! You indeed carry lightning in your hands.$B$BYou are the chosen one, $N. You will be my champion, and carry my vengeance to realms where I cannot tread...', `DetailsEmote1` = 1, `DetailsEmote2` = 25 WHERE `entry` = 25355;
        UPDATE `quest_template` SET `OfferRewardText` = 'I trust we both know what''s been going on inside these crates...$b$bThat''s right... ferrrmenntation! Here y''are. My personal secret recipe.$b$bYou wouldn''t get this from any other guy!', `OfferRewardEmote1` = 30 WHERE `entry` = 25358;
        UPDATE `quest_template` SET `OfferRewardText` = 'I remember you. You were there when they attacked us back in the cave.$B$BGood to have you with me, $c. Ready for a little vengeance?', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25359;
        UPDATE `quest_template` SET `OfferRewardText` = 'Does everything down here only come in jumbo size? Oooh! That''s a thought. Maybe there are some hunky sea goblins around here somewhere.$B$BThanks, by the way.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25360;
        UPDATE `quest_template` SET `OfferRewardText` = 'Amazing! You look exhausted. She must have really made you work for it.$B$BLife should be a lot easier down here going forward with a mount that swift at your beckoning. Congratulations, $n!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25371;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is the key, $N! With the seedlings you collected for me earlier, the animals you''ve saved from around Hyjal, and the Heart of the Forest you''ve just discovered, we can rejuvenate this land right from under the feet of Twilight''s Hammer. Imagine their astonishment to see their work undone, as life triumphs over chaos...$B$BI will begin the ceremony at once!', `OfferRewardEmote1` = 5 WHERE `entry` = 25372;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 1 WHERE `entry` = 25381;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dead? Good!$B$BBut it seems there''s still so much to be done... fires to quench... and the soil to heal...$B$BI hope you''ll stay close and help us reclaim Hyjal!' WHERE `entry` = 25382;
        UPDATE `quest_template` SET `OfferRewardText` = 'Squueeeee!$B$BDid the nice $gMr.:Mrs.; $c pull you from the flames, little friend? You''re safe now!$B$BHooray!', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25385;
        UPDATE `quest_template` SET `OfferRewardText` = 'Why, $n! What a surprise!$b$bIf anyone ever calls your character into question you be sure to send them my way.$b$bI''ll tell anyone who''ll listen that in my moment of need, you gave me a case of crabs...', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25388;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, my!$b$bThat''s some of the biggest, juiciest tail I''ve ever seen!' WHERE `entry` = 25389;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, you''ve found them! I was sure they were lost forever...$b$bHere you are, $n. I hope this is ample payment.', `RequestItemsText` = 'Well, $r?$b$bWere you able to recover my valuables?', `OfferRewardEmote1` = 71 WHERE `entry` = 25390;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh yay! Happy little deer!$B$BNow they can grow up and have ADVENTURES.$B$BYou''re swell.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 25392;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very well, $r. I will help you mortals, even from within my bonds.$B$BBut don''t sicken me by claiming it''s my redemption. I do this for my own ends.$B$B<Blackhorn''s sudden grin is unsettling.>', `OfferRewardEmote1` = 1 WHERE `entry` = 25404;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000 WHERE `entry` = 25405;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very good. Please crush the berries into a pulpy liquid. That''s quite an aroma isn''t it?$B$BNow now, don''t gag. It''s beneath you.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 11 WHERE `entry` = 25408;
        UPDATE `quest_template` SET `OfferRewardText` = '<The wretched creature before you speaks in a wavering voice, its body broken but briefly animated by Blackhorn''s vile potion.>$B$BYes, master?', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 6 WHERE `entry` = 25411;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, yes! Show me the runes you discovered.$B$B"Vol''talo Thol''embaar." That''s the name of your real enemy.$B$BPresumably you''re dealing with one of Ragnaros''s generals, sent here to scorch the mountainside and pave the way for his conquest.$B$BI will show you how to crush him.', `OfferRewardEmote1` = 1 WHERE `entry` = 25412;
        UPDATE `quest_template` SET `OfferRewardText` = 'This treasure was obviously crafted by the local water-goblins for a female they regarded highly.', `OfferRewardEmote1` = 396 WHERE `entry` = 25419;
        UPDATE `quest_template` SET `OfferRewardText` = 'There it is! Such a trophy! Born in the fires of another plane...$B$BGo ahead, $r. Crush it. Crush his charcoal heart in your hands and let the winds scatter the ashes... yes, yes.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 25428;
        UPDATE `quest_template` SET `OfferRewardText` = 'My duties are here, viewing the enemy''s movement from above, commanding our armies where they''re needed.$B$BYour aid would be most welcome.' WHERE `entry` = 25430;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25439;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25440;
        UPDATE `quest_template` SET `OfferRewardText` = 'Too often, we are mistaken for druidic types. Perhaps that''s true for some shaman, but do not let yourself be plagued by the ignorant belief that we are always peaceful.$B$BNothing about what I do is harmonious. I command the elements to my will. There is nothing offered in return. I would have it no other way.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25441;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 25442;
        UPDATE `quest_template` SET `OfferRewardText` = 'Sam''s in one piece then? And his poor assistant Felice? Good to hear.$B$BI hope that one day he''ll learn to respect the elements as more than just a tool.', `OfferRewardEmote1` = 1 WHERE `entry` = 25456;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well that''s a load off my mind.$b$bThank you again, $c.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25459;
        UPDATE `quest_template` SET `OfferRewardText` = 'I thank you, $N. Those little bears are shaken up but they''ll survive.$B$BAt least the ones that hit the mat.', `OfferRewardEmote1` = 1 WHERE `entry` = 25462;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N.  We cannot afford to lose any further ground in Hyjal.$B$BBy stopping Baron Geddon we will have dealt a huge blow to the enemy.' WHERE `entry` = 25464;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ello, mon! You look a bit more capable then most of dem coming through here.$B$BCome rest a bit. Make yaself at home.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25471;
        UPDATE `quest_template` SET `OfferRewardText` = 'Just so you know, you''ll find Kaja''Cola all over town. It''s the Bilgewater Cartel''s best-selling product of all time!$B$BJust remember, image is everything if we''re going to get you promoted to Trade $g Prince : Princess;! No, wait, profits are everything! Explosions are a close second! Then, image!', `RequestItemsText` = '<Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.>$B$BWe need more Kaja''Cola than this!$B$BI swear I''m going to fire Dampwick if I don''t kill him first!', `DetailsEmote1` = 6, `DetailsEmote2` = 5, `DetailsEmote3` = 6, `CompleteEmote` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 25, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 25473;
        UPDATE `quest_template` SET `OfferRewardText` = 'How unfortunate...$b$bWell, all things considered, it is good to see that you made it back unharmed.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25477;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 25478;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25490;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Arch Druid inspects the seedlings.>$B$BThese seedlings have survived an apocalypse. Even a handful hold great power. Life always replenishes itself, often stronger than before.$B$BOnce the way is clear, we will use these to perform a miracle on this mountain, $N. You will see.', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25491;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work, $N. There''s a chance the forest will recover from this yet.$B$BNow, there''s something else I need you to take care of for me...', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25492;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very good. We will need these to act as bait while they are still warm.$B$BHere is my plan...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25493;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4 WHERE `entry` = 25496;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh.  You''re still alive.$B$BNot bad.', `OfferRewardEmote1` = 1 WHERE `entry` = 25499;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s good! Between your work and the work of a few others, that valley is secure from a counter-attack.$B$BI''ve done all I can. It''s all up to you and the Arch Druid now.', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25502;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Arch Druid takes the shell from you with surprising reverence.>$B$BNemesis is an instrument of evil, but he was forged from a shell fragment of the true ancient.$B$BWe will exploit this connection.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25507;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 25509;
        UPDATE `quest_template` SET `OfferRewardText` = '$R.$B$BThis tongue. Is not yours.$B$BWhat do you want ... tormentor?' WHERE `entry` = 25510;
        UPDATE `quest_template` SET `OfferRewardText` = '<Tortolla quivers and shakes debris free from his great back.>$B$BYou...$BAre not like the others.$B$BI am free once again.$B$BThe others...$BWill pay.' WHERE `entry` = 25514;
        UPDATE `quest_template` SET `OfferRewardText` = '$R.$BYou are not like the others.$B$BBraver. Stronger.$BA part of this world...$B    and not the shadow that came before.$B$BThank you.' WHERE `entry` = 25519;
        UPDATE `quest_template` SET `OfferRewardText` = '$N!$B$BYou were able to earn the ancient''s trust?$B$BWonderful! We are one step closer to taking back this mountain...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25520;
        UPDATE `quest_template` SET `DetailsEmote1` = 20, `OfferRewardEmote1` = 21 WHERE `entry` = 25521;
        UPDATE `quest_template` SET `DetailsEmote1` = 18, `OfferRewardEmote1` = 4 WHERE `entry` = 25522;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done! How does it feel?$B$BIt is challenging to master flight in this burning wasteland, but it is the only way.$B$BI hope you''re ready for battle, $N...', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25523;
        UPDATE `quest_template` SET `OfferRewardText` = 'Spectacular flying, $N! Their screeches of anguish echoed about this light-forsaken cavern.$B$BBut our work is not yet finished...', `OfferRewardEmote1` = 66, `OfferRewardEmote2` = 5 WHERE `entry` = 25525;
        UPDATE `quest_template` SET `OfferRewardText` = 'By the wings of Aviana - you were born to fly, $N!$B$BQuickly, let''s get back out there and hit them again...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 25544;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 66 WHERE `entry` = 25548;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 66 WHERE `entry` = 25549;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $N.  We shall soon claim victory in Hyjal.$B$BIt has been an honor to fight along your side.' WHERE `entry` = 25550;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 25560;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25575;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dead? Good. They sealed their fate when they threw their lot in with Ragnaros and his kingdom of flame.$B$BLeave their bodies down here to crumble into ash.', `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 274 WHERE `entry` = 25576;
        UPDATE `quest_template` SET `OfferRewardText` = 'Great work!$B$BThere was a time when adventurers would collect these cores in order to craft mediocre fire-resistant equipment. But for now, I''m glad just to destroy these fiends once and for all.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 25577;
        UPDATE `quest_template` SET `OfferRewardText` = 'Alysra''s decision might not have been the wisest, $N.  Yet there is little time to worry about that now.$B$BI bring important discoveries from the Emerald Dream.' WHERE `entry` = 25578;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ysera sent you? Good! We need all the help we can get.$B$BWe''ll never be able to recover the shrines to the ancients so long as Twilight''s Hammer controls the roads. Somehow we''ve got to stem the flood.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 25584;
        UPDATE `quest_template` SET `OfferRewardText` = 'I cannot thank you enough, $r.$b$bI just hope this whole nightmare has a happy ending.', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500, `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 396, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 25587;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25592;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25593;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `OfferRewardEmote1` = 1 WHERE `entry` = 25594;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25595;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hey there.  I''m glad to see they sent someone of your caliber for this operation.$B$BThis here''s going to call for some subtlety.  We can''t risk Commander Shadowsong getting killed.' WHERE `entry` = 25597;
        UPDATE `quest_template` SET `OfferRewardText` = 'Where would we be without you, $r!$b$bI don''t want to even imagine!', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 500, `OfferRewardEmote1` = 71 WHERE `entry` = 25598;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is the tome we''ve heard about?$B$B<Jordan hefts the stone slab into his arms and looks it over.>$B$BI see... I guess it''s good that I can read some of the elemental script. I''ll work on translating this. Meanwhile, there''s one final problem to take care of.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1 WHERE `entry` = 25599;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 273 WHERE `entry` = 25600;
        UPDATE `quest_template` SET `OfferRewardText` = 'There you are, $Ndamus.  I''ve been meaning to talk to you about something.$B$BI heard about the unfortunate incident that befell our poor friend, Okrog.$B$B<Mylva looks to her left, then her right.  She finally nods and shoots a sly wink in your direction.>$B$BYou might be a better pupil than I had thought.' WHERE `entry` = 25601;
        UPDATE `quest_template` SET `OfferRewardText` = 'Outstanding!$b$bLet''s see if this does the trick....$b$bStand back, $n!', `OfferRewardEmote1` = 396 WHERE `entry` = 25602;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 1, `DetailsEmote3` = 11, `DetailsEmote4` = 6, `DetailsEmoteDelay1` = 1000, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `DetailsEmoteDelay4` = 1000, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 25607;
        UPDATE `quest_template` SET `OfferRewardText` = 'They''re moving supplies to Hyjal straight from the elemental planes? That explains so much.$B$BYou''ve made Goldrinn proud by sealing that flamegate, $N, but there may be more portals to seal. You should check with the other shrines!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 25611;
        UPDATE `quest_template` SET `OfferRewardText` = 'They''re moving supplies to Hyjal straight from the elemental planes? Devious.$B$BYou''ve made Lo''Gosh proud by sealing that flamegate, $N, but there may be more portals to seal. You should check with the other shrines!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 25612;
        UPDATE `quest_template` SET `OfferRewardText` = '<Kalen sighs.>$B$BWe use guns just fine, friend. CANNONS, on the other hand, I take issue with...', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25613;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 25614;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the airways clear our hippogryphs will be able to move into Stonetalon freely. Well done, $N!$B$BNow on to more pressing matters. $B$BWhat you witnessed at Trueshot Point was a small sampling of the decimation left in the wake of Hellscream''s legacy. As Warchief of the Horde, Hellscream has declared Kalimdor as the Horde''s sovereign territory. All that would oppose the Horde are destroyed.$B$BWe are Kalimdor''s last line of defense. Should we fall, Kalimdor will also fall. The Horde must be stopped!', `DetailsEmote1` = 1, `DetailsEmote2` = 2 WHERE `entry` = 25615;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25616;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, you are the champion Lo''Gosh promised! Your eyes don''t deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We''ve got our work cut out for us here.$B$BPut aside your differences with the Alliance, there''s plenty of danger to go around.$B$BAnd take this: the Fang of Lo''Gosh will allow you to channel the ancient''s power here within the Firelands. Use it well!', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274 WHERE `entry` = 25617;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, you are the champion Goldrinn promised! Your eyes don''t deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We''ve got our work cut out for us here.$B$BPut aside your differences with the Horde, there''s plenty of danger to go around.$B$BAnd take this: the Fang of Goldrinn will allow you to channel the ancient''s power here within the Firelands. Use it well!' WHERE `entry` = 25618;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25619;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25620;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Gnomecorder crackles and pops with static electricity.>$B$BCome in, $N. Can you hear me? Zis iz Professor Xakxak!$B$B*POP*$B$B*CRACKLE*$B$BPERFECT! Viz ze Gnomecorder I vill be able to direct you about Stonetalon vile staying out of harmz vay!$B$BNow, onto our next order of buziness!', `DetailsEmote1` = 4, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 25621;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Gnomecorder buzzes loudly.>$B$BVonderful! As promised, VOILA, your reward!$B$BNow, I have a bit of news that you might find interesting.' WHERE `entry` = 25622;
        UPDATE `quest_template` SET `OfferRewardText` = 'Can this wait, $c? The battle is not going well.$B$BOh, you''re here to help. I hope you don''t mind a little heat...', `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1 WHERE `entry` = 25630;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25637;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good to see you again, $N. Thanks for the rescue in Ashenvale. Damn shame about all the gnomes we lost.$B$BYou ready to get down to business?$B$B<Boog points to "The Bomb.">', `OfferRewardEmote1` = 1 WHERE `entry` = 25640;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25642;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice job, I could hear their shrill screams from out here. You''ve turned the whole place on its head!$B$BDid you happen to find any other information about the mining operation?' WHERE `entry` = 25646;
        UPDATE `quest_template` SET `OfferRewardText` = '<Boog takes the letter from you and begins to examine it.>$B$BInteresting.$B$B<Boog smells the parchment.>$B$BHrm... Troubling...$B$B<Boog folds the paper in half and looks at you.>$B$BCan''t understand a damn thing written here - if that is writing. Could just be toilet paper. Sure smells like it.' WHERE `entry` = 25647;
        UPDATE `quest_template` SET `OfferRewardText` = '<Minx takes the letter from you and begins to read it.>$B$BUh oh...$B$B<Minx smells the parchment.>$B$BDisgusting!$B$B<Minx folds the paper in half and looks at you.>$B$BThe good news is that this isn''t toilet paper. The bad news is that the ink on this paper is a mixture of kodo poop and blood. That''s not the worst of it, though...', `OfferRewardEmote1` = 1 WHERE `entry` = 25649;
        UPDATE `quest_template` SET `OfferRewardText` = '<Beads of sweat roll down Boog''s overly large forehead as he reads the translated letter.>$B$BThis is bad. Really, really bad. You have to warn Lord Fallowmere at Windshear Hold.$B$BWhat in the... It''s MOVING! The goblin balloon is taking off! We''re too late!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 25650;
        UPDATE `quest_template` SET `OfferRewardText` = 'My gunpowder!$b$bYou found it! I''m not crazy after all!', `RequestItemsText` = 'You want nuthin'' to do with me, $r.$b$bI''m a touch... screwy.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 25651;
        UPDATE `quest_template` SET `OfferRewardText` = 'Amazing story, $g lad:lass;. I''d have never believed you had I not seen it with my own eyes. You did enough damage to that balloon to make those fiends pull back! Alas, the threat is far from over. We have only delayed the attack. There is much work to do if we are to stop the Horde from destroying Stonetalon!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 25652;
        UPDATE `quest_template` SET `OfferRewardText` = 'By relieving Tortolla of his final burdens you have acquired for us a formidable ally... and the final piece of the puzzle.$B$BSteel yourself, $N. The most difficult part of our journey is to begin.$B$BWe will bring the fight to their stronghold.' WHERE `entry` = 25653;
        UPDATE `quest_template` SET `OfferRewardText` = '<Thisalee nods, contentedly, her eyes sparkling.>$B$BFeels great to be off the leash, doesn''t it?', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25655;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good, that''s a start.$B$BThe birds who laid these eggs will never accept them again, so we''ll have to raise these birds as orphans in the shrine here. Were Aviana here, she never would''ve let this travesty happen.$B$BBut, on to business...', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 25656;
        UPDATE `quest_template` SET `OfferRewardText` = 'Amazing!$b$bYou watch the great white beast swim off into the depths and wonder to yourself if anything could ever take him down...', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 1000 WHERE `entry` = 25657;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25658;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 25659;
        UPDATE `quest_template` SET `RequestItemsText` = 'My captor holds the key to this cage.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25662;
        UPDATE `quest_template` SET `OfferRewardText` = '<A whispered plea rings within your head.>$B$BTo be born again, but in darkness...$B$BI have been stolen away.$B$B<The spirit appears frantic, but falls silent as her image fades.>' WHERE `entry` = 25663;
        UPDATE `quest_template` SET `OfferRewardText` = 'That was nasty work, $N, but it had to be done.$B$BAnd if Aviana is truly to be resurrected, then perhaps your actions have enabled Blaithe to someday come back as well?$B$BNow let''s see if we can contact our long lost guardian...', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 2, `OfferRewardEmote3` = 1 WHERE `entry` = 25664;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 274 WHERE `entry` = 25665;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25667;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25668;
        UPDATE `quest_template` SET `OfferRewardText` = 'A hero thwarted their plans to destroy Windshear Hold, eh? That hero was you, $N. You are the pride of the Alliance!$B$BIt seems that you have bought us a little bit of time. I must plan for the battle that lies ahead of us. Seek out the other inhabitants of Windshear Hold and lend them your assistance. I will call for you when I am ready to initiate our defensive strategy.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 25, `OfferRewardEmote3` = 66, `OfferRewardEmote4` = 1 WHERE `entry` = 25669;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 5, `DetailsEmote4` = 396, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500, `DetailsEmoteDelay4` = 500, `OfferRewardEmote1` = 396 WHERE `entry` = 25670;
        UPDATE `quest_template` SET `OfferRewardText` = '<Alice claps excitedly.>$B$BMr. P you''re gonna be ok! Hooray!$B$B<Alice expertly places all of the parts you collected into Big Papa.>$B$BOh, Mr. P! I knew it!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25673;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25724;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lord Fallowmere coughs.>$B$BThis is awkward...$B$BGood job out there with the robot. You caught me a little off guard. I didn''t realize the little girl was so...$B$B<Lord Fallowmere points to his temple and twirls his finger around.>$B$BSpecial...$B$BWell, whatever gets the job done, right? Am I right?$B$BProbably.$B$BHave some ice cream.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25728;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Gnomecorder buzzes loudly.>$B$BVonderful! That''s von more name I can scratch off of my list!$B$BI vill be in touch.$B$BXakxak, out!' WHERE `entry` = 25729;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 1 WHERE `entry` = 25730;
        UPDATE `quest_template` SET `OfferRewardText` = 'So the harpies are tools of some sort of dragon - "Sethria."$B$BBut what are the dragons doing to those eggs? And what''s this ''special'' egg that Sethria wanted so badly?$B$BThis is beyond me, $N. I''ve given a report to Skylord Omnuron - he''ll know what to do next.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 25731;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is it?$b$bHow is this gunna remove - wait a minute...', `RequestItemsText` = 'So, $r...$b$bYou gunna remove this curse, or what?', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 6 WHERE `entry` = 25732;
        UPDATE `quest_template` SET `OfferRewardText` = '<Captain Kosak forces a smile at you.>$B$BDon''t worry about me. Should be ok now that big hero killed the spider queen.$B$BCan get reinforcements through safely now.' WHERE `entry` = 25739;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, $N! I was hoping to see you out here.$B$BWhat, Omnuron calls this a ''fact-finding mission?'' Bah! Facts are best found on corpses.$B$BLet''s do some damage.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5 WHERE `entry` = 25740;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 25741;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25743;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re good at this.$B$BI like you.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 25746;
        UPDATE `quest_template` SET `OfferRewardText` = 'Look at these things. Ugh, the runes make my eyes hurt. This one here is meant to sear flesh? Seriously? Ouch! Wait a minute...$B$BThese plates are designed to be riveted directly into flesh. The pain must be unbearable!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 274 WHERE `entry` = 25758;
        UPDATE `quest_template` SET `OfferRewardText` = 'That was some fancy bladework, $N!$B$BThere''s one less threat for us to worry about in Hyjal.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 25761;
        UPDATE `quest_template` SET `OfferRewardText` = 'They''re doing what?$B$BThey''re cloaking something? Of course - so our aerial scouts can''t see anything with our eagle-eyes!', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5 WHERE `entry` = 25763;
        UPDATE `quest_template` SET `OfferRewardText` = 'We did it, $N! Aviana''s Egg should soon be tucked safely in the boughs of her shrine.$B$BDo you think this means she''ll really return to us?', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 25764;
        UPDATE `quest_template` SET `OfferRewardText` = 'Kosak sent you, eh? Surprising. I thought for sure that he''d be dead by now.$B$BWell if you made it past the blockade then you definitely have something that we can use.$B$BNow, do you have any news of the Horde? What are they doing? Where are they going? Tell me everything.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 25765;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25766;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 25767;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 113, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25768;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25769;
        UPDATE `quest_template` SET `OfferRewardText` = 'Sethria is slain! I knew it was worth the risk.$B$BI''ll stay here to look for survivors, but I imagine they''ll want to see you back at the shrine.', `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1 WHERE `entry` = 25776;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25792;
