        UPDATE `quest_template` SET `OfferRewardText` = 'We must make haste!$b$bAs you can surely see, his time is not long.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 396, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 25794;
        UPDATE `quest_template` SET `OfferRewardText` = '$N! Is it true you led an assault against a twilight dragon?$B$BYou are truly a herald of the ancients!', `OfferRewardEmote1` = 6 WHERE `entry` = 25795;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Gnomecorder buzzes and whirs.>$B$BHey, this thing on?$B$B<You hear a tapping sound.>$B$BAnybody there?', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 25806;
        UPDATE `quest_template` SET `OfferRewardText` = 'I ... live.$B$BThose that tried to corrupt me and kidnap my children will soon feel the rake of my talons, $c. Believe it.$B$BContinue to push forward across Hyjal. I will collect myself and assemble with the other ancients.', `OfferRewardEmote1` = 1 WHERE `entry` = 25807;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25808;
        UPDATE `quest_template` SET `DetailsEmote1` = 5 WHERE `entry` = 25809;
        UPDATE `quest_template` SET `OfferRewardText` = 'So it''s true - Aviana has returned, with you as her herald.$B$BThere''s much to be done here. We are deep in the heart of the Firelands. Sethria smuggled stolen eggs from Mount Hyjal here to hatch her own hideous creations - birds of prey, trained for war.$B$BI hope you''re ready to fight back!', `OfferRewardEmote1` = 5 WHERE `entry` = 25810;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 25811;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25821;
        UPDATE `quest_template` SET `DetailsEmote1` = 273, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 25822;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 71 WHERE `entry` = 25823;
        UPDATE `quest_template` SET `OfferRewardText` = '<Aviana''s face is immobile as you tell her about what happened within the hatchery.>$B$BThey stole my eggs, $c. They took them to that foul place. Corrupted them.$B$BMy children stolen, tormented, killed in a vat of flame... Yes, we will make Twilight''s Hammer pay.$B$BBut I confess, part of me wants to fly up and simply watch this whole... world... burn.' WHERE `entry` = 25832;
        UPDATE `quest_template` SET `OfferRewardText` = 'The name be "Cookie," $g lad:lass;: greatest cook ''cross Azeroth. Now the Commander''s told me what we be needin'' to do. To gain audience with the Grimtotem chief we''re gonna have to cook up the finest of tauren cuisine.$B$BYe get me the ingredients and I''ll put together an offerin'' no tauren could refuse. Not even a grim tauren or whatever them things be.', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote4` = 273, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25834;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25837;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 25838;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25839;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25840;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25841;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $r.$B$BI am ready now.$B$BAll that I am, and all that this forest once was... it is now yours.' WHERE `entry` = 25842;
        UPDATE `quest_template` SET `OfferRewardText` = '$R.$B$BI remember you. Savior of my children.$B$BThe time has come. For vengeance.' WHERE `entry` = 25843;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ton and his bodyguards scarf down the meaty offering.>$B$BThis... this is the greatest thing I have ever tasted. You may prove to be a valuable ally, but before the Grimtotem agree to work with the Alliance, you must agree to our terms. I will now give to you those terms as told to me by my leader. Take them back to your commander and see if he accepts.', `RequestItemsText` = '<Ton Window sniffs at the air and raises his left hand.>$B$BYou have brought something for us?', `DetailsEmote1` = 396, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 397 WHERE `entry` = 25844;
        UPDATE `quest_template` SET `OfferRewardText` = 'Weapons, eh?$B$B<Force Commander Valen sighs.>$B$BI''m about to make an executive decision here, $N. Let''s hope this pays off, else King Wrynn will have my head!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 397, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 25845;
        UPDATE `quest_template` SET `OfferRewardText` = 'These are fine weapons! Powerful steel! My warriors will be unstoppable armed with such weaponry. Magatha smiles down upon you, $N.$B$BThere is but one thing I ask of you, perhaps two.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 66, `OfferRewardEmote1` = 15, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 66 WHERE `entry` = 25846;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you armed the Grimtotem?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25847;
        UPDATE `quest_template` SET `OfferRewardText` = '<Grundig crushes the insignia in his massive fist.>$B$BYes, ally, you have done it! It will take Hellscream weeks to recover from this blow. Southern Stonetalon belongs to the Grimtotem... and the Alliance, of course.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 15 WHERE `entry` = 25848;
