        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve assembled the survivors? Good, good. And the rest of the mountain - healed?$B$BHaha, strike me down! We''re on the front lines again!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 11 WHERE `entry` = 25881;
