        UPDATE `quest_template` SET `OfferRewardText` = 'The waters surrounding the Holding Pens are red with the blood of the naga.$b$bRendel would be proud!', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 5, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25884;
