        UPDATE `quest_template` SET `OfferRewardText` = 'It is as it should be.$b$bNow the way is clear to deal these naga a crippling blow.', `DetailsEmote1` = 396, `DetailsEmote2` = 5, `DetailsEmote3` = 396 WHERE `entry` = 25887;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 25889;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 25890;
        UPDATE `quest_template` SET `OfferRewardText` = 'Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal''darah Grove?$B$BTogether, we will make them understand. They will know that what they do comes at a great cost.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 15 WHERE `entry` = 25891;
