        UPDATE `quest_template` SET `OfferRewardText` = 'Wonderful! Still sharp. A little blood on the fletching, but they''ll fly true.$B$BThank you, $N. Our defense of Hyjal can continue.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 25901;
        UPDATE `quest_template` SET `OfferRewardText` = 'This power is ancient.$BPrimitive.$BEasy.$B$BWe will use it against them.' WHERE `entry` = 25904;
