        UPDATE `quest_template` SET `OfferRewardEmote1` = 6 WHERE `entry` = 25908;
        UPDATE `quest_template` SET `OfferRewardText` = 'So it is done.$B$BKnowing that Twilight''s Hammer is in league with creatures of malice such as these... it really curdles the blood.', `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 25910;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 25912;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25913;
