        UPDATE `quest_template` SET `OfferRewardText` = 'Ah yes, yes... the secret strength of Nemesis, unearthed here in these caverns.$B$BWe know all that we need to know, $N. It is time to finish this.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 25915;
        UPDATE `quest_template` SET `OfferRewardText` = 'The usurper has perished!$B$BTwilight''s Hammer dreamed of creating their own pantheon of twisted ancients to rule over the land, sea, and air. With your help, they''ve all been executed.$B$BWe must tell Tortolla at once!', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 4 WHERE `entry` = 25923;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 5, `DetailsEmote3` = 396, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1000, `OfferRewardEmote1` = 396 WHERE `entry` = 25924;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 25925;
