        UPDATE `quest_template` SET `OfferRewardText` = 'Gnolls and murlocs? Horse poopy, $g pal:lady;! Gnolls and murlocs didn''t kill these people. I''ve seen what gnolls and murlocs do to people that they kill and this... isn''t it. Too pretty. Too... perfect.$B$BFurthermore, the Furlbrow''s had been squatting on this farm for 5 years. No, whoever wiped them out had a reason. This is murder, plain and simple and we''re gonna get to the bottom of it...', `RequestItemsText` = 'Anything yet?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `IncompleteEmote` = 6, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 274 WHERE `entry` = 26209;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `IncompleteEmote` = 6, `CompleteEmote` = 6, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 274 WHERE `entry` = 26213;
        UPDATE `quest_template` SET `OfferRewardText` = 'Nice find, rookie. I think I have a stack of these on my desk back at the station. We''re basically back to square one. What do we know? Someone that likes to write fiction about the past sent the Furlbrows a letter.$B$BLooks like we got ourselves a real history... mystery.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `IncompleteEmote` = 6, `CompleteEmote` = 6, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26214;
        UPDATE `quest_template` SET `OfferRewardText` = 'Look, we ain''t got no room for no more...$B$BHoratio sent you? Right then... um, how can I help you?$B$BHe''s not here is he? Heh, he knows I wasn''t hidin'' from him, right? Was just tryin'' to lay low and all that, ya know?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 24 WHERE `entry` = 26215;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 26220;
