        UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to dig up some crawfish?', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 26226;
        UPDATE `quest_template` SET `OfferRewardText` = 'Let me see your hands... Aha!  You''re not any better at collecting these wretched things than I am!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 4 WHERE `entry` = 26227;
        UPDATE `quest_template` SET `OfferRewardText` = '<Lou puts his hands to his ears and starts talking loudly.>$B$BSTOP! STOP! STOP! I don''t wanna hear it! I don''t wanna know and I don''t care! That kind of information is liable to get you killed ''round these parts.$B$BI got one more bit of information for you and then we''re done!', `RequestItemsText` = 'Be careful with my old house. I plan to hand that off to my kids when they move out.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5, `OfferRewardEmote4` = 274 WHERE `entry` = 26228;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh SWEET justice! Killin'' those kobolds won''t make me walk like a normal person and it sure won''t get me a job, but damn does it feel good.$B$B<Jimb reaches into a crusty old sack.>$B$BHere, I think I got somethin'' for you from my kobold huntin'' days. Maybe you can put it to good use.', `RequestItemsText` = 'I just want those kobolds dead. Dead!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `IncompleteEmote` = 5, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 273 WHERE `entry` = 26229;
