        UPDATE `quest_template` SET `OfferRewardText` = 'Horatio Laine? That man is a scumbag. Dirty as my underwear.$B$BListen, friend, I don''t often give out advice like this, but you seem like a good $g man:woman;. GET OUT OF WESTFALL. You''re already in way over your head. All you''re doing now is putting your neck on the chopping block.', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 26236;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $g brother:sister;. You''ve done Salma and I a great service and I promise that it won''t soon be forgotten. I don''t have much money, but you''re welcome to what I do have.', `RequestItemsText` = 'Did you destroy the harvest watchers?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `DetailsEmote4` = 20, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 26237;
        UPDATE `quest_template` SET `OfferRewardText` = 'Bless your heart, dear. These poor orphans haven''t had a hot meal in days.$B$BIt looks like we will have enough left over to help feed many more of the homeless of Westfall.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `IncompleteEmote` = 1, `CompleteEmote` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26241;
