        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 26296;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26297;
        UPDATE `quest_template` SET `OfferRewardText` = '<Sauranok seems uninterested in the map as you relate your story.>$B$BTwilight Assassins followed you to the bar? Here, in Orgrimmar?$B$BThe Warchief won''t be happy about this.$B$BContinue your preparations for the invasion and I will investigate.', `RequestItemsText` = '<Sauranok is surprised to see you back so soon.>$B$BAh, $c, you return. What have you discovered?', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 26311;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1 WHERE `entry` = 26319;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 26320;
        UPDATE `quest_template` SET `OfferRewardText` = 'What, another message from Hellscream? His patience is thinner than calf''s hide.$B$BHave you ever worked with goblins before? Everywhere is another hidden cost! Our ships lie half-assembled and the air fleet is scattered to the winds.$B$BIf this invasion is going to happen, I''m going to need your help.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 26324;
        UPDATE `quest_template` SET `OfferRewardText` = '<Here, in excruciating detail, are the blueprints for the Foebreaker.>$B$B<You twist the documents every which way, trying to make sense of the incomprehensible scribbles, notes, and corrections.>', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `DetailsEmote3` = 5 WHERE `entry` = 26335;
        UPDATE `quest_template` SET `OfferRewardText` = 'So they were trying to skimp on production costs? Unacceptable!$B$BI''m glad you knocked some sense into them. If that foreman makes good on his word, our fleet will be ship-shape in time for the invasion.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 26337;
        UPDATE `quest_template` SET `OfferRewardText` = 'Praise you, brave $C.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.$b$bI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny.', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 1 WHERE `entry` = 26347;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.$b$bReturn to me when the foul beast is dead.' WHERE `entry` = 26349;
        UPDATE `quest_template` SET `OfferRewardText` = 'The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.$b$bCongratulations!' WHERE `entry` = 26356;
        UPDATE `quest_template` SET `OfferRewardText` = '<Fleep wipes her face, plastering an enormous grease smear across her cheek.>$B$BWhat? The Captain said WHAT?$B$B<She shakes her pipe wrench threateningly.>$B$BIt''s HIS fault this big beast of an engine is delayed.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 15 WHERE `entry` = 26358;
        UPDATE `quest_template` SET `RequestItemsText` = 'Smoot''s a good engineer.$B$BA samophlange can kill from thirty yards if you misalign the reduction caliphracts.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `OfferRewardEmote1` = 4 WHERE `entry` = 26361;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26365;
        UPDATE `quest_template` SET `OfferRewardText` = 'Aye... I used to be flesh and blood, just like you, $g lad:missy;. That is, until that fateful day when the murlocs attacked the lighthouse...', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 19, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26371;
        UPDATE `quest_template` SET `OfferRewardText` = 'My airship has engines? At last!$B$BNow we can rip the heavens a new one!$B$BOnce the ground and naval forces are ready, we''re going to light up the skies over the Twilight Highlands.', `DetailsEmote1` = 273, `DetailsEmote2` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 26372;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $N! Most of my soldiers have already reported for duty, some a little worse for the wear.$B$BOne night in Bilgewater makes a hard orc humble.$B$BStill, fresh fighting in the Twilight Highlands should restore discipline.', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 66 WHERE `entry` = 26374;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 26378;
        UPDATE `quest_template` SET `OfferRewardText` = 'These look promising. I''ve heard great things about the Short and Stout Brewery, but I haven''t had the chance to try their ale until now.$B$BWhile you''re here, relax a little. If you need a spare hearthstone or wish to make Kharanos your home, just speak to me and I''ll be happy to help.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26380;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmoteDelay2` = 60 WHERE `entry` = 26383;
        UPDATE `quest_template` SET `OfferRewardText` = 'Our allies have come to our aid? Thank Elune. Tyrande was wise to extend open arms to your people.$B$BWe need help.  We need everyone we can get.', `DetailsEmote1` = 5, `DetailsEmote2` = 2, `DetailsEmoteDelay2` = 60, `OfferRewardEmote1` = 6 WHERE `entry` = 26385;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is a disaster, $N!$B$BOur air fleet was decimated. And reports are coming in that our navy was attacked - unprovoked - by the Alliance in open water.$B$BAnd what of Hellscream? Is the Warchief dead?', `DetailsEmote1` = 1, `DetailsEmote2` = 4, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 274 WHERE `entry` = 26388;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 26389;
        UPDATE `quest_template` SET `OfferRewardText` = 'With Kurtok slain we are safe once again from the orcish hordes. I will send peasants to the pass in an attempt to seal the passage so that no more orcs may come through into our territory.$B$BYou have the thanks of Stormwind and of the Alliance, hero!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 5 WHERE `entry` = 26390;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 20, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 26391;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26393;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, a note from Smith Argus?  I''m not surprised he needs more gear.  There are so many new recruits these days.$B$BWell thank you, $N.  Here''s some money to cover your travel costs.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26394;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 26395;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hiya! Lend a hand, would ya, $g bub : toots;?', `OfferRewardEmote1` = 3 WHERE `entry` = 26409;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good thing that I just happen to be a grand master of all things explosively alchemical.$B$BThis won''t ignite on its own, though.', `OfferRewardEmote1` = 11 WHERE `entry` = 26410;
        UPDATE `quest_template` SET `OfferRewardText` = 'Looks like that did it. He should come to any moment now.$B$BI told you I was a grand master of alchemy!$B$BI''ve got some extra resin leftover. I can make it into all kinds of explosively wonderful stuff. What do you want?', `OfferRewardEmote1` = 1 WHERE `entry` = 26411;
        UPDATE `quest_template` SET `OfferRewardText` = 'We are honored by Flint Oremantle''s presence. I am given to understand that the Stonefather is in possession of a fragment of the World Pillar.$B$BIt is imperative that we recover all of the fragments. The instability between worlds is increasing. Soon it may become too great even for mighty Thrall to hold at bay.', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 26413;
        UPDATE `quest_template` SET `OfferRewardText` = 'All right, help me get tied to the wheel.$B$B<Moody sips from the bottle.>' WHERE `entry` = 26427;
        UPDATE `quest_template` SET `RequestItemsText` = 'What do you have there, $g sir : ma''am;?' WHERE `entry` = 26443;
        UPDATE `quest_template` SET `DetailsEmote1` = 66, `DetailsEmote2` = 396, `OfferRewardEmote1` = 2 WHERE `entry` = 26452;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s good to see another new arrival here at Forest Song.$B$BVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.$B$BTake a look around, $c. It may not be much now, but with time and help from our night elf allies, we''ll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2 WHERE `entry` = 26453;
        UPDATE `quest_template` SET `RequestItemsText` = '<The ancient creaks as it turns toward you.>$B$BArchitect Nemos said that you might be bringing wood salvaged from befouled Satyrnaar.', `DetailsEmote1` = 1 WHERE `entry` = 26454;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you for delivering this report, $c. From what Sentinel Melyria writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.$B$BWe can''t afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I''m certain we could triumph.$B$BWill you join our fight? A new front has just opened in Warsong Gulch to the south.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 26456;
        UPDATE `quest_template` SET `OfferRewardText` = 'Teronis'' body lies broken atop the small rise next to the Keeper.$B$BDeep slashes crisscross his corpse.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6 WHERE `entry` = 26463;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is terrible, $N. Teronis is dead?!$B$BThe time for mourning will come, but for now we must focus our efforts. I will send some of the Sentinels to recover Teronis'' body and to assist the keeper.$B$BYou have the gem that Teronis was seeking? It must be delivered to Astranaar.', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26464;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s quite a few that you have found! Thank you, $N!$B$BThe old city of Zoram holds many secrets, and these statuettes may be the key to many of them.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 2 WHERE `entry` = 26465;
        UPDATE `quest_template` SET `OfferRewardText` = 'You found the ring! Thank you, $N.$B$BPlease take this as payment, and know that your deeds today will remain forever in my memory.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 2 WHERE `entry` = 26466;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N! With the befouled elemental numbers thinned and Tideress put back into the lake, we should be able to launch a counter-offensive on Silverwind Refuge.$B$B<The sentinel frowns a bit, concern washing over her face.>$B$BJust as soon as we''re done with defending the spire....', `DetailsEmote1` = 66, `DetailsEmote2` = 1, `OfferRewardEmote1` = 2 WHERE `entry` = 26470;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah, you have the hair! This is a good first step. There are other ingredients that we will need, but the hair of the fallen Ancient could well be the most important.$B$BI only hope that whatever the Forsaken are devising from the plant will not be turned into a weapon. We simply do not have the numbers to remove them right now, especially with Maestra''s Post under attack!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 6, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmoteDelay2` = 2000 WHERE `entry` = 26473;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is from Orendil?$B$BHis skill with herbs and healing is great! This cure gives me hope, when before I had little....', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 2 WHERE `entry` = 26474;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, you found it! Odd... it looks tarnished somehow. I will place the tear in a stew, and pray that it will cure her.$B$BThank you! Thank you, $N!', `DetailsEmote1` = 18, `DetailsEmote2` = 1, `DetailsEmote3` = 20, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 2000, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 2 WHERE `entry` = 26475;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, Raene sent you? It must be serious indeed.$B$BWhat can I help you with?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 26476;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26477;
        UPDATE `quest_template` SET `OfferRewardText` = 'You got it? Wonderful for you... and for Raene!$B$BI guess we''ll have to see about reassembling it, won''t we?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 18, `DetailsEmote4` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 21, `OfferRewardEmote3` = 6 WHERE `entry` = 26478;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve recreated the rod Teronis had set out to find? That''s wonderful to hear.$B$BShael''dryn has been indispensible in her assistance. Teronis would be proud to see his quest is continuing even after his tragic passing.$B$B<Raene looks over the reconstructed rod with a look of approval and thoughts racing behind her eyes.>$B$BNow it is time for us to make use of its power to eliminate the enemies of Ashenvale!', `DetailsEmote1` = 4, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26479;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 26480;
        UPDATE `quest_template` SET `OfferRewardText` = '<Gregor bows respectfully to Zaela.>$B$BIf it is Zaela''s wish, then you shall have your supplies. Just don''t tell the Dragonmaw Warchief...', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 26538;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 273, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 26539;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dragon''s Blood!? We best not tell our red dragon allies that we''ve used these.$B$BStill, it''s powerful magic... We''ll have our fighting force back in no time.', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 274 WHERE `entry` = 26540;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wake up, $N! We don''t have much time.$B$BI rescued your gear for you.$B$BAt least now you''ve seen the foolishness of our leader first-hand. His blood is contaminated, his rage is unquenchable -- and he''ll destroy us all trying to defeat the Horde!', `RequestItemsText` = '$N, I understand you''re going to speak with our "Warchief" about joining your Horde.$B$BBe careful, $c.$B$BSee me afterwards... ', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 26549;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1 WHERE `entry` = 26593;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 26596;
        UPDATE `quest_template` SET `OfferRewardText` = '...feel strength returning....$b$bWhere might I be?  Booty Bay?  Oh my!  I had the strangest dream...$b$b...the weakness has not completely left me....', `RequestItemsText` = '....mother?$b$b...so cold...$b$b...heading into the Twisting Nether...h-h-h-hold me mother....' WHERE `entry` = 26597;
        UPDATE `quest_template` SET `OfferRewardText` = 'Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.$b$bYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!', `RequestItemsText` = 'Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!$b$bMe speak with spirits and make he come, I do.$b$bBut other gorilla-beast like spirit talkin'' too.  You protect Witch Doctor Unbagwa and I make he come to you.$b$bWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26598;
        UPDATE `quest_template` SET `OfferRewardText` = 'You found it!  What a glorious day for ol'' Hecklebury, this is.  Getting back my chest cools some of the fire in me.$B$BBut my revenge isn''t complete...', `OfferRewardEmote1` = 1 WHERE `entry` = 26599;
        UPDATE `quest_template` SET `OfferRewardText` = 'This wasn''t expensive, was it?  Well, here''s some pieces of eight to reimburse you.$b$bNow let''s get onto this revenge, shall we?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26600;
        UPDATE `quest_template` SET `OfferRewardText` = 'Mok''rash... Negolash... Gorlash... they''re all gone.$b$bI suppose I have no excuses now.  I can return to the high seas and a life of pillage and booty!  And it''s all thanks to you.$b$bNow I just need to get myself a ship...', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26601;
        UPDATE `quest_template` SET `OfferRewardText` = 'I can''t believe my fortune, $N!  Meeting you has turned my luck to the better, make no mistake there!$B$BIf I ever get a new ship and you''re looking to sail the seas, you would be my honored guest.', `OfferRewardEmote1` = 1 WHERE `entry` = 26602;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s about time you returned.  I was beginning to worry that I was going to be eaten while you hunted.$b$bA cat eating a princess... wouldn''t that be a fancy feast?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 11 WHERE `entry` = 26604;
        UPDATE `quest_template` SET `OfferRewardText` = '<Poobah surveys her belongings.>$b$bLooks like it''s all here.  Alright, I think I''m ready to be rescued now.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26605;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 26606;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Fel Orcs from Outland have laid claim to the Dragonmaw? Obscene!$B$BIf Hellscream knew what was happening here, he''d raze their city to the ground...', `DetailsEmote1` = 1, `DetailsEmote2` = 66 WHERE `entry` = 26608;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26609;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 26610;
        UPDATE `quest_template` SET `OfferRewardText` = 'Bloodsail Buccaneers attacking Booty Bay?  This isn''t the first time that those blaggards have tried something.  Booty Bay is impenetrable!$b$bSounds like they might be changing their strategies up, though.  Wouldn''t put it past Firallon to try something crazy.  Very well, let''s see what else they''re up to.', `DetailsEmote1` = 5, `DetailsEmote2` = 6, `DetailsEmote3` = 5, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 26611;
        UPDATE `quest_template` SET `OfferRewardText` = 'Perfect, $n.  Now that we know their plan, it''s just a matter of time.$b$bAnd to think the fools have dropped anchor just off the cape....', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26612;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 6, `OfferRewardEmote1` = 21 WHERE `entry` = 26613;
        UPDATE `quest_template` SET `OfferRewardText` = 'Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let''s see if she still fits.$b$b<Kshhh-thunk>$b$b$n ho!  Blimey, I can see!!', `RequestItemsText` = 'Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.$b$bCould really use me eye back.  Captain''s going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.$b$bWhat good is a lookout who can''t see?  The crow''s nest used to be me home...without me deadlights I''d be lucky to scrub the bilge.', `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 6, `OfferRewardEmote1` = 4 WHERE `entry` = 26614;
        UPDATE `quest_template` SET `OfferRewardText` = 'That coin!  Where did you get it?$b$bBruce... yes, I see.  He was one of the Blackwater Raiders once.  One of us, before Greymane closed the Gilneas ports and held his crew captive.$b$bI know that what happened in Gilneas changed the people there, but I never expected them to change their loyalties.  Especially not Bruce.$b$bIf you wouldn''t mind, could I keep the coin?  I''ll pay its worth in gold.', `OfferRewardEmote1` = 1 WHERE `entry` = 26617;
        UPDATE `quest_template` SET `OfferRewardText` = '$N, what are your people doing? Are you attacking the Dragonmaw or are you here to rid us of Mor''ghor''s corruption?$B$B<Zaela listens to the plan.>$B$BAh, I see now. I like the way you think. Warchief Mor''ghor won''t even know what hit him.$B$BLet''s do this!', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 66, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 1 WHERE `entry` = 26619;
        UPDATE `quest_template` SET `OfferRewardText` = 'We''ve lost a lot of good orcs, but the fight is going our way, $N.$B$BMor''ghor''s regime is collapsing. All that remains is to destroy the beast himself.', `DetailsEmote1` = 1, `DetailsEmote2` = 11, `DetailsEmote3` = 25, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 25 WHERE `entry` = 26621;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N! You have done the Horde proud in my absence.$B$BThe Dragonmaw have joined us, with Zaela as their new leader. Blood was shed, but casualties were low, and we have their complete loyalty.$B$BOur Horde grows stronger!', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 15, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 26622;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yarr, ya made a good decision, $g lad: wench;.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26624;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmote4` = 396 WHERE `entry` = 26629;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 24, `DetailsEmote3` = 1 WHERE `entry` = 26630;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done well. Now that these rocklings are free to learn our ways, they will grow tall and strong.$B$BOne day, we will extinguish the gyreworm infestation from our realm, and these rocklings shall no longer be plagued in their youth.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26710;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, it''s you, ma''am! Sorry, I didn''t recognize you at first with all of these commoners milling about.$B$BYou people cool your heels! $N is here!$B$BHere are your macaroons, $g sir : ma''am;. Come back anytime if you need more.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 5 WHERE `entry` = 26711;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, it''s you, sir! Sorry, I didn''t recognize you at first with all of these commoners milling about.$B$BYou people cool your heels! $N is here!$B$BHere are your macaroons, $g sir : ma''am;. Come back anytime if you need more.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 5 WHERE `entry` = 26712;
        UPDATE `quest_template` SET `OfferRewardText` = 'These are perfect! The restless waters of that troubled river will now do much more than move silt or stone... They''ll move you across continents.$B$BFinish up the rest of your business here in Dragonmaw and then we should be able to proceed.', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 26784;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your Warchief is decisive, $N. He makes things happen. I like him.$B$BLet''s talk about this portal that he wants!', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 25, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 273 WHERE `entry` = 26786;
        UPDATE `quest_template` SET `OfferRewardText` = '<Ornak allows the muck to drip from his fingertips.>$B$BNow that''s the stuff! I''ll start mixing and diluting this with gravel and water. Just a few handfuls of this can enhance enough cement for an entire stone tower.$B$BWe''ve got big plans for this port, $N. You''ll see!', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 21, `OfferRewardEmote2` = 1 WHERE `entry` = 26788;
        UPDATE `quest_template` SET `OfferRewardText` = '$C, you''ve returned from Dragonmaw. The portal is functioning then? Good.$B$BBefore you return to your work there, we''ve got some dirty business to clean up right here in Orgrimmar...', `DetailsEmote1` = 1, `DetailsEmote2` = 273, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274 WHERE `entry` = 26798;
        UPDATE `quest_template` SET `OfferRewardText` = 'Not even the power of the val''kyr was enough to save these creatures.  They were doomed from the beginning.$b$bI have obtained some equipment for you, $N.  It''s not much, but it will help.  Please, take your pick.', `RequestItemsText` = 'You will not go far in this new life if you are unable to kill even the weakest, most brainless creatures, $N.  Do not return until you have success to report.', `DetailsEmote1` = 1 WHERE `entry` = 26799;
        UPDATE `quest_template` SET `OfferRewardText` = 'Great work $N.  I knew you weren''t useless.$b$bHere, take one of these.  We deathguards have piles of these things just sitting around.', `DetailsEmote1` = 5 WHERE `entry` = 26800;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''re growing in strength, $n.  I''ve seen your type before.  You will be moving out of Deathknell and on to greater things before long.  Just make sure you don''t lose sight of where you started.$b$bYou have much to accomplish, $c.', `RequestItemsText` = 'Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let''s hope you will fare better than them, yes? ', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26801;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank you, $n. This armor should help you out.$b$bHopefully, it should do you more good than the last one to wear it...', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26802;
        UPDATE `quest_template` SET `DetailsEmote1` = 34, `DetailsEmote2` = 24, `DetailsEmote3` = 1, `DetailsEmote4` = 1 WHERE `entry` = 26822;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26823;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 26826;
        UPDATE `quest_template` SET `OfferRewardText` = 'Sauranok, Sauranok. His own visions worked against him. Twilight''s Hammer probably corrupted him from afar. Bah! Weak! We''ll speak his name no more.$B$BI told him you were investigating the airship docks, $N. To flush him out. Yes, I used you as bait. You served your Horde well, and deserve a reward for outing this viper from our midst.', `DetailsEmote1` = 1, `DetailsEmote2` = 274, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 26830;
        UPDATE `quest_template` SET `OfferRewardText` = '$N! I trust Orgrimmar fares well?$B$BAs you can see, construction of Dragonmaw Port continues at a breakneck pace. If my people questioned the Horde''s power before... the sight of this imposing edifice and the speed in which it was constructed leaves no doubt.$B$BA new day dawns for the Dragonmaw.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 11 WHERE `entry` = 26840;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26856;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 4 WHERE `entry` = 26858;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26862;
        UPDATE `quest_template` SET `DetailsEmote1` = 15 WHERE `entry` = 26865;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 2 WHERE `entry` = 26870;
        UPDATE `quest_template` SET `OfferRewardText` = 'Your efforts shall not go unnoticed, $n.$b$bThank you for your dedication.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 2 WHERE `entry` = 26872;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 21, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26873;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 29 WHERE `entry` = 26881;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1 WHERE `entry` = 26884;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 26885;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 21 WHERE `entry` = 26886;
        UPDATE `quest_template` SET `OfferRewardText` = 'More gold! We''ll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.$B$BAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26887;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26888;
        UPDATE `quest_template` SET `DetailsEmote1` = 25, `OfferRewardEmote1` = 273 WHERE `entry` = 26889;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight''s Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.$B$BYou''ve done well here today; the Earthen Ring looks upon you warmly for assisting us.  You''ve also helped the Horde as a whole, and for that you should be proud.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 26891;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 4 WHERE `entry` = 26892;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26897;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Flaming Eradicator appears to concentrate.>$B$BI spare your life for your help, $r. Leave now...before I change my...mind.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 5 WHERE `entry` = 26899;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26908;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 26910;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26916;
        UPDATE `quest_template` SET `OfferRewardText` = 'I knew you would master Steady Shot quickly. I''m looking forward to showing you other techniques as you get more experienced in the ways of the hunter.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 26917;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26948;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 21 WHERE `entry` = 26964;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well that was unexpected. I am not one to doubt our Warchief, but...$B$BNevermind! We have work to do. I''m sure the Dark Lady and the Warchief will get this all worked out.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 66, `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 26965;
        UPDATE `quest_template` SET `RequestItemsText` = 'Have you practiced using your seal and your judgement?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 26966;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes! The Scarlet Monastery is ours! You''re a real friend. Take this as a reward, and feel free to visit again once I''ve taken the Undercity too.$B$BIt''ll be a Scarlet Paradise!', `OfferRewardEmote1` = 4 WHERE `entry` = 26976;
        UPDATE `quest_template` SET `OfferRewardText` = '$Nnub has returned! And in one piece!$B$BDefender of Silverpine! Redeemer of the Horde! $Nnub, your bravery must be rewarded!', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `DetailsEmote4` = 397, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 21, `OfferRewardEmote4` = 21 WHERE `entry` = 26989;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 26991;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 26992;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very good. Yes, very good indeed.$B$BYour reward, as promised. No questions.' WHERE `entry` = 26994;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 26995;
        UPDATE `quest_template` SET `OfferRewardText` = '<Dominic hands you your reward. No words are spoken.>' WHERE `entry` = 26996;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 273 WHERE `entry` = 26998;
        UPDATE `quest_template` SET `OfferRewardText` = 'Smells like someone else was in this cell recently.$b$bGross!' WHERE `entry` = 27003;
        UPDATE `quest_template` SET `OfferRewardText` = '<The examiner takes a look at the plans that you hand to him.>$B$BThis is just gibberish!$B$BWhat does this even say? What language is that?', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `OfferRewardEmote1` = 5, `OfferRewardEmoteDelay1` = 1000 WHERE `entry` = 27005;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is the place.  Our scouts confirmed the presence of high-ranking Twilight officers nearby as well as potential trogg hunting parties.$B$BBe on the lookout, $N.' WHERE `entry` = 27007;
        UPDATE `quest_template` SET `OfferRewardText` = 'A waygate?! They unearthed a Titan waygate.$B$BThis is very interesting and potentially very bad.', `DetailsEmote1` = 6, `DetailsEmote2` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 27008;
        UPDATE `quest_template` SET `OfferRewardText` = 'A job well done, $N. The Quilboar here can no longer be saved, but at least they are no longer organized for attack, or slaves under Amnennar''s tyrannic rule.$B$BLeave quickly, please. Razorfen Downs is without hope. It must be purged.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396 WHERE `entry` = 27009;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27015;
        UPDATE `quest_template` SET `RequestItemsText` = 'I''m not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.$B$BIf you''re willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I''m... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.', `DetailsEmote1` = 5, `OfferRewardEmote1` = 21 WHERE `entry` = 27019;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27020;
        UPDATE `quest_template` SET `OfferRewardText` = 'Belnistrasz''s sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz''s voice speaks directly to you.$B$B"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in your kind has been once more renewed.  Take this as a reward befitting of a hero."', `DetailsEmote1` = 1 WHERE `entry` = 27022;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27023;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27024;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27029;
        UPDATE `quest_template` SET `OfferRewardText` = 'Belmont gets a little nervous and sends some newbie to look for me? Listen, I''ve been staking out the old Ivar cottage from inside this outhouse for three days. Your presence threatens the whole damn operation!$B$BThere''s no time to explain. We have to act now or this mission will be compromised.', `DetailsEmote1` = 6, `DetailsEmote2` = 1 WHERE `entry` = 27039;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ah ha! So, that''s it! They''re planning on invading Uldum.$B$BWhat''s worse is that the pyramid inside the Maker''s Rise at Uldum can be reconfigured to become a weapon. A weapon that is capable of destroying all life on Azeroth!', `DetailsEmote1` = 6 WHERE `entry` = 27041;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 25 WHERE `entry` = 27043;
        UPDATE `quest_template` SET `OfferRewardText` = 'Alas, poor Yorick! I knew her, $N. An assassin of infinite courage...$B$BNow, tell me what''s going on? What did you and Yorick discover?', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 27045;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 27051;
        UPDATE `quest_template` SET `OfferRewardText` = 'Crowley... A gnat. An insect, waiting to be crushed beneath my boot heel.$B$BSo he thinks to rouse the feral worgen of Silverpine? We shall show him and his allies the might of the Forsaken!$B$BBut first we must clean up the mess made by the Warchief''s fleet. Without their aid we may lose this war.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274, `OfferRewardEmote4` = 5 WHERE `entry` = 27056;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it! Excellent work, $g my boy : young lady;. You found out what the Twilight''s Hammer were up to and you stopped them dead in their tracks!$B$B<Examiner Rowe pats you on the back with his bony hand.>$B$BNow I''m certain that I have something around here for you.$B$B<He begins rummaging around for your reward.>', `OfferRewardEmote1` = 4 WHERE `entry` = 27059;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27065;
        UPDATE `quest_template` SET `OfferRewardText` = 'He''s gone? Did he have the sword?$B$BNah...don''t tell me. Don''t matter no more. Mazoga don''t care.$B$BI''m off now, mon. De consequences of my actions await me. Take whatever I was holdin''... I don''t need it where I''m goin''...' WHERE `entry` = 27068;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent! This Tiara will grant me complete control of the water around here, and the Electrified Scale will serve to power all the machines I need to use it all to my advantage!$B$BYou''re going to make me a very rich and powerful goblin! You can have this, it''s nothing compared to what I''ll have soon.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 27070;
        UPDATE `quest_template` SET `OfferRewardText` = 'You killed dem? All of dem? And you return alive?$B$BTake what you want off my body, den. It''s mostly curse-free, Mazoga promises.' WHERE `entry` = 27071;
        UPDATE `quest_template` SET `OfferRewardText` = 'Looks as if you really gave those worgen a beating and, in the process, lifted the "shame haze" they cast over us. Perhaps the sea dogs will quit drinkin'' now.$B$BWho am I kidding?$B$BHah!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 11 WHERE `entry` = 27073;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27076;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1 WHERE `entry` = 27082;
        UPDATE `quest_template` SET `OfferRewardText` = '<Apothecary Wormcrud laughs maniacally.>$B$BWas there ever any doubt? An ettin is no match for science!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 25 WHERE `entry` = 27088;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 66 WHERE `entry` = 27094;
        UPDATE `quest_template` SET `DetailsEmote1` = 15, `DetailsEmote2` = 1, `DetailsEmote3` = 5 WHERE `entry` = 27095;
        UPDATE `quest_template` SET `OfferRewardText` = '<Sylvanas raises an eyebrow.>$B$BSo the orcs are in order?$B$B<Sylvanas reads the commendation letter.>$B$BRecovered their supplies? Killed a dozen worgen? Toppled an ettin? Freed their soldiers and destroyed the Skitterweb matriarch?$B$BI say this rarely, $N, but I am impressed. Perhaps your ability matches your aspirations. We shall see, for now you will be tested!' WHERE `entry` = 27096;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27097;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 25, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 5 WHERE `entry` = 27098;
        UPDATE `quest_template` SET `OfferRewardText` = 'It would seem that Crowley is more formidable than I anticipated. Still, he is a man - flesh and bone - full of secrets. Secrets that I know all about...$B$BYou have served me well, $N. I could use someone of your ability at the Sepulcher. I have a plan to deal with Crowley and his insurgents once and for all. Will you help?', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 25, `OfferRewardEmote4` = 6 WHERE `entry` = 27099;
        UPDATE `quest_template` SET `OfferRewardText` = 'The notes deal with High Cultist Maziel''s research on the elemental properties of quicksilver.$B$BHis obsession with the subject borders on the insane.' WHERE `entry` = 27100;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27103;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27107;
        UPDATE `quest_template` SET `OfferRewardText` = 'This web have lots of magic! Master will be very happy now!$B$BAnd you make Dagg''thol happy, $r. Take this so you believe how happy you make Dagg''thol!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27108;
        UPDATE `quest_template` SET `DetailsEmote1` = 6, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 2, `DetailsEmoteDelay1` = 500, `DetailsEmoteDelay2` = 1000, `DetailsEmoteDelay3` = 1500, `DetailsEmoteDelay4` = 2000, `OfferRewardEmote1` = 21 WHERE `entry` = 27110;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 2 WHERE `entry` = 27111;
        UPDATE `quest_template` SET `RequestItemsText` = 'Did you slay those abominations?' WHERE `entry` = 27112;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve arrived just in time, $N.  All our resources are tied up keeping the rift stable.$B$BWe need someone like you to help us recover the fragments of the World Pillar.' WHERE `entry` = 27123;
        UPDATE `quest_template` SET `OfferRewardText` = 'Uh oh. Sounds like he wasn''t very happy about the situation. How was I to know? I''m just an initiate after all.$B$BAnyway, I''ll worry about Magmatooth later.', `OfferRewardEmote1` = 430, `OfferRewardEmote2` = 11 WHERE `entry` = 27135;
        UPDATE `quest_template` SET `OfferRewardText` = 'There you are, my $g boy : girl;. I have something very important for you to do!', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27139;
        UPDATE `quest_template` SET `OfferRewardText` = 'You did it!  They are defeated!  And the Gambit... did it work?$B$BVery interesting. You''ve done well, $N.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 6, `OfferRewardEmote3` = 2 WHERE `entry` = 27140;
        UPDATE `quest_template` SET `OfferRewardText` = 'Shake it off, kid.$b$bHappens to me all the time...', `OfferRewardEmote1` = 396 WHERE `entry` = 27141;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 4 WHERE `entry` = 27142;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 5 WHERE `entry` = 27143;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N!  It''ll be a long time before they can grow another clutch of dragons.$B$B...At least, I hope it will!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4 WHERE `entry` = 27145;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 27146;
        UPDATE `quest_template` SET `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 25 WHERE `entry` = 27147;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 25 WHERE `entry` = 27148;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27159;
        UPDATE `quest_template` SET `OfferRewardText` = '<Doctor Jones puts on his spectacles.>$b$bLet''s have a look at this. Shall we?', `OfferRewardEmote1` = 6 WHERE `entry` = 27176;
        UPDATE `quest_template` SET `OfferRewardText` = 'These tablets are covered with titan writings. There''s never-before seen information here, $n!$b$bMissing pieces to an ancient puzzle...$b$bGood work!', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 27179;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 27180;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Banshee Queen''s voice invades your thoughts.>$B$BYou have avenged the fallen, $N, but there is more to be done.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 25 WHERE `entry` = 27181;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 27183;
        UPDATE `quest_template` SET `OfferRewardText` = 'The world is a better place because of your deeds here today.' WHERE `entry` = 27187;
        UPDATE `quest_template` SET `OfferRewardText` = 'Truly, you have uncovered the snuff of legends. It is nearly impossible to place a value on this historical tobacco.$b$bHere, have a few coins.', `OfferRewardEmote1` = 1 WHERE `entry` = 27192;
        UPDATE `quest_template` SET `OfferRewardText` = '<The Banshee Queen''s words float in your head.>$B$BThis book documents a recent meeting with Ivar Bloodfang. The location mentioned is the Deep Elem Mine. I know of this place. It has only one entrance.$B$BWe shall corner and crush them!' WHERE `entry` = 27193;
        UPDATE `quest_template` SET `OfferRewardText` = 'I s''pose we''re to corner them first then crush, eh?', `OfferRewardEmote1` = 6 WHERE `entry` = 27194;
        UPDATE `quest_template` SET `OfferRewardText` = 'WHAT!?$B$B<Sylvanas shrieks.>$B$BCROWLEY!!!!!$B$BBastards. Those were some of our strongest soldiers. I have underestimated Crowley and Bloodfang for the last time. Clearly they are an enemy the likes of which we have never seen - willing to sacrifice their own to set a trap like this... unheard of in Alliance warfare.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 15, `OfferRewardEmote3` = 5, `OfferRewardEmote4` = 5 WHERE `entry` = 27195;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 27196;
        UPDATE `quest_template` SET `OfferRewardText` = '<Thrall''s muscles strain as primal energy flows through him.  His eyes shift your way, acknowledging your arrival.>$B$BIt is good to see you, $N.' WHERE `entry` = 27203;
        UPDATE `quest_template` SET `RequestItemsText` = 'Don''t let my sea dogs die!', `DetailsEmote1` = 5, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 27226;
        UPDATE `quest_template` SET `OfferRewardText` = '<Hatchet''s communication device crackles.>$B$BHatchet here, are they all dead?' WHERE `entry` = 27231;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27253;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well if it isn''t $Nnub!$B$BI hope you''re ready for battle, because that''s all you''ll find in this hellhole. We''re at the heart of contested territory and these worgen mongrels won''t give an inch!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 274 WHERE `entry` = 27290;
        UPDATE `quest_template` SET `OfferRewardText` = 'If I could still breathe I''d let out a sigh of relief.$B$BDon''t get too comfortable, though, $N, your mission here has just begun.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5 WHERE `entry` = 27333;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27336;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27339;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27340;
        UPDATE `quest_template` SET `OfferRewardText` = '<Belmont takes the wolfsbane from you.>$B$BGood. Now just do as Forward Commander Onslaught commands. Try your best to fit in with the rest of the soldiers. We don''t want the Gilneas Liberation Front to get suspicious.$B$BOh, you didn''t know they were watching us? Right now there are five different worgen spies looking down on our position. Just be calm and follow orders. I''ll let you know when we are ready to proceed.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 273, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 27342;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27345;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27346;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27347;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27348;
        UPDATE `quest_template` SET `OfferRewardText` = '<The F.C.D. crackles with static.>$B$BDreadwatch is lost? This is bad, $N. Real bad.$B$BIf Dreadwatch is compromised it means we''ve lost Gilneas City.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27349;
        UPDATE `quest_template` SET `OfferRewardText` = 'Th... Af... After we lost Gilneas City, the port fell.$B$BHU... HUM... HUMANS ARE HERE! Reinforcements from Stormwind! They slaughtered my men. Left me alive to witness their strength. To tell high command... To tell them that the 7th Legion are here...' WHERE `entry` = 27350;
        UPDATE `quest_template` SET `OfferRewardText` = 'Though we were shamed in battle, the enemy was not victorious. I will not soon forget this, $N.$B$BIf I make it back to Silverpine I will likely retire from the service. War is not in my blood.' WHERE `entry` = 27360;
        UPDATE `quest_template` SET `OfferRewardText` = '<The F.C.D. crackles with electricity.>$B$BAn Alliance armada is en route? How could this have happened?$B$B<Forward Commander Onslaught cuts out for a moment. You hear worgen howling in the background.>$B$BYou''ve got to hurry, $N. We''re being overrun up here at Forward Command.' WHERE `entry` = 27364;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 27399;
        UPDATE `quest_template` SET `OfferRewardText` = '<The F.C.D. crackles with electricity.>$B$BTORPEDOED! We had everything at the water line covered, but nothing below the line. They must have snuck in beneath our defenses and then blown our warships to smithereens.$B$BAnd now the rest of the Alliance fleet is nearly here...' WHERE `entry` = 27401;
        UPDATE `quest_template` SET `OfferRewardText` = 'Forward Commander Onslaught fought until the bitter end, $N. It took a pack of bloodthirsty worgen to finally bring him down. We must not let his death, or the death of all of our soldiers in Gilneas, go in vain. Our mission MUST succeed.$B$BNow I will reveal to you why we are here.', `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27405;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 273, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27406;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27407;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27413;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 274, `OfferRewardEmote2` = 1 WHERE `entry` = 27423;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27424;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 396 WHERE `entry` = 27431;
        UPDATE `quest_template` SET `OfferRewardText` = 'I had no doubt that you would succeed, $N. I hope you can understand why I kept the true purpose of your mission a secret. Should Crowley and Bloodfang have found out about our plan, they would have surely gotten to Godfrey first and disposed of the body.$B$BStand by, $N. The time of their rebirth is at hand.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 27438;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27470;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 27472;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27474;
        UPDATE `quest_template` SET `DetailsEmote1` = 457, `DetailsEmote2` = 457, `DetailsEmote3` = 457 WHERE `entry` = 27475;
        UPDATE `quest_template` SET `OfferRewardText` = 'That must have been exciting.$B$BDespite any losses that the Kor''kron may have incurred along the way, no one will be able to doubt their effectiveness, nor that of Garona. And with you in the mix, it''s only a matter of time before victory is ours.', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27491;
        UPDATE `quest_template` SET `OfferRewardText` = 'And here I thought that today couldn''t get any better.$B$BI enjoy being wrong, occasionally.', `DetailsEmote1` = 25, `OfferRewardEmote1` = 273 WHERE `entry` = 27493;
        UPDATE `quest_template` SET `OfferRewardText` = 'Success!', `DetailsEmote1` = 1, `DetailsEmote2` = 25, `DetailsEmote3` = 15 WHERE `entry` = 27495;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 1, `OfferRewardEmote1` = 273 WHERE `entry` = 27497;
        UPDATE `quest_template` SET `OfferRewardText` = 'The horns have been sounded.  Crushblow should launch their attack at any moment.$B$BNow there''s only one thing left to take care of.' WHERE `entry` = 27499;
        UPDATE `quest_template` SET `OfferRewardText` = '<The noble lady grins wickedly.>$B$BThat''s quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.$B$BThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.', `CompleteEmote` = 6, `OfferRewardEmote1` = 11, `OfferRewardEmote2` = 273 WHERE `entry` = 27501;
        UPDATE `quest_template` SET `OfferRewardText` = 'This can''t be good!', `DetailsEmote1` = 1, `DetailsEmote2` = 25 WHERE `entry` = 27503;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ahh, rope! Thanks, kid.$b$bSomething tells me I''m going to need this.' WHERE `entry` = 27517;
        UPDATE `quest_template` SET `OfferRewardText` = 'I thank you, $N.  Orsis was punished for not joining the forces of Deathwing.$B$BPrince Nadun has offered my people refuge in his city.  I must go there and tend the survivors.' WHERE `entry` = 27519;
        UPDATE `quest_template` SET `OfferRewardText` = 'Odd...$b$bIt looks as if someone used gemstones as lenses.$b$bI should be able to fix them without too much trouble.', `OfferRewardEmote1` = 396 WHERE `entry` = 27541;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, kid, it looks like you''ve done it again.$b$b<Harrison points to an image on the tablets.>$b$bThis starlight is exactly what we were missing.$b$bNow we can get to work!', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 5, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 27549;
        UPDATE `quest_template` SET `OfferRewardText` = 'I would stay away from Oralius. Far, far, far away. He isn''t quite right in the head.$B$BNow, let''s get onto business!', `DetailsEmote1` = 5, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmote4` = 18 WHERE `entry` = 27568;
        UPDATE `quest_template` SET `OfferRewardText` = 'I''m sure you are up to the task I have for you if you''ve made it this far in one piece.$B$B<Mayara Brightwing lowers her voice to a whisper.>$B$BBetween you and me, you may want to enjoy yourself in the Grim Guzzler while you''re there. It could be the last drink you ever have.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396 WHERE `entry` = 27569;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Dark Irons took our Thunderbrew. I''ll never let them live after that. I''d kill ''em all myself if I could!$B$BHowever, look ahead and you''ll see we have slightly more dire matters to attend to at the moment.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396 WHERE `entry` = 27571;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396 WHERE `entry` = 27573;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmote4` = 113 WHERE `entry` = 27578;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27604;
        UPDATE `quest_template` SET `OfferRewardText` = 'You only defeated Eranikus'' Shade? This is most troubling...$B$BLet us hope that his full form does not still exist outside the Temple. Only Ysera herself is stronger than him in our flight.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27605;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s right baby! That''s right! Cold steel and hot death!$B$BWhat should we name our new creation? The Gnugatron? No - better - the $N-o-matic. That''s got a ring to it.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 11 WHERE `entry` = 27622;
        UPDATE `quest_template` SET `OfferRewardText` = 'Fine work, $n.$b$b<Harrison studies the tablets.>$b$bIt looks as though our work here is nearly complete.', `OfferRewardEmote1` = 396 WHERE `entry` = 27624;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 27628;
        UPDATE `quest_template` SET `OfferRewardText` = 'What manner of creature are you?  You will leave the king''s lands before...$B$BWait!  You are that $N I''ve heard so much about.$B$BYou must pardon my lack of hospitality.  We have seen all manner of hostile intruders since the barrier around Uldum failed.' WHERE `entry` = 27629;
        UPDATE `quest_template` SET `OfferRewardText` = 'War, you say.$B$BDivinations for war are always difficult.  Some wars must never be fought, even if victory was assured.  Some wars have to be waged even if defeat is certain.' WHERE `entry` = 27630;
        UPDATE `quest_template` SET `OfferRewardText` = 'No need to fill me in on the events in Orsis, $N.$B$BI''ve heard about them already.  And about you.  Any enemy of Al''Akir is a friend of mine.', `OfferRewardEmote1` = 1 WHERE `entry` = 27631;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have successfully stopped Hakkar here, but I fear we are far from done. The Atal''ai transported most of the blood they produced to Zul''Gurub, where the Hakkari work to summon The Blood God there.$B$B$N, I do not think that this was ever meant to be the place of Hakkar''s arrival - it was merely a test to see if the blood was potent enough! Hakkar can only be summoned in Zul''Gurub...and I fear we may be too late to stop the Hakkari with the blood they now have in their possession.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27633;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 6 WHERE `entry` = 27638;
        UPDATE `quest_template` SET `OfferRewardText` = 'What do you think I should do with all of these? Maybe I''ll melt them down and have the metal imbued into a new dagger that I can thrust into Cho''gall''s chest.$B$BThink there''s time for that?', `DetailsEmote1` = 273, `DetailsEmote2` = 6, `DetailsEmoteDelay2` = 1000, `CompleteEmote` = 6, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 27653;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 397, `OfferRewardEmote1` = 6 WHERE `entry` = 27655;
        UPDATE `quest_template` SET `OfferRewardText` = '$N! I''m glad you''re here.$B$BOf course, I''m more than willing to help you in any way that I can.', `DetailsEmote1` = 396, `DetailsEmote2` = 274, `DetailsEmoteDelay2` = 1000, `OfferRewardEmote1` = 1 WHERE `entry` = 27658;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 273 WHERE `entry` = 27659;
        UPDATE `quest_template` SET `OfferRewardText` = 'I know why you are here, $N. Your reasons sing within your fluids.$B$BI know about the dead dwarf forgesmith polluting my lake. If you want to find out what his corpse remembers, you must earn it.', `DetailsEmote1` = 274, `DetailsEmote2` = 1, `OfferRewardEmote1` = 33 WHERE `entry` = 27660;
        UPDATE `quest_template` SET `DetailsEmote1` = 34 WHERE `entry` = 27661;
        UPDATE `quest_template` SET `DetailsEmote1` = 273, `DetailsEmote2` = 25, `OfferRewardEmote1` = 11 WHERE `entry` = 27662;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, now. Would ya look at that!$b$bAs amazing as this is, I am confident that there''s more to our discovery than meets the eye...$b$bMuch more.', `OfferRewardEmote1` = 396 WHERE `entry` = 27669;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27680;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396 WHERE `entry` = 27681;
        UPDATE `quest_template` SET `OfferRewardText` = 'Both of these cores are still far more potent than most of the cores we use  to power our own protectors, and these are ancient devices!$B$BThank you, these will prove extremely valuable to our society.', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmote4` = 397 WHERE `entry` = 27682;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, finally...$b$bI don''t know how much longer I can last!', `DetailsEmote1` = 396, `DetailsEmote2` = 396, `DetailsEmote3` = 396, `DetailsEmoteDelay2` = 500, `DetailsEmoteDelay3` = 500, `OfferRewardEmote1` = 5 WHERE `entry` = 27685;
        UPDATE `quest_template` SET `OfferRewardText` = 'That takes care of most of their leaders outside of the Bastion of Twilight. Not bad work, $N. Not bad at all.', `DetailsEmote1` = 1, `DetailsEmote2` = 397, `OfferRewardEmote1` = 1 WHERE `entry` = 27689;
        UPDATE `quest_template` SET `DetailsEmote1` = 274, `DetailsEmote2` = 396, `DetailsEmote3` = 6, `CompleteEmote` = 6, `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 274 WHERE `entry` = 27696;
        UPDATE `quest_template` SET `OfferRewardText` = 'Excellent work, $N! Eliminating Vyletongue''s presence is a key step to freeing me and, ultimately, saving these lands from corruption. Take this as a token of my thanks and an incentive to continue your work here.$B$B<You hear the jingle of coins coming from your bag.>' WHERE `entry` = 27697;
        UPDATE `quest_template` SET `OfferRewardText` = 'What?!$b$bGnaws ain''t dead?!$b$bThis kinda takes the quick outta my get rich quick scheme...$b$bThem giant shark teeth are nice and all, but we can''t stop ''til that shiney is ours!', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 396, `OfferRewardEmoteDelay2` = 500 WHERE `entry` = 27699;
        UPDATE `quest_template` SET `OfferRewardText` = 'Isn''t she beautiful? So graceful.$B$BI hope she gets her fill of revenge and then some.', `DetailsEmote1` = 396, `OfferRewardEmote1` = 6 WHERE `entry` = 27701;
        UPDATE `quest_template` SET `DetailsEmote1` = 396, `DetailsEmote2` = 273 WHERE `entry` = 27703;
        UPDATE `quest_template` SET `OfferRewardText` = 'If the prisoner''s information is true, Tahet is in great danger.' WHERE `entry` = 27707;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is good that this operation has been undone.$b$bSoon, I must move on...' WHERE `entry` = 27708;
        UPDATE `quest_template` SET `OfferRewardText` = 'Brilliant! I can''t have expected much more with the tools I gave you.$B$BI should be able to fill in the blanks and get this all written out shortly. There''s no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.$B$BThank you again, $n. You''re not bad.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27717;
        UPDATE `quest_template` SET `OfferRewardText` = 'Lok''tar, $g brother:sister;! You have arrived just in time.', `OfferRewardEmote1` = 66 WHERE `entry` = 27718;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 27721;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 27722;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 27726;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 5 WHERE `entry` = 27727;
        UPDATE `quest_template` SET `OfferRewardText` = 'You can add this to list of things you can tell your grandchildren that you''ve done for them.' WHERE `entry` = 27729;
        UPDATE `quest_template` SET `OfferRewardText` = 'Thank goodness! With this fire, our men will live through this ordeal!$B$BThank you so much, hero.' WHERE `entry` = 27737;
        UPDATE `quest_template` SET `OfferRewardText` = 'You have performed a deed this day unlike any I have seen in my long career. Hogger''s death will plague the Riverpaw for years to come, and hopefully put an end to their attacks on our people.$B$BGreatest of heroes, please take this as a sign of my eternal gratitude.' WHERE `entry` = 27739;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 27755;
        UPDATE `quest_template` SET `OfferRewardText` = 'Scanning subject...$B$BCerebral cortex diagnostics indicate the absence of "tomb curse" phenomenon.$B$BDiagnostics did reveal frequent head trauma.  The user would do well to exercise more caution around blunt objects in the future.' WHERE `entry` = 27760;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well done, $N.  The expedition has already doomed itself.$B$BThere is no need for it to endanger the rest of the world as well.' WHERE `entry` = 27761;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 27836;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes, $N.  I can feel the disruption in the river fading.$B$BYet, I feel the source of this taint still lingers.' WHERE `entry` = 27837;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yes.  The waters are clearing up.$B$BI am certain I will be visited by a vision before the High Council meets.$B$BBe warned, $r.  My vote will only be swayed by what I see.$B$BYou might have helped us greatly here today, but if the vision sways me to make a case against war then that is the way my vote will be cast.' WHERE `entry` = 27838;
        UPDATE `quest_template` SET `OfferRewardText` = 'This is quite timely.  I will distribute these armaments to my best men and to the laborers that you recruited.$B$BI''ve a feeling they''ll show as much courage as my best trained captains.' WHERE `entry` = 27839;
        UPDATE `quest_template` SET `OfferRewardText` = 'Do not be alarmed, $N. I am close to you, waiting in the shadows. You''ve done well.$B$BYou must continue the mission here - I am too valuable to risk my life against petty criminals like these.' WHERE `entry` = 27842;
        UPDATE `quest_template` SET `OfferRewardText` = 'My employers do not take kindly to traitors.$B$BOn the flip side, they are renown for their kindness towards the loyal! You deserve to be rewarded!' WHERE `entry` = 27844;
        UPDATE `quest_template` SET `OfferRewardText` = 'Brilliant! Now all I have to do is finish my work, and my Mayhem Reapers will cause...mayhem...on any Horde front!$B$BAnd there won''t be any Defias knockoffs to steal my profits!' WHERE `entry` = 27847;
        UPDATE `quest_template` SET `OfferRewardText` = 'It''s a shame that he was both a human and a worgen. Had he been a proud orc warrior I''d have liked to charge into battle alongside such a fierce combatant.$B$BWe can speak of ill-fated desires another day. It is time to take what is ours from the enemy.' WHERE `entry` = 27848;
        UPDATE `quest_template` SET `OfferRewardText` = 'COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight!$B$B<Kagtha composes herself.>$B$BNo matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!', `OfferRewardEmote1` = 15, `OfferRewardEmote2` = 396, `OfferRewardEmote3` = 153 WHERE `entry` = 27850;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27863;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27865;
        UPDATE `quest_template` SET `OfferRewardText` = 'Wow! When I saw that... thing stumble into the arena, I thought you didn''t stand a chance. But you proved me wrong. You tore it apart!$B$BGrizzly business.', `OfferRewardEmote1` = 1 WHERE `entry` = 27866;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 27867;
        UPDATE `quest_template` SET `OfferRewardText` = 'Looks like this title is yours! You really pulled that one out of the fire. $B$BCongratulations. I hope the coin serves you well.', `OfferRewardEmote1` = 1 WHERE `entry` = 27868;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ysera herself sent you to me? Oh! It''s an honor to speak with a representative of the aspects.$B$BIt''s true that our shrine is in jeopardy. The harpies we once sheltered in our boughs have suddenly turned against us.$B$BBut please, don''t rejoin the fight until you are ready. Our shrine is no mere battleground. Use its peace and power to center yourself.', `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1 WHERE `entry` = 27874;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s a relief. Thanks, $n.$b$bTurns out I''ve got my hands full here.' WHERE `entry` = 27900;
        UPDATE `quest_template` SET `OfferRewardText` = 'That''s it!$b$bGood work, $n!' WHERE `entry` = 27901;
        UPDATE `quest_template` SET `OfferRewardText` = 'According to Harrison''s notes, placing the lens upon this dais should re-activate this obelisk.$b$bExactly what that means remains to be seen...' WHERE `entry` = 27903;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good work back there, $n.$b$bLooks like we''ve lost them, for now at least.' WHERE `entry` = 27905;
        UPDATE `quest_template` SET `OfferRewardText` = 'The scent of freshly spilled traitor blood fills my nostrils, and it is absolutely invigorating. However, my bloodlust will not be sated until Godfrey lies on the floor as a lifeless heap.$B$BHe thinks an army of mindless corpses can stop the wrath of the Bloodfang? We''ll gnaw on their bones for years to come after our work is done!' WHERE `entry` = 27917;
        UPDATE `quest_template` SET `OfferRewardText` = '<Packleader Ivar Bloodfang grins, revealing his razor-sharp teeth.>$B$BIt won''t be long now before the entire keep is ours, thanks to your valiant efforts.' WHERE `entry` = 27921;
        UPDATE `quest_template` SET `OfferRewardText` = 'A djinn!  We must escape as soon as possible.$B$BThis unholy alliance of the Neferset with the minions of Deathwing does not bode well for us.' WHERE `entry` = 27922;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 6 WHERE `entry` = 27926;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh, these are exquisite!$b$bThe commander will be able to make a winter uniform with these.', `OfferRewardEmote1` = 5 WHERE `entry` = 27928;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done it!$b$bPerhaps I can trust you vizh more serious matters, hmm?', `OfferRewardEmote1` = 396, `OfferRewardEmote2` = 6 WHERE `entry` = 27939;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve made the Cradle of the Ancients a somewhat less despicable place to travel through.' WHERE `entry` = 27940;
        UPDATE `quest_template` SET `OfferRewardText` = 'Most efficient work, $c.$b$bYou should rise rapidly through the ranks.', `OfferRewardEmote1` = 396 WHERE `entry` = 27941;
        UPDATE `quest_template` SET `OfferRewardText` = 'Zhese look to be of sufficient quality.$b$bVizh zhese, ve are vone shtep closah to zhe cleansink ritual.', `OfferRewardEmote1` = 396 WHERE `entry` = 27942;
        UPDATE `quest_template` SET `OfferRewardText` = 'Very goot!$b$bYou have earned yourself a place at zhe ritual.$b$bYou shall be among zhe first to velcome Gobbles back to his... original form.', `OfferRewardEmote1` = 396 WHERE `entry` = 27943;
        UPDATE `quest_template` SET `OfferRewardText` = 'That was probably not the transformation Schnottz was hoping for...' WHERE `entry` = 27950;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 6, `OfferRewardEmote1` = 1 WHERE `entry` = 27953;
        UPDATE `quest_template` SET `OfferRewardText` = 'You didn''t... KILL the machines to get these, right?.$b$b<Lunk looks upset.>$b$bRight?', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 27956;
        UPDATE `quest_template` SET `OfferRewardText` = 'No!  You are the same as Thorium Brotherhood dwarf.$b$b"Kill dwarf.  Kill spider.  Kill machine.  Kill, kill, kill."$b$bLunk come to gorge to go on adventure, not to go on murder spree.$b$bGoodbye, $r.  You kill too much.' WHERE `entry` = 27957;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 27958;
        UPDATE `quest_template` SET `OfferRewardText` = 'Lunk is very happy that you let him ride on the spiders.  Lunk is also happy that $n was able to do $n''s adventures without killing anything.$b$bMaybe Lunk see you later.', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27959;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 27960;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve got quick hands if you were able to gather this many in such a short time.$b$bExcellent work, $N.  I''ll make sure these ones don''t go to waste.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27961;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yup, this was Margol''s horn alright.  No doubt about it.$b$bBarnabas was a digger, like me.  He never stood a chance in combat against the beast.  I''m glad you were here to set things right.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 27962;
        UPDATE `quest_template` SET `OfferRewardText` = 'Let''s see... Overseer Maltorius... we''re quite familiar with him and his work.$b$bWhat''s this?  The "archduke"?  That sounds promising.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 6 WHERE `entry` = 27963;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 5 WHERE `entry` = 27964;
        UPDATE `quest_template` SET `OfferRewardText` = 'Do I know you, $r?$b$b<Overseer Oilfist listens as you describe what you saw within the flames at Thorium Advance.>$b$bSounds like another one of Ragnaros'' minions.  I don''t like the sound of that.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 27965;
        UPDATE `quest_template` SET `OfferRewardText` = 'We did it, $N! At terrible cost... but victory is ours.$B$BThis keep could serve well as a home for me and my pack, though we tend to prefer more natural habitats.$B$BIt may be best to leave it as a reminder of Godfrey''s betrayal and of the Bloodfang warriors that died here in battle.' WHERE `entry` = 27968;
        UPDATE `quest_template` SET `OfferRewardText` = 'Vell done, $c.$b$bZhere may be hope for you yet.' WHERE `entry` = 27969;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ye''re a good $g lad:lass;, ye are. I got ye a lil'' present fer yer troubles.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `DetailsEmote4` = 25, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 21 WHERE `entry` = 27976;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 21 WHERE `entry` = 27977;
        UPDATE `quest_template` SET `OfferRewardText` = '<Hansel weighs the stone in his hands.>$b$bThis thing is strange, $N.  I don''t know what to make of it.  It ain''t natural, that''s for sure.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 25 WHERE `entry` = 27979;
        UPDATE `quest_template` SET `OfferRewardText` = 'There''s no way you coulda killed all the spiders in the gorge, but you definitely made a dent.$b$bFine, here''s what I promised ya.  Don''t spend it all in one place.  Unless it''s at Thorium Point.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27980;
        UPDATE `quest_template` SET `OfferRewardText` = 'Yeeeeeeowch!  Don''t just go puttin'' this stuff into a dwarf''s open hand.  This stuff is burnin'' up!$b$bNow me hands are gonna get even more swollen...', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 18 WHERE `entry` = 27981;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.$b$bAh well!  A little spit and polish should do the trick, and if not, I can use ''em to practice my disenchanting.', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27982;
        UPDATE `quest_template` SET `OfferRewardText` = 'Dwarfs is going to sleep good tonight.$b$bLunk hopes you got everything you were looking for.  Now time to go off and find other adventures.$b$bBye!', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 27983;
        UPDATE `quest_template` SET `OfferRewardText` = 'As your eyes pass over the words of Zamael''s prayer, you feel the tablet grow lighter.$b$bA wave of warmth passes over you, and the tablet is gone.', `RequestItemsText` = '<You glance over the night elf''s prayer.>', `DetailsEmote1` = 6, `DetailsEmote2` = 1 WHERE `entry` = 27985;
        UPDATE `quest_template` SET `OfferRewardText` = 'And who might you be?$b$bAh, an emissary from the Thorium Brotherhood.  They''re looking for my support?  Fine, I might be willin'' to help out...$b$b...for a price.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 27986;
        UPDATE `quest_template` SET `OfferRewardText` = 'Cromush has both a thick skull and a fool''s brain, and we''ll use that to our advantage. By the time anybody finds out about the plague''s true potency, it''ll be far too late.$B$BThank you for keeping quiet during his tirade. I promise you won''t regret it.' WHERE `entry` = 27988;
        UPDATE `quest_template` SET `OfferRewardText` = 'Honey! Delicious honey!$B$BWell done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there.' WHERE `entry` = 27989;
        UPDATE `quest_template` SET `OfferRewardText` = 'Auch!$b$bIf I vere an inch or two taller, I''d be dead!', `OfferRewardEmote1` = 5 WHERE `entry` = 27990;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good to see ya, kid.$b$bWould''ve been even better if you''d have been here to help me take care of these little savages...' WHERE `entry` = 27993;
        UPDATE `quest_template` SET `OfferRewardText` = 'It worked!$B$BI mean, uh, YES, the will of Ruumbo has been carried out! You have done well, creature! You may have these shiny coins!' WHERE `entry` = 27994;
        UPDATE `quest_template` SET `OfferRewardText` = 'Those two brats... I should have known! They were smart enough to hush whenever I went to examine the totem.$B$BI''ll be sure to find them and drag them back to Timbermaw Hold by the ears! Thank you for looking into it...' WHERE `entry` = 27995;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 27997;
        UPDATE `quest_template` SET `OfferRewardText` = 'For a moment there, I thought all was lost. Even when surrounded by the worgen in Gilneas I had higher hopes!$B$BBut you proved me wrong $N. I will see to it that Sylvanas herself hears of your triumph here today. Don''t worry about the mess here, I will gladly see to it myself.' WHERE `entry` = 27998;
        UPDATE `quest_template` SET `OfferRewardText` = 'Imps are creatures of deception. With so many of them spotted at Shadowlurk Ridge, I''m positive something is being hidden there.$B$BOur little friend will tell us exactly how to find it... if he doesn''t want to go back in the sack.', `DetailsEmote1` = 1 WHERE `entry` = 28000;
        UPDATE `quest_template` SET `OfferRewardText` = 'Hmm, still a bit frazzled, are they?$b$bWell, you know what they say. Time heals all wounds.$b$bExcept for those of the ambassador, of course...', `OfferRewardEmote1` = 396 WHERE `entry` = 28002;
        UPDATE `quest_template` SET `OfferRewardText` = 'If nothin'' else, you bought us some time, and some room to open up our supply lines through this siege.$b$bYer a fine $c.', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 66 WHERE `entry` = 28028;
        UPDATE `quest_template` SET `RequestItemsText` = 'A real $c woulda caught the bullets with $g his: her; teeth.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 11, `OfferRewardEmote1` = 2 WHERE `entry` = 28030;
        UPDATE `quest_template` SET `OfferRewardText` = 'Ooh, these are nice.  Now, leave me alone with my gizzards.  I''ve got studying to do!$b$b<Agnes starts to poke the gizzards with a stick.>$b$bYes, very interesting.  Very interesting indeed...', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 5, `OfferRewardEmote3` = 273, `OfferRewardEmoteDelay3` = 2000 WHERE `entry` = 28032;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well well well.  Look who come searching for Lunk this time!$b$bThis sounds like case for Lunk''s unique brand of no-kill problem-solve.', `DetailsEmote1` = 24, `DetailsEmote2` = 1, `DetailsEmote3` = 6 WHERE `entry` = 28033;
        UPDATE `quest_template` SET `OfferRewardText` = 'Did I stutter?  I believe I clearly stated that I... won''t...$b$bWow, ye''ve got some good moves there!  I''m impressed!', `OfferRewardEmote1` = 5, `OfferRewardEmote2` = 25, `OfferRewardEmote3` = 10 WHERE `entry` = 28034;
        UPDATE `quest_template` SET `OfferRewardText` = 'So, Rendan''s on our side?  About time that oaf came around.$b$bLet''s get moving, then.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 2, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1, `OfferRewardEmote4` = 4 WHERE `entry` = 28035;
        UPDATE `quest_template` SET `OfferRewardText` = 'The Claw of Tichondrius...$B$BYou hold a piece of the very demon that led the Legion to these woods, $n. Better for it to be in our hands than with the satyr.$B$BHold still. I''m going to pull you back to our plane and make sure you and the claw arrive here safely...', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28044;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh good, you''re back! Don''t leave me alone with her! She''s crazy!$B$BGimme that, I''ll have you seeing the invisible in no time!' WHERE `entry` = 28049;
        UPDATE `quest_template` SET `OfferRewardText` = 'Well, here we are.$b$bI hope you''re ready, $N.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 28052;
        UPDATE `quest_template` SET `OfferRewardText` = 'Lunk heared that you used the stone to banish fire-lizard.  You saved Gorge, and you didn''t even kill!$b$bLunk so proud.  Lunk happy to be $n''s teacher.$b$bMaybe you take this.  Lunk doesn''t need it.  Lunk too busy adventuring!' WHERE `entry` = 28053;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 24, `DetailsEmote3` = 5, `DetailsEmote4` = 1, `OfferRewardEmote1` = 273 WHERE `entry` = 28054;
        UPDATE `quest_template` SET `OfferRewardText` = 'Strange how so many slaves cope poorly with freedom.  It''s a shame to have to do what we do, but such are the truths of war.$b$bNow, we must move on to more pressing tasks.', `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 28055;
        UPDATE `quest_template` SET `OfferRewardText` = 'A fight well-fought, $N!  I''m beginning to feel the tide turn.$b$bNow, when you''re ready, let''s hit these Dark Irons where it really hurts!', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 5 WHERE `entry` = 28056;
        UPDATE `quest_template` SET `OfferRewardText` = 'I see Evonice is up to her old tricks again.  I guess I''ll just... um... hang onto these pillows for a while.$b$bThe important part is that you''re here.  We''re going to need your help.', `RequestItemsText` = 'What?  Pillows?$b$bWhat?', `DetailsEmote1` = 1, `DetailsEmote2` = 5, `DetailsEmote3` = 1, `OfferRewardEmote1` = 6, `OfferRewardEmote2` = 1 WHERE `entry` = 28057;
        UPDATE `quest_template` SET `OfferRewardText` = 'Twilight''s Hammer, eh?  I should''ve expected as much.  I''m glad you arrived to help them out when you did.$b$bIt looks like, despite all odds, we''ve pressed our offensive to the doorstep of Calcinder''s lair.  It''s now time to finish the job.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 5, `DetailsEmote4` = 1, `OfferRewardEmote1` = 273, `OfferRewardEmote2` = 1, `OfferRewardEmote3` = 1 WHERE `entry` = 28060;
        UPDATE `quest_template` SET `OfferRewardText` = 'The remains of Calcinder''s minions lie smoldering at your feet.  Oilfist will be relieved to hear that you succeeded.', `DetailsEmote1` = 1, `DetailsEmote2` = 1 WHERE `entry` = 28061;
        UPDATE `quest_template` SET `OfferRewardText` = 'Archduke Calcinder has been banished from Azeroth.  All that remains is a small, ashy spot where he once stood.$b$bYour work here is done.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `DetailsEmote3` = 1 WHERE `entry` = 28062;
        UPDATE `quest_template` SET `OfferRewardText` = 'Our task is complete, and it''s all thanks to you, $N.  I''d like to offer you your choice from our coffers.  In addition, I intend to make you a full-fledged member of our order.$b$bWelcome to the Thorium Brotherhood, $N.  I''m proud to call you a $g brother: sister;.' WHERE `entry` = 28064;
        UPDATE `quest_template` SET `OfferRewardText` = 'Good going.$B$BDoesn''t look like much, does it?', `CompleteEmote` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28090;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 28091;
        UPDATE `quest_template` SET `RequestItemsText` = 'Keep moving. We need to get that gate open.', `DetailsEmote1` = 1, `IncompleteEmote` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28092;
