        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 28097;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is, unfortunately, as I expected.  These bracers bear the indelible mark of the firelord and his minions.$b$bVery well.  With no Horde or Alliance forces anywhere near this godforsaken gorge, it falls upon the Thorium Brotherhood to stop this Archduke before he spreads any more of his evil.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 28099;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 28100;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 28102;
        UPDATE `quest_template` SET `OfferRewardText` = 'It is true then?  An outsider rescued Prince Nadun from the Neferset?$B$BWe are truly in your debt, stranger.' WHERE `entry` = 28112;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 28116;
