        UPDATE `quest_template` SET `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 28121;
        UPDATE `quest_template` SET `OfferRewardText` = 'With the braziers gone, the druids of the Emerald Circle can enter Shadow Hold and clear out the last of the cultists. In time, it may even be used as the barrow den it once was.$B$BYou have my thanks, $n. Please take this reward.', `DetailsEmote1` = 1, `DetailsEmote2` = 1, `OfferRewardEmote1` = 1, `OfferRewardEmote2` = 1 WHERE `entry` = 28126;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 4, `OfferRewardEmote2` = 1 WHERE `entry` = 28128;
        UPDATE `quest_template` SET `OfferRewardText` = 'Oh look, it''s one of little Schnottz''s pamphlets.$b$bI''ll just be taking that from you, if you don''t mind.', `OfferRewardEmote1` = 396 WHERE `entry` = 28132;
        UPDATE `quest_template` SET `OfferRewardText` = 'Orsis!  Of course!$B$BHow could I not have seen this?' WHERE `entry` = 28134;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 273 WHERE `entry` = 28148;
        UPDATE `quest_template` SET `OfferRewardText` = 'There is little time for talk, $c. The druids fight valiantly against the satyr, but fel sorcery blocks their path.$B$BLuckily, I have a plan...', `DetailsEmote1` = 1 WHERE `entry` = 28150;
        UPDATE `quest_template` SET `DetailsEmote1` = 1 WHERE `entry` = 28153;
        UPDATE `quest_template` SET `OfferRewardText` = 'Truly incredible, $n. To journey within the very lair of evil here and slay every fiend that stands before you... I am overwhelmed.$B$BThe Emerald Circle thanks you for your work here in Felwood. As for Andalar, we will send scouts to rescue him at once. He shall have a hero''s welcome.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28155;
        UPDATE `quest_template` SET `OfferRewardText` = 'It seems you are still with us. I''m somewhat appreciative of that.$B$BThank you.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28171;
        UPDATE `quest_template` SET `OfferRewardText` = 'You seem to have made use of the disturbing implements with ease.$B$BI take solace in knowing that some tools of evil can ultimately still lead to safeguarding life. Nothing is without purpose.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28173;
        UPDATE `quest_template` SET `OfferRewardText` = 'You''ve started a wonderful thing this day, amidst all of this blood shed.$B$BIt may take many years, but this ravaged land will be restored. It will be beautiful again.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28175;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28176;
        UPDATE `quest_template` SET `DetailsEmote1` = 1, `OfferRewardEmote1` = 1 WHERE `entry` = 28191;
        UPDATE `quest_template` SET `OfferRewardText` = 'Zhey know nozhink, you say?$b$bVery vell, zhen. Zhe search goes on...' WHERE `entry` = 28193;
        UPDATE `quest_template` SET `OfferRewardText` = 'These are perfect, $c.$b$bWish us luck!', `OfferRewardEmote1` = 396 WHERE `entry` = 28194;
        UPDATE `quest_template` SET `OfferRewardEmote1` = 1 WHERE `entry` = 28201;
        UPDATE `quest_template` SET `OfferRewardText` = 'You killed Obsidia within her own lair? Impressive, $r. I''m sorry that I could not be there.$B$BYou''re true to your word, and you most certainly have the bite to back your bellow. Thank you.', `DetailsEmote1` = 1, `OfferRewardEmote1` = 6 WHERE `entry` = 28247;
